(window.JCPA_DATA=window.JCPA_DATA||{})["exams"]={"papers":[{"id":"2023-06","year":2023,"month":6,"label":"دورة حزيران 2023","session":"حزيران","src":"829ad251.json","questions":[{"num":1,"type":"mcq","q":"موظف دخله السنوي من الرواتب للعام 2022 بواقع 36.000 دينار ولديه دخل سنوي من الايجارات بقيمة 12.000 دينار ومصاريف المجاري المدفوعة 500 دينار والمسقفات المدفوعة بقيمة 1,500 دينار وهو متزوج وزوجته لا تعمل ولديه 3 أولاد الأول يدرس في الجامعة قيمة القسط السنوي 3,000 دينار والثاني يدرس في مدرسة خاصة قسطها السنوي 2000 دينار، إن الضريبة المستحقة:","o":["3,090 دينار","3,990 دينار","3,280 دينار","لاشيء مما ذكر"],"answer":3,"orig_answer":3,"law":"income","article":"9","status":"valid","explanation":"المادتان (9) و(11/أ): الدخل 36,000 + صافي الإيجار 11,500 = 47,500، ينزل 18,000 إعفاء شخصي ومعالين و2,000 تعليم ولدين (1,000 لكل ولد) فالخاضع 27,500 والضريبة 4,375 دينار، وهي غير واردة."},{"num":2,"type":"mcq","q":"وفقا لقانون ضريبة الدخل فان العبارة التالية صحيحة لنسبة ضريبة الدخل والمساهمة الوطنية:","o":["شركات التأجير التمويلي تخضع لنسبة 24% و 3% مساهمة وطنية.","شركات التامين تخضع لنسبة 24% ضريبة دخل و 2% مساهمة وطنية.","شركات الاتصالات تخضع لنسبة 24 و 4% مساهمة وطنية.","جميع ماذكر صحيح."],"answer":1,"orig_answer":1,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2 و و/1/د): التأمين وإعادة التأمين 24% ومساهمة وطنية 2%؛ التأجير التمويلي 4% والاتصالات 2%."},{"num":3,"type":"mcq","q":"شركة صناعة الكرتون المحدودة اعلنت في قائمة الدخل لسنة 2022 دخل صافي بقيمة 100.000 دينار وعلية فان ضريبة الدخل المستحقة:","o":["19,000 دينار","18,000 دينار","17,000 دينار","16,000 دينار"],"answer":1,"orig_answer":1,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/1 و ج/1): 20% مخفضة 10% عن سنة 2022 للنشاط الصناعي = 18% أي 18,000 دينار (السؤال محدد بسنة 2022؛ اعتباراً من 2024 تصبح النسبة 20%)."},{"num":4,"type":"mcq","q":"إن نشاط صناعة الأدوية والملابس في السنة المالية 2023 خاضعة لضريبة الدخل بنسبة:","o":["20%","19%","18%","17%"],"answer":1,"orig_answer":1,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ج/2): تخفيض 5% لصناعة الأدوية والملابس سنة 2023 فتصبح النسبة 20%×95% = 19%."},{"num":5,"type":"mcq","q":"حسب المادة 49 من قانون ضريبة الدخل يستوفى عن الدعوى رسم بنسبة:","o":["3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة أو المطالبة على أن لا يقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وأن لا تزيد على ثلاثماية دينار لكل فترة ضريبية عن جميع درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة أو مطالبة لوقوع المدعي في خسارة وأن لا تزيد على ثلاثماية دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة أو المطالبة على ان لايقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وأن لا تزيد على مئتين دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لا يقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة أو مطالبة لوقوع المدعي في خسارة وأن لا تزيد مئتين دينار لكل فترة ضريبية عن جميع درجات التقاضي."],"answer":1,"orig_answer":1,"law":"income","article":"49","status":"valid","explanation":"المادة (49/أ): 3% بحد أدنى 30 ديناراً وأعلى 300 دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي."},{"num":6,"type":"mcq","q":"حسب قانون ضريبة الدخل رقم 38 لسنة 2018 وحسب المادة 72 فان العبارة التالية صحيحة:","o":["يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي اي وقت ان يصحح بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي وتكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته أو بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي ولا تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير أو الموظف المفوض منه أو المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته أو بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي وتكون اجراءات التصحيح خاضعة للطعن."],"answer":3,"orig_answer":2,"law":"income","article":"72","status":"changed","explanation":"نص المادة (72) يطابق (ج)، لكن المحكمة الدستورية (القرار 7 لسنة 2018) قضت بعدم دستورية عبارة «ولا تكون إجراءات التصحيح خاضعة للطعن»، فالتصحيح يبقى قابلاً للطعن ويصبح (د) هو الأدق؛ إجابة الكتاب (ج) بحرفية النص."},{"num":7,"type":"mcq","q":"أبرمت شركة الاتحاد عقد تأمين على مكتبها في عمان مع شركة ما وراء البحار ولمدة سنة كاملة يبدأ العقد بتاريخ 1/3/2022 وينتهي بتاريخ 28/2/2023 حيث بلغت قيمة عقد التأمين 200 الف دينار وقامت شركة التأمين بإعادة تأمين 75% من قيمة العقد لدى شركة جنيف السويسرية. وعليه قيمة مخصص الاقساط غير المكتسبة الواجب تنزيله في 31/12/2022 هو:","o":["32,328 دينار","24,246 دينار","8,082 دينار","لا شيء مما ذكر."],"answer":2,"orig_answer":2,"law":"income","article":"6","status":"valid","explanation":"المادة (6/د): يُنزل مخصص الأقساط غير المكتسبة بعد خصم حصة معيدي التأمين: (200,000−150,000)×59/365 = 8,082 دينار."},{"num":8,"type":"mcq","q":"وفق تعليمات احتساب حوافز ضريبية للقطاع الصناعي وفقا لأحكام المادة 81 من قانون ضريبة الدخل حسب المعادلة التالية: (الدخل الصافي للنشاط الصناعي المستهدف ÷ مجموع الأرباح الصافية للمكلف من جميع الانشطة والمصادر الأخرى) × الدخل الخاضع للضريبة للمكلف من جميع الانشطة. وتسري هذه المعادلة على:","o":["للأنشطة الصناعية صناعة الأدوية والملابس وفقا للجدول الملحق بالتعليمات.","إذا كان من الانشطة الصناعية المستفيدة فعليا من نظام تخفيض ضريبة الدخل في المناطق الأقل نموا رقم (44) لسنة 2016","إذا كان النشاط الصناعي مؤسسة مسجلة في المناطق التنموية.","جميع ما ذكر خطأ."],"answer":3,"orig_answer":3,"law":"income","article":"","status":"unverified","explanation":"حسب تعليمات احتساب حوافز ضريبة الدخل للقطاع الصناعي لسنة 2020 (غير واردة في نص القانون): لا تسري على حالتي (ب) و(ج) والمعادلة عامة لكل الأنشطة المستهدفة، فالإجابة (د) وفق الكتاب."},{"num":9,"type":"mcq","q":"أحد العبارات التالية ليست صحيحة - باستثناء الشركات المساهمة العامة والشركات المساهمة الخاصة المتداولة لغايات احتساب ضريبة الدخل على أرباح بيع أسهم أو حصص الشركات أو أرباح بيع أسهم أو حصص للشخص الطبيعي المقيم أو غير المقيم أو الشركات يتم:","o":["احتساب نسبة (1%) من قيمة البيع اذا كانت تزيد عن (500) الف دينار ولا تتجاوز مليون دينار.","احتساب نسبة (1.5%) من قيمة البيع اذا كانت تزيد عن مليون دينار ولا تتجاوز (3) مليون دينار.","احتساب نسبة (0.75%) من قيمة البيع اذا كانت لا تزيد (250) الف دينار وبما لا يقل عن (500) دينار.","احتساب نسبة (0.75%) من قيمة البيع اذا كانت لا تتجاوز (250) الف دينار وبما لا يقل عن (100) دينار."],"answer":2,"orig_answer":2,"law":"income","article":"","status":"unverified","explanation":"النسب واردة في التعليمات/النظام لا في القانون: 0.5% حتى 250 ألف وبحد أدنى 100 دينار، 0.75% من 250-500 ألف، 1% من 500 ألف-مليون، 1.5% من 1-3 ملايين؛ فـ(ج) و(د) كلاهما خطأ، والكتاب يعتمد (ج) لخطأ الحد الأدنى."},{"num":10,"type":"mcq","q":"وفقاً لقانون الضريبة العامة على المبيعات إحدى العبارات التالية صحيحة:","o":["تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","تطبق محكمة الاستئناف الضريبية الأصول المنصوص عليها في قانون أصول المحاكمات الجزائية بالقدر الذي لا يتعارض فيه مع احكام قانون الضريبة العامة على المبيعات.","تطبق محكمة البداية الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","جميع ما ذكر خطأ."],"answer":3,"orig_answer":3,"law":"sales","article":"59","status":"valid","explanation":"المادة (59): تطبق المحكمتان أصول المحاكمات الجزائية والمدنية بالقدر الذي لا يتعارض مع أحكام قانون المبيعات، وكل خيار يجتزئ النص فيكون (د)."},{"num":11,"type":"mcq","q":"في حال إسقاط القضية بسبب الغياب لدى المحكمة فإن الجهات الملزمة بتبليغ الاسقاط هي:","o":["قرارات قضايا الدخل (محكمة الضريبة) وقرارات المبيعات (دائرة الضريبة).","قرارات الإسقاط لقضايا الدخل والمبيعات (دائرة ضريبة الدخل).","قرارات الإسقاط لقضايا الدخل والمبيعات (محكمة الضريبة)","كل ما ذكر غير صحيح."],"answer":0,"orig_answer":0,"law":"sales","article":"57","status":"valid","explanation":"المادة (57/ط) مبيعات: تبليغ الدائرة للمكلف بقرار الإسقاط؛ والمادة (46/ج) دخل: تبليغ المحكمة قرار الإسقاط للمكلف."},{"num":12,"type":"mcq","q":"يجوز الاعتراض على قرار التغريم بمقتضى أحكام المادة 28 من قانون الضريبة العامة على المبيعات:","o":["لدى المحكمة خلال 30 يوم من تبلغ المكلف قرار التغريم","لدى الوزير خلال 30 يوم من تبلغ المكلف قرار التغريم.","لدى المدير خلال 30 يوم من تبلغ المكلف قرار التغريم.","لدى هيئة الاعتراض المشكلة لهذه الغاية خلال 30 يوم من تبلغ المكلف قرار التغريم."],"answer":1,"orig_answer":1,"law":"sales","article":"29","status":"valid","explanation":"المادة (29/ب): يجوز الاعتراض لدى الوزير خلال ثلاثين يوماً من التبلغ."},{"num":13,"type":"mcq","q":"أي من العبارات التالية تعتبر صحيحة فيما يتعلق بتأجيل توريد ضريبة المبيعات على السلع عند الاستيراد حسب المادة 14 من التعليمات رقم (1) لسنة 2010:","o":["للمدير تأجيل دفع الضريبة المترتبة على السلع والخدمات عند الاستيراد للمسجل حتى تتحقق واقعة البيع الواردة في الفقرة أ من المادة (4) من القانون وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنة واحدة على ان لا يكون مستورد لحساب الغير","للمدير تأجيل دفع الضريبة المترتبة على السلع عند الاستيراد للمسجل حتى تتحقق واقع البيع الواردة في الفقرة أ من المادة (4) من القانون أو التوريد وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنة واحدة.","للمدير تأجيل دفع الضريبة المترتبة على السلع عند الاستيراد للمسجل حتى تتحقق واقع البيع الواردة في الفقرة أ من المادة (4) من القانون أو التوريد وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنتين.","للمدير تأجيل دفع الضريبة المترتبة على السلع عند الاستيراد للمسجل حتى تتحقق واقع البيع الواردة في الفقرة أ من المادة (4) من القانون أو التوريد وتكون موافقة المدير على التأجيل لا تزيد مدتها على سنة واحدة ."],"answer":2,"orig_answer":2,"law":"sales","article":"26","status":"unverified","explanation":"المادة (14/أ) من التعليمات التنفيذية رقم (1) لسنة 2010: مدة التأجيل لا تزيد على سنتين؛ والقانون (المادة 26/د) يحيل شروط التأجيل إلى التعليمات."},{"num":14,"type":"mcq","q":"حسب المادة 46 من قانون ضريبة الدخل إذا تم اسقاط الدعوى بسبب الغياب أو لأي سبب آخر ولم يتم تجديدها يعتبر القرار المطعون فيه قطعيا بعد مرور:","o":["ثلاثون يوما من تاريخ تبليغ المحكمة قرار الاسقاط للمكلف أو وكيله وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرتين وبسبب مبرر.","ثلاثون يوما من تاريخ إسقاط الدعوى وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لأكثر من مرتين وبسبب مبرر.","ثلاثون يوما من تاريخ تبليغ المحكمة قرار الاسقاط للمكلف أو وكيله وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرة وبسبب مبرر.","ثلاثون يوما من تاريخ إسقاط الدعوى وفي جميع الأحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرة وبسبب مبرر."],"answer":0,"orig_answer":0,"law":"income","article":"46","status":"valid","explanation":"المادة (46/ج): ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الإسقاط ولا يجوز التجديد لأكثر من مرتين وبسبب مبرر."},{"num":15,"type":"mcq","q":"مصنع (أ) ينتج سلع خاضعة لضريبة المبيعات بنسبة 16% قام ببيع بضاعة بقيمة 10.000 دينار إلى الشركة (ب) بموجب بيان جمركي إدخال المنطقة الحرة بناءا على طلب الشركة (ب) علما بإن الشركة (ب) ليست مسجلة بالمنطقة الحرة: - إن ضريبة المبيعات المستحقة على المصنع (أ) هي:","o":["700 دينار.","1,600 دينار","500 دينار.","لاشيء مما ذكر"],"answer":3,"orig_answer":3,"law":"sales","article":"7","status":"valid","explanation":"المادة (7/ب/2): السلع المبيعة إلى المناطق الحرة بموجب بيان إدخال تخضع للضريبة بنسبة الصفر."},{"num":16,"type":"mcq","q":"بلغت قيمة مبيعات الشقق للشركة اسكانات البناء الحديث لسنة 2020 بقيمة 150,000 دينار ان ضريبة الدخل المستحقة على الشركة حسب تعليمات نسب الارباح:","o":["3,000 دينار","5,250 دينار","4,500 دينار","3,750 دينار"],"answer":3,"orig_answer":3,"law":"income","article":"","status":"unverified","explanation":"وفق تعليمات نسب الأرباح (غير واردة في القانون): مجمل ربح 25% = 37,500 ينزل منه 50% مصاريف فالخاضع 18,750 × 20% = 3,750 دينار."},{"num":17,"type":"mcq","q":"قدمت الشركة المتحدة الإقرار ضريبة الدخل لسنة 2019 بتاريخ 31/3/2020 وأعلنت عن ضريبة دخل بقيمة 10.000 دينار لم تقم بدفعها بتاريخ 31/5/2021 وافقت الشركة على قرار المدقق الضريبي بتعديل الاقرار لتصبح الضريبة المستحقة 12000 دينار إن غرامة تأخير دفع الضريبة على الشركة بتاريخ 31/5/2021 هي:","o":["2,736 دينار","2,440 دينار","2,928 دينار","لا شيء مما ذكر."],"answer":0,"orig_answer":0,"law":"income","article":"36","status":"valid","explanation":"المادة (36/أ): لم تُدفع الضريبة المعلنة فتحتسب 4 بالألف أسبوعياً على كامل 12,000 من 1/5/2020 حتى 31/5/2021 (57 أسبوعاً) = 2,736 دينار."},{"num":18,"type":"mcq","q":"قامت شركة بإستيراد خدمة بتاريخ 1/1/2022 وسجلت الخدمة بالمصاريف بتاريخ الفاتورة في 1/1/2022، قامت الشركة بدفع قيمة الفاتورة بتاريخ 1/5/2022، اذا علمت أن قيمة الخدمة 1.000 دينار وان الشركة قامت بدفع ضريبة المبيعات على الخدمة المستوردة بتاريخ 12/6/2022 فإن قيمة الضريبة والغرامات المستحقة هي:","o":["160 دينار 320 مثلي الضريبة غرامة 12.60 دينار غرامة 4 بالالف + 200- 1000 دينار غرامة جزائية.","160 دينار غرامة 1.28 دينار غرامة 4 بالالف.","160 دينار غرامة 12.60 دينار غرامة 4 بالالف + 100- 500 دينار غرامة جزائية.","160 دينار، غرامة 1.28 دينار غرامة 4 بالالف + 100 - 500 دينار غرامة جزائية."],"answer":1,"orig_answer":1,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج): تستحق خلال شهر من دفع البدل أي 1/6/2022؛ التأخير 12 يوماً = أسبوعان، فغرامة المادة (51) = 160×0.004×2 = 1.28 دينار ولا تهرب (أقل من 3 أشهر)."},{"num":19,"type":"mcq","q":"حسب المادة 30 من قانون الضريبة العامة على المبيعات أي من العبارات التالية صحيحة ويعتبر من جرائم التهرب الضريبي:","o":["تطبيق نسب أو فئات ضريبية على السلع أو الخدمات الخاضعة للضريبة بصورة مخالفة لأحكام هذا القانون إذا أدى ذلك إلى نقص في مقدار الضريبة المستحقة يتجاوز مئتين دينار","التخلف عن تقديم طلب التسجيل لدى الدائرة في الموعد المحدد للتسجيل بموجب هذا القانون.","استيفاء ضريبة غير مستحقة وتوريدها خلال المدة التي يحددها القانون لتوريد الضريبة.","جميع ما ذكر غير صحيح."],"answer":3,"orig_answer":3,"law":"sales","article":"30","status":"valid","explanation":"المادة (30): الحد 500 دينار لا 200، والتخلف عن التسجيل تهرب إذا زاد على 60 يوماً، واستيفاء ضريبة غير مستحقة مع توريدها في الموعد ليس تهرباً."},{"num":20,"type":"mcq","q":"أي من الحالات الآتية لا تستوجب فرض غرامة لا تقل عن 100 دينار ولا تتجاوز 500 دينار:","o":["عدم إعلام الدائرة بالتغييرات التي طرأت على البيانات الواردة في طلب التسجيل خلال الموعد المحدد.","عدم تمكين موظفي الدائرة من ممارسة صلاحياتهم في التفتيش والرقابة.","خصم الضريبة أو ردها بصورة مخالفة للقانون إذا ظهرت زيادة في الخصم أو الرد يتجاوز 500 دينار.","التخلف عن تقديم الإقرارات الضريبية مدة لا تزيد عن (60) يوما."],"answer":2,"orig_answer":2,"law":"sales","article":"28","status":"valid","explanation":"المادة (28): الخصم أو الرد المخالف الذي يتجاوز 500 دينار تهرب وفق المادة (30/ز) لا مخالفة غرامتها 100-500."},{"num":21,"type":"mcq","q":"قامت شركة بشراء اثاث بفواتير ضريبية بقيمة 5,000 دينار وضريبة مبيعات 800 دينار عند بداية عملها في 1/1/2022، بتاريخ 1/4/2022 قامت الشركة بالتسجيل في الشبكة العامة لضريبة المبيعات وأرفقت كشوفات جرد المستودعات الذي ظهرت فيها قيمة البضاعة 15.312 دينار وبفواتير ضريبية وجرد الموجودات الثابتة والضرائب المدفوعه، تستهلك الشركة موجوداتها الثابتة بنسبة 10% سنويا، ان ضريبة المبيعات واجبة التخصيم:","o":["2,892 دينار","3,170 دينار","3,250 دينار","3,230 دينار"],"answer":3,"orig_answer":3,"law":"sales","article":"19","status":"valid","explanation":"المادة (19/د): يخصم ما تحمله قبل التسجيل على السلع التي بحوزته: بضاعة 15,312×16% = 2,450 + أثاث بالقيمة الدفترية 4,875×16% = 780 = 3,230 دينار."},{"num":22,"type":"mcq","q":"حسب قانون الضريبة العامة على المبيعات أي من العبارات التالية غير صحيحة:","o":["لا تخضع للضريبة السلع والخدمات المهربة.","لا يخضع للضريبة العامة على المبيعات بيع الأموال غير المنقولة.","تستحق الضريبة العامة والخاصة على السلع المستوردة في مرحلة التخليص عليها حسب نسبة الضريبة أو فئتها في تاريخ تسجيل البيان.","تستحق الضريبة على بيع الخدمة عند إصدار فاتورة ضريبية وعند تسلم بدل الخدمة كليا أو جزئيا أيهما أسبق."],"answer":0,"orig_answer":0,"law":"sales","article":"12","status":"valid","explanation":"المادة (12): تخضع للضريبة السلع والخدمات المهربة حسب الفئات النافذة في تاريخ التهرب."},{"num":23,"type":"mcq","q":"يجوز لأي شركة أن تعترض خطياً لدى الوزير بتسجيل شركة أخرى لإلغاء تسجيل تلك الشركة الأخرى إذا كان الاسم الذي سجلت به مماثلاً لاسمها أو يشبهه إلى درجة قد تؤدي إلى اللبس أو الغش وذلك:","o":["لا يوجد مدة محددة.","خلال تسعين يوما من تاريخ نشر القرار في الجريدة الرسمية.","خلال ستين يوما من تاريخ نشر القرار في الجريدة الرسمية.","خلال ثلاثون يوما من تاريخ نشر القرار في الجريدة الرسمية."],"answer":2,"orig_answer":2,"law":"companies","article":"5","status":"valid","explanation":"المادة (5/ب): الاعتراض لدى الوزير خلال ستين يوماً من نشر قرار التسجيل في الجريدة الرسمية."},{"num":24,"type":"mcq","q":"سنداً لأحكام نظام تصفية الشركات للمراقب عام الشركات أثناء السير في إجراءات التصفية الاختيارية إحالة الشركة للمحكمة لتستمر التصفية تحت إشرافها أو لتصفية الشركة تصفية إجبارية للأسباب التي يضمنها طلبه وذلك:","o":["بعد مدة أقصاها ثلاث سنوات.","بعد مدة اقصاها سنتين.","بأي وقت أثناء السير بإجراءات التصفية.","بعد مدة أقصاها سنة من تاريخ التصفية"],"answer":2,"orig_answer":2,"law":"other:نظام تصفية الشركات","article":"9","status":"unverified","explanation":"المادة (9) من نظام تصفية الشركات: للمراقب وبأي وقت أثناء السير في إجراءات التصفية إحالة الشركة للمحكمة."},{"num":25,"type":"mcq","q":"سنداً لأحكام نظام تصفية الشركات لا يجوز في أي حال من الأحوال أن يتجاوز مجموع أتعاب المصفي نسبة:","o":["30% من واردات أموال التصفية","20% من واردات أموال التصفية","10% من واردات أموال التصفية","5% من واردات أموال التصفية"],"answer":2,"orig_answer":2,"law":"other:نظام تصفية الشركات","article":"16","status":"unverified","explanation":"المادة (16/ب) من نظام التصفية: لا تتجاوز أتعاب المصفي 10% من واردات أموال التصفية."},{"num":26,"type":"mcq","q":"تعتبر أي عوائد إضافية تحققها الشركات التي لا تهدف إلى تحقيق الربح وفراً لها ولا يجوز استخدامها:","o":["يجوز استخدام تلك العوائد وفقاً لما يراه مجلس الإدارة مناسب.","إلا لتحقيق غاياتها والأهداف التي أنشئت من أجلها.","إلا للشركاء.","إلا للجهات المانحة."],"answer":1,"orig_answer":1,"law":"other:نظام الشركات التي لا تهدف الى تحقيق الربح لسنة 2010","article":"7","status":"unverified","explanation":"المادة (7/أ) من النظام: العوائد الصافية وفر لا تستخدم إلا لتحقيق غاياتها وأهدافها وتوسعة أنشطتها."},{"num":27,"type":"mcq","q":"يحق للمساهمين الطلب من مراقب عام الشركات إجراء تدقيق على أعمال الشركة بعد تقديمهم كفالة لتغطية نفقات التدقيق:","o":["مساهمين يملكون 40% من رأسمال الشركة","مساهمين يملكون 10% من رأسمال الشركة.","مساهمين يملكون 5% من رأسمال الشركة.","مساهمين يملكون 1% من رأسمال الشركة."],"answer":1,"orig_answer":1,"law":"companies","article":"275","status":"valid","explanation":"المادة (275/أ): مساهمون يملكون ما لا يقل عن 10% من رأس المال أو ربع أعضاء مجلس الإدارة."},{"num":28,"type":"mcq","q":"تحدد بدلات الانتقال والسفر للرئيس وأعضاء مجلس الإدارة بموجب:","o":["بموجب نظام خاص تصدره الشركة لهذه الغاية.","قرار يتخذه المراقب ومجلس الإدارة.","قرار يتخذه مراقب عام الشركات.","قرار يتخذه مجلس إدارة الشركة."],"answer":0,"orig_answer":0,"law":"companies","article":"162","status":"valid","explanation":"المادة (162/د): تحدد بموجب نظام خاص تصدره الشركة لهذه الغاية."},{"num":29,"type":"mcq","q":"سندا لتعليمات الأسهم القابلة للاسترداد، عند قيام الشركة بإسترداد الأسهم القابلة للاسترداد يترتب على الشركة تقديم كتاب من مدقق الحسابات:","o":["يبين المعالجة المحاسبية لاسترداد هذه الأسهم.","يبين آلية نشوء هذه الأسهم.","يبين عدد هذه الأسهم.","يبين نوع هذه الأسهم."],"answer":0,"orig_answer":0,"law":"other:تعليمات الأسهم القابلة للاسترداد للشركات المساهمة الخاصة","article":"8","status":"unverified","explanation":"المادة (8) من التعليمات: كتاب من مدقق الحسابات يبين المعالجة المحاسبية عند استرداد الأسهم."},{"num":30,"type":"mcq","q":"تصدر القرارات في اجتماع الهيئة العامة غير العادي للشركة المساهمة العامة بأكثرية:","o":["75% من مجموع الأسهم الممثلة في الاجتماع.","(50% + 1) من مجموع الأسهم الممثلة في الاجتماع.","50% من مجموع الأسهم الممثلة في الاجتماع.","40% من مجموع الأسهم الممثلة في الاجتماع."],"answer":0,"orig_answer":0,"law":"companies","article":"175","status":"valid","explanation":"المادة (175/ب): بأكثرية 75% من مجموع الأسهم الممثلة في الاجتماع."},{"num":31,"type":"mcq","q":"يعتبر أي اجتماع تعقده الهيئة العامة للشركة المساهمة العامة المحدودة باطلا:","o":["إذا لم يحضر الوزير أو من يندبه خطيا.","إذا لم يحضر مدقق حسابات الشركة.","إذا لم يحضر مراقب عام الشركات أو من ينتدبه خطيا من موظفي الدائرة ومدقق حسابات الشركة.","إذا لم يحضر مراقب عام الشركات أو من ينتدبه خطيا من موظفي الدائرة."],"answer":3,"orig_answer":3,"law":"companies","article":"182","status":"valid","explanation":"المادة (182): يعتبر الاجتماع باطلاً إذا لم يحضره المراقب أو من ينتدبه خطياً من موظفي الدائرة."},{"num":32,"type":"mcq","q":"تتكون هيئة مالكي إسناد القرض من:","o":["مالكي إسناد القرض.","مالكي إسناد القرض ومجلس الإدارة.","مجلس الإدارة ومساهمي الشركة.","مساهمي الشركة."],"answer":0,"orig_answer":0,"law":"companies","article":"126","status":"valid","explanation":"المادة (126/أ): تتكون حكماً من مالكي أسناد القرض في كل إصدار."},{"num":33,"type":"mcq","q":"إذا تخلفت الهيئة العامة للشركة عن انتخاب مدقق الحسابات أو اعتذر المدقق الذي انتخبته عن العمل أو امتنع عن القيام به لأي سبب من الأسباب أو توفي:","o":["يبقى شاغرا تعيين مدقق لحين اجتماع هيئة عامة قادم.","يعين مجلس الإدارة مدقق حسابات.","يعين مراقب عام الشركات من تلقاء نفسه مدقق حسابات.","على مجلس الإدارة أن ينسب للمراقب ثلاثة من مدققي الحسابات على الأقل وذلك خلال أربعة عشر يوما من تاريخ شغور هذا المركز ليختار أحدهم."],"answer":3,"orig_answer":3,"law":"companies","article":"192","status":"valid","explanation":"المادة (192/ب): ينسب مجلس الإدارة للمراقب ثلاثة مدققين على الأقل خلال 14 يوماً ليختار أحدهم."},{"num":34,"type":"mcq","q":"إحدى العبارات التالية الصحيحة:","o":["للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها بدون أي سبب.","للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها إذا زاد عن حاجتها أو لحقت بها خسائر تزيد عن نصف رأسمالها.","للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها إذا لحقت بها خسائر فقط.","للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها إذا زاد عن حاجتها فقط."],"answer":1,"orig_answer":1,"law":"companies","article":"68","status":"valid","explanation":"المادة (68/أ): إذا زاد على حاجتها أو لحقت بها خسائر تزيد على نصف رأسمالها."},{"num":35,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة بموجب قانون التجارة رقم (12) لعام 1966.","o":["يجوز اعادة الاعتبار للمفلس بعد وفاته.","لا يجوز إعادة الاعتبار الى المفلسين الذين حكم عليهم بالافلاس الاحتيالي أو بسرقة أو احتيال أو إساءة أمانة إلا إذا كانوا قد حصلوا على إعادة الاعتبار الجزائي.","تخضع الشركات المدنية والشركات المرخصة أو المسجلة بمقتضى قانون الشركات الساري المفعول الى اجراءات التصفية الفسخ الواردة فيه.","جميع العبارات صحيحة."],"answer":null,"orig_answer":3,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"obsolete","explanation":"أحكام الإفلاس في قانون التجارة أُلغيت وحل محلها قانون الإعسار رقم (21) لسنة 2018؛ وقد أُلغي السؤال ومُنحت علامته للجميع (إجابة الكتاب د)."},{"num":36,"type":"mcq","q":"أي من العبارات التالية تعتبر صحيحة فيما يتعلق بالسندات بالمادة (97) من قانون التجارة رقم (12) لعام 1966.","o":["إذا تعددت سندات الرجوع يجوز مطالبة اخر مظهر للسند بنفقات سند رجوع واحد.","إذا تعددت سندات الرجوع فلا يجوز مطالبة ساحب السند الأصلي وكل مظهر له إلا بنفقات سند رجوع واحد.","إذا تعددت سندات الرجوع يجوز مطالبة صاحب السند الأصلي وكل مظهر له بنفقات كل سند رجوع.","جميع العبارات غير صحيحة."],"answer":1,"orig_answer":1,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة (أحكام سند السحب/الرجوع): عند تعدد سندات الرجوع لا يطالب الساحب الأصلي وكل مظهر إلا بنفقات سند رجوع واحد."},{"num":37,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة فيما يتعلق بالعقود التجارية حسب قانون التجارة:","o":["كل التزام تجاري يقصد به القيام بعمل أو بخدمة لا يعد معقودا على وجه مجاني واذا لم يعين الفريقين أجرة أو عمولة أو سمسرة فيستحق الدائن الاجر المعروف في المهنة.","يخضع إثبات العقود التجارية مبدئيا للقواعد الحصرية الموضوعة للعقود المدنية.","يعتمد في اثبات العدل والثمن الدارج على اسعار البورصة والتسعيرات ان وجدت ما لم يوجد اتفاق مخالف","أ + ب غير صحيح."],"answer":1,"orig_answer":1,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة: لا يخضع إثبات العقود التجارية مبدئياً للقواعد الحصرية للعقود المدنية ويجوز إثباتها بجميع طرق الإثبات."},{"num":38,"type":"mcq","q":"بموجب قانون التجارة فيما يتعلق بالوكالة التجارية فإن احدى العبارات التالية غير صحيحة:","o":["الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل لا يعد مطلق اليد في الجزء الباقي.","عندما يعمل الوكيل باسم موكله تكون حقوقه والتزاماته خاضعة للاحكام الواردة بهذا الشأن في القانون المدني.","الوكالة التجارية وان احتوت على توكيل مطلق لا تجيز الاعمال غير التجارية الا بنص صريح.","يسمى هذا العقد وكالة بالعمولة ويجب على الوكيل أن يعمل باسمه الخاص أو تحت عنوان تجاري لحساب من وكله."],"answer":0,"orig_answer":0,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة: الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي، فالعبارة (أ) غير صحيحة."},{"num":39,"type":"mcq","q":"حسب المادة (211) من قانون التجارة رقم 12 لعام 1966 جميع العبارات التالية صحيحة ماعدا:","o":["يكون لهذه الصورة ما للأصل من أحكام.","لحامل السند أن يحرر صورا منه.","لا يجوز أن يظهر الصورة وضمانها إحتياطياً على الوجه الذي يجري عليه الاصل.","جميع العبارات غير صحيحة."],"answer":2,"orig_answer":2,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"211","status":"unverified","explanation":"المادة (211) من قانون التجارة: يجوز تظهير الصورة وضمانها احتياطياً على الوجه الذي يجري عليه الأصل."},{"num":40,"type":"mcq","q":"على المحاسب القانوني المسجل في سجل غير المزاولين والراغب في العودة الى التسجيل في سجل المزاولين للمهنة أن يقدم للمجلس شهادة تعليم مستمر قبل نقل اسمه إلى سجل المزاولين بعدد ساعات هي:","o":["40 ساعة.","20 ساعة","30 ساعة.","لا شيء مما ذكر."],"answer":0,"orig_answer":0,"law":"accounting","article":"","status":"unverified","explanation":"الحكم وارد في النظام/التعليمات الصادرة بموجب القانون (المادة 9 منها) لا في نص القانون: شهادة تعليم مستمر لا تقل عن 40 ساعة."},{"num":41,"type":"mcq","q":"تتولى الجمعية في سبيل تحقيق اهدافها المهام والصلاحيات التالية ماعدا:","o":["تطوير التشريعات ذات العلاقة بالمهنة.","التعاون في مجال المهنة مع الجامعات والمؤسسات التعليمية.","الانضمام إلى عضوية الهيئات العربية والدولية ذات العلاقة بالمهنة اذا رأت ذلك مناسباً.","توثيق العلاقات المهنية والاجتماعية بين مزاولي المهنة محليا وعربيا ودوليا."],"answer":0,"orig_answer":0,"law":"accounting","article":"9","status":"valid","explanation":"المادة (9/هـ): مهمة الجمعية «اقتراح» تطوير التشريعات لا تطويرها."},{"num":42,"type":"mcq","q":"كل من خالف أحكام المادة (21) من قانون تنظيم مهنة المحاسبة القانونية لسنة 2003 والتي تحظر على أي شخص غير حاصل على إجازة المزاولة وغير مسجل في سجل المزاولين وقام بمزاولة أعمال التدقيق بالعقوبة التالية:","o":["يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات او بغرامة لا تقل عن خمسة الاف دينار ولا تزيد على عشرين ألف دينار أو بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على اربع سنوات أو بغرامة لا تقل عن خمسة الاف دينار ولا تزيد على عشرين الف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات او بغرامة لا تقل عن أربعة الاف دينار ولا تزيد على عشرة الاف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على اربع سنوات او بغرامة لا تقل عن خمسة الاف دينار ولا تزيد على عشرة الاف دينار او بكلتا العقوبتين."],"answer":0,"orig_answer":0,"law":"accounting","article":"43","status":"valid","explanation":"المادة (43/أ/1): حبس سنة إلى ثلاث سنوات أو غرامة 5,000-20,000 دينار أو كلتاهما."},{"num":43,"type":"mcq","q":"أي من العبارات التالية غير صحيحة فيما يتعلق بضمانات المسؤولية المدنية المنصوص عليها في المادة (36) من القانون على وكيل الاعسار:","o":["على وكيل الاعسار تقديم ضمانات كافية أو استصدار بوليصة تأمين ضد المسؤولية المهنية وفقا للشروط التي ينص عليها النظام الذي يصدر بموجب احكام هذا القانون.","يكون وكيل الاعسار مسؤولا عن أي ضرر يلحق بذمة الاعسار أو بالاشخاص الذين اشتركوا في اجراءات الاعسار نشأ عن إهماله او اهمال ممثليه او تابعيه في اداء مهامهم أو إخلالهم بالواجبات المنوطة بهم.","يسقط حق المطالبة بالتعويض المنصوص عليه في الفقرة أ بمرور ثلاث سنوات على تاريخ علم المضرور بالضرر وبالشخص المسؤول عنه أو بمرور ثلاث سنوات على تاريخ إستكمال إجراءات الاعسار أيهما يقع أولاً.","جميع العبارات صحيحة"],"answer":2,"orig_answer":2,"law":"insolvency","article":"56","status":"valid","explanation":"المادة (56/ب): يسقط الحق بمرور ثلاث سنوات ... «أيهما يقع لاحقاً» لا أولاً (والنص في المادة 56 لا 36)."},{"num":44,"type":"mcq","q":"حسب المادة (51) من قانون الاعسار ان العبارة التالية صحيحة:","o":["على وكيل الاعسار أن يؤدي واجباته بنفسه وبالدقة والأمانة المطلوبة وأن يلتزم الحياد مع جميع الجهات التي تتأثر بإجراءات الإعسار.","لوكيل الاعسار الاستعانة بخبراء يختارهم لتنفيذ مهامه على أن يبقى مسؤولا عن تنفيذ تلك المهام ويتحمل أتعاب الخبراء ما لم يقرر الدائنين غير ذلك.","يحظر على وكيل الاعسار تفويض مهامه للغير الا في ظروف استثنائية على أن يكون التفويض محددا من حيث المدة والمهام وبموافقة المحكمة على ان يكون وكيل الاعسار مسؤول عن أعمال المفوض.","جميع العبارات غير صحيحة"],"answer":3,"orig_answer":3,"law":"insolvency","article":"51","status":"valid","explanation":"المادة (51): لا ترد كلمة «بنفسه»، والاستثناء في أتعاب الخبراء بقرار المحكمة لا الدائنين، والمفوض ووكيل الإعسار مسؤولان بالتكافل والتضامن."},{"num":45,"type":"mcq","q":"حسب قانون الاعسار فإن العبارة التالية غير صحيحة:","o":["لدائني هذه الديون الحق في تقديم دفوعهم واعتراضاتهم على طلب المدين بالابراء خلال مدة سبعة أيام من تاريخ تبلغهم الطلب.","للمدين حسن النية تقديم طلب للمحكمة بالابراء من الديون غير المسددة وعلى المحكمة تبليغ هذا الطلب الى دائني هذه الديون ووكيل الاعسار خلال اسبوع من وروده إليها","تعلن المحكمة إنتهاء إجراءات الاعسار بعد إتمام التوزيع النهائي أو اذا تم سداد كامل الديون اثناء السير في إجراءات الاعسار ويتم اشهار قرار المحكمة وسبب انتهاء الاجراءات.","اذا كان المدين شخصاً اعتبارياً تنتهي شخصيته الاعتبارية باستكمال توزيع العوائد ما لم يتم سداد ديونه بالكامل وعلى وكيل الاعسار تبليغ الجهة التي تم تسجيل الشخص الاعتباري لديها بقرار المحكمة لغايات شطب تسجيله وفقاً للتشريعات ذات العلاقة."],"answer":1,"orig_answer":1,"law":"insolvency","article":"108","status":"valid","explanation":"المادة (108/أ): على المحكمة تبليغ الطلب «فور وروده» لا خلال أسبوع."},{"num":46,"type":"mcq","q":"حسب قانون البيئة الإستثمارية رقم (21) لسنة 2022 أي من العبارات التالية تعتبر غير صحيحة:","o":["إذا لم يقم المطور الرئيسي بإنجاز اعمال التطوير في المنطقة التنموية على الوزارة مطالبته بغرامة نسبتها (2%) من قيمة الأرض السوقية التي لم يتم تطويرها وذلك عن كل سنة تأخير عن الجدول الزمني المحدد في اتفاقية التطوير.","على الرغم مما ورد في اي تشريع آخر تعتبر الرخصة الممنوحة في المنطقة التنموية لممارسة النشاط الاقتصادي في المنطقة بمثابة رخصة مهن.","على الرغم مما ورد في اي تشريع آخر، لا تطبق في المنطقة التنموية أي قيود متعلقة بنسبة رأس المال الأجنبي.","لا شيء مما ذكر غير صحيح."],"answer":3,"orig_answer":3,"law":"investment","article":"19","status":"valid","explanation":"المواد (19/د) و(26) و(27/أ): العبارات الثلاث صحيحة."},{"num":47,"type":"mcq","q":"حسب قانون التأجير التمويلي رقم 45 لسنة 2008 أي من العبارات التالية غير صحيحة:","o":["لا يترتب على تأجير المأجور من الباطن أي مساس في حقوق المستأجر والتزاماته المحددة في عقد التأجير في مواجهة المؤجر.","للمستأجر الحق في تأجير المأجور من الباطن ويعتبر المؤجر من الباطن والمستأجر من الباطن بمثابة مؤجر ومستأجر وفق احكام هذا القانون ويتمتعان بحقوق اطراف عقد التأجير ويتحملان التزاماتهم","إذا كان المستأجر أجنبيا أو شخص اعتباري فيجب عليه الحصول على اي موافقات رسمية لاستئجار العقار او تملكه وفق احكام التشريعات النافذة المفعول.","يحق للمستأجر تملك المأجور مقابل تسديد كامل ما تبقى من بدل الايجار قبل انتهاء عقد التأجير."],"answer":1,"orig_answer":1,"law":"leasing","article":"9","status":"valid","explanation":"المادة (9/أ): التأجير من الباطن «بموافقة خطية من المؤجر»؛ و(د) ينقصها «ما لم ينص العقد على خلاف ذلك» (المادة 6/ب) لكن (ب) أوضح خطأً."},{"num":48,"type":"mcq","q":"إحدى العبارات التالية غير صحيحة بموجب قانون رسوم الطوابع والواردات لسنة 2001","o":["يعتبر تجديد أي معاملة واردة في جدول المعاملات الخاضعة للرسوم الملحق بالقانون أو تمديدها بمثابة معاملة جديدة تخضع للرسوم المنصوص عليها في هذا الجدول.","تفرض على الموظف الذي لم يبطل الطوابع على المعاملة بالصورة التي حددها القانون غرامة تعادل مثلا مقدار الرسم المقرر وبحد أدنى مقداره دينار واحد.","تفرض غرامة على المكلف بدفع الرسم المقرر إذا تأخر عن دفعه في الموعد المحدد بواقع مثل الرسم المستحق أو مقدار النقص فيه اذا كان التأخير لمدة تزيد على ثلاثين يوماً ولا تتجاوز ستين يوماً وبحد أدنى مقداره دينار واحد.","إذا تداخلت أكثر من معاملة خاضعة للرسم في معاملة واحدة فيستوفى عن كل منها الرسم المقرر باعتبارها معاملة مستقلة."],"answer":1,"orig_answer":1,"law":"stamp","article":"12","status":"valid","explanation":"المادة (12/ب/2): غرامة الموظف الذي لم يبطل الطوابع تعادل «مثل» الرسم لا مثليه."},{"num":49,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة بموجب قانون ديوان المحاسبة رقم 28 لسنة 1952 وتعديلاته:","o":["على أي جهة من الجهات الخاضعة لرقابة ديوان المحاسبة الاجابة على اي استيضاح يوجهه اليها الديوان ضمن نطاق مهامه وذلك خلال مدة لا تتجاوز ستين يوما اعتبارا من تاريخ وصوله إلى تلك الجهة.","يتولى ديوان المحاسبة التدقيق اللاحق على النفقات إلا أنه يجوز لرئيس ديوان المحاسبة في حالات خاصة أن يقرر التدقيق في النفقات قبل الصرف.","إذا وقع خلاف بالرأي بين الديوان وإحدى الوزارات او الدوائر يعرض موضوع الخلاف على مجلس الوزراء للفصل فيه.","على وزارة المالية أن تقدم لديوان المحاسبة الحساب الختامي عن كل سنة مالية خلال مدة لا تزيد على ستة أشهر من تاريخ انتهاء تلك السنة."],"answer":0,"orig_answer":0,"law":"audit","article":"16","status":"valid","explanation":"المادة (16): المدة 30 يوماً للجهة داخل المملكة و60 يوماً خارجها (ويلاحظ أن المادة 25 تشترط موافقة رئيس الوزراء للتدقيق قبل الصرف)."},{"num":50,"type":"mcq","q":"أي من العبارات تعتبر غير صحيحة وفقا لقانون المنافسة لسنة 2004 وتعديلاته:","o":["تشكل لجنة شؤون المنافسة برئاسة وزير الصناعة والتجارة والتموين تجتمع بدعوة من رئيسها أو نائبه عند غيابه مرة واحدة شهرياً ويكون اجتماعها قانونياً بحضور ما لا يقل عن ثلثي أعضائها على أن يكون من بينهم الرئيس أو نائبه.","يختص للنظر في قضايا الممارسات المخلة بالمنافسة ضمن محكمة البداية قاض أو أكثر من ذوي الاختصاص ممن تلقوا تدريباً خاصا على ان يتم تعيينهم بقرار من المجلس القضائي.","يحظر على أي مؤسسة لها وضع مهيمن في السوق إذا تجاوزت حصتها السوقية (40%) أو جزء هام منه إساءة استغلال هذا الوضع التمييز بين العملاء في العقود المتشابهة بالنسبة لأسعار السلع والخدمات أو شروط بيعها وشرائها.","تحدد أسعار السلع والخدمات وفقا لقواعد السوق ومبادئ المنافسة الحرة باستثناء أسعار الخدمات التي يتم تحديدها وفقا لأحكام قانون الصناعة والتجارة والتموين أو أي قانون اخر."],"answer":0,"orig_answer":0,"law":"competition","article":"15","status":"valid","explanation":"المادة (15/أ): تجتمع اللجنة مرة كل ستة أشهر على الأقل لا شهرياً."},{"num":51,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون مكافحة غسل الأموال وتمويل الارهاب رقم (20) لسنة 2021:","o":["تمارس النيابة العامة أو المحكمة المختصة اختصاصاتها في الجرائم المنصوص عليها في هذا القانون وفق أصول المحاكمات الجزائية ولها حجز ممتلكات اختلطت فيها المتحصلات مع أموال من مصادر مشروعة إلى أن تحدد قيمة المتحصلات غير المشروعة ونواتج استغلالها.","يعد مرتكبا لجريمة الارهاب كل شخص يقوم بتمويل سفر الاشخاص إلى دول غير دول إقاماتهم لغايات التخطيط لارتكاب الأعمال الارهابية حتى لو لم يقع العمل الارهابي.","لغايات هذا القانون تشمل متحصلات الجريمة أي متحصلات ناجمة عن أي فعل يعتبر جريمة بمقتضى اتفاقيات دولية.","تنتفي المسؤولية الجزائية عن كل شخص طبيعي أو معنوي عند قيامه بحسن نية بواجب الاخطار عن أي من العمليات التي يشتبه بأنها مرتبطة بجريمة غسل الأموال أو بتمويل الارهاب."],"answer":2,"orig_answer":2,"law":"aml","article":"3","status":"valid","explanation":"المادة (3/ج/2): يشترط أن تكون الاتفاقية مصادقاً عليها من المملكة وأن يكون الفعل معاقباً عليه في القانون الأردني."},{"num":52,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون النزاهة ومكافحة الفساد رقم (13) لسنة 2016:","o":["على الرغم مما ورد في أي تشريع آخر تلتزم الهيئة بإصدار قراراتها في موعد لا يتجاوز ثلاثة أشهر من تاريخ بدء اجراءات التحقيق والتحري في الشكوى وللمجلس إذا اقتضت الضرورة تمديد ذلك الموعد لمدة اضافية مماثلة.","لمجلس الوزراء بناء على تنسيب مجلس الهيئة إنهاء خدمة أي عضو من أعضائه خلال مدة المجلس إذا تغيب عن اجتماعات المجلس ثلاث جلسات متتالية أو ست جلسات متفرقة خلال السنة الواحدة دون عذر يقبله المجلس.","لمرتكب أي من جرائم الفساد المنصوص عليها في هذا القانون التقدم بطلب للهيئة لإجراء مصالحة معه إذا أعاد كليا الأموال والمنافع المرتبطة بها التي حصل عليها نتيجة ارتكاب جريمة فساد أو أجرى تسوية عليها.","تمارس الهيئة مهامها وأعمالها بحرية واستقلال دون تأثير أو تدخل من أي جهة فلا يجوز تفتيش مقر هيئة النزاهة ومكافحة الفساد إلا بأمر قضائي وبحضور المدعي العام المختص على أن يتم تبليغ رئيس المجلس بذلك ودعوة من يمثل الهيئة لحضور التفتيش"],"answer":0,"orig_answer":0,"law":"integrity","article":"21","status":"valid","explanation":"المادة (21): المدة ستة أشهر لا ثلاثة."},{"num":53,"type":"mcq","q":"الجهة الوحيدة المخول لها تسجيل ملكية الأوراق المالية هي:","o":["دائرة مراقبة الشركات.","مركز إيداع الأوراق المالية.","بورصة عمان.","هيئة الأوراق المالية."],"answer":1,"orig_answer":1,"law":"securities","article":"75","status":"valid","explanation":"المادة (75/ب): المركز الجهة الوحيدة المصرح لها بتسجيل الأوراق المالية وحفظ ونقل ملكيتها."},{"num":54,"type":"mcq","q":"يتم تأسيس صناديق الاستثمار المشترك من قبل:","o":["شركة الاستثمار المشترك.","أمين الاستثمار.","مدير الاستثمار.","مدير الإصدار."],"answer":2,"orig_answer":2,"law":"securities","article":"92","status":"valid","explanation":"المادة (92/أ): تنشأ الصناديق من قبل الشركات المرخصة لممارسة أعمال إدارة الاستثمار (مدير الاستثمار)."},{"num":55,"type":"mcq","q":"على المصدر تزويد الهيئة بالتقرير السنوي خلال:","o":["90 يوم من نهاية السنة المالية.","60 يوم من نهاية السنة المالية.","30 يوم من نهاية السنة المالية.","45 يوم من نهاية السنة المالية."],"answer":0,"orig_answer":0,"law":"securities","article":"43","status":"valid","explanation":"المادة (43/أ/1): تقرير سنوي خلال تسعين يوماً من انتهاء السنة المالية."},{"num":56,"type":"mcq","q":"يكون الحق بالأسهم المجانية:","o":["بتاريخ قرار وزير الصناعة والتجارة بالموافقة على قرار الهيئة العامة المتعلق بزيادة رأس المال عن طريق الأسهم المجانية.","بتاريخ قرار مجلس مفوضي الهيئة بالموافقة على تسجيل الأسهم.","بتاريخ اجتماع الهيئة العامة التي تقرر فيه زيادة رأس المال عن طريق توزيع الأسهم المجانية.","للمساهمين كما هم بنهاية اليوم الخامس عشر من تاريخ موافقة مجلس مفوضي الهيئة على تسجيل الأسهم."],"answer":2,"orig_answer":2,"law":"securities","article":"","status":"unverified","explanation":"لا نص صريح في قانون الأوراق المالية؛ الكتاب يقيس على المادة (191/ب) من قانون الشركات (الحق بالربح لمالك السهم بتاريخ اجتماع الهيئة العامة) فاختار (ج)."},{"num":57,"type":"mcq","q":"يتطلب إعداد نشرة إصدار لعرض الأوراق المالية إذا كان عرض الأوراق المالية موجه لـ:","o":["لجميع مساهمي الشركة.","أكثر من (30) شخص.","(200) شخص فأكثر.","(100) شخص فأكثر."],"answer":1,"orig_answer":1,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): العرض العام عرض لبيع ورقة مالية لأكثر من ثلاثين شخصاً من الجمهور ويتطلب نشرة إصدار."},{"num":58,"type":"mcq","q":"على الشركة المصدرة إعلام الهيئة عند توافر أي معلومة جوهرية:","o":["خلال (10) أيام عمل من تاريخ حدوثها.","خلال أسبوع من تاريخ حدوثها.","قبل تداول يوم العمل التالي لتاريخ حدوثها.","خلال (3) أيام عمل من تاريخ حدوثها."],"answer":1,"orig_answer":1,"law":"securities","article":"43","status":"unverified","explanation":"تعليمات إفصاح الشركات المصدرة (المادة 9/أ): تقرير مفصل خلال أسبوع؛ والقانون (43/د) يوجب بياناً علنياً فور العلم وتزويد الهيئة به."},{"num":59,"type":"mcq","q":"يقصد بعرض التملك العام:","o":["العرض المقدم من المؤسسات الرسمية العامة لتملك جميع أسهم مساهمي الشركة.","عرض تملك جميع أسهم مساهمي الشركة.","عرض تملك أو مبادلة (40%) فأكثر من الأوراق المالية للمصدر.","عرض الأوراق المالية للجمهور عن طريق العرض العام."],"answer":2,"orig_answer":2,"law":"securities","article":"2","status":"valid","explanation":"المادة (2) و(45/أ): عرض التملك العام عرض لشراء 40% أو أكثر من الأوراق المالية لمصدر واحد أو حيازتها بالمبادلة."},{"num":60,"type":"mcq","q":"يقرر المرجع الطبي حاجة المصاب مجددا للعلاج واستحقاقه للبدل اليومي إذا حصلت الانتكاسة و/أو مضاعفات خلال:","o":["سنتان من تاريخ وقوع الاصابة.","سنة من تاريخ استقرار الحالة.","ستة أشهر من تاريخ استقرار الحالة.","لا شيء مما ذكر."],"answer":1,"orig_answer":1,"law":"social","article":"28","status":"valid","explanation":"المادة (28/ج): خلال سنة من تاريخ استقرار حالته."},{"num":61,"type":"mcq","q":"من شروط انتفاع المؤمن عليها من تأمين الأمومة أن تكون مشمولة بأحكام هذا التأمين خلال:","o":["اثني عشر شهرا تسبق استحقاقها لإجازة الأمومة.","الستة أشهر الأخيرة التي تسبق استحقاقها لإجازة الأمومة.","ستة أشهر متصلة أو متقطعة في تأمين الأمومة في الاثني عشر شهرا التي تسبق استحقاقها لإجازة الأمومة.","ب + ج"],"answer":3,"orig_answer":3,"law":"social","article":"44","status":"unverified","explanation":"الكتاب يعتمد تعديل 2023 للمادة (44/أ): الأشهر الستة الأخيرة أو ستة اشتراكات متصلة أو متقطعة خلال 12 شهراً؛ أما النص الأساسي المتوفر (معدل 2019) فيقتصر على الأشهر الستة الأخيرة (ب)."},{"num":62,"type":"mcq","q":"يجوز للمؤمن عليه أن يتقدم بطلب لفحصه وهو على رأس عمله لبيان ما إذا كان ينطبق عليه مفهوم العجز الكلي الطبيعي الدائم إذا كان لديه:","o":["60 اشتراكا منها 24 اشتراكا متصلاً","60 اشتراكا","اشتراكا منها 12 اشتراكاً متصلاً.","لا شيء مما ذكر."],"answer":3,"orig_answer":3,"law":"social","article":"67","status":"valid","explanation":"المادة (67/ز): إذا «زاد» عدد اشتراكاته على 60 منها 24 متصلاً، فـ(أ) غير دقيقة."},{"num":63,"type":"mcq","q":"يتم ربط راتب التقاعد وراتب الاعتلال بـ:","o":["معدل النمو السنوي أو التضخم أيهما أقل.","معدل النمو السنوي والتضخم معا.","التضخم","معدل النمو السنوي فقط"],"answer":0,"orig_answer":0,"law":"social","article":"90","status":"valid","explanation":"المادة (90/ب): بالتضخم أو بمعدل النمو السنوي لمتوسط الأجور أيهما أقل وبحد أعلى 20 ديناراً."},{"num":64,"type":"mcq","q":"إذا تأخرت المنشأة عن تزويد المؤسسة بالبيانات بأسماء العاملين لديها الذين انتهت خدماتهم لديها تلتزم بدفع غرامة قدرها:","o":["5% من الاشتراكات المستحقة.","9% من الاشتراكات المستحقة.","30% من الاشتراكات المستحقة.","1% من الاشتراكات المستحقة."],"answer":3,"orig_answer":3,"law":"social","article":"22","status":"valid","explanation":"المادة (22/ب): غرامة 1% من الاشتراكات المستحقة عن كل شهر تأخير في تزويد البيانات الواردة في المادة (21/أ)."},{"num":65,"type":"mcq","q":"إذا نشأ عن إصابة العمل عجز جزئي دائم بنسبة لا تقل عن 30% فيستحق المصاب:","o":["تعويض دفعة واحدة أو راتب اعتلال حسب طلب المصاب","تعويض الدفعة الواحدة.","راتب اعتلال شهري","لا شيء مما ذكر"],"answer":2,"orig_answer":2,"law":"social","article":"30","status":"valid","explanation":"المادة (30): عجز جزئي إصابي دائم لا يقل عن 30% يستحق عنه راتب اعتلال شهري، وأقل من 30% تعويض دفعة واحدة."},{"num":66,"type":"mcq","q":"في حال ترك صاحب راتب التقاعد المبكر العمل تضاف مدة اشتراكه السابقة إلى اللاحقة","o":["لا تضاف المدة ابدا ويصرف عنها تعويض الدفعة الواحدة","بعد تركه للعمل مباشرة.","عند اكماله سن الستين للذكر أو الخامسة والخمسين للأنثى","أ + ب"],"answer":2,"orig_answer":2,"law":"social","article":"85","status":"valid","explanation":"المادة (85): لا تضاف مدة اشتراكه اللاحقة إلى السابقة إلا عند إكماله سن الستين للذكر أو 55 للأنثى أو الوفاة."},{"num":67,"type":"mcq","q":"يتولى إدارة شؤون البنك المركزي الأردني العامة:","o":["مجلس إدارة مكون من محافظ ونواب اثنين وخمسة اعضاء","مجلس إدارة مكون من محافظ ونواب اثنين وسبعة أعضاء","مجلس إدارة مكون من محافظ ونواب اثنين وستة أعضاء","لا شيء مما ذكر"],"answer":2,"orig_answer":2,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"10","status":"unverified","explanation":"المادة (10/أ) من قانون البنك المركزي: المحافظ رئيساً ونائبان وستة أعضاء."},{"num":68,"type":"mcq","q":"تعتبر الموافقة على ترخيص المؤسسات المالية وسحب ترخيصها من صلاحيات:","o":["مجلس الوزراء بناء على تنسيب مجلس إدارة البنك المركزي.","جمعية البنوك الأردنية.","مجلس إدارة البنك المركزي الأردني","محافظ البنك المركزي"],"answer":2,"orig_answer":2,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"12","status":"unverified","explanation":"المادة (12) من قانون البنك المركزي: من صلاحيات مجلس إدارة البنك المركزي."},{"num":69,"type":"mcq","q":"ينطبق تعريف الأوراق المالية الحكومية الوارد في قانون البنك المركزي الأردني رقم (23) لسنة 1971 وتعديلاته على كل مما يلي باستثناء:","o":["الأوراق المالية المكفولة من الحكومة.","الأوراق المالية المصدرة من شركات الخدمات المالية.","الأوراق المالية المصدرة من المؤسسات الرسمية العامة.","الأوراق المالية المصدرة من الحكومة."],"answer":1,"orig_answer":1,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"2","status":"unverified","explanation":"تعريف الأوراق المالية الحكومية: المصدرة من الحكومة أو المؤسسات الرسمية العامة أو الحكومية العامة أو المكفولة من الحكومة."},{"num":70,"type":"mcq","q":"الدائرة المسؤولة عن ضبط النقد والأدوات القابلة للتداول لحاملها التي يتم الاشتباه بارتباطها بغسل الأموال أو أي من الجرائم الأصلية المرتبطة بها أو تمويل الإرهاب هي:","o":["دائرة الجمارك","وحدة مكافحة غسل الأموال وتمويل الإرهاب","دائرة التنفيذ القضائي","دائرة المخابرات العامة"],"answer":0,"orig_answer":0,"law":"aml","article":"24","status":"valid","explanation":"المادة (24/أ): على دائرة الجمارك ضبط النقد والأدوات القابلة للتداول لحاملها عند الاشتباه."},{"num":71,"type":"essay","q":"السؤال الأول (علامة واحدة): البيانات التالية تخص شركة تجارية للعام 2019: قرض ممنوح من طرف ذو علاقة بقيمة 120.000 دينار، بلغ رأسمال الشركة 10.000 دينار، بلغ متوسط حقوق الملكية 20000 دينار، بلغت الفوائد المطالب بها من قبل الشركة بواقع 15.000 دينار. المطلوب: احتساب قيمة الفوائد المقبولة ضريبياً.","law":"income","article":"6","status":"valid","model_answer":"- المادة (6/ب/2): فوائد الأطراف ذوي العلاقة تقبل بنسبة 3:1 للدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر.\n- الدين المسموح = 3 × 20,000 = 60,000.\n- الفوائد المقبولة = 15,000 × 60,000 ÷ 120,000 = 7,500 دينار، والباقي 7,500 لا ينزل ولا يدور."},{"num":72,"type":"essay","q":"السؤال الثاني (علامة واحدة): قام شخص بإستيراد سيارة بلغت قيمتها 10.000 دينار وقيمتها التخمينية 12000 دينار وضريبة خاصة 2500 دينار وجمارك بنسبة 30% ورسوم ترخيص 250 دينار. المطلوب: احتساب قيمة ضريبة المبيعات.","law":"sales","article":"","status":"unverified","model_answer":"- (الحل التفصيلي على منصة المؤلف) على افتراض اعتماد القيمة التخمينية أساساً للقيمة الجمركية:\n- الرسوم الجمركية = 12,000 × 30% = 3,600.\n- وعاء الضريبة العامة = القيمة 12,000 + الجمارك 3,600 + الضريبة الخاصة 2,500 = 18,100 (رسوم الترخيص لا تدخل في الوعاء).\n- ضريبة المبيعات = 18,100 × 16% = 2,896 دينار تستحق عند التخليص (المادة 9/د)."},{"num":73,"type":"essay","q":"السؤال الثالث (ثلاث علامات): البيانات التالية مستخرجة من سجلات الشركة الاردنية للاعلاف والدواجن عن الفترة 5+6/2022 تحليل مبيعات الشركة خلال الفترة الضريبية: بيض المائدة نسبة الضريبة 1% قيمة المبيعات 1.000.000 دينار؛ صوص لاحم صفر 3.000.000؛ اعلاف 5% 1.500.000؛ ادوية بيطرية 16% 800.000؛ مبيعات اعلاف الى جهات معفاة صفر 600.000. إذا علمت أن إستيراد الشركة مؤجل توريد ضريبة المبيعات على الاستيراد حيث بلغ إجمالي المستوردات خلال الفترة الضريبية 20.000.000 دينار اردني وأن هامش الربح للأعلاف 10% وبلغت إجمالي ضريبة المصاريف المشتركة 100.000 دينار، ولا يوجد مشتريات محلية خلال الفترة الضريبية. المطلوب: احتساب قيمة ضريبة المبيعات واجبة الدفع خلال الفترة الضريبية 5+6/2022.","law":"sales","article":"19","status":"unverified","model_answer":"- (الحل التفصيلي على منصة المؤلف) ضريبة المخرجات: بيض 1,000,000×1% = 10,000؛ أعلاف 1,500,000×5% = 75,000؛ أدوية بيطرية 800,000×16% = 128,000؛ الصوص والمبيعات للجهات المعفاة بنسبة الصفر؛ المجموع 213,000.\n- الضريبة المؤجلة على المستوردات تستحق عند بيع السلع أو مخرجاتها (المادة 26/د وتعليمات التأجير م14)، وتستحق على مبيعات الأعلاف المعفاة على أساس ضريبة استيرادها: كلفة المبيعات المعفاة = 600,000 ÷ 1.10 = 545,455 تقريباً.\n- تخصم ضريبة المصاريف المشتركة 100,000 بنسبة المبيعات الخاضعة (بما فيها الصفرية) إلى إجمالي المبيعات وفق المادة (19).\n- الرصيد الواجب الدفع = ضريبة المخرجات + الضريبة المؤجلة المستحقة − الضريبة القابلة للخصم."},{"num":74,"type":"essay","q":"السؤال الرابع (علامتان): أردني اعزب يعمل موظف لدى بنك الكويت الوطني في الكويت بلغت رواتبه من البنك خلال 12 شهر لعام 36.000 دينار، يتقاضى راتب تقاعدي من الضمان الاجتماعي بواقع 3.500 دينار، قدم خدمات استشارات لشركة في الأردن بقيمة 10.000 دينار وقامت الشركة باقتطاع مبلغ 1.000 دينار تحت حساب الضريبة وتحويل مبلغ 9,000 دينار له بموجب حوالة بنكية. يملك عقار في الاردن مؤجر بقيمة 50.000 دينار بلغت مصاريف الصيانة للعقار المقبولة 10.000 دينار بلغت قيمة مصاريف المجاري المدفوعة 1.920 دينار والمسقفات المدفوعة 9.600 دينار. المطلوب: إحتساب قيمة الضريبة المستحقة.","law":"income","article":"3","status":"unverified","model_answer":"- (الحل التفصيلي على منصة المؤلف) الراتب من الكويت لا يخضع لأنه مصدر خارجي لم ينشأ عن أموال أو ودائع من المملكة (المادة 3/ج).\n- الراتب التقاعدي 3,500 سنوياً معفى (أول 2,500 دينار شهرياً معفاة - المادة 4).\n- دخل الاستشارات 10,000 يخضع، والمقتطع 1,000 يخصم من الضريبة (المادة 12).\n- صافي الإيجار (على افتراض قبول المجاري والمسقفات) = 50,000 − 10,000 − 1,920 − 9,600 = 28,480.\n- مجموع الدخل 38,480 − إعفاء شخصي 9,000 = 29,480 (المادة 9).\n- الضريبة = 250+500+750+1,000 + 9,480×25% = 4,870 (المادة 11/أ)؛ ينزل المقتطع 1,000 فالرصيد 3,870 دينار."},{"num":75,"type":"essay","q":"السؤال الخامس (علامتان): استوردت شركة القمر ذ.م.م خدمة من الخارج بتاريخ 1/3/2022 بموجب فاتورة بذلك التاريخ بلغت قيمة الخدمة الموردة للشركة بما يعادل 10.000 دينار، بتاريخ 1/6/2022 قامت شركة القمر بتحويل مبلغ 5.000 دينار للشركة الموردة للخدمة بموجب حوالة بنكية، بتاريخ 1/7/2022 قامت الشركة بتحويل مبلغ 5.000 دينار الرصيد المستحق عن الخدمة المستوردة. بتاريخ 1/12/2022 قامت الشركة بدفع ضريبة المبيعات عن الخدمة المستوردة البالغة 1,600 دينار. المطلوب: إحتساب الغرامات المستحقة عند دفع الضريبة.","law":"sales","article":"26","status":"valid","model_answer":"- المادة (26/ج): تستحق الضريبة خلال شهر من دفع كل جزء أو ستة أشهر من تلقي الخدمة أيهما أسبق: الجزء الأول 800 يستحق 1/7/2022، والجزء الثاني 800 يستحق 1/8/2022.\n- غرامة التأخير (المادة 51) 4 بالألف أسبوعياً: 800×0.004×22 أسبوعاً = 70.4 + 800×0.004×18 أسبوعاً = 57.6، المجموع 128 دينار.\n- التأخير تجاوز ثلاثة أشهر من تاريخ الاستحقاق للجزأين فيعد تهرباً (المادة 30/ل): تعويض مدني من مثلي إلى ثلاثة أمثال الضريبة (3,200-4,800) وغرامة جزائية 200-1,000 دينار (المادة 31)، ويجوز الصلح بمثل الضريبة (المادة 32)."},{"num":76,"type":"essay","q":"السؤال السادس (علامة ونصف): اذكر القرارات الواجب اتخاذها في الاجتماع التأسيسي للشركة المساهمة الخاصة؟","law":"companies","article":"71 مكرر","status":"valid","model_answer":"- المادة (71 مكرر): يعقد اجتماع هيئة عامة عادي تأسيسي خلال شهر من صدور شهادة التسجيل ويتم فيه:\n- انتخاب مجلس الإدارة الأول.\n- اتخاذ القرار المناسب بشأن مصاريف التأسيس وأي التزامات تمت من المؤسسين قبل التأسيس.\n- انتخاب مدقق حسابات وتحديد أتعابه أو تفويض مجلس الإدارة بتحديدها."},{"num":77,"type":"essay","q":"السؤال السابع (علامة ونصف): تنظم الأمور المالية والمحاسبية والإدارية للشركة المساهمة العامة بموجب أنظمة داخلية خاصة يعدها مجلس إدارة الشركة، بين ما هي الأمور الواجب تحديدها بصورة مفصلة في هذه الأنظمة؟","law":"companies","article":"151","status":"valid","model_answer":"- المادة (151/ب): يحدد فيها بصورة مفصلة واجبات المجلس وصلاحياته ومسؤولياته.\n- وعلاقته بالإدارة التنفيذية.\n- واللجان الواجب تأليفها، بما يتماشى ودليل قواعد الحوكمة.\n- تحتفظ الشركة بنسخة منها وتزود المراقب بها عند طلبه (151/ج)."},{"num":78,"type":"essay","q":"السؤال الثامن (علامة واحدة): بين ما يحظر ولا يجوز لمدقق الحسابات القيام به تجاه الشركات المساهمة العامة.","law":"companies","article":"197","status":"valid","model_answer":"- المادة (197): لا يجوز له الاشتراك في تأسيس الشركة التي يدقق حساباتها.\n- أو عضوية مجلس إدارتها.\n- أو الاشتغال بصفة دائمة في أي عمل فني أو إداري أو استشاري فيها.\n- أو أن يكون شريكاً لأي عضو في مجلس إدارتها أو موظفاً لديه، تحت طائلة البطلان.\n- ويحظر عليه وعلى موظفيه المضاربة بأسهم الشركة التي يدقق حساباتها تحت طائلة العزل والتعويض."},{"num":79,"type":"essay","q":"السؤال التاسع (علامة واحدة): اذكر ما يترتب على الشخص المفوض بإدارة شركة التضامن أن يقدم للشركاء فيها خلال مدة لا تزيد عن ثلاثة أشهر من انتهاء عمله في إدارة الشركة.","law":"companies","article":"19","status":"valid","model_answer":"- المادة (19/أ) سواء طلبوا أم لم يطلبوا:\n- حساباً عن كل منفعة نقدية أو عينية أو حقوق حصل عليها من أي عمل يتعلق بالشركة واحتفظ بها لنفسه (ومنها استغلال اسم الشركة أو علاماتها أو شهرتها) مع ردها وضمان الضرر.\n- حساباً عن أي أموال أو موجودات للشركة وضعها تحت حيازته أو استغلها لمنفعته وإعادتها وضمان ما لحق بها من تلف وخسارة وتعويض الشركة."},{"num":80,"type":"essay","q":"السؤال العاشر (علامة واحدة): إذا تقدم أكثر من شريك في الشركة ذات المسؤولية المحدودة لشراء الحصة أو الحصص المراد التنازل عنها بالسعر المعروض وفي حالة الاختلاف على السعر بين الإجراء القانوني الذي يقوم به مراقب عام الشركات.","law":"companies","article":"73","status":"valid","model_answer":"- المادة (73/ب): إذا تقدم أكثر من شريك تقسم الحصص بين الراغبين كل بنسبة حصته في رأس المال.\n- عند الاختلاف على السعر يعين المراقب مدقق حسابات قانونياً على نفقة البائع والمشتري لتحديد السعر ويعتبر تقديره نهائياً."},{"num":81,"type":"essay","q":"السؤال الحادي عشر (علامة واحدة): حسب المادة (290) من احكام قانون التجارة رقم 12 لسنة 1966 يحق لكل تاجر قبل توقفه عن الوفاء او خلال الايام العشرة التي تلي هذا التوقف ان يتقدم الى المحكمة البدائية في المنطقة التي يكون فيها مركزه الرئيسي ويطلب اليها ان تدعو دائنيه ليعرض عليهم صلحاً واقياً من الافلاس على ان يقدم ويوضح عدة أمور اذكر اثنين منها:","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"290","status":"obsolete","model_answer":"- أحكام الصلح الواقي والإفلاس في قانون التجارة أُلغيت بصدور قانون الإعسار رقم (21) لسنة 2018 (حسب الكتاب: «ملغي»)، ولا يطلب حالياً."},{"num":82,"type":"essay","q":"السؤال الثاني عشر (علامتان): حسب المادة (386) من احكام قانون التجارة رقم 12 لسنة 1966 لا يجوز للدائنين الحاضرين في إجتماع هيئة المصالحة ان يقبلوا عقد الصلح بعد التفليسة ما لم تتوفر شرطين اذكرهما:","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"386","status":"obsolete","model_answer":"- أحكام الصلح بعد التفليسة أُلغيت وحل محلها قانون الإعسار رقم (21) لسنة 2018 (حسب الكتاب: «ملغي»)."},{"num":83,"type":"essay","q":"السؤال الثالث عشر (علامتان): تتولى الهيئة العليا لتنظيم مهنة المحاسبة القانونية المهام والصلاحيات المنصوص عليها بالمادة 5 من القانون أذكر اربعاً منها:","law":"accounting","article":"5","status":"valid","model_answer":"- المادة (5): اعتماد معايير المحاسبة والتدقيق بتنسيب المجلس.\n- تشكيل لجنة ترخيص المهنة ووضع تعليماتها وكيفية إجراء الامتحانات.\n- المصادقة على منح إجازة المزاولة بتنسيب لجنة الترخيص وإلغائها بتنسيب المجلس.\n- النظر في الاعتراضات على قرارات المجلس.\n- تشكيل اللجان، إصدار التعليمات، إعداد مشروعات التشريعات، اعتماد المعاهد المهنية."},{"num":84,"type":"essay","q":"السؤال الرابع عشر (علامة): متى يتولى وكيل الاعسار إدارة أعمال الاعسار؟","law":"insolvency","article":"17","status":"valid","model_answer":"- المادة (17/ب): إذا كان طلب الإشهار مقدماً من الدائنين أو المراقب تعلق صلاحيات المدين ويمارسها وكيل الإعسار في حدود تسيير الأعمال المعتادة.\n- (17/أ): إذا قدم الطلب من المدين يحتفظ بإدارة أعماله المعتادة تحت إشراف الوكيل.\n- (17/ج): للدائنين وللوكيل طلب وقف صلاحية المدين لأسباب مبررة."},{"num":85,"type":"essay","q":"السؤال الخامس عشر (علامة): لأي رقابة يخضع وكيل الاعسار؟","law":"insolvency","article":"52","status":"valid","model_answer":"- المادة (52/أ): يخضع لإشراف المحكمة ورقابة الدائنين أو من يمثلهم.\n- (52/ب): للمحكمة وللجنة الدائنين تكليفه بتقديم معلومات أو تقرير عن سير الإجراءات وإدارة ذمة الإعسار."},{"num":86,"type":"essay","q":"السؤال السادس عشر (علامة): يحق للمؤمن له او المستفيد من عقد التأمين الانتفاع من شرط الاختراق ولا يجوز لأي جهة الاعتراض على تفعيله فما هو شرط الاختراق؟","law":"insurance","article":"71","status":"valid","model_answer":"- المادة (71/ب): الشرط الوارد في عقد إعادة التأمين الذي يقضي بمسؤولية معيد التأمين في حدود حصته من الخسارة المعاد تأمينها تجاه المؤمن له والمستفيد عند تعذر وفاء المؤمن بالتزاماته (كتصفية شركة التأمين) فتنشأ علاقة مباشرة بينهم."},{"num":87,"type":"essay","q":"السؤال السابع عشر (علامة): حسب المادة (18) من قانون التأجير التمويلي يحق للمستأجر في حالة تصفية المؤجر خيارين اذكرهما:","law":"leasing","article":"18","status":"valid","model_answer":"- المادة (18/أ): الاستمرار في تنفيذ عقد التأجير طبقاً لشروطه وأحكامه.\n- أو تسليم المأجور للمصفي والدخول مع باقي الدائنين في تحصيل ما دفعه للمؤجر بعد خصم أجر المثل."},{"num":88,"type":"essay","q":"السؤال الثامن عشر (ثلاث علامات): ما هي الجهات التي تخضع لرقابة هيئة الأوراق المالية؟","law":"securities","article":"15","status":"valid","model_answer":"- المادة (15/أ): المصدرون.\n- المرخص لهم.\n- المعتمدون.\n- السوق المالي.\n- المركز (مركز الإيداع).\n- صناديق الاستثمار المشترك وشركات الاستثمار."},{"num":89,"type":"essay","q":"السؤال التاسع عشر (علامة واحدة): تحدث عن نسبة الاشتراكات الشهرية لمنشآت القطاع الخاص من حيث النسبة المقتطعة من المنشأة وعن المؤمن عليه؟","law":"social","article":"59","status":"valid","model_answer":"- إصابات العمل: 2% على المنشأة (المادة 24).\n- التعطل عن العمل: 0.5% منشأة و1% مؤمن عليه (المادة 48).\n- الأمومة: 0.75% منشأة (المادة 42).\n- الشيخوخة والعجز والوفاة: 11% منشأة و6.5% مؤمن عليه (المادة 59).\n- المجموع: 14.25% على المنشأة و7.5% على المؤمن عليه."},{"num":90,"type":"essay","q":"السؤال العشرون (علامتان): تحدث عن شروط الجمع بين راتب التقاعد المبكر والأجر من أي عمل مشمول بأحكام القانون؟","law":"social","article":"85","status":"valid","model_answer":"- المادة (85/د): أن يكون قد انقطع عن العمل مدة لا تقل عن 24 شهراً من استحقاق راتب التقاعد المبكر.\n- ألا يعود للعمل في المنشآت التي عمل بها خلال آخر 36 اشتراكاً قبل الاستحقاق.\n- ألا يعود من خصص له الراتب وفق المادة (64/ج) إلى العمل في مهنة خطرة.\n- أن يعود للشمول بالضمان عند عودته للعمل، ويجمع بالنسب الواردة في الجدول (7)."}]},{"id":"2022-12","year":2022,"month":12,"label":"دورة كانون الأول 2022","session":"كانون الأول","src":"c1054cc4.json","questions":[{"num":1,"type":"mcq","q":"موظف دخله السنوي من الرواتب للعام 2020 بواقع 21,400 دينار ولديه دخل سنوي من الايجارات بقيمة 12,000 دينار ومصاريف المجاري المدفوعة 300 دينار والمسقفات المدفوعة بقيمة 1,200 دينار وهو متزوج وزوجته تعمل براتب شهري قدره 1,000 دينار اذا علمت تم تقديم اقرار ضريبي مشترك، ولديهم 3 اولاد الاول يدرس في الجامعة قيمة القسط السنوي 2,000 دينار والثاني يدرس في مدرسة خاصة قسطها السنوي 1,500 دينار، إن الضريبة المستحقة:","o":["3,775 دينار.","2,575 دينار.","2,777 دينار.","لاشيء مما ذكر."],"answer":3,"orig_answer":null,"law":"income","article":"9","status":"valid","explanation":"المادة (9) والمادة (11): مجموع الدخل المشترك = رواتب 21,400 + راتب الزوجة 12,000 + صافي الإيجار (12,000 − 300 مجاري − 1,200 مسقفات = 10,500) = 43,900؛ الإعفاءات لسنة 2020: 9,000 شخصي + 9,000 معالين + 2,000 تعليم للولدين (1,000 لكل ولد) = 20,000؛ الخاضع 23,900 والضريبة 2,500 + (3,900×25%) = 3,475 دينار، فلا يطابق أياً من الخيارات (أ–ج)."},{"num":2,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فان العبارة التالية صحيحة لنسبة ضريبة والمساهمة الوطنية:","o":["شركات التاجير التمويلي تخضع لنسبة 24% و 4% مساهمة وطنية","شركات التامين تخضع لنسبة 24% ضريبة دخل و 4% مساهمة وطنية.","شركات الاتصالات تخضع لنسبة 24% و4% مساهمة وطنية.","جميع ماذكر غير صحيح."],"answer":0,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2) و(11/و): شركات التأجير التمويلي 24% ضريبة و4% مساهمة وطنية، أما التأمين والاتصالات فـ24% و2% مساهمة وطنية."},{"num":3,"type":"mcq","q":"شركة صناعة الكرتون المحدودة اعلنت في قائمة الدخل لسنة 2021 دخل صافي بقيمة 100000 دينار وعليه فان ضريبة الدخل المستحقة:","o":["19,000 دينار.","18,000 دينار.","17,000 دينار.","16,000 دينار."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/1) و(11/ج/1): نسبة الشخص الاعتباري 20% (20,000) تخفض للنشاط الصناعي لسنة 2021 بنسبة 15% فتصبح الضريبة 17,000 دينار (إضافة لمساهمة وطنية 1%)."},{"num":4,"type":"mcq","q":"شركة صناعة الادوية الاردنية في قائمة الدخل لسنة 2020 دخل صافي بقيمة 120000 دينار وعليه فان ضريبة الدخل المستحقة:","o":["24,000 دينار.","19,200 دينار.","18,000 دينار.","16,800 دينار."],"answer":3,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ج/2): صناعة الأدوية لسنة 2020 تخفض ضريبتها 30%: 120,000×20% = 24,000 × 70% = 16,800 دينار."},{"num":5,"type":"mcq","q":"أحد العبارات التالية ليست صحيحة، ضريبة الدخل على أرباح المتاجرة بالأسهم عن كل عملية هي:","o":["8 بالعشرة الاف من الشخص الطبيعي والشخص غير المقيم .","8 بالعشرة الاف من الشخص الطبيعي والشخص غير المقيم وشركات التضامن.","8 بالعشرة الاف من الشخص الطبيعي وشركات التضامن.","8 بالعشرة الاف من الشخص الطبيعي عدا الشركات."],"answer":null,"orig_answer":null,"law":"other:نظام الضريبة على أرباح المتاجرة بالأسهم","article":"","status":"unverified","explanation":"تحكمها أنظمة/تعليمات الضريبة على أرباح المتاجرة بالأسهم الصادرة بمقتضى قانون ضريبة الدخل وليست نصاً في القانون؛ لم يتم التحقق من النص."},{"num":6,"type":"mcq","q":"وفق تعليمات إحتساب حوافز ضريبية للقطاع الصناعي وفقاً لإحكام المادة 81 من قانون ضريبة الدخل حسب المعادلة التالية: (الدخل الصافي للنشاط الصناعي المستهدف ÷ مجموع الارباح الصافية للمكلف من جميع الانشطة والمصادر الاخرى) X الدخل الخاضع للضريبة للمكلف من جميع الانشطة. وتسري هذه المعادلة على:","o":["للإنشطة الصناعية صناعة الادوية والملابس وفقاً للجدول الملحق بالتعليمات.","إذا كان من الانشطة الصناعية المستفيدة فعلياً من نظام تخفيض ضريبة الدخل في المناطق الاقل نمواً رقم (44) لسنة 2016.","إذا كان النشاط الصناعي مؤسسة مسجلة في المناطق التنموية.","جميع ما ذكر خطأ."],"answer":null,"orig_answer":null,"law":"other:تعليمات احتساب الحوافز الضريبية للقطاع الصناعي","article":"81","status":"unverified","explanation":"المادة (81) تجيز منح حوافز ضريبية لقطاعات محددة بنظام؛ أما المعادلة فوردت في تعليمات احتساب الحوافز للقطاع الصناعي ولم يتم التحقق من نصها."},{"num":7,"type":"mcq","q":"وفقاً لقانون الضريبة العامة على المبيعات إحدى العبارات التالية صحيحة:","o":["تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع اصول المحاكمات المدنية.","تطبق محكمة الاستئناف الضريبية الاصول المنصوص عليها في قانون أصول المحاكمات الجزائية بالقدر الذي لا يتعارض فيه مع احكام قانون الضريبة العامة على المبيعات.","تطبق محكمة البداية الضريبيه قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","جميع ما ذكر خطأ."],"answer":1,"orig_answer":null,"law":"sales","article":"59","status":"valid","explanation":"المادة (59): تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية أصول المحاكمات الجزائية وكذلك أصول المحاكمات المدنية بالقدر الذي لا يتعارض مع أحكام القانون، فالخيار (ب) هو الصحيح."},{"num":8,"type":"mcq","q":"في حال إسقاط القضية بسبب الغياب لدى المحكمة فإن الجهات الملزمة بتبليغ الاسقاط هي:","o":["قرارات قضايا الدخل ( محكمة الضريبة) وقرارات المبيعات (دائرة الضريبة).","قرارات الإسقاط لقضايا الدخل والمبيعات ( دائرة ضريبة الدخل).","قرارات الإسقاط لقضايا الدخل والمبيعات (محكمة الضريبة).","كل ما ذكر غير صحيح."],"answer":0,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"في الدخل: المادة (46/ج) تبليغ المحكمة قرار الإسقاط للمكلف؛ وفي المبيعات: المادة (57/ط) من قانون الضريبة العامة على المبيعات تبليغ الدائرة للمكلف إشعاراً بقرار الإسقاط."},{"num":9,"type":"mcq","q":"البيانات التالية تخص شركة تجارية للعام 2019: قرض ممنوح من طرف ذو علاقة بقيمة 100,000 دينار، بلغ راسمال الشركة 10,000 دينار، بلغ متوسط حقوق الملكية 20,000 دينار، بلغت الفوائد المطالب بها من قبل الشركة بواقع 15,000 دينار. وعليه فأن قيمة الفوائد المقبوله ضريبياً بواقع:","o":["12,000 دينار.","3,750 دينار.","9,000 دينار.","3,000 دينار."],"answer":2,"orig_answer":null,"law":"income","article":"6","status":"valid","explanation":"المادة (6/ب/2): الفوائد لذوي العلاقة تقبل بنسبة 3:1 من رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر: 3×20,000 = 60,000 ÷ 100,000 × 15,000 = 9,000 دينار."},{"num":10,"type":"mcq","q":"تنفيذاً لاحكام قانون الضريبة العامة على المبيعات، يُعتمد لإغراض تحديد مسميات الخدمات:","o":["التصنيفات الصادره بموجب التصنيف المحلي للمهن الصادر بموجب احكام قانون الشركات وفق التشريعات النافذة.","التصنيفات الدولية الصادرة عن الامانة العامة للامم المتحدة.","جداول التعرفة وشروحاتها النافذة وفق لقرارات مجلس الوزراء.","جداول التعرفة وشروحاتها النافذة وفق أحكام قانون الجمارك."],"answer":1,"orig_answer":null,"law":"sales","article":"5","status":"valid","explanation":"المادة (5/أ): مسميات السلع وفق جداول التعرفة وقانون الجمارك، أما مسميات الخدمات فتعتمد التصنيفات الدولية الصادرة عن الأمانة العامة للأمم المتحدة."},{"num":11,"type":"mcq","q":"يترتب ضريبة خاصة مقدارها .......... دينار على كل تذكرة سفر بالجو إلى خارج المملكة وعلى كل مسافر ضمن الرحلات العادية أو غير المنتظمه أو الاضافية أو العارضة أو الخاصة والتي تتضمن مقطع مغادرة في اي من مطارات المملكة:","o":["40 دينار.","30 دينار.","20 دينار.","10 دنانير."],"answer":0,"orig_answer":null,"law":"sales","article":"","status":"unverified","explanation":"الضريبة الخاصة على تذاكر السفر جواً مقررة في جداول الضريبة الخاصة/قرارات مجلس الوزراء وليست في نص القانون المتوفر؛ الإجابة الشائعة 40 ديناراً ولم يتم التحقق منها."},{"num":12,"type":"mcq","q":"حسب المادة 46 من قانون ضريبة الدخل اذا تم اسقاط الدعوى بسبب الغياب أو لإي سبب آخر ولم يتم تجديدها يعتبر القرار المطعون فيه قطعياً بعد مرور:","o":["ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الاسقاط للمكلف أو وكيله وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرتين وبسبب مبرر.","ثلاثون يوماً من تاريخ إسقاط الدعوى وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرتين وبسبب مبرر.","ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الاسقاط للمكلف أو وكيله وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مرة وبسبب مبرر.","ثلاثون يوماً من تاريخ إسقاط الدعوى وفي جميع الاحوال لا يجوز تجديد الدعوى المسقطة للسبب نفسه لاكثر من مره وبسبب مبرر."],"answer":0,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"المادة (46/ج): ثلاثون يوماً من تاريخ تبليغ المحكمة قرار الإسقاط للمكلف أو وكيله، ولا يجوز التجديد للسبب نفسه لأكثر من مرتين وبسبب مبرر."},{"num":13,"type":"mcq","q":"حسب المادة 49 من قانون ضريبة الدخل يستوفى عن الدعوى رسم بنسبة:","o":["3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد على ثلاثماية دينار لكل فترة ضريبية عن جميع درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن ثلاثين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد على ثلاثماية دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد على مئتين دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي.","3% من الفرق بين مقدار الضريبة أو المطالبة والمقدار الذي يسلم به المدعي من تلك الضريبة او المطالبة على ان لايقل الرسم عن عشرين دينار بما في ذلك حالة عدم وجود ضريبة او مطالبة لوقوع المدعي في خسارة وان لاتزيد مئتين دينار لكل فترة ضريبية عن جميع درجات التقاضي."],"answer":1,"orig_answer":null,"law":"income","article":"49","status":"valid","explanation":"المادة (49/أ): 3% من الفرق بحد أدنى ثلاثين ديناراً وحد أعلى ثلاثمائة دينار لكل فترة ضريبية عن كل درجة من درجات التقاضي."},{"num":14,"type":"mcq","q":"حسب المادة 67 من قانون ضريبة الدخل يتحمل المحاسب القانوني المسؤولية عن المصادقة على بيانات مالية غير مطابقة للواقع بشكل جوهري أو تخالف أحكام هذا القانون أو معايير المحاسبة الدولية والقوانين والانظمة سواء كان ذلك ناجم عن خطأ متعمد او عمل جرمي او عن اهمال جسيم يعتبر المحاسب القانوني مرتكب لجرم ويعاقب:","o":["غرامة تعويضية لا تقل عن مثلي فرق الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئة دينار ولا تزيد عن خمسماية دينار.","غرامة تعويضية لا تقل عن مثلي فرق الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئة دينار ولا تزيد عن مئتي دينار.","غرامة تعويضية لا تقل عن مثلي فرق الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئتي دينار ولا تزيد عن خمسماية دينار.","بغرامة تعويضية تعادل مثل الفرق الضريبي."],"answer":3,"orig_answer":null,"law":"income","article":"67","status":"valid","explanation":"المادة (67/أ) تحيل إلى عقوبة المادة (66): غرامة تعويضية تعادل مثل الفرق الضريبي."},{"num":15,"type":"mcq","q":"أصدر المدقق قرار التدقيق الاولي وتم بموجبه فرض فرق ضريبي وغرامات مثلي وغرامات جزائية وغرامات المادة (28) وقام بإصدار اشعار مطالبة بالفرق الضريبي وتم الاعتراض على قرار التدقيق وصدر قرار هيئة الاعتراض برد الاعتراض وتم تبليغه للمكلف بموجب إشعار فإنه يحق للمكلف الاعتراض على الاشعار الصادر من هيئة الاعتراض لدى المحكمة على:","o":["غرامة المادة(28).","الغرامات الجزائية.","غرامة المثلي.","الفرق الضريبي."],"answer":3,"orig_answer":null,"law":"income","article":"42","status":"unverified","explanation":"المادة (42/أ) تجعل لمحكمة البداية الضريبية النظر في الطعن بقرار هيئة الاعتراض (الضريبة والغرامات المتعلقة بها)؛ لم يتم العثور على نص يحدد البند المقصود بدقة والإجابة المرجحة الفرق الضريبي."},{"num":16,"type":"mcq","q":"حسب قانون ضريبة الدخل رقم 38 لسنة 2018 وحسب المادة 72 فان العبارة التالية صحيحة:","o":["يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي و تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته او بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي ولا تكون اجراءات التصحيح خاضعة للطعن.","يجوز للمدير او الموظف المفوض منه او المدقق حسب مقتضى الحال وفي اي وقت ان يصحح من تلقاء ذاته او بناء على طلب المكلف الاخطاء الكتابية والحسابية التي تقع في القرارات والاشعارات عن طريق السهو العرضي وتكون اجراءات التصحيح خاضعة للطعن."],"answer":2,"orig_answer":null,"law":"income","article":"72","status":"valid","explanation":"المادة (72): التصحيح من تلقاء ذاته أو بناءً على طلب المكلف للأخطاء الكتابية والحسابية الناتجة عن السهو العرضي، ولا تكون إجراءات التصحيح خاضعة للطعن."},{"num":17,"type":"mcq","q":"قامت شركة بشراء اثاث بفواتير ضريبية بقيمة 5,000 دينار وضريبة مبيعات 800 دينار عند بداية عملها في 2022/1/1، بتاريخ 2022/4/1 قامت الشركة بالتسجيل في الشبكة العامة لضريبة المبيعات وارفقت كشوفات جرد المستودعات وجرد الموجودات الثابتة والضرائب المدفوعه، تستهلك الشركة موجوداتها الثابتة بنسبة 10% سنوياً، ان الضريبة واجبة التخصيم على الاصول:","o":["780 دينار.","720 دينار.","800 دينار.","لا يجوز تخصيم الضريبة على شراء الاصول كون تواريخ الشراء قبل التسجيل في ضريبة المبيعات."],"answer":0,"orig_answer":null,"law":"sales","article":"19","status":"valid","explanation":"المادة (19/د): يخصم المسجل الضريبة التي تحملها قبل التسجيل على السلع التي في حوزته عند التسجيل؛ وللأصول الثابتة تحتسب على صافي القيمة بعد الاستهلاك: 5,000 − (5,000×10%×3/12=125) = 4,875 × 16% = 780 ديناراً."},{"num":18,"type":"mcq","q":"قام شخص بإستيراد سيارة بلغت قيمتها 10,000 دينار وقيمتها التخمينية 12,000 دينار وضريبة خاصة 2,500 دينار وجمارك بنسبة 30% ورسوم ترخيص 250 دينار وعليه فان قيمة ضريبة المبيعات تكون:","o":["2,936 دينار.","2,080 دينار.","2,896 دينار.","2,176 دينار."],"answer":2,"orig_answer":null,"law":"sales","article":"15","status":"valid","explanation":"المادة (15/ج): الأساس هو القيمة الجمركية (12,000) + الرسوم الجمركية (3,600) + الضريبة الخاصة (2,500) = 18,100 × 16% = 2,896 ديناراً؛ ورسوم الترخيص لا تدخل لأنها ليست مستحقة قبل التخليص."},{"num":19,"type":"mcq","q":"قامت شركة بإستيراد خدمة بتاريخ 2022/1/1 وسجلت الخدمة بالمصاريف بتاريخ الفاتورة في 2022/1/1، قامت الشركة بدفع قيمة الفاتورة بتاريخ 2022/5/1، اذا علمت ان قيمة الخدمة 1,000 دينار وان الشركة قامت بدفع ضريبة المبيعات على الخدمة المستوردة بتاريخ 2022/6/12 فإن قيمة الضريبة والغرامات المستحقة هي:","o":["160 دينار+ 320 مثلي الضريبة +غرامة 12.60 دينار غرامة 4 بالالف +200- 1,000 دينار غرامة جزائية.","160 دينار+ غرامة 1.28 دينار غرامة 4 بالالف.","160 دينار+ غرامة 12.60 دينار غرامة 4 بالالف +100- 500 دينار غرامة جزائية.","160 دينار+ غرامة 1.28 دينار غرامة 4 بالالف +100- 500 دينار غرامة جزائية."],"answer":1,"orig_answer":null,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج): تدفع ضريبة الخدمة المستوردة خلال شهر من دفع بدلها (حتى 2022/6/1)؛ التأخير 11 يوماً = أسبوعان، وغرامة التأخير وفق المادة (51) 4 بالألف أسبوعياً: 160×0.004×2 = 1.28 دينار، ولا تهرب لأن التأخير أقل من ثلاثة أشهر (المادة 30/ل)."},{"num":20,"type":"mcq","q":"إبرمت شركة البحار عقد تأمين على مكتبها في عمان مع شركة التأمين العامة ولمدة سنة كاملة يبدأ العقد بتاريخ 2022/3/1 وينتهي بتاريخ 2023/2/28 حيث بلغت قيمة عقد التأمين 100 الف دينار، وقامت شركة التأمين بإعادة تأمين 75% من قيمة العقد لدى شركة ليدز البريطانية. وعليه قيمة مخصص الاقساط غير المكتسبة الواجب تنزيله في 2022/12/31 هو:","o":["16,164 دينار.","12,123 دينار.","4,041 دينار.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"income","article":"6","status":"valid","explanation":"المادة (6/د): مخصص الأقساط غير المكتسبة يحسب بعد خصم حصة معيد التأمين: 25% × 100,000 = 25,000 × 59 يوماً (كانون الثاني وشباط 2023) ÷ 365 = 4,041 ديناراً."},{"num":21,"type":"mcq","q":"حسب المادة 30 من قانون الضريبة العامة على المبيعات اي من العبارات التالية صحيحة ويعتبر من جرائم التهرب الضريبي:","o":["تطبيق نسب او فئات ضريبية على السلع او الخدمات الخاضعة للضريبة بصورة مخالفة لاحكام هذا القانون اذا ادى ذلك الى نقص في مقدار الضريبة المستحقة يتجاوز مئتين دينار .","التخلف عن تقديم طلب التسجيل لدى الدائرة في الموعد المحدد للتسجيل بموجب هذا القانون.","إستيفاء ضريبة غير مستحقة وتوريدها خلال المدة التي يحددها القانون لتوريد الضريبة.","جميع ما ذكر غير صحيح."],"answer":3,"orig_answer":null,"law":"sales","article":"30","status":"valid","explanation":"المادة (30): تطبيق نسب مخالفة يعد تهرباً إذا تجاوز النقص خمسمائة دينار لا مئتين، والتخلف عن التسجيل يعد تهرباً إذا زاد على ستين يوماً، واستيفاء ضريبة غير مستحقة لا يعد تهرباً إذا وردت خلال المدة؛ فجميعها غير صحيحة."},{"num":22,"type":"mcq","q":"تلتزم شركة التضامن بتعيين مدقق حسابات قانوني ينتخب بأكثرية الأعضاء إذا كان رأسمالها يبلغ:","o":["100,000 دينار أو أكثر.","75,000 دينار.","50,000 دينار.","10,000 دينار."],"answer":0,"orig_answer":null,"law":"companies","article":"24","status":"valid","explanation":"المادة (24/ب): تلتزم شركة التضامن التي يبلغ رأسمالها مائة ألف دينار أو أكثر بتعيين مدقق حسابات قانوني ينتخب بأكثرية الشركاء."},{"num":23,"type":"mcq","q":"لا يجوز للشركاء في شركة التضامن اخراج أي من الشركة، إلا ؟","o":["قرار من الوزير.","بقرار من المحكمة بناء على طلب اي منهم.","بقرار من (75%) من حصص الشركاء.","بقرار من المراقب."],"answer":1,"orig_answer":null,"law":"companies","article":"23","status":"valid","explanation":"المادة (23): لا يجوز إخراج أي شريك إلا بقرار من المحكمة بناءً على طلب أي من الشركاء."},{"num":24,"type":"mcq","q":"يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ بإسمها الأصلي في حال؟","o":["لا يجوز الاحتفاظ بالاسم الاصلي اذا تغيرت صفة الشركة.","تم تصفيتها ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","تم شطب تسجيلها، ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","رغبت بالتحول إلى شركة ذات مسؤولية محدودة."],"answer":3,"orig_answer":null,"law":"companies","article":"56","status":"valid","explanation":"المادة (56): يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ باسمها الأصلي إذا رغبت بالتحول إلى شركة ذات مسؤولية محدودة."},{"num":25,"type":"mcq","q":"إذا كان رأسمال الشركة ذات المسؤولية المحدودة أو جزء منه حصصاً عينية فعلى مقدمي هذه الحصص المحافظة على هذه المقدمات وعدم التصرف بها إلى حين؟","o":["تسليمها إلى الشركة وتسجيلها بإسمها ونقل ملكيتها إليها.","بيعها وتوزيع حصيلة البيع على الشركات مالكي هذه المقدمات العينية.","بيعها وإيداع حصيلة البيع في حسابات الشركة.","جميع ما ذكر صحيح."],"answer":0,"orig_answer":null,"law":"companies","article":"58","status":"valid","explanation":"المادة (58/أ): على مقدمي الحصص العينية المحافظة عليها وعدم التصرف بها إلى حين تسليمها إلى الشركة وتسجيلها باسمها ونقل ملكيتها إليها."},{"num":26,"type":"mcq","q":"ينشأ حق المساهم في الأرباح السنوية للشركة المساهمة العامة عند:","o":["موافقة الوزير ومراقب عام الشركات.","صدور قرار الهيئة العامة بتوزيع الأرباح.","موافقة هيئة الأوراق المالية.","موافقة مراقب عام الشركات."],"answer":1,"orig_answer":null,"law":"companies","article":"191","status":"valid","explanation":"المادة (191/أ): ينشأ حق المساهم في الأرباح السنوية بصدور قرار الهيئة العامة بتوزيعها."},{"num":27,"type":"mcq","q":"يتطلب موافقة ثلثي دائني الشركة في احدى الحالات التالية:","o":["شطب تسجيل شركة.","تسجيل شركة.","دمج الشركات.","تحويل الصفة القانونية للشركة."],"answer":3,"orig_answer":null,"law":"companies","article":"218","status":"valid","explanation":"المادتان (216/ج) و(218/ب): لا يتم تحويل الصفة القانونية للشركة إلا بموافقة خطية من الدائنين الذين يملكون أكثر من ثلثي ديونها."},{"num":28,"type":"mcq","q":"نصاب الحضور في اجتماع الهيئة العامة غير العادي الثاني (المؤجل) هو:","o":["10%.","75%.","50%.","40%."],"answer":3,"orig_answer":null,"law":"companies","article":"173","status":"valid","explanation":"المادة (173/أ): الاجتماع غير العادي الثاني (المؤجل) قانوني بحضور مساهمين يمثلون (40%) من الأسهم المكتتب بها على الأقل."},{"num":29,"type":"mcq","q":"تستمد الشركة ذات المسؤولية المحدودة اسمها من:","o":["اسم أحد الشركاء ويقترن بكلمة وشركاه.","غاياتها.","أسماء الشركاء.","في جميع الخيارات أعلاه."],"answer":1,"orig_answer":null,"law":"companies","article":"55","status":"valid","explanation":"المادة (55): تستمد الشركة ذات المسؤولية المحدودة اسمها من غاياتها."},{"num":30,"type":"mcq","q":"يتولى إدارة الشركة ذات المسؤولية المحدودة مدير أو هيئة مديرين عددهم:","o":["غير محدد العدد.","لا يقل عن اثنين ولا يزيد على سبعة.","لا يقل عن خمسة ولا يزيد على تسعة أعضاء.","لا يقل عن ثلاثة ولا يزيد على تسعة أعضاء."],"answer":1,"orig_answer":null,"law":"companies","article":"60","status":"valid","explanation":"المادة (60/أ): يتولى إدارتها مدير أو هيئة مديرين لا يقل عددها عن اثنين ولا يزيد على سبعة."},{"num":31,"type":"mcq","q":"لغايات تطبيق أحكام قانون الإعسار يعتبر الشخص الاعتباري ذا صلة بالمدين:","o":["أي شخص يملك (10%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة.","أي شخص يملك (3%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة","أي شخص يملك (5%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة.","أي شخص يملك (19%) و أكثر من أسهم الشركة المساهمة العامة أو أياً من الشركات الحليفة."],"answer":2,"orig_answer":null,"law":"insolvency","article":"4","status":"valid","explanation":"المادة (4/ب/4): أي شخص يمتلك (5%) أو أكثر من أسهم الشركة المساهمة العامة أو أي من الشركات الحليفة يعتبر ذا صلة بالمدين."},{"num":32,"type":"mcq","q":"تعتبر المحكمة قد بدأت في تصفية الشركة المساهمة العامة وذلك من:","o":["بعد شهر من تاريخ تعيين مصفي.","من تاريخ تعيين المحكمة مصفي للشركة.","من تاريخ موافقة مراقب عام الشركات على احالتها للتصفية الاجبارية.","تاريخ تقديم لائحة دعوى التصفية لها."],"answer":3,"orig_answer":null,"law":"companies","article":"267","status":"valid","explanation":"المادة (267/أ): تعتبر المحكمة قد بدأت في التصفية من تاريخ تقديم لائحة دعوى التصفية لها."},{"num":33,"type":"mcq","q":"النسبة المحددة التي تجيز لمساهمين الطلب من مراقب عام الشركات اجراء تدقيق على أعمال الشركة هي:","o":["30%.","20%.","10%.","5%."],"answer":2,"orig_answer":null,"law":"companies","article":"275","status":"valid","explanation":"المادة (275): لمساهمين يملكون ما لا يقل عن (10%) من رأس المال الطلب من المراقب إجراء تدقيق على أعمال الشركة."},{"num":34,"type":"mcq","q":"أي من العبارات التاليه تعتبر غير صحيحة بموجب قانون التجاره رقم (12) لعام 1966.","o":["يجوز اعادة الاعتبار للمفلس بعد وفاته.","لا يجوز إعادة الاعتبار الى المفلسين الذين حكم عليهم بالافلاس الاحتيالي او بسرقة او احتيال او اساءة امانة الا اذا كانوا قد حصلوا على اعادة الاعتبار الجزائي.","تخضع الشركات المدنية والشركات المرخصة او المسجلة بمقتضى قانون الشركات الساري المفعول الى اجراءات التصفية الفسخ الواردة فيه.","جميع العبارات صحيحة."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":35,"type":"mcq","q":"أي من العبارات التاليه تعتبر غير صحيحة فيما يتعلق بالسمسره حسب قانون التجاره رقم (12) لعام 1966.","o":["يجب على السمسار ان يحتفظ بالعينة في البيوعات بالعينه الى ان تتم العمليه.","اذا اشترط إرجاع النفقات التي صرفها السمسار فترجع له، وان لم يتم الاتفاق.","تسري قواعد الوكالة بوجه محدد على أعمال السمسره.","تسري قواعد الوكالة بوجه عام على السمسره."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق (المرجح أن الخطأ في (ج) لأن قواعد الوكالة تسري بوجه عام على السمسرة)."},{"num":36,"type":"mcq","q":"أي من العبارات التاليه تعتبر غير صحيحة فيما يتعلق بالعقود التجارية حسب قانون التجاره :","o":["كل التزام تجاري يقصد به القيام بعمل او بخدمة لا يعد معقوداً على وجه مجاني واذا لم يعين الفريقين اجرة او عمولة او سمسرة فيستحق الدائن الاجر المعروف في المهنة.","يخضع إثبات العقود التجارية مبدئياً للقواعد الحصرية الموضوعة للعقود المدنية.","يعتمد في اثبات العدل والثمن الدارج على اسعار البورصة والتسعيرات ان وجدت ما لم يوجد اتفاق مخالف.","أ+ج غير صحيح."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول؛ المرجح أن العبارة غير الصحيحة (ب) لأن إثبات العقود التجارية لا يخضع مبدئياً للقواعد الحصرية للعقود المدنية."},{"num":37,"type":"mcq","q":"بموجب قانون التجاره فيما يتعلق بالوكالة التجارية فان احدى العبارات التالية غير صحيحة:","o":["الوكيل الذي لم يتلق تعليمات الا في شأن جزء من العمل لا يعد مطلق اليد في الجزء الباقي.","عندما يعمل الوكيل باسم موكله تكون حقوقه والتزاماته خاضعة للاحكام الواردة بهذا الشأن في القانون المدني.","الوكالة التجارية وان احتوت على توكيل مطلق لا تجيز الاعمال غير التجارية الا بنص صريح.","يسمى هذا العقد وكالة بالعمولة ويجب على الوكيل ان يعمل باسمه الخاص او تحت عنوان تجاري لحساب من وكله."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":38,"type":"mcq","q":"جميع الامور التاليه صحيحه بخصوص الشيكات حسب قانون التجارة بإستثناء:","o":["تسقط بالتقادم دعاوى رجوع مختلف الملتزمين بوفاء الشيك بعضهم تجاه بعض بمضي خمس سنوات محسوبة من اليوم الذي خوصم فيه بدعوى الرجوع.","تسقط بالتقادم دعاوى رجوع الحامل على المظهرين والساحب والملتزمين الاخرين بمضي ستة شهور محسوبة من تاريخ انقضاء ميعاد التقديم.","تسقط بالتقادم دعوى حامل الشيك تجاه المسحوب عليه بمقتضى خمس سنوات محسوبة من تاريخ انقضاء الميعاد المحدد لتقديم الشيك للوفاء.","لحامل الشيك مطالبة من له حق الرجوع عليه بمبلغ الشيك غير المدفوع والفوائد ابتداء من يوم التقديم محسوبة بسعرها القانوني للشيكات المسحوبة في المملكة الاردنية الهاشمية والمستحقة الوفاء فيها وبسعر 6% بالنسبة للشيكات الاخرى ومصاريف الاحتجاج والاشعارات."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966 (أحكام الشيك) غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":39,"type":"mcq","q":"يتولى رئيس مجلس إدارة جمعية المحاسبين القانونيين المهام والصلاحيات التالية بإستثناء:","o":["وضع جدول اعمال إجتماعات المجلس.","الاشراف على الموظفين والعاملين في الجمعية.","التوقيع عن الجمعية في الامور المالية.","جميع ما ذكر."],"answer":null,"orig_answer":null,"law":"other:نظام جمعية المحاسبين القانونيين الأردنيين","article":"45","status":"unverified","explanation":"المادة (45) تحيل تحديد صلاحيات الرئيس والمفوضين بالتوقيع إلى نظام يصدر بمقتضى القانون؛ لم يتوفر نص النظام للتحقق."},{"num":40,"type":"mcq","q":"تتولى الجمعية في سبيل تحقيق اهدافها المهام والصلاحيات التالية ماعدا:","o":["اقتراح تطوير التشريعات ذات العلاقة بالمهنة.","التعاون في مجال المهنة مع الجامعات والمؤسسات التعليمية.","ترسيخ قواعد السلوك المهني.","توثيق العلاقات المهنية والاجتماعية بين مزاولي المهنة محلياً وعربياً ودولياً."],"answer":2,"orig_answer":null,"law":"accounting","article":"9","status":"valid","explanation":"المادة (9): مهام الجمعية تشمل اقتراح تطوير التشريعات والتعاون مع الجامعات وتوثيق العلاقات المهنية، وليس من بينها (ترسيخ قواعد السلوك المهني)."},{"num":41,"type":"mcq","q":"كل من خالف احكام المادة (21) من قانون تنظيم مهنة المحاسبة القانونية لسنة 2003 والتي تحظر على اي شخص غير حاصل على إجازة المزاوله وغير مسجل في سجل المزاولين وقام بمزاولة اعمال التدقيق بالعقوبة التالية:","o":["يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات او بغرامه لا تقل عن خمسة الاف دينار ولا تزيد على عشرين الف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على اربع سنوات او بغرامه لا تقل عن خمسة الاف دينار ولا تزيد على عشرين الف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات او بغرامه لا تقل عن أربعة الاف دينار ولا تزيد على عشرة الاف دينار او بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على اربع سنوات او بغرامه لا تقل عن خمسة الاف دينار ولا تزيد على عشرة الاف دينار او بكلتا العقوبتين."],"answer":0,"orig_answer":null,"law":"accounting","article":"43","status":"valid","explanation":"المادة (43/أ/1): الحبس من سنة إلى ثلاث سنوات أو غرامة من خمسة آلاف إلى عشرين ألف دينار أو كلتاهما."},{"num":42,"type":"mcq","q":"إي من العبارات التالية غير صحيحة فيما يتعلق بضمانات المسؤولية المدنية المنصوص عليها في المادة 56 من القانون على وكيل الاعسار :","o":["على وكيل الاعسار تقديم ضمانات كافية أو استصدار بوليصة تأمين ضد المسؤولية المهنية وفقاً للشروط التي ينص عليها النظام الذي يصدر بموجب احكام هذا القانون.","يكون وكيل الاعسار مسؤولاً عن اي ضرر يلحق بذمة الاعسار أو بالاشخاص الذين اشتركوا في اجراءات الاعسار نشأ عن إهماله او اهمال ممثليه او تابعيه في اداء مهامهم او إخلالهم بالواجبات المنوطة بهم.","يسقط حق المطالبة بالتعويض المنصوص عليه في الفقرة أ بمرور ثلاث سنوات على تاريخ علم المضرور بالضرر وبالشخص المسؤول عنه أو بمرور ثلاث سنوات على تاريخ إستكمال إجراءات الاعسار أيهما يقع اولاً.","جميع العبارات صحيحة."],"answer":2,"orig_answer":null,"law":"insolvency","article":"56","status":"valid","explanation":"المادة (56/ب): يسقط حق المطالبة بمرور ثلاث سنوات على العلم أو ثلاث سنوات على استكمال إجراءات الإعسار أيهما يقع لاحقاً لا أولاً."},{"num":43,"type":"mcq","q":"حسب المادة 51 من قانون الاعسار ان العبارة التالية صحيحة:","o":["على وكيل الاعسار ان يؤدي واجباته بنفسه وبالدقة والامانة المطلوبة وان يلتزم الحياد مع جميع الجهات التي تتاثر باجراءات الإعسار.","لوكيل الاعسار الاستعانة بخبراء يختارهم لتنفيذ مهامه على ان يبقى مسؤولاً عن تنفيذ تلك المهام و يتحمل أتعاب الخبراء ما لم يقرر الدائنين غير ذلك.","يحظر على وكيل الاعسار تفويض مهامه للغير الا في ظروف إستثنائية على ان يكون التفويض محددا من حيث المده والمهام وبموافقة المحكمة على ان يكون وكيل الاعسار مسؤول عن اعمال المفوض.","جميع العبارات غير صحيحة."],"answer":0,"orig_answer":null,"law":"insolvency","article":"51","status":"valid","explanation":"المادة (51): على وكيل الإعسار أداء واجباته بالدقة والأمانة والتزام الحياد (أ)، أما أتعاب الخبراء فما لم تقرر المحكمة (لا الدائنون)، والمفوض ووكيل الإعسار مسؤولان بالتكافل والتضامن."},{"num":44,"type":"mcq","q":"حسب قانون الاعسار فان العبارة التالية غير صحيحة:","o":["لدائني هذه الديون الحق في تقديم دفوعهم واعتراضاتهم على طلب المدين بالابراء خلال مدة سبعة ايام من تاريخ تبلغهم الطلب.","للمدين حسن النية تقديم طلب للمحكمة بالابراء من الديون غير المسددة وعلى المحكمة تبليغ هذا الطلب الى دائني هذه الديون ووكيل الاعسار خلال اسبوع من وروده اليها .","تعلن المحكمة إنتهاء إجراءات الاعسار بعد إتمام التوزيع النهائي او اذا تم سداد كامل الديون اثناء السير في إجراءات الاعسار ويتم اشهار قرار المحكمة وسبب انتهاء الاجراءات.","اذا كان المدين شخصاً إعتبارياً، تنتهي شخصيته الاعتبارية باستكمال توزيع العوائد ما لم يتم سداد ديونه بالكامل وعلى وكيل الاعسار تبليغ الجهة التي تم تسجيل الشخص الاعتباري لديها بقرار المحكمة لغايات شطب تسجيله وفقاً للتشريعات ذات العلاقة."],"answer":1,"orig_answer":null,"law":"insolvency","article":"108","status":"valid","explanation":"المادة (108/أ): على المحكمة تبليغ طلب الإبراء للدائنين ووكيل الإعسار فور وروده إليها لا خلال أسبوع."},{"num":45,"type":"mcq","q":"حسب قانون الإستثمار رقم (30) لسنة 2014 اي من العبارات التالية تعتبر غير صحيحه:","o":["تخضع للضريبة العامة على المبيعات السلع والخدمات التي يكون منشؤها في المنطقة التنموية والتي يتم بيعها إلى باقي مناطق المملكه.","تخفض الضريبة العامة المنصوص عليها في قانون الضريبة العامة على المبيعات على السلع والخدمات التي تقوم المؤسسة المسجله بشرائها او استيرادها لغايات ممارسة النشاط الاقتصادي داخل المناطق التنمويه لنسبة (الصفر) مع إلتزام بتقديم كفالة لدى دائرة ضريبة الدخل والمبيعات بهذا الخصوص.","يتم إستيفاء ضريبة مبيعات بنسبة 7% من قيمة بيع الخدمات التي يتم تحديدها بموجب النظام الصادر لهذه الغاية وذلك عند بيعها للاستهلاك في المنطقة التنموية.","لا شيء مماذكر غير صحيح."],"answer":null,"orig_answer":1,"law":"investment","article":"30","status":"changed","explanation":"قانون الاستثمار رقم 30 لسنة 2014 ألغي بقانون البيئة الاستثمارية رقم 21 لسنة 2022؛ المادة (30) منه تخضع مشتريات المؤسسة المسجلة لنسبة الصفر دون اشتراط كفالة ولم تعد تنص على نسبة 7% على الخدمات، فيصبح (ب) و(ج) غير صحيحين معاً."},{"num":46,"type":"mcq","q":"إحدى العبارات التالية غير صحيحة بموجب قانون رسوم الطوابع والواردات لسنة 2001:","o":["يعتبر تجديد أي معامله واردة في جدول المعاملات الخاضعه للرسوم الملحق بالقانون أو تمديدها بمثابة معاملة جديدة تخضع للرسوم المنصوص عليها في هذا الجدول.","تفرض على الموظف الذي لم يبطل الطوابع على المعامله بالصورة التي حددها القانون غرامة تعادل مثلا مقدار الرسم المقرر وبحد أدنى مقداره دينار واحد.","تفرض غرامة على المكلف بدفع الرسم المقرر إذا تأخر عن دفعه في الموعد المحدد بواقع مثل الرسم المستحق أو مقدار النقص فيه اذا كان التأخير لمدة تزيد على ثلاثين يوماً ولا تتجاوز ستين يوماً وبحد أدنى مقداره دينار واحد.","إذا تداخلت أكثر من معامله خاضعة للرسم في معاملة واحدة فيستوفى عن كل منها الرسم المقرر باعتبارها معاملة مستقلة."],"answer":1,"orig_answer":null,"law":"stamp","article":"12","status":"valid","explanation":"المادة (12/ب/2): غرامة الموظف الذي لم يبطل الطوابع تعادل مثل مقدار الرسم (لا مثليه) وبحد أدنى دينار واحد."},{"num":47,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحه بموجب قانون ديوان المحاسبة رقم 28 لسنة 1952 وتعديلاته:","o":["يتولى ديوان المحاسبة التدقيق اللاحق على النفقات الا انه يجوز لرئيس ديوان المحاسبة في حالات خاصة ان يقرر التدقيق في النفقات قبل الصرف.","على اي جهة من الجهات الخاضعه لرقابة ديوان المحاسبة الاجابة على اي استيضاح يوجهه اليها الديوان ضمن نطاق مهامه وذلك خلال مدة لا تتجاوز ستين يوماً اعتباراً من تاريخ وصوله الى تلك الجهة.","لرئيس ديوان المحاسبة في اي وقت ان يقدم لمجلس النواب تقارير خاصة يلفت نظره الى امور يرى انها من الخطر والاهمية بحيث تستلزم تعجيل النظر فيها.","على أي جهة خاضعه لرقابة ديوان المحاسبة ان تقدم للديوان البيانات المالية للسنة المنتهية خلال ستة اشهر من تاريخ انتهاء تلك السنة."],"answer":1,"orig_answer":null,"law":"audit","article":"16","status":"valid","explanation":"المادة (16): مدة الإجابة على الاستيضاح ثلاثون يوماً إذا كان مركز الجهة داخل المملكة وستون يوماً إذا كان خارجها (ويلاحظ أن المادة 25 تشترط أيضاً موافقة رئيس الوزراء للتدقيق المسبق)."},{"num":48,"type":"mcq","q":"أي من العبارات تعتبر غير صحيحة وفقاً لقانون المنافسة لسنة 2004.","o":["تشكل لجنة شؤون المنافسة برئاسة وزير الصناعة والتجارة تجتمع بدعوة من رئيسها او نائبه عند غيابه مره واحدة شهرياً ويكون اجتماعها قانونياً بحضور ما لايقل عن ثلثي اعضائها على ان يكون من بينهم الرئيس او نائبه.","يختص للنظر في قضايا الممارسات المخله بالمنافسة ضمن محكمة البداية قاض او اكثر من ذوي الاختصاص ممن تلقوا تدريباً خاصا على ان يتم تعيينهم بقرار من المجلس القضائي.","يحظر على اي مؤسسة لها وضع مهيمن في السوق او جزء هام منه اساءة استغلال هذا الوضع التمييز بين العملاء في العقود المتشابهه بالنسبة لاسعار السلع والخدمات او شروط بيعها وشرائها .","تحدد اسعار السلع والخدمات وفقاً لقواعد السوق ومبادئ المنافسة الحرة باستثناء اسعار الخدمات التي يتم تحديدها وفقاً لاحكام قانون الصناعه والتجارة او اي قانون اخر."],"answer":0,"orig_answer":null,"law":"competition","article":"15","status":"valid","explanation":"المادة (15/أ): تجتمع لجنة شؤون المنافسة مرة كل ستة أشهر على الأقل وليس مرة شهرياً."},{"num":49,"type":"mcq","q":"اي من العبارات التالية لا تعتبر صحيحه بموجب قانون مكافحة غسيل الاموال وتمويل الارهاب رقم (20) لسنة 2021:","o":["المتحصلات تشمل اي متحصلات ناجمة عن اي فعل يعتبر جريمة بمقتضى اتفاقيات دولية صادقت عليها المملكة شريطة ان يكون معاقباً عليها في القانون الاردني.","تمارس النيابة العامة او المحكمة المختصة اختصاصاتها في الجرائم المنصوص عليها في هذا القانون وفق اصول المحاكمات الجزائية ولها حجز ممتلكات اختلطت فيها المتحصلات مع اموال من مصادر مشروعة الى ان تحدد قيمة المتحصلات غير المشروعه ونواتج استغلالها.","المستفيد الحقيقي هو الشخص الطبيعي الذي يمتلك او يمارس سيطرة فعلية نهائية على العميل بصورة مباشرة او غير مباشرة او الذي تتم العمليات نيابة عنه او يمارس سيطرة فعلية نهائية على شخص طبيعي او ترتيب قانوني.","كل ما ذكر غير صحيح."],"answer":2,"orig_answer":null,"law":"aml","article":"2","status":"valid","explanation":"المادة (2): المستفيد الحقيقي يمارس سيطرة فعلية نهائية على شخص اعتباري أو ترتيب قانوني (لا شخص طبيعي)."},{"num":50,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون النزاهة ومكافحة الفساد رقم (13) لسنة 2016:","o":["لمجلس الوزراء بناء على تنسيب مجلس الهيئة انهاء خدمة اي عضو من اعضائه خلال مدة المجلس اذا تغيب عن اجتماعات المجلس ثلاث جلسات متتالية او ست جلسات متفرقة خلال السنة الواحدة دون عذر يقبله المجلس.","يطبق على الرئيس واعضاء المجلس قانون الكسب غير المشروع.","مدة العضوية في مجلس الهيئة اربع سنوات قابلة للتجديد لمرة واحدة للرئيس او لعضو المجلس.","تمارس الهيئة مهامها واعمالها بحرية واستقلال دون تأثير او تدخل من اي جهة فلا يجوز تفتيش مقر هيئة النزاهة ومكافحة الفساد من اي جهة."],"answer":3,"orig_answer":null,"law":"integrity","article":"5","status":"valid","explanation":"المادة (5/ب): لا يجوز تفتيش مقر الهيئة إلا بأمر قضائي وبحضور المدعي العام المختص، فالقول بعدم جواز التفتيش مطلقاً غير صحيح."},{"num":51,"type":"mcq","q":"يجوز للبنك المركزي في ظروف طارئة قد تهدد الاستقرار النقدي أو المالي في المملكة منح تسهيلات سيولة استثنائية للبنك إذا كانت مؤشرات تقييم الأوضاع المالية الخاصة به تدل على قدرته على الاستمرار في نشاطه وذلك وفقاً لشروط يحددها: (المادة 41/ قانون البنك المركزي الأردني رقم 23 لسنة 1971 وتعديلاته).","o":["وزير المالية.","محافظ البنك المركزي الأردني.","مجلس إدارة البنك المركزي الأردني.","مجلس الوزراء."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي الأردني غير مشمول بالقوانين المتوفرة؛ المرجح (ج) مجلس إدارة البنك المركزي."},{"num":52,"type":"mcq","q":"يكون أي تحديد او تغيير في نسبة الاحتياطي النقدي الالزامي نافذ المفعول بعد مضي: (المادة 42 / قانون البنك المركزي الأردني رقم 23 لسنة 1971 وتعديلاته):","o":["ثلاثين يوماً على الأقل من إرسال إشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير.","خمسة عشر على الأقل من إرسال إشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير.","عشر أيام على الأقل من إرسال إشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير.","عشرين يوماً على الأقل من إرسال اشعار خطي للبنوك يعلمها البنك المركزي فيه بهذا التحديد أو التغيير."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي الأردني غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":53,"type":"mcq","q":"لا يجوز للبنك المركزي الأردني ان يتعامل بالتجارة الا في حدود ما سمح له به في القانون، ولا يجوز أن يكون له نفع خاص في أي مشروع زراعي أو صناعي أو ما شابه ذلك ما عدا ما اتصل باستيفاء ديون للبنك المركزي شريطة التخلص منه خلال: (المادة 58 / قانون البنك المركزي الأردني رقم 23 لسنة 1971 وتعديلاته).","o":["ثلاث سنوات على الأكثر بعد تملكه له.","سنة على الأكثر بعد تملكه له.","سنتين على الأكثر بعد تملكه له.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"","status":"unverified","explanation":"قانون البنك المركزي الأردني غير مشمول بالقوانين المتوفرة؛ لم يتم التحقق."},{"num":54,"type":"mcq","q":"عرف قانون الضمان الاجتماعي صاحب العمل بأنه:","o":["الشخص الطبيعي الذي تسري عليه أحكام هذا القانون ذكراً أم أنثى.","كل شخص معنوي يستخدم عاملاً أو أكثر من الخاضعين لأحكام هذا القانون.","كل شخص طبيعي يستخدم عاملاً أو أكثر من الخاضعين لأحكام هذا لقانون.","كل شخص طبيعي أو معنوي يستخدم عاملاً أو أكثر من الخاضعين لأحكام هذا القانون."],"answer":3,"orig_answer":null,"law":"social","article":"2","status":"valid","explanation":"المادة (2): صاحب العمل كل شخص طبيعي أو معنوي يستخدم عاملاً أو أكثر من الخاضعين لأحكام القانون."},{"num":55,"type":"mcq","q":"عرف قانون الضمان الاجتماعي العجز الكلي الاصابي الدائم بأنه:","o":["كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة تقل عن 75%.","كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة لا تقل عن 75%.","كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة لا تقل عن 70%.","كل عجز ينشأ عن إصابة العمل ويفقد المؤمن عليه بسببه مقدرته الجسدية على العمل بصفة دائمة بنسبة تقل عن 70%."],"answer":1,"orig_answer":null,"law":"social","article":"2","status":"valid","explanation":"المادة (2): العجز الكلي الإصابي الدائم بنسبة لا تقل عن (75%)."},{"num":56,"type":"mcq","q":"تسري أحكام قانون الضمان الاجتماعي المتعلقة بتأمين إصابات العمل على المتدربين على العمل الذين لم يكملوا:","o":["تسعة عشرة سنة من أعمارهم.","ثماني عشرة سنة من أعمارهم.","سبعة عشرة سنة من أعمارهم.","ست عشرة سنة من أعمارهم."],"answer":3,"orig_answer":null,"law":"social","article":"5","status":"valid","explanation":"المادة (5/أ): تسري أحكام إصابات العمل على المتدربين الذين لم يكملوا ست عشرة سنة من أعمارهم."},{"num":57,"type":"mcq","q":"إن إصدار التعليمات التنفيذية والتنظيمية الداخلية والمالية والإدارية والفنية والاستثمارية للمؤسسة العامة للضمان الاجتماعي من صلاحيات:","o":["مجلس الإدارة.","مجلس الاستثمار.","مجلس التأمينات.","المدير العام."],"answer":0,"orig_answer":null,"law":"social","article":"11","status":"valid","explanation":"المادة (11/ك): إصدار التعليمات التنفيذية والتنظيمية الداخلية والمالية والإدارية والفنية والاستثمارية من صلاحيات المجلس (مجلس إدارة المؤسسة)."},{"num":58,"type":"mcq","q":"للمؤمن عليها الانتفاع من تأمين الأمومة المنصوص عليه في قانون الضمان الاجتماعي وفقاً للمدد المحددة في قانون العمل النافذ شريطة أن تثبت الولادة بشهادة رسمية وأن تكون مشمولة بأحكام هذا التأمين خلال:","o":["الستة أشهر الأخيرة التي تسبق استحقاقها اجازة الأمومة.","الشهر الأخير الذي يسبق استحقاقها اجازة الأمومة.","الثلاثة أشهر الأخيرة التي تسبق استحقاقها اجازة الأمومة.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"social","article":"44","status":"valid","explanation":"المادة (44/أ): أن تكون مشمولة بتأمين الأمومة خلال الأشهر الستة الأخيرة التي تسبق استحقاقها إجازة الأمومة."},{"num":59,"type":"mcq","q":"إذا انتهت خدمة الموظف التابع لقانون التقاعد المدني ولم يكمل مدة الخدمات المقبولة للتقاعد المنصوص عليها في ذلك القانون فيجوز بناء على طلب منه إعادة احتساب تلك الخدمات لغايات قانون الضمان الاجتماعي شريطة تحويل العائدات التقاعدية المستحقة عن تلك الخدمات إلى:","o":["المؤسسة العامة للضمان الاجتماعي بنسبة ثلثين وخزينة الدولة نسبة ثلث .","المؤسسة العامة للضمان الاجتماعي بنسبة ثلث وخزينة الدولة نسبة ثلثين .","خزينة الدولة.","المؤسسة العامة للضمان الاجتماعي."],"answer":3,"orig_answer":null,"law":"social","article":"85 مكرر","status":"valid","explanation":"المادة (85 مكرر): تحول العائدات التقاعدية إلى المؤسسة دون أن تتحمل الخزينة أي مبالغ."},{"num":60,"type":"mcq","q":"يسقط حق المؤسسة العامة للضمان الاجتماعي في المطالبة بالمبالغ المستحقة لها بموجب أحكام قانون الضمان الاجتماعي بإنقضاء:","o":["خمس عشرة سنة من تاريخ استحقاقها.","عشر سنوات من تاريخ استحقاقها.","خمس سنوات من تاريخ استحقاقها.","ثلاث سنوات من تاريخ استحقاقها."],"answer":0,"orig_answer":null,"law":"social","article":"95","status":"valid","explanation":"المادة (95/ج): يسقط حق المؤسسة بانقضاء خمس عشرة سنة من تاريخ الاستحقاق."},{"num":61,"type":"mcq","q":"يتم حجز ورهن الأوراق المالية لدى:","o":["المحكمة.","بورصة عمان.","مركز ايداع الأوراق المالية.","هيئة الأوراق المالية."],"answer":2,"orig_answer":null,"law":"securities","article":"79","status":"valid","explanation":"المادة (79/و): الحجز أو أي قيد على الأوراق المالية المودعة يثبت في سجلات مركز إيداع الأوراق المالية."},{"num":62,"type":"mcq","q":"يجب على المصدر تقديم تقرير سنوي للهيئة خلال مدة ...... من تاريخ انتهاء سنته المالية؟","o":["90 يوم.","60 يوم.","45 يوم.","30 يوم."],"answer":0,"orig_answer":null,"law":"securities","article":"43","status":"valid","explanation":"المادة (43/أ/1): التقرير السنوي خلال تسعين يوماً من انتهاء السنة المالية."},{"num":63,"type":"mcq","q":"العرض العام لبيع الأوراق المالية هو العرض الموجه:","o":["لأكثر من 50 شخص.","لأقل من 20 شخص.","لأكثر من 30 شخص.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): العرض العام عرض لبيع ورقة مالية لأكثر من ثلاثين شخصاً من الجمهور."},{"num":64,"type":"mcq","q":"وفقاً لتعليمات اصدار الأوراق المالية وتسجيلها فإن الحد الأدنى لعدد الأسهم في طلب الاكتتاب ما بين:","o":["100 إلى 500 سهم.","600 إلى 1000 سهم.","500 إلى 600 سهم.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:تعليمات إصدار الأوراق المالية وتسجيلها","article":"","status":"unverified","explanation":"تعليمات إصدار الأوراق المالية وتسجيلها غير متوفرة؛ لم يتم التحقق."},{"num":65,"type":"mcq","q":"يشترط أن لا يقل رأسمال صندوق الاستثمار المشترك عند التأسيس عن:","o":["أربعة ملايين دينار أردني أو ما يعادل ذلك من العملات الأجنبية.","خمسة ملايين دينار أردني أو ما يعادل ذلك من العملات الأجنبية.","مليوني دينار أردني أو ما يعادل ذلك من العملات الأجنبية.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:تعليمات/نظام صناديق الاستثمار المشترك","article":"","status":"unverified","explanation":"تعليمات/نظام صناديق الاستثمار المشترك غير متوفرة؛ لم يتم التحقق."},{"num":66,"type":"mcq","q":"على الشركة تقديم إفصاح للهيئة عن الفروقات التي تساوي أو تزيد عن (....) بين نتائج الأعمال الأولية والبيانات المالية السنوية وأسبابها معززة من مدقق الحسابات الخارجي:","o":["75%.","50%.","20%.","10%."],"answer":null,"orig_answer":null,"law":"other:تعليمات إفصاح الشركات المصدرة والمعايير المحاسبية ومعايير التدقيق","article":"","status":"unverified","explanation":"تعليمات الإفصاح غير متوفرة؛ لم يتم التحقق."},{"num":67,"type":"mcq","q":"يتولى مدير الاستثمار بصندوق الاستثمار المشترك المهام التالية:","o":["تزويد الهيئة بالبيانات المالية للصندوق.","إعداد نشرة الإصدار والنظام الأساسي للصندوق.","مراقبة الالتزام بالسياسة الاستثمارية للصندوق.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:تعليمات/نظام صناديق الاستثمار المشترك","article":"","status":"unverified","explanation":"تعليمات صناديق الاستثمار المشترك غير متوفرة؛ لم يتم التحقق."},{"num":68,"type":"mcq","q":"أي من الحالات التالية التي يجوز فسخ عقد التاجير بقرار من المحكمة المختصه او باشعار من المستأجر (اذا اجاز له العقد ذلك) حسب المادة 20 من قانون التأجير التمويلي رقم (45) لسنة 2008:","o":["أي حالة أخرى تشكل مخالفة جوهرية لعقد التأجير او التشريعات النافذة.","عدم تمكين المؤجر للمستأجر من الانتفاع بالمأجور وفقاً لاحكام القانون.","عدم قيام المؤجر باعمال الصيانة والاصلاح للمأجور ضمن المده المحددة في عقد التأجير او ضمن مدة معقوله في حال عدم تحديد تلك المدة وذلك في الحالات التي يفرض فيها عقد التأجير او التشريعات النافذة على المؤجر الالتزام بالصيانة والاصلاح.","جميع ما ذكر صحيح."],"answer":3,"orig_answer":null,"law":"leasing","article":"20","status":"unverified","explanation":"قانون التأجير التمويلي غير متوفر في ملفات القوانين؛ المادة (20) تجيز الفسخ في جميع الحالات المذكورة (عدم التمكين من الانتفاع، عدم الصيانة، أي مخالفة جوهرية) ولم يتم التحقق من النص."},{"num":69,"type":"mcq","q":"أي من العبارات تعتبر غير صحيحة وفقاً لقانون المنافسة لسنة 2004.","o":["تحدد كافة اسعار السلع والخدمات في السوق وفقاً لقواعد السوق ومبادئ المنافسه الحرة.","يحظر على كل منتج او مستورد او تاجر او مقدم خدمه ان يفرض بصوره مباشر او غير مباشره حد أدنى لإسعار إعادة بيع سلعة او خدمه.","يحظر على اي مؤسسة إعادة بيع منتج على حالته بسعر أقل من سعر شرائه الحقيقي مضافاً اليه الضرائب والرسوم، ولا يشمل هذا الحظر المنتجات سريعة التلف والتنزيلات المرخص بها لاي بيع يتم لتصفية الاعمال او تجديد المخزون بإسعار أقل.","تسري احكام هذا القانون على جميع انشطة الانتاج والتجارة والخدمات في المملكة كما تنصرف احكامه الى اي انشطة إقتصادية تتم خارج المملكة وتترتب عليها آثار داخلها."],"answer":0,"orig_answer":null,"law":"competition","article":"4","status":"valid","explanation":"المادة (4): تتحدد أسعار السلع والخدمات وفق قواعد السوق باستثناء أسعار المواد الأساسية والخدمات المحددة بقانون والأسعار المحددة بقرار مجلس الوزراء، فلا يصح القول (كافة الأسعار)."},{"num":70,"type":"mcq","q":"إن الشركة المعفاة هي:","o":["يمكن للشركة المعفاة بعد تسديد الرسوم المقررة عليها ان تطرح أسهمها للاكتتاب العام في حالة إذا أقامت شركة مساهمة عامة شريطة الالتزام بالأنظمة والتعليمات الصادرة عن هيئة الأوراق المالية وقانون الشركات.","يحق للشركة المعفاة أن تمارس أعمالها داخل وخارج المملكة شريطة ان تقوم بدفع رسوم سنوية تعادل بما لا يقل عن (20%) من ايراداتها السنوية كإيرادات للخزينة العامة.","الشركة المعفاة هي شركة مساهمة عامة أو شركة توصية بالأسهم أو شركة محدودة المسؤولية أو الشركات المساهمة الخاصة التي تسجل في المملكة وتزاول أعمالها خارجها ويضاف إلى اسمها عبارة (شركة معفاة) ويحظر عليها طرح أسهمها للاكتتاب العام في المملكة .","الشركة المعفاة هي الشركة التي يمكن تسجيلها بأي نوع من أنواع الشركات ويضاف على اسمها عبارة (شركة معفاة)."],"answer":null,"orig_answer":2,"law":"companies","article":"211","status":"changed","explanation":"المادة (211) المعدلة (سارية 2023/11/11): الشركة المعفاة شركة مساهمة عامة أو محدودة المسؤولية أو مساهمة خاصة فقط (حذفت التوصية بالأسهم)، ويحظر عليها طرح أسهمها للاكتتاب في المملكة؛ فالخيار (ج) لم يعد مطابقاً تماماً."},{"num":71,"essay_num":1,"type":"essay","q":"السؤال الأول (علامة واحدة): يوجد أربع حالات التي يلتزم البنك بأي منها بتخفيض المخصص المرصود مقابل الائتمان غير العامل، أذكر اثنتين منها؟","law":"income","article":"6","status":"valid","model_answer":"- المادة (6/ج/1) من قانون ضريبة الدخل: يلتزم البنك بتخفيض المخصص الخاص المرصود مقابل الائتمان غير العامل في أي من الحالات:\n  1) تحويل الائتمان غير العامل إلى ائتمان عامل وفق قانون البنوك.\n  2) تحصيل قيمة الائتمان غير العامل.\n  3) شطب قيمة الائتمان باعتباره ديناً هالكاً.\n  4) أي حالة أخرى يحددها البنك المركزي.\n- المادة (6/ج/2): يظهر البنك قيمة التخفيض المقبول سابقاً ضريبياً في دخله الإجمالي في الفترة التي جرى فيها التخفيض."},{"num":72,"essay_num":2,"type":"essay","q":"السؤال الثاني (علامتان): الشركة الأردنية تعمل في مجال بيع السيارات والإطارات ومركزها الرئيسي في عمان ولديها فرع في العقبة ولديك المعلومات التالية:\nأ. بلغت مبيعات الشركة 800 الف دينار (300 الف مبيعات عمان و 500 الف مبيعات فرع العقبة).\nب. بلغت المصاريف الكلية للشركة 255,000 دينار موزعة كما يلي (البيان: المركز الرئيسي (عمان) / فرع العقبة):\n- الإستهلاكات: 48,000 / 51,000\n- م. بيع وتوزيع: 22,800 / 25,600\n- م. إدارية: 12,000 / 19,200\n- م. تمويل: 37,200 / 39,200\n- المجموع: 120,000 / 135,000\nج. تم رد مبلغ (6,000 دينار) من المصاريف من قبل المدقق الضريبي بسبب عدم التعزيز.\nالمطلوب: إحتساب قيمة المصاريف المشتركة الواجب ردها من مصاريف المركز الرئيسي في عمان حسب المادة (9) من التعليمات التنفيذية رقم (8) لسنة 2015 بسبب ان بعض المصاريف المشتركة لا يمكن فصلها.","law":"income","article":"","status":"unverified","model_answer":"- تقوم الفكرة (تعليمات تنفيذية رقم 8 لسنة 2015، المادة 9) على توزيع المصاريف المشتركة للمركز الرئيسي التي لا يمكن فصلها على الأنشطة بنسبة إيرادات كل نشاط إلى إجمالي الإيرادات، ورد حصة النشاط ذي المعاملة الضريبية المختلفة (فرع العقبة).\n- نسبة مبيعات فرع العقبة = 500,000 ÷ 800,000 = 62.5%.\n- مصاريف المركز الرئيسي المقبولة قبل التوزيع = 120,000 − 6,000 (المردودة لعدم التعزيز) = 114,000 دينار.\n- المصاريف المشتركة الواجب ردها من مصاريف عمان = 114,000 × 62.5% = 71,250 ديناراً (وإذا وزع الإجمالي قبل رد الـ6,000 تكون 75,000 دينار).\n- ملاحظة: نص التعليمات غير متوفر للتحقق من طريقة المعالجة الدقيقة."},{"num":73,"essay_num":3,"type":"essay","q":"السؤال الثالث (علامتان): بتاريخ 2022/1/1 بلغت شركة الشركة حد التسجيل في الشبكة العامة لضريبة المبيعات وقررت التسجيل ولدى جرد المستودعات تبين ما يلي: كلفة البضاعة في المستودع عند الجرد 100,000 دينار ولتقديم كشوف الجرد التفصيلية لدائرة ضريبة الدخل والمبيعات وبالرجوع الى فواتير الشراء تبين النتائج التالية (الكلفة – تاريخ الشراء – نسبة الضريبة – المستندات):\n- 15000 – 2021/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2020/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2019/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2018/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2017/1 – 16% – فواتير ضريبية رسمية\n- 15000 – 2016/1 – 16% – فواتير ضريبية رسمية\n- 10000 – 2015/1 – 16% – فواتير غير ضريبية\nالمطلوب: إحتساب الضريبة الواجب تخصيمها عند التسجيل؟","law":"sales","article":"19","status":"valid","model_answer":"- المادة (19/د): للمسجل أن يخصم ما سبق أن تحمله قبل التسجيل من ضريبة عامة على السلع التي في حوزته عند التسجيل بشرط إثباتها بفواتير ضريبية.\n- البضاعة المؤيدة بفواتير ضريبية رسمية (2016–2021): 6 × 15,000 = 90,000 دينار × 16% = 14,400 دينار.\n- البضاعة المشتراة في 2015 بفواتير غير ضريبية (10,000 دينار) لا تخصم ضريبتها.\n- الضريبة الواجب تخصيمها عند التسجيل = 14,400 دينار (مع مراعاة أي قيد زمني تفرضه التعليمات التنفيذية على قدم الفواتير)."},{"num":74,"essay_num":4,"type":"essay","q":"السؤال الرابع (أربع علامات): شركة الاحبة مسجلة في شبكة الضريبة العامة على المبيعات ومن ضمن فترة اقرار ضريبة المبيعات 11+12/2021 ظهرت في حسابات الشركة المعطيات التالية:\n- مشتريات بضاعة قيمتها 25,000 دينار بنسبة ضريبة 16%.\n- مشتريات بضاعة معفاة قيمتها 30,000 دينار.\n- شراء اثاث لاستعمال الشركة بمبلغ 5,000 دينار وضريبة مبيعات 800 دينار.\n- شراء قرطاسية بقيمة 1,000 دينار وضريبة مبيعات 160 دينار.\n- مصاريف ضيافة بالشركة بقيمة 100 دينار وضريبة مبيعات 16 دينار.\n- مشتريات بضاعة مستوردة بقيمة 15,000 دينار وقيمتها التخمينية 18,000 دينار وجمارك 5,000 دينار وضريبة مبيعات بنسبة 16%.\n- مبيعات بقيمة 22,000 دينار خاضعة بنسبة 16%.\n- مبيعات قيمتها 16,000 دينار معفاة.\n- مبيعات قيمتها 8,000 دينار لجهات معفاة.\n- حساب امانات ضريبة المبيعات مدين في بداية الفترة بقيمة 1,500 دينار.\nالمطلوب: إحتساب رصيد امانات ضريبة المبيعات في فترة الاقرار الضريبي 11+12/2021.","law":"sales","article":"19","status":"valid","model_answer":"- ضريبة المخرجات: مبيعات خاضعة 22,000 × 16% = 3,520 دينار؛ المبيعات المعفاة (16,000) والمبيعات للجهات المعفاة (8,000) لا تحتسب عليها ضريبة.\n- ضريبة المدخلات القابلة للخصم (المادة 19/ج):\n  • مشتريات بضاعة 25,000 × 16% = 4,000\n  • أثاث لاستعمال الشركة = 800\n  • قرطاسية = 160\n  • بضاعة مستوردة: (18,000 + 5,000 جمارك) × 16% = 3,680 (المادة 15/ج)\n  • المجموع = 8,640 دينار.\n- غير قابل للخصم: ضريبة الضيافة 16 دينار (الجدول رقم 4)، ولا ضريبة على المشتريات المعفاة.\n- رصيد الأمانات = 1,500 (رصيد مدين أول المدة) + 8,640 − 3,520 = 6,620 دينار رصيد مدين (قابل للتدوير/الرد وفق المادة 20/ج).\n- ملاحظة: إذا طبقت نسبة التخصيص بسبب وجود مبيعات معفاة تخفض الضريبة المشتركة القابلة للخصم بنسبة المبيعات الخاضعة إلى إجمالي المبيعات."},{"num":75,"essay_num":5,"type":"essay","q":"السؤال الخامس (علامتان): اذكر أربع حالات تنقضي شركة التضامن بموجبها؟","law":"companies","article":"32","status":"valid","model_answer":"- المادة (32) من قانون الشركات: تنقضي شركة التضامن في أي من الحالات:\n  1) اتفاق الشركاء جميعهم على حلها أو دمجها في شركة أخرى.\n  2) انتهاء مدتها الأصلية أو الممددة.\n  3) انتهاء الغاية التي أسست من أجلها.\n  4) بقاء شريك واحد فيها (مع مراعاة المادة 28/د).\n  5) تصفيتها وشطب تسجيلها وفق قانون الإعسار.\n  6) إشهار إعسار أحد الشركاء أو الحجر عليه ما لم يقرر الباقون الاستمرار.\n  7) فسخها بحكم قضائي.\n  8) شطب تسجيلها بقرار من المراقب."},{"num":76,"essay_num":6,"type":"essay","q":"السؤال السادس (علامتان): اذكر اربع بيانات واجب أن يتضمنها نظام الشركة ذات المسؤولية المحدودة؟","law":"companies","article":"57","status":"valid","model_answer":"- المادة (57/ج): يجب أن يتضمن نظام الشركة ذات المسؤولية المحدودة بيانات عقد التأسيس (الاسم والغايات والمركز الرئيسي، أسماء الشركاء وجنسياتهم وعناوينهم، رأس المال وحصة كل شريك، الحصص العينية وقيمتها) إضافة إلى:\n  1) طريقة إدارة الشركة وعدد أعضاء هيئة المديرين وصلاحياتها بما فيها سقف الاستدانة والرهن والكفالة.\n  2) شروط وإجراءات التنازل عن الحصص.\n  3) كيفية توزيع الأرباح والخسائر.\n  4) اجتماعات الهيئة العامة وهيئة المديرين ونصابها وإجراءات الدعوة.\n  5) قواعد وإجراءات تصفية الشركة."},{"num":77,"essay_num":7,"type":"essay","q":"السؤال السابع (علامتان): اذكر الحالات التي تصفى الشركة المساهمة العامة بسببها تصفية اختيارية؟","law":"companies","article":"259","status":"valid","model_answer":"- المادة (259): تصفى الشركة المساهمة العامة تصفية اختيارية في الحالات:\n  1) انتهاء المدة المعينة لها ما لم تقرر الهيئة العامة تمديدها.\n  2) إتمام الغاية التي تأسست من أجلها أو استحالة إتمامها أو انتفاؤها.\n  3) صدور قرار من الهيئة العامة (غير العادية) بفسخها وتصفيتها.\n  4) الحالات الأخرى التي ينص عليها نظام الشركة."},{"num":78,"essay_num":8,"type":"essay","q":"السؤال الثامن (علامتان): الاوراق التجارية هي اسناد قابلة للتحويل بمقتضى احكام قانون التجارة رقم 12 لسنة 1966 اذكرها مع تعريف كل واحدة منها؟","law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","model_answer":"- الأوراق التجارية (أسناد قابلة للتحويل) ثلاثة:\n  1) سند السحب (البوليصة/الكمبيالة): محرر يأمر فيه الساحب المسحوب عليه بأن يدفع مبلغاً معيناً لأمر شخص ثالث (المستفيد) في تاريخ معين أو قابل للتعيين أو بمجرد الاطلاع.\n  2) السند لأمر (السند الإذني): محرر يتعهد فيه محرره بأن يدفع مبلغاً معيناً لأمر شخص آخر في تاريخ معين أو قابل للتعيين أو بمجرد الاطلاع.\n  3) الشيك: محرر يأمر فيه الساحب المسحوب عليه (بنك) بأن يدفع لدى الاطلاع مبلغاً معيناً لأمر شخص معين أو لحامله.\n- (القانون غير متوفر للتحقق من الصياغة الحرفية)."},{"num":79,"essay_num":9,"type":"essay","q":"السؤال التاسع (علامتان): تتولى الهيئة العليا لتنظيم مهنة المحاسبة القانونية المهام والصلاحيات المنصوص عليها بالمادة 5 من القانون أذكرها؟","law":"accounting","article":"5","status":"valid","model_answer":"- المادة (5) من قانون تنظيم مهنة المحاسبة القانونية: تتولى الهيئة العليا:\n  1) اعتماد معايير المحاسبة ومعايير التدقيق بتنسيب من المجلس.\n  2) تشكيل لجنة ترخيص المهنة ووضع تعليمات عملها والامتحانات.\n  3) المصادقة على منح إجازة المزاولة بتنسيب لجنة الترخيص وإلغاؤها بتنسيب المجلس.\n  4) النظر في الاعتراضات على قرارات المجلس.\n  5) تشكيل اللجان اللازمة لمساعدتها.\n  6) إصدار التعليمات اللازمة لتنظيم عملها وتنفيذ القانون والأنظمة.\n  7) إعداد مشروعات التشريعات المتعلقة بالمهنة بالتنسيق مع المجلس.\n  8) اعتماد المعاهد المهنية للمحاسبين القانونيين."},{"num":80,"essay_num":10,"type":"essay","q":"السؤال العاشر (علامة واحدة): متى يتولى وكيل الاعسار إدارة أعمال المعسر؟","law":"insolvency","article":"17","status":"valid","model_answer":"- المادة (17/ب): إذا كان طلب إشهار الإعسار مقدماً من الدائنين أو المراقب تعلق صلاحيات المدين ويمارسها وكيل الإعسار في حدود تسيير الأعمال المعتادة.\n- المادة (17/ج،هـ): أو إذا قررت المحكمة بطلب الدائنين أو وكيل الإعسار ولأسباب مبررة وقف صلاحية المدين في إدارة ذمة الإعسار.\n- المادة (17/و): عندها يكون وكيل الإعسار مسؤولاً عن ضمان استمرار الأعمال المعتادة للمدين."},{"num":81,"essay_num":11,"type":"essay","q":"السؤال الحادي عشر (علامة واحدة): لأي رقابة يخضع وكيل الاعسار؟","law":"insolvency","article":"52","status":"valid","model_answer":"- المادة (52/أ): يخضع عمل وكيل الإعسار لإشراف المحكمة ورقابة الدائنين أو من يمثلهم (لجنة الدائنين – المادة 48/ب/1).\n- المادة (52/ب): للمحكمة ولجنة الدائنين تكليفه بتقديم معلومات أو تقارير عن سير الإجراءات."},{"num":82,"essay_num":12,"type":"essay","q":"السؤال الثاني عشر (علامة واحدة): يحق للمؤمن له او المستفيد من عقد التأمين الانتفاع من شرط الاختراق ولا يجوز لاي جهة الاعتراض على تفعيله فما هو شرط الاختراق؟","law":"insurance","article":"71","status":"valid","model_answer":"- المادة (71/ب) من قانون تنظيم أعمال التأمين: شرط الاختراق هو الشرط الوارد في عقد إعادة التأمين الذي يقضي بمسؤولية معيد التأمين في حدود حصته من الخسارة المعاد تأمينها لديه تجاه المؤمن له والمستفيد في الحالات التي يتعذر فيها على المؤمن الوفاء بالتزاماته (كتصفية شركة التأمين)، بحيث تنشأ علاقة مباشرة بين معيد التأمين والمؤمن له والمستفيد."},{"num":83,"essay_num":13,"type":"essay","q":"السؤال الثالث عشر (علامتان): على البنك المركزي أن يحتفظ بموجودات لا تقل قيمتها في أي وقت من الأوقات عن قيمة أوراق النقد المتداولة؛ اذكر اربع من هذه الموجودات؟ (المادة 31/ قانون البنك المركزي الأردني رقم (23) لسنة 1971 وتعديلاته)","law":"other:قانون البنك المركزي الأردني رقم 23 لسنة 1971","article":"31","status":"unverified","model_answer":"- المادة (31) من قانون البنك المركزي (غير متوفر للتحقق): يحتفظ البنك المركزي مقابل النقد المتداول بموجودات منها:\n  1) الذهب.\n  2) العملات الأجنبية والأرصدة لدى البنوك المركزية والبنوك في الخارج.\n  3) الأوراق المالية الأجنبية القابلة للتداول.\n  4) سندات وأذونات الخزينة الأردنية (الأوراق المالية الحكومية).\n  5) حقوق السحب الخاصة/الشريحة الاحتياطية لدى صندوق النقد الدولي."},{"num":84,"essay_num":14,"type":"essay","q":"السؤال الرابع عشر (علامتان): عدد شروط استحقاق المؤمن عليه راتب العجز الكلي الدائم وفقاً لأحكام قانون الضمان الاجتماعي؟","law":"social","article":"67","status":"valid","model_answer":"- المادة (67/أ) من قانون الضمان الاجتماعي: يستحق المؤمن عليه راتب اعتلال العجز الكلي الطبيعي الدائم بشرط:\n  1) انتهاء خدمته.\n  2) تقديم طلب تخصيص الراتب خلال ستة أشهر من انتهاء الخدمة.\n  3) أن لا تقل اشتراكاته الفعلية عن (60) اشتراكاً منها (24) اشتراكاً متصلاً.\n  4) ثبوت العجز بقرار من المرجع الطبي.\n- (67/ب): لا يستحق عن حالات العجز السابقة لشموله بالقانون."},{"num":85,"essay_num":15,"type":"essay","q":"السؤال الخامس عشر (علامة واحدة): عدد شروط استحقاق المؤمن عليه راتب الوفاة وفقاً لأحكام قانون الضمان الاجتماعي؟","law":"social","article":"66","status":"valid","model_answer":"- المادة (66/أ): يستحق راتب تقاعد الوفاة الطبيعية إذا:\n  1) وقعت الوفاة خلال خدمته المشمولة بأحكام القانون.\n  2) سدد ما لا يقل عن (24) اشتراكاً فعلياً منها (6) اشتراكات متصلة."},{"num":86,"essay_num":16,"type":"essay","q":"السؤال السادس عشر (علامة واحدة): ما هو تعريف المعتمد حسب نظام العضوية في شركة بورصة عمان؟","law":"securities","article":"2","status":"valid","model_answer":"- تعريف المعتمد (المادة 2 من قانون الأوراق المالية، وبمعناه في أنظمة بورصة عمان): الشخص الطبيعي الذي يكون عضواً في مجلس إدارة شركة خدمات مالية أو هيئة مديريها أو مديراً أو مسؤولاً إدارياً أو موظفاً فيها، أو من يشغل وضعاً مشابهاً أو يمارس صلاحيات مماثلة لدى وسيط مالي أو وسيط لحسابه أو أمين استثمار أو مدير استثمار أو مستشار مالي أو مدير إصدار، ولا يشمل الوظائف المكتبية والخدماتية غير المتعلقة بنشاط الأوراق المالية.\n- (نظام العضوية في بورصة عمان غير متوفر للتحقق من صياغته)."},{"num":87,"essay_num":17,"type":"essay","q":"السؤال السابع عشر (علامتان): اذكر اربع من الممارسات التي قد يقوم بها المرخص له أو المعتمد وتكون مخالفة لقانون الأوراق المالية؟","law":"securities","article":"56","status":"valid","model_answer":"- المادة (56) من قانون الأوراق المالية: يعتبر مخالفة قيام المرخص له أو المعتمد بأي مما يلي:\n  1) إساءة التصرف بأموال العملاء أو المساهمين بما في ذلك إساءة توظيفها أو استخدامها.\n  2) ممارسة الخداع والتضليل والأعمال المحظورة.\n  3) التأثير سلباً على المنافسة بالتلاعب بنسب العمولات أو بدل الخدمات أو الحد من الخدمات منفرداً أو بالتواطؤ.\n  4) التأثير أو محاولة التأثير سلباً على سوق رأس المال منفرداً أو بالتواطؤ مع الغير."}]},{"id":"2022-07","year":2022,"month":7,"label":"دورة تموز 2022","session":"تموز","src":"9eb82a63.json","questions":[{"num":1,"type":"mcq","q":"يسمح لشركات التأمين تنزيل المخصص التالي لغايات ضريبة الدخل:","o":["مخصص الإقساط غير المكتسبة ومخصص الإدعاءات المبلغة تحت التسوية والمخصص المحاسبي.","مخصص الإقساط غير المكتسبة ومخصص الإدعاءات غير المبلغة تحت التسوية والمخصص المحاسبي.","مخصص الإقساط المكتسبة ومخصص الإدعاءات المبلغة تحت التسوية والمخصص المحاسبي.","مخصص الإقساط المكتسبة ومخصص الإدعاءات تحت التسوية والمخصص المحاسبي."],"answer":0,"orig_answer":null,"law":"income","article":"6","status":"valid","explanation":"المادة (6/د): تُنزل مخصصات شركات التأمين المتعلقة بالأقساط غير المكتسبة ومخصص الادعاءات المبلغة تحت التسوية والمخصص الحسابي (ورد في الخيار \"المحاسبي\")."},{"num":2,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فإن نسبة الضريبة لشركات تعدين المواد الأساسية:","o":["24% ضريبة دخل ونسبة 2% المساهمة الوطنية.","24% ضريبة دخل ونسبة 3% المساهمة الوطنية.","24% ضريبة دخل ونسبة 7% المساهمة الوطنية.","24% ضريبة دخل ونسبة 1% المساهمة الوطنية."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2) و(11/و/1/ب): شركات تعدين المواد الأساسية 24% ضريبة دخل و7% مساهمة وطنية."},{"num":3,"type":"mcq","q":"رتب قانون ضريبة الدخل إنشاء حساب المساهمة الوطنية والذي ألزم الشركات باقتطاع المبالغ التالية:","o":["3% من الدخل الخاضع لشركات الاتصالات الأساسية.","7% من الدخل الخاضع للبنوك وشركات توزيع وتوليد الكهرباء.","4% من الدخل الخاضع لشركات التأجير التمويلي.","نسب محددة على الدخل الخاضع للضريبة مما يزيد عن 200.000 دينار للشخص الطبيعي والاعتباري."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/و/1/ج): 4% من الدخل الخاضع لشركات الوساطة والشركات المالية والتأجير التمويلي؛ البنوك والكهرباء 3% والاتصالات 2% و1% للشخص الطبيعي فقط فيما زاد عن 200 ألف."},{"num":4,"type":"mcq","q":"شركة صناعات الملابس أعلنت في قائمة الدخل لسنة 2021 دخل صافي بقيمة 320.000 دينار، وعليه فإن ضريبة الدخل المستحقة:","o":["54.400 دينار.","64.000 دينار.","44.800 دينار.","51.200 دينار."],"answer":3,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/1) و(11/ج/2): نسبة 20% مخفضة بنسبة 20% لصناعة الملابس لسنة 2021 = 16% × 320,000 = 51,200 دينار (دون المساهمة الوطنية). التخفيض انتهى بعد سنة 2023 لكنه يبقى نافذاً على سنة 2021."},{"num":5,"type":"mcq","q":"شركة صناعات الكرتون أعلنت في قائمة الدخل لسنة 2020 دخل صافي بقيمة 100.000 دينار، وعليه فإن ضريبة الدخل المستحقة:","o":["20.000 دينار.","17.000 دينار.","16.000 دينار.","15.000 دينار."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ج/1): 20% مخفضة بنسبة 20% لسنة 2020 للأنشطة الصناعية = 16% × 100,000 = 16,000 دينار."},{"num":6,"type":"mcq","q":"موظف دخله السنوي من الرواتب للعام 2020 بواقع 21.400 دينار ولديه دخل سنوي من الإيجارات بقيمة 12.000 دينار ومصاريف المجاري المدفوعة 300 دينار والمسقفات المدفوعة بقيمة 1.200 دينار، وهو متزوج وزوجته تعمل براتب شهري قدره 1.000 دينار إذا علمت تم تقديم إقرار ضريبي مشترك، ولديهم 3 أولاد الأول يدرس في الجامعة قيمة القسط السنوي 2.000 دينار والثاني يدرس في مدرسة خاصة قسطها السنوي 1.500 دينار، إن الضريبة المستحقة:","o":["3.775 دينار.","2.575 دينار.","2.777 دينار.","لا شيء مما ذكر."],"answer":3,"orig_answer":null,"law":"income","article":"9","status":"unverified","explanation":"المادة (9) و(11/أ): الدخل 21,400+12,000 (الزوجة)+12,000 إيجار ناقص المسقفات والمجاري 1,500 = 43,900؛ الإعفاءات 9,000+9,000+إعفاءات النفقات (حد أقصى إجمالي 23,000) فتكون الضريبة نحو 2,725 دينار، وهي لا تطابق أياً من الخيارات (أ-ج)؛ النتيجة تعتمد على افتراضات التنزيل لذا تحتاج تحقق."},{"num":7,"type":"mcq","q":"إحدى العبارات التالية صحيحة:","o":["يُعفى من الضريبة ما يتحقق للبنوك والشركات المالية غير العاملة في المملكة من البنوك العاملة في المملكة من فوائد الودائع والعمولات وأرباح الودائع المشاركة في استثمار البنوك والشركات المالية التي لا تتعاطى بالفائدة.","يُعفى من الضريبة ما يتحقق للبنوك والشركات المالية العاملة في المملكة من البنوك العاملة في المملكة من فوائد الودائع والعمولات وأرباح الودائع المشاركة في استثمار البنوك والشركات المالية التي تتعاطى بالفائدة.","يُعفى من الضريبة ما يتحقق للبنوك والشركات المالية غير العاملة في المملكة من البنوك العاملة في المملكة من فوائد الودائع والعمولات وأرباح الودائع المشاركة في استثمار البنوك والشركات المالية التي تتعاطى بالفائدة.","يُعفى من الضريبة ما يتحقق للبنوك والشركات المالية العاملة في المملكة من فوائد الودائع والعمولات وأرباح الودائع المشاركة في استثمار البنوك والشركات المالية التي لا تتعاطى بالفائدة."],"answer":0,"orig_answer":null,"law":"income","article":"4","status":"valid","explanation":"المادة (4/ب/16): يعفى ما يتحقق للبنوك والشركات المالية غير العاملة في المملكة من البنوك العاملة في المملكة من فوائد الودائع والعمولات وأرباح الودائع لدى البنوك التي لا تتعاطى بالفائدة."},{"num":8,"type":"mcq","q":"أرباح شركات إعادة التأمين غير العاملة في المملكة الناجمة عن عقود التأمين التي تبرمها مع شركات التأمين العاملة في المملكة تخضع بنسبة:","o":["20%.","15%.","10%.","لا شيء مما ذكر."],"answer":3,"orig_answer":null,"law":"income","article":"4","status":"valid","explanation":"المادة (4/ب/17): أرباح شركات إعادة التأمين غير العاملة في المملكة من عقودها مع شركات التأمين العاملة في المملكة معفاة، فلا تنطبق أي نسبة."},{"num":9,"type":"mcq","q":"العبارة التالية صحيحة وفقاً لإحكام قانون ضريبة الدخل:","o":["إذا تم إسقاط الدعوى بسبب الغياب أو لا سبب آخر، ولم يتم تجديدها يُعتبر القرار المطعون فيه قطعياً بعد مرور ثلاثين يوماً من تاريخ تبليغ المحكمة قرار الإسقاط للمكلف أو وكيله، ويجوز تجديد الدعوى المسقطة لمرة واحدة وبسبب مبرر.","يقع على المكلف إقامة الدليل على أن المبلغ التي حددها القرار المطعون فيه باهظه ولا يجوز له تقديم المستندات التي لم يقدمها إلى هيئة الاعتراض.","للمحكمة أن تؤيد ما ورد في القرار المطعون فيه أو تخفض أو تزيد أو تلغي الضريبة والمبالغ الأخرى المقررة بموجبه.","جميع ما ذكر غير صحيح."],"answer":3,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"المادة (46): يجوز للمكلف تقديم مستندات لم يقدمها لهيئة الاعتراض، وليس للمحكمة \"الزيادة\"، ولا يجوز تجديد الدعوى للسبب نفسه أكثر من مرتين (لا مرة واحدة)؛ فجميع العبارات غير صحيحة."},{"num":10,"type":"mcq","q":"حسب قانون ضريبة الدخل يجوز للبنك تنزيل مخصصات التسهيلات الائتمانية غير العاملة التي يرصدها البنك وفق أحكام قانون البنوك والتعليمات الصادرة عن البنك المركزي الأردني بما في ذلك:","o":["مخصصات التسهيلات الائتمانية غير العاملة والتي لم يتم تخصيصها لكل عميل على حدة.","احتياطي المخاطر المصرفية العامة.","مخصص تدني التسهيلات الائتمانية تحت المراقبة.","جميع ما ذكر خطأ."],"answer":3,"orig_answer":null,"law":"income","article":"6","status":"valid","explanation":"المادة (6/ج): تنزل مخصصات البنوك وفق قانون البنوك وتعليمات البنك المركزي ولا يشمل ذلك المخصصات غير المخصصة لكل عميل ولا احتياطي المخاطر المصرفية العامة ولا مخصص التسهيلات تحت المراقبة."},{"num":11,"type":"mcq","q":"أحد العبارات التالية ليست صحيحة، ضريبة الدخل على أرباح المتاجرة بالأسهم عن كل عملية هي:","o":["8 بالعشرة آلاف من الشخص الطبيعي والشخص غير المقيم.","8 بالعشرة آلاف من الشخص الطبيعي والشخص غير المقيم وشركات التضامن.","8 بالعشرة آلاف من الشخص الطبيعي وشركات التضامن.","8 بالعشرة آلاف من الشخص الطبيعي عدا الشركات."],"answer":null,"orig_answer":null,"law":"income","article":"","status":"unverified","explanation":"نسبة 8 بالعشرة آلاف على أرباح المتاجرة بالأسهم واردة في نظام/تعليمات وليست في نص القانون؛ لم يتم التحقق."},{"num":12,"type":"mcq","q":"من شروط قبول مخصص الديون المشكوك في تحصيلها للشركات والمكلفين عدا البنوك أن يكون المخصص:","o":["50% من أرصدة حسابات المدينين في نهاية السنة المتعلقة بالنشاط الخاضع للضريبة.","10% من الأرصدة التي مضى على استحقاقها من سنة لغاية سنتين.","10% من الأرصدة التي مضى على استحقاقها من سنتين لغاية 3 سنوات.","5% من الأرصدة التي مضى على استحقاقها سنتين وأقل من 3 سنوات."],"answer":null,"orig_answer":null,"law":"income","article":"6","status":"unverified","explanation":"المادة (6/هـ) تجيز تنزيل مخصص الديون المشكوك فيها، أما النسب والشروط فواردة في النظام الصادر بمقتضاه وليست في نص القانون؛ لم يتم التحقق."},{"num":13,"type":"mcq","q":"وفق تعليمات احتساب حوافز ضريبية للقطاع الصناعي وفقاً لإحكام المادة 81 من قانون ضريبة الدخل حسب المعادلة التالية: (الدخل الصافي للنشاط الصناعي المستهدف ÷ مجموع الأرباح الصافية للمكلف من جميع الأنشطة والمصادر الأخرى) × الدخل الخاضع للضريبة للمكلف من جميع الأنشطة. وتسري هذه المعادلة على:","o":["للأنشطة الصناعية صناعة الأدوية والملابس وفقاً للجدول الملحق بالتعليمات.","إذا كان من الأنشطة الصناعية المستفيدة فعلياً من نظام تخفيض ضريبة الدخل في المناطق الأقل نمواً رقم (44) لسنة 2016.","إذا كان النشاط الصناعي مؤسسة مسجلة في المناطق التنموية.","جميع ما ذكر خطأ."],"answer":null,"orig_answer":null,"law":"income","article":"11","status":"unverified","explanation":"تخفيضات المادة (11/ج) للقطاع الصناعي سرت لمدة خمس سنوات (2019-2023) والمعادلة واردة في تعليمات غير موجودة في نص القانون؛ لم يتم التحقق من الخيار الصحيح."},{"num":14,"type":"mcq","q":"إحدى العبارات التالية غير صحيحة يعفى من تقديم الإقرار الضريبي الشخص المقيم الذي يقتصر دخله على التقاعد ولا يتجاوز في الفترة الضريبية ما يلي:","o":["الشخص الطبيعي المقيم الذي لا يزيد دخله الإجمالي السنوي من أي مصدر دخل خاضع للضريبة عدا الدخل الخاضع للضريبة القطعية على 10.000 دينار لسنة 2019 و9.000 دينار لسنة 2020 وما يليها للمكلف غير المعيل.","الشخص الذي يقتصر دخله السنوي على دخل خاضع للضريبة القطعية.","39.000 دينار لسنة 2020 وما يليها للمكلف المعيل.","40.000 دينار لسنة 2019 للمكلف غير المعيل."],"answer":null,"orig_answer":null,"law":"income","article":"17","status":"unverified","explanation":"المادة (17/هـ): تعفى فئات من تقديم الإقرار بموجب نظام يصدر لهذه الغاية؛ الحدود المذكورة في الخيارات غير واردة في نص القانون."},{"num":15,"type":"mcq","q":"التخلف عن تقديم طلب التسجيل في الضريبة العامة على المبيعات لمدة تزيد عن ستين يوم من تاريخ انقضاء المدة المحددة للتسجيل بموجب أحكام المادة 13 من القانون تُعتبر:","o":["جريمة يستحق عليها غرامة بواقع مثلي الضريبة.","مخالفة يستحق عليها غرامة بواقع 100 دينار.","مخالفة يستحق عليها غرامة من 100 إلى 500 دينار.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"sales","article":"30","status":"valid","explanation":"المادة (30/أ): التخلف عن التسجيل أكثر من ستين يوماً تهرب (جريمة) يعاقب عليه وفق المادة (31) بتعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها وغرامة 200-1000 دينار؛ أما ما دون الستين فمخالفة غرامتها 100-500 (م28)."},{"num":16,"type":"mcq","q":"وفقاً لقانون الضريبة العامة على المبيعات إحدى العبارات التالية صحيحة:","o":["تطبق محكمة البداية الضريبية ومحكمة الاستئناف الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","تطبق محكمة الاستئناف الضريبية الأصول المنصوص عليها في قانون أصول المحاكمات الجزائية بالقدر الذي لا يتعارض فيه مع أحكام قانون الضريبة العامة على المبيعات.","تطبق محكمة البداية الضريبية قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","جميع ما ذكر خطأ."],"answer":1,"orig_answer":null,"law":"sales","article":"59","status":"valid","explanation":"المادة (59): تطبق محكمتا البداية والاستئناف الضريبيتان أصول المحاكمات الجزائية والمدنية بالقدر الذي لا يتعارض مع أحكام القانون."},{"num":17,"type":"mcq","q":"وفقاً لقانون الضريبة العامة على المبيعات يتحمّل المحاسب القانوني المسؤولية عن المصادقة عن بيانات مالية تخالف معايير المحاسبة الدولية والأنظمة النافذة بسبب إهمال جسيم منه ويعاقب وفق القانون:","o":["تعويض مدني لا يقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئة دينار ولا تزيد عن خمسماية دينار.","تعويض مدني لا يقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئة دينار ولا تزيد عن مئتي دينار.","تعويض مدني لا يقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئتي دينار ولا تزيد عن خمسماية دينار.","تعويض مدني لا يقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزائية لا تقل عن مئتي دينار ولا تزيد عن ألف دينار."],"answer":3,"orig_answer":null,"law":"sales","article":"67","status":"valid","explanation":"المادة (67) والمادة (31): يعتبر المحاسب القانوني مرتكباً لجرم التهرب ويعاقب بتعويض مدني من مثلي إلى ثلاثة أمثال الضريبة وغرامة جزائية من 200 إلى 1000 دينار."},{"num":18,"type":"mcq","q":"تنفيذاً لأحكام قانون الضريبة العامة على المبيعات، يُعتمد لإغراض تحديد مسميات الخدمات:","o":["التصنيفات الصادرة بموجب التصنيف المحلي للمهن الصادر بموجب أحكام قانون الشركات وفق التشريعات النافذة.","التصنيفات الدولية الصادرة عن الأمانة العامة للأمم المتحدة.","جداول التعرفة وشروحاتها النافذة وفق لقرارات مجلس الوزراء.","جداول التعرفة وشروحاتها النافذة وفق أحكام قانون الجمارك."],"answer":1,"orig_answer":null,"law":"sales","article":"5","status":"valid","explanation":"المادة (5/أ): مسميات الخدمات تعتمد التصنيفات الدولية الصادرة عن الأمانة العامة للأمم المتحدة، والسلع جداول التعرفة وفق قانون الجمارك."},{"num":19,"type":"mcq","q":"يجوز الاعتراض على قرار التغريم بمقتضى أحكام المادة 28 من قانون الضريبة العامة على المبيعات:","o":["لدى هيئة الاعتراض المشكلة لهذه الغاية خلال 30 يوم تبلغ المكلف قرار التغريم.","لدى المدير خلال 30 يوم من تبلغ المكلف قرار التغريم.","لدى الوزير خلال 30 يوم من تبلغ المكلف قرار التغريم.","لدى المحكمة خلال 30 يوم من تبلغ المكلف قرار التغريم."],"answer":2,"orig_answer":null,"law":"sales","article":"29","status":"valid","explanation":"المادة (29/ب): يجوز الاعتراض لدى الوزير على قرارات التغريم بمقتضى المادة (28) خلال ثلاثين يوماً من التبلغ."},{"num":20,"type":"mcq","q":"في حال إسقاط القضية بسبب الغياب لدى المحكمة فإن الجهات الملزمة بتبليغ الإسقاط هي:","o":["قرارات قضايا الدخل (محكمة الضريبة) وقرارات المبيعات (دائرة الضريبة).","قرارات الإسقاط لقضايا الدخل والمبيعات (دائرة ضريبة الدخل).","قرارات الإسقاط لقضايا الدخل والمبيعات (محكمة الضريبة).","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"sales","article":"57","status":"valid","explanation":"الدخل م(46/ج): المحكمة تبلغ قرار الإسقاط؛ المبيعات م(57/ط/1): الدائرة تبلغ المكلف إشعاراً بصدور قرار الإسقاط."},{"num":21,"type":"mcq","q":"أصدر المدقق قرار التدقيق الأولي وتمّ بموجبه فرض فرق ضريبي وغرامات مثلي وغرامات جزائية وغرامات المادة (28) وقام بإصدار إشعار مطالبة بالفرق الضريبي وتم الاعتراض على قرار التدقيق وصدر قرار هيئة الاعتراض برد الاعتراض وتم تبليغه للمكلف بموجب إشعار فإنه يحق للمكلف الاعتراض على الإشعار الصادر من هيئة الاعتراض لدى المحكمة على:","o":["غرامة المادة (28).","الغرامات الجزائية.","غرامة المثلي.","الفرق الضريبي."],"answer":3,"orig_answer":null,"law":"sales","article":"48","status":"valid","explanation":"المادة (48/ح) و(57/أ/1): يطعن المكلف لدى المحكمة بقرار هيئة الاعتراض المتعلق بقرار التدقيق (الفرق الضريبي)، أما غرامات المادة (28) فيعترض عليها لدى الوزير (م29) والغرامات الجزائية تنظر بها المحكمة كجرائم."},{"num":22,"type":"mcq","q":"أي من العبارات التالية تُعتبَر صحيحة وبموجب قانون التجارة رقم (12) لعام 1966.","o":["تُعتبَر النوادي والجمعيات ذات الشخصية الاعتبارية من التجار إذا قامت بمعاملات تجارية ومعاملاتها تكون خاضعة لأحكام قانون التجارة.","لا يُعَدُّ تاجر من قام بمعاملة تجارية عرضاً إلا أن المعاملة المذكورة لا تكون خاضعة لأحكام قانون التجارة.","يعد تاجر كل من أعلن في الصحف أو النشرات أو أية واسطة أخرى عن المحل الذي أسسه وفتحه للاشتغال بالإعمال التجارية وإن لم يتخذ التجارة مهنة مألوفه له.","تخضع الأهلية التجارية لإحكام قانون التجارة."],"answer":2,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966: يعد تاجراً من أعلن في الصحف أو النشرات عن المحل الذي أسسه للاشتغال بالأعمال التجارية وإن لم يتخذ التجارة مهنة مألوفة له؛ قانون غير مدرج للتحقق."},{"num":23,"type":"mcq","q":"أي من العبارات التالية تُعتبَر غير صحيحة فيما يتعلق بالسمسرة حسب قانون التجارة رقم (12) لعام 1966.","o":["يجب على السمسار أن يحتفظ بالعينة في البيوعات بالعينة إلى أن تتم العملية.","إذا اشترط إرجاع النفقات التي صرفها السمسار فترجع له، وإن لم يتم الاتفاق.","تسري قواعد الوكالة بوجه محدد على أعمال السمسرة.","تسري قواعد الوكالة بوجه عام على السمسرة."],"answer":2,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966: تسري قواعد الوكالة بوجه عام على السمسرة، فعبارة \"بوجه محدد\" غير صحيحة؛ غير متحقق من النص."},{"num":24,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة فيما يتعلق بالحساب الجاري حسب قانون التجارة:","o":["ان الديون المترتبة لأحد الفريقين إذا دخلت الحساب الجاري لا تفقد صفاتها الخاصة وكيانها الذاتي.","لا يعد أحد الفريقين دائناً أو مديناً للفريق الآخر قبل ختام الحساب الجاري.","تزول التأمينات الشخصية أو العينية المتصلة بالديون التي أدخلت في الحساب الجاري ما لم يكن اتفاق مخالف بين الفريقين.","إن وجود الحساب الجاري لا يمنع أحد المتعاقدين من مطالبة الآخر بالعمولة التي استحقها عن عمل قام به بالعمولة."],"answer":0,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966: الديون إذا دخلت الحساب الجاري تفقد صفاتها الخاصة وكيانها الذاتي، فالعبارة (أ) غير صحيحة؛ غير متحقق من النص."},{"num":25,"type":"mcq","q":"بموجب قانون التجارة سند السحب الخالي من أحد البيانات المذكورة في المادة 125 لا يُعتبر سند سحب إلا في الحالة التالية:","o":["سند السحب الخالي من ذكر تاريخ إنشائه فيُعتبر التاريخ الحقيقي الذي تمّ فيه تسليم السند للمستفيد أو الحامل هو تاريخ إنشائه.","سند السحب الخالي من تاريخ الاستحقاق يكون مستحق الأداء خلال 7 أيام عمل.","سند السحب الخالي من تاريخ الاستحقاق يكون مستحق الأداء خلال شهر.","جميع ما ذكر غير صحيح."],"answer":3,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"قانون التجارة 1966: السند الخالي من تاريخ الاستحقاق يكون مستحق الأداء لدى الاطلاع، فالخيارات (ب) و(ج) خاطئة؛ غير متحقق من النص."},{"num":26,"type":"mcq","q":"جميع الأمور التالية صحيحة بخصوص الوكالة التجارية حسب قانون التجارة باستثناء:","o":["الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي.","الوكالة التجارية وإن احتوت على توكيل مطلق لا تجيز الأعمال غير التجارية إلا بنص صريح.","في المواد التجارية يستحق الوكيل الأجر في جميع الأحوال ما لم يكن هناك نص مخالف.","يجب على الوكيل أن يعمل باسم موكله تكون حقوقه والتزاماته خاضعة للأحكام الواردة بهذا الشأن في القانون التجاري."],"answer":null,"orig_answer":null,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"أحكام الوكالة التجارية في قانون التجارة 1966؛ القانون غير مدرج ولم يتم التحقق من العبارة المستثناة."},{"num":27,"type":"mcq","q":"إلغاء إجازة المزاولة وشطب اسم المحاسب القانوني نهائياً من سجل المزاولين عقوبة توقعها:","o":["لجنة الترخيص بعد التنسيب من مجلس الإدارة.","اللجنة التأديبية.","مجلس إدارة جمعية المحاسبين القانونيين.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"accounting","article":"36","status":"valid","explanation":"المادة (36/أ/4): توقع اللجنة التأديبية عقوبة إلغاء الإجازة والشطب، وتخضع لمصادقة المجلس ثم الهيئة العليا (م37)."},{"num":28,"type":"mcq","q":"أي من المهام والصلاحيات ليست من صلاحيات مجلس إدارة جمعية المحاسبين القانونيين:","o":["ترسيخ قواعد السلوك المهني.","اعتماد المعاهد المهنية للمحاسبين القانونيين أو ما يماثلها.","التعاون مع الهيئة العليا في إعداد مشروعات التشريعات واقتراح مشروعات الأنظمة المتعلقة بالمهنة.","التنسيب للهيئة العليا بإلغاء إجازة مزاولة المحاسب القانوني."],"answer":1,"orig_answer":null,"law":"accounting","article":"5","status":"valid","explanation":"المادة (5/ح): اعتماد المعاهد المهنية للمحاسبين القانونيين من صلاحيات الهيئة العليا لا مجلس إدارة الجمعية."},{"num":29,"type":"mcq","q":"كل من خالف أحكام المادة (21) من قانون تنظيم مهنة المحاسبة القانونية لسنة 2003 والتي تحظر على أي شخص غير حاصل على إجازة المزاولة وغير مسجل في سجل المزاولين وقام بمزاولة أعمال التدقيق بالعقوبة التالية:","o":["يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات أو بغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار أو بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على أربع سنوات أو بغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرين ألف دينار أو بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات أو بغرامة لا تقل عن أربعة آلاف دينار ولا تزيد على عشرة آلاف أو بكلتا العقوبتين.","يعاقب بالحبس مدة لا تقل عن سنة ولا تزيد على أربع سنوات أو بغرامة لا تقل عن خمسة آلاف دينار ولا تزيد على عشرة آلاف دينار أو بكلتا العقوبتين."],"answer":0,"orig_answer":null,"law":"accounting","article":"43","status":"valid","explanation":"المادة (43/أ/1): الحبس من سنة إلى ثلاث سنوات أو غرامة من 5,000 إلى 20,000 دينار أو بكلتا العقوبتين."},{"num":30,"type":"mcq","q":"تسري أحكام قانون الإعسار رقم (21) لسنة 2018 على أي شخص يمارس نشاطاً اقتصادياً ما عدا:","o":["أصحاب المهن المسجلون والمرخص لهم بالعمل بموجب أحكام التشريعات النافذة.","الأشخاص الطبيعيون الذين يخضعون لأحكام القانون المدني.","التجار أصحاب المؤسسات الفردية.","الأشخاص الاعتباريون بما في ذلك الشركات المدنية والشركات التي تملكها الحكومة."],"answer":1,"orig_answer":null,"law":"insolvency","article":"3","status":"valid","explanation":"المادة (3/ب/4): لا يسري القانون على الأشخاص الطبيعيين الخاضعين للقانون المدني (باستثناء أصحاب المهن)."},{"num":31,"type":"mcq","q":"أي من الحالات التالية لا تُعتبَر دليلاً على الإعسار الفعلي:","o":["صدور قرار من المحكمة يقضي بالاعتراف بإجراءات إعسار أجنبية رئيسية.","إذا كان المدين شخصاً طبيعياً، أصبح مجهول مكان الإقامة أو أنه أغلق مكان المصالح الرئيسية له إذا كان شخصاً اعتبارياً.","إذا هرب المدين أمواله أو باعها بغبن فاحش.","إلغاء الحجز التنفيذي على جزء من أموال المدين."],"answer":3,"orig_answer":null,"law":"insolvency","article":"10","status":"valid","explanation":"المادة (10/ج): من أدلة الإعسار الفعلي إلقاء الحجز التنفيذي على كامل أموال المدين، لا إلغاء الحجز على جزء منها."},{"num":32,"type":"mcq","q":"تجتمع الهيئة العامة للدائنين بناءاً على دعوة وكيل الاعسار إما من تلقاء نفسه أو بناءاً على طلب لجنة الدائنين أو دائنين يمثلون:","o":["50% على الأقل من إجمالي الديون.","30% على الأقل من إجمالي الديون.","20% على الأقل من إجمالي الديون.","10% على الأقل من إجمالي الديون."],"answer":2,"orig_answer":null,"law":"insolvency","article":"44","status":"valid","explanation":"المادة (44/أ): بناء على طلب لجنة الدائنين أو دائنين يمثلون 20% على الأقل من إجمالي الديون."},{"num":33,"type":"mcq","q":"حسب قانون الاعسار تعتبر الديون المبينة أدناه ديوناً ممتازة باستثناء:","o":["نفقات إجراءات الإعسار، بما في ذلك الرسوم والمصاريف القضائية، أتعاب وكيل الإعسار والنفقات التي وافقت عليها لجنة الدائنين وأتعاب محامي ذمة الإعسار.","المطالبات بالتعويض الناشئ عن الفعل الضار الذي تسبَّب به المدين قبل إشهار الإعسار.","نفقة الزوجة والأولاد والوالدين والأقارب المستحقة على المدين من الأشخاص الطبيعيين قبل إشهار الإعسار.","أجور العاملين لدى المدين ومستحقاتهم الناشئة عن إنهاء عقود العمل وبحد أعلى ثلاثة أشهر."],"answer":0,"orig_answer":null,"law":"insolvency","article":"40","status":"valid","explanation":"المادة (40): الديون الممتازة هي أجور العاملين (3 أشهر) والنفقة والتعويض عن الفعل الضار؛ أما نفقات إجراءات الإعسار فهي ديون في مواجهة الإجراءات (م38)."},{"num":34,"type":"mcq","q":"حسب قانون الاستثمار رقم (30) لسنة 2014 أي من العبارات التالية تعتبر صحيحة:","o":["تخضع للضريبة العامة على المبيعات السلع والخدمات التي يكون منشؤها في المنطقة التنموية والتي يتم بيعها إلى باقي مناطق المملكة.","تخفض الضريبة العامة المنصوص عليها في قانون الضريبة العامة على المبيعات على السلع والخدمات التي تقوم المؤسسة المسجلة بشرائها أو استيرادها لغايات ممارسة النشاط الاقتصادي داخل المناطق التنموية لنسبة (الصفر) مع التزام بتقديم كفالة لدى دائرة ضريبة الدخل والمبيعات بهذا الخصوص.","يتم استيفاء ضريبة مبيعات بنسبة 7% من قيمة بيع الخدمات التي يتم تحديدها بموجب النظام الصادر لهذه الغاية وذلك عند بيعها للاستهلاك في المنطقة التنموية.","لا شيء مما ذكر غير صحيح."],"answer":0,"orig_answer":null,"law":"investment","article":"30","status":"changed","explanation":"قانون الاستثمار 2014 أُلغي وحل محله قانون البيئة الاستثمارية رقم 21 لسنة 2022؛ المادة (30/أ/2) منه: تخضع للضريبة العامة السلع والخدمات التي منشؤها المنطقة التنموية والمبيعة لباقي مناطق المملكة، ونسبة الصفر على المشتريات بلا اشتراط كفالة."},{"num":35,"type":"mcq","q":"إحدى العبارات التالية غير صحيحة بموجب قانون رسوم الطوابع والواردات لسنة 2001:","o":["خلافاً لأحكام أي تشريع آخر لا تقبل لدى أي جهة رسمية أي معاملة خاضعة للرسم تتعلق بأموال واقعة في المملكة أو بأي شأن آخر فيها بصورة كلية أو جزئية ما لم يدفع الرسم المستحق عليها باستثناء ما يقدم في الدعوى الجزائية.","تفرض على الموظف الذي لم يبطل الطوابع على المعاملة بالصورة التي حددها القانون غرامة تعادل مثلاً مقدار الرسم المقرر وبحد أدنى مقداره دينار واحد.","تفرض غرامة على المكلف بدفع الرسم المقرر إن تأخر عن دفعه في الموعد المحدد تعادل مثلاً الرسم أو مقدار النقص في حالة التأخير لمدة تزيد عن ستين يوم وبحد أدنى مقداره دينار واحد.","تفرض غرامة على المكلف بدفع الرسم المقرر إن تأخر عن دفعه في اليوم المحدد تعادل 50% من الرسم أو مقدار النقص في حالة التأخير لمدة تزيد عن سبعة أيام ولا تتجاوز ثلاثين وبحد أدنى مقداره دينار واحد."],"answer":1,"orig_answer":null,"law":"stamp","article":"12","status":"valid","explanation":"المادة (12/ب/2): غرامة الموظف الذي لم يبطل الطوابع تعادل \"مثل\" مقدار الرسم لا \"مثلا\" الرسم."},{"num":36,"type":"mcq","q":"أي من العبارات التالية تعتبر غير صحيحة بموجب قانون ديوان المحاسبة رقم 28 لسنة 1952 وتعديلاته:","o":["إذا وقع خلاف بالرأي بين الديوان وإحدى الوزارات أو الدوائر يُعرض موضوع الخلاف على مجلس الوزراء للفصل فيه وعلى رئيس الديوان أن يتضمّن تقريره إلى مجلس النواب المسائل التي وقع الخلاف حولها.","لرئيس ديوان المحاسبة أن يقدم لمجلس النواب تقارير خاصة دورية يلفت فيها نظره إلى أمور يرى أنها من الخطر والأهمية بحيث تستلزم تعجيل النظر فيها.","يقدم رئيس ديوان المحاسبة تقريراً سنوياً عن كل سنة مالية إلى مجلسي الأعيان والنواب على أن يضمن التقرير ملاحظاته والمخالفات المرتكبة والمسؤولية المترتبة عليها.","على وزارة المالية أن تقدم لديوان المحاسبة الحساب الختامي عن كل سنة مالية خلال مدة لا تزيد على ستة أشهر من تاريخ انتهاء تلك السنة."],"answer":2,"orig_answer":null,"law":"audit","article":"22","status":"valid","explanation":"المادة (22): يقدم رئيس الديوان تقريره السنوي إلى مجلس النواب (لا مجلسي الأعيان والنواب)، ويرسل صوراً إلى رئيس الوزراء ووزير المالية."},{"num":37,"type":"mcq","q":"أي من العبارات تعتبر غير صحيحة وفقاً لقانون المنافسة لسنة 2004:","o":["تحدد كافة أسعار السلع والخدمات في السوق وفقاً لقواعد السوق ومبادئ المنافسة الحرة.","يحظر على كل منتج أو مستورد أو تاجر أو مقدم خدمة أن يفرض بصورة مباشرة أو غير مباشرة حد أدنى لأسعار إعادة بيع سلعة أو خدمة.","يحظر على أي مؤسسة إعادة بيع منتج على حالته بسعر أقل من سعر شرائه الحقيقي مضافاً إليه الضرائب والرسوم، ولا يشمل هذا الحظر المنتجات سريعة التلف والتنزيلات المرخص بها لأي بيع يتم لتصفية الأعمال أو تجديد المخزون بأسعار أقل.","تسري أحكام هذا القانون على جميع أنشطة الإنتاج والتجارة والخدمات في المملكة كما تنصرف أحكامه إلى أي أنشطة اقتصادية تتم خارج المملكة وتترتب عليها آثار داخلها."],"answer":0,"orig_answer":null,"law":"competition","article":"4","status":"valid","explanation":"المادة (4): تتحدد الأسعار وفق قواعد السوق باستثناء أسعار المواد الأساسية المحددة قانوناً والأسعار المحددة بقرار مجلس الوزراء، فليست \"كافة\" الأسعار."},{"num":38,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون مكافحة غسيل الأموال وتمويل الإرهاب رقم (20) لسنة 2021:","o":["الجهات المبلغة هي المؤسسات المالية التي تُمنح بموجب التشريعات السارية في أي دولة الاختصاصات اللازمة لمكافحة غسيل الأموال وتمويل الإرهاب وتخضع لقواعد قانونية كافية للالتزام بسرية المعلومات.","من السلطات المختصة المسؤولة عن ضمان التزام الجهات المبلغة بمتطلبات مكافحة غسيل الأموال وتمويل الإرهاب البنك المركزي وهيئة الأوراق المالية ووزارة الصناعة والتجارة والتموين ودائرة الأراضي والمساحة.","المتحصلات تعني أي أموال أو أصول ناشئة أم تمّ الحصول عليها بصورة مباشرة أو غير مباشرة من خلال ارتكاب فعل أو الامتناع عن القيام بفعل بما يشكل جريمة وفق التشريعات النافذة بالمملكة.","كل ما ذكر غير صحيح."],"answer":0,"orig_answer":null,"law":"aml","article":"2","status":"valid","explanation":"المادة (2): التعريف في (أ) هو تعريف \"الجهة النظيرة\"، أما الجهات المبلغة فهي المؤسسات المالية والمهن والأعمال غير المالية."},{"num":39,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة بموجب قانون النزاهة ومكافحة الفساد رقم (13) لسنة 2016:","o":["لا يجوز تفتيش مقر هيئة النزاهة ومكافحة الفساد إلا بأمر قضائي وبحضور المدعي العام المختص على أن يتم تبليغ الرئيس بذلك ودعوة من يمثل الهيئة لحضور التفتيش.","التأكد من قيام مؤسسات الرقابة على القطاع الخاص ومؤسسات المجتمع المدني بوضع معايير الحوكمة الرشيدة وسلامة تطبيقها.","مكافحة اغتيال الشخصية.","التأكد من التزام السلطات بالشفافية عند وضع السياسات والتشريعات واتخاذ القرارات وضمان حق المواطن في الاطلاع على المعلومات وفق للتشريعات."],"answer":3,"orig_answer":null,"law":"integrity","article":"4","status":"valid","explanation":"المادة (4/د): التأكد من التزام \"السلطة التنفيذية\" بالشفافية عند وضع السياسات واتخاذ القرارات، وليس \"السلطات\" ووضع التشريعات."},{"num":40,"type":"mcq","q":"يحتفظ البنك المركزي باحتياطي عام يقيد فيه 20% من الربح الصافي للبنك المركزي في كل سنة مالية، وتدفع جميع الأرباح الصافية للحكومة عندما يزيد مقدار الاحتياطي العام على: (المادة 9/ قانون البنك المركزي الأردني رقم 23 لسنة 1971 وتعديلاته)","o":["خمسة أمثال رأس المال.","مثلي رأس المال.","ثلاثة أمثال رأس المال.","لا شيء مما ذكر."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"9","status":"unverified","explanation":"قانون البنك المركزي غير مدرج ضمن القوانين المتاحة للتحقق."},{"num":41,"type":"mcq","q":"بموجب قانون البنك المركزي الأردني رقم (23) لسنة 1971 وتعديلاته، على البنك المركزي أن يقدم لوزير المالية تقريراً موجزاً عن أعماله ونسخة من الميزانية السنوية العامة وحساب الأرباح والخسائر خلال: (المادة 61)","o":["ستة أشهر من انتهاء السنة المالية.","أربعة أشهر من انتهاء السنة المالية.","شهرين من انتهاء السنة المالية.","ثلاثة أشهر من انتهاء السنة المالية."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"61","status":"unverified","explanation":"قانون البنك المركزي غير مدرج ضمن القوانين المتاحة للتحقق."},{"num":42,"type":"mcq","q":"بموجب قانون البنك المركزي رقم 23 لسنة 1971 وتعديلاته على البنك المركزي أن يحصل من البنك الذي تنقص لديه قيمة الاحتياطي النقدي غرامة نقدية تساوي: (المادة 42)","o":["1.000 دينار أو بنسبة (1/3650) من قيمة النقص عن كل يوم يستمر فيه النقص أيهما أكثر.","1.000 دينار أو بنسبة (1/3650) من قيمة النقص عن كل يوم يستمر فيه النقص أيهما أقل.","1.000 دينار ونسبة (1/3650) من قيمة النقص.","1.000 دينار."],"answer":null,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"42","status":"unverified","explanation":"قانون البنك المركزي غير مدرج ضمن القوانين المتاحة للتحقق."},{"num":43,"type":"mcq","q":"تعيين محاسب قانوني لوحدة غسل الأموال تعتبر من مهام: (المادة 6/ قانون مكافحة غسل الأموال وتمويل الإرهاب رقم (20) لسنة 2021)","o":["ديوان المحاسبة.","البنك المركزي الأردني.","مجلس الوزراء.","اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب."],"answer":3,"orig_answer":null,"law":"aml","article":"6","status":"valid","explanation":"المادة (6/أ/12): من مهام اللجنة الوطنية تعيين محاسب قانوني للوحدة وتحديد أتعابه."},{"num":44,"type":"mcq","q":"في حال تأخر المؤمن عليه الذي انتسب بصفة اختيارية عن دفع لاشتراكات خلال الخمسة عشر يوماً من الشهر التالي للاستحقاق فإنه يدفع فائدة تأخير قدرها:","o":["اثنان بالمائة شهرياً عن أي من الاشتراكات والفوائد التي تأخر عن أدائها.","اثنان بالمائة شهرياً عن أي من الاشتراكات التي تأخر عن أدائها.","واحد بالمائة شهرياً عن أي من الاشتراكات والفوائد التي تأخر عن أدائها.","واحد بالمائة شهرياً عن أي من الاشتراكات التي تأخر عن أدائها."],"answer":3,"orig_answer":null,"law":"social","article":"7","status":"valid","explanation":"المادة (7/ب): فائدة تأخير واحد بالمائة شهرياً عن أي من الاشتراكات التي تأخر عن أدائها."},{"num":45,"type":"mcq","q":"لا يجوز الجمع بين عضوية أي من مجلس الإدارة أو مجلس التأمينات أو مجلس الاستثمار وتمثيل المؤسسة في رئاسة أو عضوية أي من هيئات مديري ومجالس إدارة الشركات التي تساهم فيها المؤسسة باستثناء:","o":["الشركات المملوكة بالكامل للمؤسسة.","الشركات المملوكة بالكامل للمؤسسة وبموافقة مجلس الوزراء على ذلك.","الشركات المملوكة بنسبة تزيد عن 50% للمؤسسة وبموافقة مجلس الوزراء على ذلك.","الشركات المملوكة بنسبة تقل عن 50% للمؤسسة."],"answer":1,"orig_answer":null,"law":"social","article":"17","status":"valid","explanation":"المادة (17/هـ): باستثناء الشركات المملوكة بالكامل للمؤسسة وبموافقة مجلس الوزراء."},{"num":46,"type":"mcq","q":"تلتزم المنشأة التي لم تقتطع الاشتراكات عن كل أو بعض العاملين لديها أو التي لم تؤد الاشتراكات على أساس الأجور الحقيقية زيادة أو نقصاناً بأن تؤدي غرامة قدرها:","o":["ثلاثون بالمائة من قيمة الاشتراكات التي لم تؤدها أو التي قامت بتأديتها زيادة عن المقرر دون شريطة إنذار أو إخطار مسبق من المؤسسة.","ثلاثون بالمائة من قيمة الاشتراكات التي لم تؤدها أو التي قامت بتأديتها زيادة عن المقرر دون إنذار أو إخطار مسبق من المؤسسة.","واحد بالمائة من قيمة الاشتراكات التي لم تؤدها أو التي قامت بتأديتها زيادة عن المقرر دون إنذار أو إخطار مسبق من المؤسسة شريطة أن لا تزيد عن اثنا عشر بالمئة سنوياً.","واحد بالمائة من قيمة الاشتراكات التي لم تؤدها أو التي قامت بتأديتها زيادة عن المقرر دون إنذار أو إخطار مسبق من المؤسسة."],"answer":1,"orig_answer":null,"law":"social","article":"22","status":"valid","explanation":"المادة (22/ج): غرامة ثلاثين بالمائة من الاشتراكات دون إنذار أو إخطار مسبق."},{"num":47,"type":"mcq","q":"في حال تأخر المنشأة عن إشعار المؤسسة بإصابة العمل فإنه يترتب عليها تحمّل:","o":["ما نسبته (15%) من تكاليف العناية الطبية المترتبة كامل البدل اليومي المستحق.","كامل تكاليف العناية الطبية المترتبة وما نسبته (15%) من البدل اليومي المستحق.","كامل تكاليف العناية الطبية المترتبة وكامل البدل اليومي المستحق.","ما نسبته (50%) من تكاليف العناية الطبية المترتبة وما نسبته (15%) من البدل اليومي المستحق."],"answer":0,"orig_answer":null,"law":"social","article":"27","status":"valid","explanation":"المادة (27/ج): تتحمل المنشأة 15% من تكاليف العناية الطبية وكامل البدل اليومي المستحق."},{"num":48,"type":"mcq","q":"إذا لم تقم المنشأة بإشعار المؤسسة بإصابة العمل للمؤمن عليه أو لذويه الحق في إشعار المؤسسة خلال مدة لا تتجاوز:","o":["أربعة عشر يوماً من تاريخ وقوعها.","ثلاثون يوماً من تاريخ وقوعها.","ثلاثة أشهر من تاريخ وقوعها.","أربعة أشهر من تاريخ وقوعها."],"answer":3,"orig_answer":null,"law":"social","article":"27","status":"valid","explanation":"المادة (27/د): للمؤمن عليه أو ذويه إشعار المؤسسة خلال مدة لا تتجاوز أربعة أشهر من تاريخ وقوعها."},{"num":49,"type":"mcq","q":"يصرف للمؤمن عليه بدل التعطل عن العمل وذلك في كل مرة يستحق فيها صرف هذا البدل إذا كان عدد اشتراكاته بأحكام هذا القانون أقل من (180) اشتراكاً وفقاً للمدة التالية:","o":["ستة أشهر.","خمسة أشهر.","أربعة أشهر.","ثلاثة أشهر."],"answer":3,"orig_answer":null,"law":"social","article":"52","status":"valid","explanation":"المادة (52/أ/1): ثلاثة أشهر إذا كانت الاشتراكات أقل من 180 اشتراكاً، وستة أشهر لـ180 فأكثر."},{"num":50,"type":"mcq","q":"يستحق المؤمن عليه الذكر راتب تقاعد الشيخوخة شريطة تحقق ما يلي:","o":["إكمال سن الخامسة والأربعين وأن تكون اشتراكاته في تأمين الشيخوخة والعجز والوفاة (180) اشتراكاً على الأقل منها (84) اشتراكاً فعلياً.","إكمال سن الخمسين وأن تكون اشتراكاته في تأمين الشيخوخة والعجز والوفاة (180) اشتراكاً على الأقل منها (84) اشتراكاً فعلياً.","إكمال سن الخامسة والخمسين وأن تكون اشتراكاته في تأمين الشيخوخة والعجز والوفاة (180) اشتراكاً على الأقل منها (84) اشتراكاً فعلياً.","إكمال سن الستين وأن تكون اشتراكاته في تأمين الشيخوخة والعجز والوفاة (180) اشتراكاً على الأقل منها (84) اشتراكاً فعلياً."],"answer":3,"orig_answer":null,"law":"social","article":"62","status":"valid","explanation":"المادة (62/أ): إكمال الذكر سن الستين و180 اشتراكاً منها 84 اشتراكاً فعلياً."},{"num":51,"type":"mcq","q":"عرف قانون الأوراق المالية المعلومات الداخلية بأنها:","o":["المعلومات غير المعلن عنها المتعلقة بمصدر أو أكثر أو بورقة مالية أو أكثر والتي قد تؤثر على سعر أي ورقة مالية في حال الإعلان ولا يشمل ذلك الاستنتاجات المبنية على الدراسات والبحوث والتحاليل الاقتصادية المالية.","المعلومات غير المعلن عنها المتعلقة بمصدر أو أكثر أو بورقة مالية أو أكثر والتي قد تؤثر على سعر أي ورقة مالية في حال الاعلان ويشمل ذلك الاستنتاجات المبنية على الدراسات والبحوث والتحاليل الاقتصادية المالية.","المعلومات غير المعلن عنها المتعلقة بمصدر أو أكثر أو بورقة مالية أو أكثر والتي قد لا تؤثر على سعر أي ورقة مالية في حال الاعلان ولا يشمل ذلك الاستنتاجات المبنية على الدراسات والبحوث والتحاليل الاقتصادية المالية.","المعلومات المعلن عنها المتعلقة بمصدر أو أكثر أو بورقة مالية أو أكثر والتي قد تؤثر على سعر أي ورقة مالية في حال الاعلان ولا يشمل ذلك الاستنتاجات المبنية على الدراسات والبحوث والتحاليل الاقتصادية المالية."],"answer":0,"orig_answer":null,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): المعلومات الداخلية هي غير المعلن عنها التي قد تؤثر على السعر ولا تشمل الاستنتاجات المبنية على الدراسات والبحوث."},{"num":52,"type":"mcq","q":"عرف قانون الأوراق المالية التسليم مقابل الدفع:","o":["طريقة من طرق التسوية يتم بموجبها بيع الأوراق المالية مقابل تسديد أثمانها.","طريقة من طرق التسوية يتم بموجبها تسليم الأسهم مقابل تسديد اثمانها.","طريقة من طرق التسوية يتم بموجبها تسليم الأوراق المالية والتجارية مقابل تسديد اثمانها.","طريقة من طرق التسوية يتم بموجبها تسليم الأوراق المالية مقابل تسديد اثمانها."],"answer":3,"orig_answer":null,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): التسليم مقابل الدفع طريقة من طرق التسوية يتم بموجبها تسليم الأوراق المالية مقابل تسديد أثمانها."},{"num":53,"type":"mcq","q":"عرف قانون الأوراق المالية شركة الاستثمار المشترك بأنها:","o":["الشركة المساهمة العامة التي تقتصر غاياتها على استثمار أموالها وأموال الغير في الأوراق المالية على اختلاف أنواعها بما فيها البنوك وشركات التأمين التي تمارس أعمالها بهذه الصفة.","الشركة المساهمة العامة وذات المسؤولية المحدودة التي تقتصر غاياتهما على استثمار أموالها وأموال الغير في الأوراق المالية على اختلاف أنواعها باستثناء البنوك وشركات التأمين التي تمارس أعمالها بهذه الصفة.","الشركة المساهمة العامة الخاصة التي تقتصر غاياتهما على استثمار أموالهم وأموال الغير في الأوراق المالية على اختلاف أنواعها باستثناء البنوك وشركات التأمين التي تمارس أعمالها بهذه الصفة.","الشركة المساهمة العامة التي تقتصر غاياتها على استثمار أموالها وأموال الغير في الأوراق المالية على اختلاف أنواعها باستثناء البنوك وشركات التأمين التي تمارس أعمالها بهذه الصفة."],"answer":3,"orig_answer":null,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): الشركة المساهمة العامة التي تقتصر غاياتها على استثمار أموالها وأموال الغير في الأوراق المالية باستثناء البنوك وشركات التأمين."},{"num":54,"type":"mcq","q":"عرف قانون الأوراق المالية الساري المفعول عرض التملك العام بأنه:","o":["أي عرض أو طلب يقصد به شراء أو بيع (40%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد أو حيازتها عن طريق المبادلة.","أي عرض يقصد به بيع (40%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد أو حيازتها عن طريق المبادلة.","أي عرض يقصد به شراء وبيع (40%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد أو حيازتها عن طريق المبادلة.","أي عرض يقصد به شراء (40%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد أو حيازتها عن طريق المبادلة."],"answer":3,"orig_answer":null,"law":"securities","article":"2","status":"valid","explanation":"المادة (2): عرض التملك العام أي عرض يقصد به شراء 40% أو أكثر من الأوراق المالية العائدة لمصدر واحد أو حيازتها بالمبادلة."},{"num":55,"type":"mcq","q":"وفقاً لقانون الأوراق المالية أي العبارات الآتية تعتبر صحيحة:","o":["على المصدر إعلام الهيئة والمركز والبورصة خطياً أو الكترونياً بأي تغيير يطرأ على المعلومات الواردة في نشرة الإصدار خلال خمسة أيام عمل بعد حال حدوثه سواء تم إعلان نفاذ النشرة أم لم يتم.","على المصدر إعلام الهيئة خطياً أو الكترونياً بأي تغيير يطرأ على المعلومات الواردة في نشرة الإصدار حال حدوثه سواء بعد إعلان نفاذ النشرة.","على المصدر إعلام الهيئة خطياً أو الكترونياً بأي تغيير يطرأ على المعلومات الواردة في نشرة الإصدار خلال خمسة أيام عمل بعد حدوثه سواء تم اعلان نفاذ النشرة أم لم يتم.","على المصدر اعلام الهيئة خطياً أو الكترونيا بأي تغيير يطرأ على المعلومات الواردة في نشرة الإصدار حال حدوثه سواء تم اعلان نفاذ النشرة أم لم يتم."],"answer":3,"orig_answer":null,"law":"securities","article":"40","status":"valid","explanation":"المادة (40): على المصدر إعلام الهيئة خطياً أو إلكترونياً بأي تغيير حال حدوثه سواء تم إعلان نفاذ النشرة أم لم يتم."},{"num":56,"type":"mcq","q":"وفقاً لقانون الأوراق المالية أي العبارات الاتية صحيحة:","o":["يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفض أي منهما خلال ستين يوماً من تاريخ دفع رسوم الترخيص أو الاعتماد إليها مستكملا الشروط والمتطلبات.","يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفض أي منهما خلال ستين يوماً من تاريخ تقديم الطلب اليها مستكملاً الشروط والمتطلبات.","يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفض أي منهما خلال خمس وأربعون يوما من تاريخ تقديم الطلب إليها مستكملا الشروط والمتطلبات.","يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفض أي منهما خلال ثلاثين يوما من تاريخ تقديم الطلب إليها مستكملا الشروط والمتطلبات."],"answer":1,"orig_answer":null,"law":"securities","article":"48","status":"valid","explanation":"المادة (48/هـ): خلال ستين يوماً من تاريخ تقديم الطلب مستكملاً الشروط والمتطلبات."},{"num":57,"type":"mcq","q":"وفقاً لقانون الأوراق المالية تخضع الأنظمة الداخلية والتعليمات الخاصة بالسوق المالي ومركز الإيداع المتعلقة بالتعامل بالأوراق المالية لموافقة:","o":["مجلس الأمة (النواب، الأعيان).","مجلس الوزراء.","المجلس: مجلس مفوضي هيئة الأوراق المالية.","مجلس إدارة كل منهما."],"answer":2,"orig_answer":null,"law":"securities","article":"70","status":"valid","explanation":"المادتان (70/أ) و(81/أ): يقدم السوق والمركز أنظمتهما الداخلية وتعليماتهما للمجلس (مجلس مفوضي الهيئة) للموافقة عليها."},{"num":58,"type":"mcq","q":"يتحمل الشخص المفوض بإدارة شركة التضامن مسؤولية ضمان أي ضرر يلحقه بالشركة أو يلحق بها إهماله أو تقصيره وتسقط هذه المسؤولية لأي سبب من الاسباب بانقضاء:","o":["تبقى مسؤوليته قائمة دون مدد.","(5) سنوات على انتهاء عمله في إدارة الشركة.","(2) سنة على انتهاء عمله في إدارة الشركة.","(1) سنة على انتهاء عمله في إدارة الشركة."],"answer":1,"orig_answer":null,"law":"companies","article":"18","status":"valid","explanation":"المادة (18/ب): تسقط المسؤولية بانقضاء خمس سنوات على انتهاء عمله في إدارة الشركة."},{"num":59,"type":"mcq","q":"إذا زادت خسائر الشركة ذات المسؤولية المحدودة على نصف رأسمالها فيترتب على مديرها أو هيئة المديرين فيها دعوة الهيئة العامة للشركة إلى اجتماع غير عادي لتصدر قرارها إما:","o":["أحالها الى النائب العام.","إقالة المدير العام أو هيئة المديرين.","تصفيتها تصفية إجبارية.","بتصفية الشركة أو استمرار قيامها بما يحقق تصحيح أوضاعها."],"answer":3,"orig_answer":null,"law":"companies","article":"75","status":"valid","explanation":"المادة (75/أ): تصدر الهيئة العامة غير العادية قرارها إما بتصفية الشركة أو باستمرار قيامها بما يحقق تصحيح أوضاعها."},{"num":60,"type":"mcq","q":"تاريخ اشهار الاعسار هو:","o":["تاريخ تقديم طلب الاعسار.","تاريخ صدور المحكمة باشهار الاعسار.","تاريخ صدور قرار من الوزير بإحالة الشركة للاعسار.","تاريخ صدور قرار من مراقب عام الشركات بإحالة الشركة للاعسار."],"answer":1,"orig_answer":null,"law":"insolvency","article":"2","status":"valid","explanation":"المادة (2): تاريخ إشهار الإعسار هو تاريخ صدور قرار المحكمة بإشهار الإعسار."},{"num":61,"type":"mcq","q":"المدة الممنوحة لوكيل الاعسار لتبليغ الدائنين المسجلين في قيود وسجلات المدين لدعوتهم للتقدم بمطالباتهم وفقاً للإجراءات المنصوص عليها في قانون الاعسار هي:","o":["لا يوجد مدة محددة.","لا تتجاوز خمسة أيام من تاريخ صدور قرار اشهار الاعسار.","لا تتجاوز أسبوعين من تاريخ صدور قرار اشهار الاعسار.","لا تتجاوز شهر من تاريخ صدور قرار اشهار الاعسار."],"answer":1,"orig_answer":null,"law":"insolvency","article":"14","status":"valid","explanation":"المادة (14/أ): خلال مدة لا تتجاوز خمسة أيام من تاريخ صدور قرار إشهار الإعسار."},{"num":62,"type":"mcq","q":"إذا كان طلب اشهار الاعسار مقدم من المدين يقوم بصلاحية إدارة أعماله:","o":["يقوم بصلاحية إدارة أعماله.","يحتفظ بصلاحية إدارة اعماله المعتادة تحت اشراف وكيل الاعسار.","تعلق صلاحيات المدين في إدارة أموال ذمة الاعسار والتصرف بها.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"insolvency","article":"17","status":"valid","explanation":"المادة (17/أ): إذا كان الطلب مقدماً من المدين يحتفظ بصلاحية إدارة أعماله المعتادة تحت إشراف وكيل الإعسار."},{"num":63,"type":"mcq","q":"يحظر التصرف بالسهم التأسيسي في الشركة المساهمة العامة قبل مرور:","o":["لا يوجد مدة محددة.","خمس سنوات على الأقل من تأسيس الشركة.","ثلاث سنوات على الأقل من تأسيس الشركة.","سنتين على الأقل من تأسيس الشركة."],"answer":3,"orig_answer":null,"law":"companies","article":"100","status":"valid","explanation":"المادة (100/أ): يحظر التصرف بالسهم التأسيسي قبل مرور سنتين على الأقل من تأسيس الشركة."},{"num":64,"type":"mcq","q":"يجوز للشركة المساهمة العامة أن تزيد رأسمالها المصرح به بموافقة هيئتها العامة إذا كان:","o":["قد اكتتب به بالكامل.","قد اكتتب به 75% منه.","قد اكتتب به 50% منه.","قد اكتتب به 25% منه."],"answer":0,"orig_answer":null,"law":"companies","article":"112","status":"valid","explanation":"المادة (112): بموافقة الهيئة العامة غير العادية إذا كان رأس المال المصرح به قد اكتتب به بالكامل."},{"num":65,"type":"mcq","q":"يشترط في إصدار اسناد القرض (غير القابلة للتحويل الى أسهم):","o":["موافقة النصف + 1 من أعضاء مجلس الإدارة.","موافقة ثلثي أعضاء مجلس إدارة الشركة.","موافقة كامل أعضاء مجلس إدارة الشركة.","موافقة الهيئة العامة في اجتماع غير عادي."],"answer":1,"orig_answer":null,"law":"companies","article":"117","status":"valid","explanation":"المادة (117): موافقة مجلس الإدارة بأغلبية ثلثي أعضائه، وتشترط موافقة الهيئة العامة غير العادية إذا كانت قابلة للتحويل."},{"num":66,"type":"mcq","q":"تحدد مكافأة رئيس وأعضاء مجلس الإدارة في الشركة المساهمة وفق الآتي:","o":["20% من الربح الصافي القابل للتوزيع على المساهمين بعد تنزيل جميع الضرائب والاحتياطات وبحد أقصى (10,000) دينار لكل منهم في السنة.","من الربح الصافي القابل للتوزيع على المساهمين بعد تنزيل جميع الضرائب والاحتياطات وبحد أقصى (5,000) دينار لكل منهم في السنة.","من الربح الصافي القابل للتوزيع على المساهمين بعد تنزيل جميع الضرائب والاحتياطات وبحد أقصى (10,000) دينار لكل منهم في السنة.","من الربح الصافي القابل للتوزيع على المساهمين بعد تنزيل جميع الضرائب والاحتياطات وبحد أقصى (5,000) دينار لكل منهم في السنة."],"answer":3,"orig_answer":null,"law":"companies","article":"162","status":"valid","explanation":"المادة (162/أ): 10% من الربح الصافي القابل للتوزيع وبحد أقصى 5,000 دينار لكل منهم (سقطت النسبة من الخيار في ورقة الامتحان)."},{"num":67,"type":"mcq","q":"إذا كانت الشركة المساهمة العامة في مرحلة التأسيس ولم تحقق بعد أرباحاً يجوز توزيع مكافأة سنوية لرئيس واعضاء مجلس الادارة بمعدل لا يتجاوز:","o":["لا يحق توزيع مكافأة.","5.000 دينار.","2.000 دينار.","10.000 دينار."],"answer":null,"orig_answer":null,"law":"companies","article":"162","status":"valid","explanation":"المادة (162/ب): يجوز توزيع مكافأة لا تتجاوز ألف دينار لكل عضو، وهذا المبلغ غير وارد في الخيارات فلا يوجد خيار صحيح."},{"num":68,"type":"mcq","q":"للهيئة العامة للشركة المساهمة العامة أن قرر في اجتماع غير عادي اطفاء خسائرها من المبالغ المتجمعة في حساب الاحتياطي الاجباري:","o":["في حال وجود احتياطي اختياري فقط.","في أي حال.","في حال استنفاد الاحتياطيات الأخرى.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"companies","article":"186","status":"valid","explanation":"المادة (186/ج): للهيئة العامة بعد استنفاد الاحتياطيات الأخرى أن تقرر في اجتماع غير عادي إطفاء الخسائر من الاحتياطي الإجباري."},{"num":69,"type":"mcq","q":"ينشأ حق المساهم في الارباح السنوية للشركة المساهمة العامة:","o":["عند إصدار وإقرار البيانات المالية.","عند صدور قرار من مجلس الإدارة بتوزيعها.","عند صدور قرار من الهيئة العامة بتوزيعها.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"companies","article":"191","status":"valid","explanation":"المادة (191/أ): ينشأ حق المساهم في الأرباح بصدور قرار الهيئة العامة بتوزيعها."},{"num":70,"type":"mcq","q":"إذا اطلع مدقق الحسابات على أي مخالفة ارتكبتها الشركة لقانون الشركات أو نظام الشركة أو اي امور مالية ذات اثر سلبي على اوضاع الشركة المالية أو الإدراية فعليه أن يبلغ ذلك خطياً الى:","o":["الهيئة والسوق.","مجلس الإدارة والمراقب والهيئة والسوق.","مراقب عام الشركات فقط.","مجلس الإدارة فقط."],"answer":1,"orig_answer":null,"law":"companies","article":"200","status":"valid","explanation":"المادة (200): يبلغ المدقق خطياً رئيس مجلس الإدارة والمراقب والهيئة والسوق المالي."},{"num":71,"type":"essay","q":"السؤال الأول (علامتان): ما هي شروط إعفاء دخل الشركة المعفاة المسجلة وفقاً لقانون الشركات من ضريبة الدخل؟","law":"income","article":"4","status":"valid","model_answer":"- المادة (4/ج/3) من قانون ضريبة الدخل: يعفى دخل الشركة المعفاة المسجلة بموجب قانون الشركات المتأتي لها من مزاولة أعمالها خارج المملكة.\n- يستثنى من الإعفاء الدخل المتأتي لها من مصادر دخل خاضعة للضريبة في المملكة.\n- تحدد الأحكام والشروط بنظام يصدر لهذه الغاية.\n- قانون الشركات م(211-212): الشركة المعفاة مساهمة عامة أو ذات مسؤولية محدودة أو مساهمة خاصة تسجل في المملكة وتزاول أعمالها خارجها، ولا يجوز لها طرح أسهمها للاكتتاب في المملكة."},{"num":72,"type":"essay","q":"السؤال الثاني (علامتان): الشركة الأردنية تعمل في مجال بيع السيارات والإطارات ومركزها الرئيسي في عمان ولديها فرع في العقبة ولديك المعلومات التالية:\nأ- بلغت مبيعات الشركة 800 ألف دينار (300 ألف مبيعات عمان و500 ألف مبيعات فرع العقبة).\nب- بلغت المصاريف الكلية للشركة 255.000 دينار موزعة كما يلي:\n| البيان | المركز الرئيسي (عمان) | فرع العقبة |\n| الاستهلاكات | 48.000 | 51.000 |\n| م. بيع وتوزيع | 22.800 | 25.600 |\n| م. إدارية | 12.000 | 19.200 |\n| م. تمويل | 37.200 | 39.200 |\n| المجموع | 120.000 | 135.000 |\nج- تم رد مبلغ (6.000 دينار) من المصاريف من قبل المدقق الضريبي بسبب عدم التعزيز.\nالمطلوب: احتساب قيمة المصاريف المشتركة الواجب ردها من مصاريف المركز الرئيسي في عمان حسب المادة 9 من التعليمات التنفيذية رقم 8 لسنة 2015 بسبب أن بعض المصاريف المشتركة لا يمكن فصلها.","law":"income","article":"","status":"unverified","model_answer":"- عند تعذر فصل المصاريف المشتركة توزع على الأنشطة/المناطق بنسبة الإيرادات (التعليمات التنفيذية 8/2015 م9)، لأن دخل فرع العقبة يخضع لنسبة مختلفة.\n- المصاريف المقبولة بعد رد غير المعزز: 255,000 − 6,000 = 249,000.\n- نصيب عمان = 249,000 × (300,000 ÷ 800,000) = 93,375 دينار.\n- المصاريف المسجلة على عمان بعد الرد (بافتراض أن الـ6,000 من مصاريف عمان) = 114,000؛ الواجب رده = 114,000 − 93,375 = 20,625 دينار.\n- (بدون اعتبار الـ6,000: 255,000 × 37.5% = 95,625، والزيادة 120,000 − 95,625 = 24,375)."},{"num":73,"type":"essay","q":"السؤال الثالث (علامة واحدة): مصنع (س) ينتج سلع خاضعة لضريبة المبيعات بنسبة 16% قام ببيع بضاعة بقيمة 10.000 دينار إلى شركة (ص) بموجب بيان جمركي إدخال المنطقة الحرة بناءاً على طلب الشركة (ص) علماً بأن الشركة (ص) ليست مسجله بالمنطقة الحرة. قامت الشركة (ص) ببيع البضاعة إلى شركة مصرية بموجب بيان جمركي تصديري بمبلغ 11.000 دينار.\nالمطلوب:\nأ- احتساب ضريبة المبيعات المستحقة على المصنع (س).\nب- احتساب ضريبة المبيعات المستحقة على الشركة (ص).","law":"sales","article":"20","status":"unverified","model_answer":"- أ) لا يعامل البيع كتصدير بنسبة الصفر لأن المشتري (ص) غير مسجل في المنطقة الحرة، فيعتبر بيعاً محلياً: الضريبة على (س) = 10,000 × 16% = 1,600 دينار.\n- ب) بيع (ص) للشركة المصرية بموجب بيان تصدير يخضع لنسبة الصفر: ضريبة المخرجات = صفر.\n- يحق لـ(ص) إن كانت مسجلة خصم أو استرداد الـ1,600 المدفوعة على المشتريات المصدرة (م19 وم20/أ)."},{"num":74,"type":"essay","q":"السؤال الرابع (علامتان): بتاريخ 2022/1/1 بلغت شركة الشركة حد التسجيل في الشبكة العامة لضريبة المبيعات وقررت التسجيل ولدى جرد المستودعات تبين ما يلي: كلفة البضاعة في المستودع عند الجرد 100.000 دينار ولتقديم كشوف الجرد التفصيلية لدائرة ضريبة الدخل والمبيعات وبالرجوع إلى فواتير الشراء تبين النتائج التالية:\n| الكلفة - دينار | تاريخ الشراء | نسبة الضريبة | المستندات |\n| 15.000 | 2021/1 | 16% | فواتير ضريبية رسمية |\n| 15.000 | 2020/1 | 16% | فواتير ضريبية رسمية |\n| 15.000 | 2019/1 | 16% | فواتير ضريبية رسمية |\n| 15.000 | 2018/1 | 16% | فواتير ضريبية رسمية |\n| 15.000 | 2017/1 | 16% | فواتير ضريبية رسمية |\n| 15.000 | 2016/1 | 16% | فواتير ضريبية رسمية |\n| 10.000 | 2015/1 | 16% | فواتير غير ضريبية |\nالمطلوب احتساب الضريبة الواجب تخصيمها عند التسجيل؟","law":"sales","article":"19","status":"unverified","model_answer":"- المادة (19/د): يخصم المسجل ما سبق له تحمله قبل التسجيل من ضريبة عامة على السلع التي تكون في حوزته عند التسجيل، بشرط وجود فواتير ضريبية رسمية (وضمن المدة التي تحددها التعليمات التنفيذية).\n- تستبعد بضاعة 2015 (10,000) لأن فواتيرها غير ضريبية.\n- إذا اعتبرت جميع الفواتير الرسمية مقبولة: 6 × 15,000 = 90,000 × 16% = 14,400 دينار.\n- ملاحظة: إذا كانت التعليمات تقيد الخصم بمدة معينة قبل التسجيل يقتصر الخصم على الفواتير ضمن تلك المدة."},{"num":75,"type":"essay","q":"السؤال الخامس (علامتان): ما قيمة ضريبة المبيعات مستحقة الدفع على الشركة خلال الفترة الضريبية التي كانت نتيجة نشاط الشركة المبينة على النحو التالي:\n| 10.000 | ضريبة مبيعات مدفوعة عن المشتريات |\n| 8.000 | ضريبة مبيعات محصلة عن المبيعات |\n| 40.000 | قيمة المبيعات لجهات خاضعة لنسبة الصفر |\n| 40.000 | قيمة المبيعات المصدرة |\n| 40.000 | قيمة المبيعات المعفاة |","law":"sales","article":"19","status":"unverified","model_answer":"- المادة (19): تخصم ضريبة المدخلات المتعلقة بالمبيعات الخاضعة (بما فيها نسبة الصفر والتصدير) ولا تخصم المتعلقة بالمبيعات المعفاة، وعند الاشتراك يتم الخصم بالتناسب.\n- المبيعات الخاضعة بالنسبة العامة = 8,000 ÷ 16% = 50,000؛ المبيعات المؤهلة للخصم = 50,000 + 40,000 + 40,000 = 130,000 من أصل 170,000.\n- الضريبة القابلة للخصم = 10,000 × 130/170 = 7,647 دينار تقريباً.\n- الضريبة مستحقة الدفع = 8,000 − 7,647 = 353 دينار تقريباً."},{"num":76,"type":"essay","q":"السؤال السادس (علامة واحدة): يجب على كل تاجر أن ينظم على الاقل ثلاث دفاتر اذكرها واذكر مدة الاحتفاظ بها بعد اختتامها.","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","model_answer":"- دفتر اليومية.\n- دفتر صور الرسائل (المراسلات).\n- دفتر الجرد والميزانية.\n- يحتفظ بها مدة عشر سنوات بعد اختتامها."},{"num":77,"type":"essay","q":"السؤال السابع (علامة واحدة): الأوراق التجارية هي اسناد قابلة للتداول وتشمل سند السحب وسند الأمر عرفها.","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","model_answer":"- سند السحب (البوليصة): محرر مكتوب وفق شكل محدد قانوناً يتضمن أمراً من الساحب إلى المسحوب عليه بدفع مبلغ معين لأمر المستفيد أو لحامله في تاريخ معين أو قابل للتعيين أو لدى الاطلاع.\n- سند الأمر (الكمبيالة): محرر مكتوب وفق شكل محدد قانوناً يتعهد بموجبه محرره بدفع مبلغ معين لأمر المستفيد في تاريخ معين أو قابل للتعيين أو لدى الاطلاع."},{"num":78,"type":"essay","q":"السؤال الثامن (علامتان): يحظر على المحاسب القانوني المزاول لأعمال التدقيق أو المحاسبة القيام ببعض الأعمال لمخالفتها لإحكام قانون المهنة أذكر أربعا منها.","law":"accounting","article":"","status":"unverified","model_answer":"- (المحظورات تفصيلها في نظام مزاولة المهنة وقواعد السلوك المهني الصادرة بمقتضى المادة 27) ومنها:\n- تدقيق حسابات جهة يكون شريكاً أو مساهماً مؤثراً فيها أو موظفاً لديها أو له فيها مصلحة مادية، أو يكون عضواً في مجلس إدارتها أو قريباً لأحد أعضائه.\n- الجمع بين تدقيق حسابات جهة ومسك حساباتها أو تقديم خدمات تخل باستقلاله.\n- إشراك غير المحاسبين القانونيين في الأتعاب أو العمل باسم غيره أو السماح لغيره بالعمل باسمه.\n- الإعلان عن نفسه بصورة تخالف آداب المهنة أو تقاضي أتعاب مشروطة بنتيجة العمل.\n- إفشاء أسرار العميل (م27/ب)."},{"num":79,"type":"essay","q":"السؤال التاسع (علامة واحدة): عرف الاعسار الوشيك:","law":"insolvency","article":"2","status":"valid","model_answer":"- المادة (2): الإعسار الوشيك هو الحالة التي يتوقع فيها أن يفقد المدين القدرة المستقبلية على سداد ديونه عند استحقاقها خلال ستة أشهر رغم قدرته الحالية على سدادها."},{"num":80,"type":"essay","q":"السؤال العاشر (علامة واحدة): عرف عقد التأمين:","law":"insurance","article":"2","status":"valid","model_answer":"- المادة (2) من قانون تنظيم أعمال التأمين رقم 12 لسنة 2021: اتفاق تلتزم بمقتضاه شركة التأمين أن تؤدي إلى المؤمن له أو المستفيد عوضاً مالياً أو أي منفعة أخرى عند تحقق الخطر المؤمن منه أو حدوث الواقعة المحددة في العقد، مقابل مبلغ محدد أو أقساط يؤديها المؤمن له."},{"num":81,"type":"essay","q":"السؤال الحادي عشر (علامة ونصف): أذكر أنشطة التأجير التي تخضع لإحكام قانون التأجير التمويلي رقم (45) لسنة 2008. تعتبر الأنشطة التالية من أنشطة التأجير وتخضع لإحكام هذا القانون:","law":"leasing","article":"4","status":"valid","model_answer":"- المادة (4):\n- البيع وإعادة الاستئجار: يبيع المورد المال إلى المؤجر ثم يعيد استئجاره منه.\n- التأجير اللاحق: يعيد المؤجر تأجير المأجور إلى مستأجر جديد بعد فسخ عقد التأجير مع مستأجر سابق.\n- التأجير من الباطن: يقوم المستأجر بموافقة خطية مسبقة من المؤجر بتأجير المأجور إلى شخص ثالث مقابل بدل إيجار."},{"num":82,"type":"essay","q":"السؤال الثاني عشر (علامة واحدة): حسب المادة 16 من قانون رسوم الطوابع والواردات لسنة 2001 لوزير المالية إعادة الرسوم المستوفاة في حالات محددة اذكر اثنين منها.","law":"stamp","article":"16","status":"valid","model_answer":"- المادة (16/أ):\n- إذا تلفت الطوابع التي في حيازة أي شخص دون تقصير متعمد منه بصورة يتعذر معها استعمالها.\n- إذا ألصق المكلف طوابع أو دمغها بمبلغ يزيد على الرسم المستحق.\n- إلغاء المعاملة الخاضعة لرسوم الطوابع.\n- يحسم لحساب الخزينة 10% من الرسوم المعادة (م16/ب)."},{"num":83,"type":"essay","q":"السؤال الثالث عشر (علامة ونصف): اذكر ثلاث مهام التي يقوم بها البنك المركزي نيابة عن الحكومة وفقاً لما ورد في قانون البنك المركزي الأردني رقم (23) لسنة 1971 وتعديلاته؟","law":"other:قانون البنك المركزي الأردني رقم (23) لسنة 1971","article":"","status":"unverified","model_answer":"- العمل كبنك للحكومة ووكيل مالي لها والاحتفاظ بحساباتها وتنفيذ مدفوعاتها.\n- إدارة الدين العام نيابة عن الحكومة وإصدار سندات وأذونات الخزينة وخدمتها.\n- تقديم المشورة للحكومة في الشؤون المالية والاقتصادية.\n- إدارة احتياطيات المملكة من العملات الأجنبية والذهب وتمثيل الحكومة في المؤسسات المالية الدولية.\n(القانون غير مدرج للتحقق من الصياغة)"},{"num":84,"type":"essay","q":"السؤال الرابع عشر (علامة ونصف): عدد الفئات التي لا تخضع لأحكام قانون الضمان الاجتماعي؟","law":"social","article":"4","status":"valid","model_answer":"- المادة (4/ب):\n- الأشخاص الذين يؤدون اشتراكات تقاعدية وفق قانون التقاعد المدني أو العسكري.\n- غير الأردنيين العاملون لدى البعثات الإقليمية والدولية والسياسية والعسكرية العربية والأجنبية والملحقيات والمراكز التابعة لها.\n- العمال الذين تكون علاقتهم بصاحب العمل غير منتظمة (تعتبر منتظمة إذا عمل 16 يوماً فأكثر في الشهر للمياومة وبالساعة/القطعة، والأجر الشهري بغض النظر عن الأيام)."},{"num":85,"type":"essay","q":"السؤال الخامس عشر (علامة ونصف): عدد الحالات التي يسقط حق المصاب في البدل اليومي وفي تعويض الدفعة الواحدة المنصوص عليه في قانون الضمان الاجتماعي؟","law":"social","article":"31","status":"valid","model_answer":"- المادة (31/أ):\n- إذا نشأت الإصابة عن فعل متعمد من المصاب.\n- إذا نشأت بسبب تعاطي المشروبات الروحية أو المخدرات أو المؤثرات العقلية أو العقاقير الخطرة.\n- إذا خالف المصاب تعليمات العلاج أو السلامة والصحة المهنية المعلنة وكانت المخالفة سبباً أساسياً للإصابة أو ذات أثر مهم في وقوعها أو تأخر شفائها.\n- لا يسري ذلك إذا نشأ عن الإصابة وفاة المصاب أو عجز (م31/ج)."},{"num":86,"type":"essay","q":"السؤال السادس عشر (علامتان ونصف): وفقاً لأحكام قانون الأوراق المالية عدد الحالات الخمس التي يحق للمرخص له بالتمويل على الهامش تحديد حقوقه المتعلقة بالأوراق المالية الخاصة بأي من عملائه دون الرجوع إليه؟","law":"securities","article":"55","status":"valid","model_answer":"- المادة (55/د):\n- وفاة العميل.\n- صدور قرار بتصفية العميل.\n- شهر إفلاسه.\n- الحجر عليه.\n- صدور أمر حجز عن سلطة مختصة على الأوراق المالية العائدة لعميله.\n- وعليه إعلام الهيئة والمركز خلال يوم العمل الثاني ثم البيع بالقدر الكافي لاستيفاء حقوقه (م55/هـ)."},{"num":87,"type":"essay","q":"السؤال السابع عشر (ثلاث علامات):\n1. عرّف الشركة المدنية.\n2. عرّف الشريك الموصي؟\n3. عرّف رأس مال الشركة المساهمة الخاصة وهل يجوز أن يكون بالعملة الأجنبية وبين الحد الأدنى لرأسمال الشركة المساهمة الخاصة؟","law":"companies","article":"7","status":"valid","model_answer":"- الشركة المدنية (م7/ج): الشركات التي تؤسس بين شركاء من ذوي الاختصاص والمهن وتخضع لأحكام القانون المدني والقوانين الخاصة بها وعقودها وأنظمتها الداخلية، وتسجل في سجل الشركات المدنية.\n- الشريك الموصي (م41/ب): يشارك في رأس المال دون أن يحق له إدارة الشركة أو ممارسة أعمالها، ويكون مسؤولاً عن ديونها بمقدار حصته في رأس المال.\n- رأس مال المساهمة الخاصة (م66 مكرر): مجموع القيم الاسمية لأسهم الشركة، ويحدد بالدينار الأردني (لا يجوز بالعملة الأجنبية)، وحده الأدنى للمكتتب به خمسون ألف دينار."},{"num":88,"type":"essay","q":"السؤال الثامن عشر (علامة واحدة): عرّف ذمة الاعسار الواردة في قانون الاعسار رقم (21) لسنة 2018؟","law":"insolvency","article":"2","status":"valid","model_answer":"- المادة (2): الأموال والحقوق المادية والمعنوية العائدة للمدين في تاريخ إشهار الإعسار أو بعده، دون أن تشمل الأموال والحقوق العائدة للشخص الطبيعي المستثناة من الحجز بموجب أحكام القانون (وانظر م59)."},{"num":89,"type":"essay","q":"السؤال التاسع عشر (علامة ونصف): اذكر البنود الواردة في نظام تصفية الشركات رقم (6) لسنة 2021 التي يجب أن يتضمّنها قرار الهيئة العامة للشركة في اجتماعها غير العادي لتصفية الشركة تصفية اختيارية؟","law":"other:نظام تصفية الشركات رقم (6) لسنة 2021","article":"","status":"unverified","model_answer":"- (النظام غير مدرج للتحقق) ويتضمن القرار عادة:\n- الموافقة على تصفية الشركة تصفية اختيارية وأسبابها.\n- تعيين المصفي (أو أكثر) وتحديد أتعابه.\n- تحديد صلاحيات المصفي والمدة اللازمة لإتمام التصفية.\n- الإقرار بقدرة الشركة على الوفاء بالتزاماتها (إقرار الملاءة) وتحديد تاريخ بدء التصفية.\n- تفويض المصفي باتخاذ إجراءات النشر والتسجيل لدى المراقب."}]},{"id":"2022-02","year":2022,"month":2,"label":"دورة شباط 2022","session":"شباط","src":"5d334b48.json","questions":[{"num":1,"type":"mcq","q":"يُعرف الدخل الخاضع للضريبة:","o":["ما تبقى من الدخل الصافي بعد تنزيل المصاريف المقبولة والخسارة المدورة من الفترات الضريبية السابقة والتبرعات والإعفاءات الشخصية على التوالي.","ما تبقى من الدخل الصافي بعد تنزيل المصاريف المقبولة والخسارة المدورة من الفترات الضريبية السابقة والإعفاءات الشخصية والتبرعات على التوالي.","الدخل الإجمالي بعد تنزيل المصاريف والخسارة المدورة من الفترات السابقة والتبرعات والإعفاءات.","الدخل الإجمالي بعد تنزيل المصاريف والخسارة المدورة من الفترات السابقة."],"answer":1,"orig_answer":null,"law":"income","article":"2","status":"valid","explanation":"المادة (2): الدخل الخاضع للضريبة ما يتبقى من الدخل الصافي بعد تنزيل الخسارة المدورة والإعفاءات الشخصية والتبرعات على التوالي، وهو الترتيب الوارد في (ب)."},{"num":2,"type":"mcq","q":"أي من العبارات التالية صحيحة حسب قانون ضريبة الدخل (الشركة المالية):","o":["الشركة المرخصة لممارسة الأعمال المصرفية في المملكة بما في ذلك شركة الصرافة وشركة التمويل وفقاً لقانون البنك.","الشركة المالية المعرفة وفقاً لقانون ضريبة الدخل بما في ذلك شركة الصرافة وشركة التمويل.","الشركة المالية المعرفة وفقاً لقانون البنك المركزي بما في ذلك شركة الصرافة وشركة التمويل.","الشركة المالية المعرفة وفقاً لقانون البنوك بما في ذلك شركة الصرافة وشركة التمويل."],"answer":3,"orig_answer":null,"law":"income","article":"2","status":"valid","explanation":"المادة (2): الشركة المالية هي الشركة المالية المعرفة وفقاً لقانون البنوك بما في ذلك شركة الصرافة وشركة التمويل."},{"num":3,"type":"mcq","q":"أي من العبارات التالية خطأ حسب قانون ضريبة الدخل:","o":["تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 24% عن كل دينار لشركات توزيع الكهرباء وشركات تعدين المواد الأساسية وشركات التأمين وشركات إعادة التأمين وشركات الوساطة المالية والشركات المالية والأشخاص الاعتباريين الذين يمارسون أنشطة التأجير التمويلي.","تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 35% عن كل دينار للبنوك.","تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 24% عن كل دينار لجميع شركات الاتصالات.","تستوفى الضريبة عن الدخل الخاضع للضريبة بنسبة 20% عن كل دينار لجميع الأشخاص الاعتباريين باستثناء ما ورد في (أ+ج)."],"answer":2,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2): نسبة 24% تخص شركات الاتصالات الأساسية فقط وليس جميع شركات الاتصالات، لذا (ج) خطأ."},{"num":4,"type":"mcq","q":"الدخل التالي يخضع للضريبة باستثناء:","o":["الدخل الناجم عن التجارة الالكترونية للسلع والخدمات.","الدخل التالي لشركات رأس المال المغامر المعرفة والمسجلة وفق قانون الشركات.","الدخل الصافي الذي يتحقق للشخص المقيم من أي مصدر خارج المملكة شريطة أن يكون قد نشأ عن أموال أو ودائع من المملكة.","بدل الخدمة الذي يجنيه الشخص غير المقيم من المملكة والناشئ عن خدمة قدمها لأي شخص إذا تمت مزاولة العمل أو النشاط المتعلق بذلك اليد في المملكة أو إذا تم استخدام مخرجات هذه الخدمة داخلها."],"answer":1,"orig_answer":null,"law":"income","article":"4","status":"valid","explanation":"المادة (4/أ/6): يعفى الدخل المتأتي لشركات رأس المال المغامر المعرفة والمسجلة وفق قانون الشركات."},{"num":5,"type":"mcq","q":"حسب قانون ضريبة الدخل النشاط الزراعي يعني التالي باستثناء:","o":["تربية الأسماك والطيور والنحل بما في ذلك إنتاج البيض والعسل.","إنتاج المحاصيل والحبوب والخضروات والفواكه والنباتات والزهور والأشجار.","تربية وتجارة المواشي والأسماك والطيور.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"income","article":"5","status":"valid","explanation":"المادة (5/ج): النشاط الزراعي يشمل إنتاج المحاصيل وتربية المواشي والأسماك والطيور والنحل، ولا يشمل تجارة المواشي."},{"num":6,"type":"mcq","q":"أرباح شركات إعادة التأمين غير العاملة في المملكة الناجمة في المملكة عن عقود التأمين التي تبرمها معها شركات التأمين العاملة في المملكة تخضع بنسبة:","o":["معفاة من ضريبة الدخل.","20%.","10%.","15%."],"answer":0,"orig_answer":null,"law":"income","article":"4","status":"valid","explanation":"المادة (4/أ/17): تعفى أرباح شركات إعادة التأمين غير العاملة في المملكة الناجمة عن عقود التأمين مع شركات التأمين العاملة فيها."},{"num":7,"type":"mcq","q":"حسب قانون ضريبة الدخل في حال تملك إحدى الشركات كلياً أو جزئياً نسبة لا تقل عن 10% من رأسمال شركة أخرى فلا يجوز تقاضي الضريبة عن أرباح الشركة المالكة للشركة المملوكة بنسبة تزيد على:","o":["20% من مقدار أرباحها في تلك الأرباح.","10% من مقدار أرباحها في تلك الأرباح.","15% من مقدار أرباحها في تلك الأرباح.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ي): لا يجوز تقاضي الضريبة عن أرباح الشركة المالكة بنسبة تزيد على (10%) من مقدار أرباحها في تلك الأرباح."},{"num":8,"type":"mcq","q":"للتوصل إلى رصيد الضريبة المستحقة يجري تقاص ما نسبته ........ من ضريبة الأبنية والأراضي داخل مناطق أمانة عمان الكبرى والبلديات التي يدفعها المكلف في أي سنة عن العقارات المؤجرة التي تأتي منها دخل من ضريبة الدخل المستحقة عليه بمقتضى أحكام قانون ضريبة الدخل.","o":["100% على أن لا يتجاوز التقاص المسموح به مقدار الضريبة المستحقة على هذا الدخل عن تلك السنة ومع مراعاة نسبة هذا الدخل إلى الدخل الإجمالي للمكلف.","25% من مقدار الضريبة المستحقة على هذا الدخل عن تلك السنة ومع مراعاة نسبة هذا الدخل إلى الدخل الإجمالي للمكلف.","50% من مقدار الضريبة المستحقة على هذا الدخل عن تلك السنة ومع مراعاة نسبة هذا الدخل إلى الدخل الإجمالي للمكلف.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"income","article":"18","status":"valid","explanation":"المادة (18/ب): يجري تقاص (100%) من ضريبة الأبنية والأراضي على ألا يتجاوز الضريبة المستحقة على هذا الدخل ومع مراعاة نسبته إلى الدخل الإجمالي."},{"num":9,"type":"mcq","q":"يلتزم المكلف الذي يمارس أنشطة أعمال وتجاوز دخله الإجمالي من هذه الأنشطة في الفترة الضريبية السابقة ........... بتوريد الدفعات النصف سنوية المقدمة على حساب الضريبة المستحقة على الدخل المتأتي من تلك الأنشطة وفق المواعيد المحددة:","o":["مليون دينار خلال النصف الأول من العام السابق.","مليون و500 ألف.","مليون دينار.","500 ألف دينار."],"answer":2,"orig_answer":null,"law":"income","article":"19","status":"valid","explanation":"المادة (19/ب): يلزم بالدفعات المقدمة من تجاوز دخله الإجمالي من أنشطة الأعمال في الفترة السابقة مليون دينار."},{"num":10,"type":"mcq","q":"يلتزم المكلف بتنظيم السجلات والبيانات المالية اللازمة لتحديد مقدار الضريبة المستحقة عليه شريطة أن تكون معدة وفق معايير المحاسبة الدولية ومدققة ومصادق عليها من محاسب قانوني وبالاحتفاظ بها لمدة أربع سنوات تبدأ من آخر أي تاريخ:","o":["تبليغ الإشعار بنتيجة التقدير الإداري.","إنهاء الفترة الضريبية التي تم تنظيم السجلات.","تقديم الإقرار الضريبي.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"income","article":"23","status":"valid","explanation":"المادة (23/أ): الاحتفاظ أربع سنوات من آخر التواريخ: انتهاء الفترة الضريبية، تقديم الإقرار، تبليغ إشعار التقدير الإداري."},{"num":11,"type":"mcq","q":"يترتب على الشخص المرخص له مزاولة مهنة محاسب قانوني في المملكة أن يقدم لدائرة ضريبة الدخل والمبيعات بياناً بأسماء عملائه وعناوينهم خلال مدة لا تتجاوز ........... من السنة اللاحقة للسنة المالية:","o":["الشهر الثاني.","الشهر الأول.","الشهر الثالث.","الشهر الرابع مع الإقرار الضريبي."],"answer":2,"orig_answer":null,"law":"income","article":"25","status":"valid","explanation":"المادة (25): يقدم المحاسب القانوني بيان أسماء عملائه وعناوينهم خلال مدة لا تتجاوز نهاية الشهر الثالث من السنة اللاحقة."},{"num":12,"type":"mcq","q":"تصدر هيئة الاعتراض قراراً معللاً بشأن الاعتراض خلال ........ من تاريخ تقديم الاعتراض ولها تأييد القرار المعترض عليه أو تعديله سواءً بزيادة الضريبة أو تخفيضها أو إلغائها:","o":["مئة وعشرون يوماً.","تسعون يوماً.","ستون يوماً.","ثلاثون يوماً."],"answer":1,"orig_answer":null,"law":"income","article":"33","status":"valid","explanation":"المادة (33/ز): تصدر هيئة الاعتراض قرارها المعلل خلال تسعين يوماً من تاريخ تقديم الاعتراض."},{"num":13,"type":"mcq","q":"للمحكمة المختصة وفق المادة (46) من أحكام قانون ضريبة الدخل أن:","o":["أن تؤيد ما ورد في القرار المطعون فيه أو تخفض أو تلغي الضريبة والمبالغ الأخرى المقررة بموجبه.","أن تؤيد ما ورد في القرار المطعون فيه أو تخفض أو تزيد أو تلغي الضريبة والمبالغ الأخرى المقررة بموجبه.","أن تعيد القضية إلى مصدر القرار المطعون فيه لإعادة النظر فيه.","أ+ج."],"answer":3,"orig_answer":null,"law":"income","article":"46","status":"valid","explanation":"المادة (46/ب): للمحكمة تأييد القرار أو تخفيض الضريبة أو إلغاؤها (دون زيادة) ولها إعادة القضية لمصدر القرار لإعادة النظر."},{"num":14,"type":"mcq","q":"يعين أعضاء النيابة العامة الضريبية بقرار من:","o":["وزير العدل.","وزير المالية.","المجلس القضائي.","مدير عام ضريبة الدخل والمبيعات."],"answer":2,"orig_answer":null,"law":"income","article":"55","status":"valid","explanation":"المادة (55/ب): يعين أعضاء النيابة العامة الضريبية بقرار من المجلس القضائي."},{"num":15,"type":"mcq","q":"حسب قانون الضريبة العامة على المبيعات أي من العبارات التالية غير صحيحة:","o":["لا تخضع للضريبة السلع والخدمات المهربة.","لا يخضع للضريبة العامة على المبيعات بيع الأموال غير المنقولة.","تستحق الضريبة العامة والخاصة على السلع المستوردة في مرحلة التخليص عليها حسب نسبة الضريبة أو فئتها في تاريخ تسجيل البيان.","تستحق الضريبة على بيع الخدمة عند إصدار فاتورة ضريبية وعند تسلم بدل الخدمة كلياً أو جزئياً أيهما أسبق."],"answer":0,"orig_answer":null,"law":"sales","article":"12","status":"valid","explanation":"المادة (12): تخضع للضريبة السلع والخدمات المهربة حسب الفئات النافذة بتاريخ التهرب، فالعبارة (أ) غير صحيحة."},{"num":16,"type":"mcq","q":"الخدمة المستوردة هي:","o":["الخدمة المؤداة داخل وخارج المملكة من أشخاص مقيمين وغير مقيمين أو مؤسسة أجنبية وبغض النظر عن موقع فروعها.","الخدمة المؤداة من أشخاص غير مقيمين أو من شركات أو مؤسسات أجنبية لها فروع عاملة داخل المملكة.","الخدمة المؤداة من أشخاص مقيمين أو من شركات أو مؤسسات أجنبية ليس لها فروع عاملة داخل المملكة.","الخدمة المؤداة من أشخاص غير مقيمين أو من شركات أو مؤسسات أجنبية ليس لها فروع عاملة داخل المملكة."],"answer":null,"orig_answer":3,"law":"sales","article":"4 مكرر","status":"changed","explanation":"كان القانون يعرّف الخدمة المستوردة بأنها المؤداة من غير مقيمين أو مؤسسات أجنبية ليس لها فروع عاملة في المملكة (د)؛ ألغي هذا التعريف وحل محله مفهوم (استيراد الخدمات) وفق المادة (4 مكرر/هـ) المرتبط بمكان متلقي الخدمة."},{"num":17,"type":"mcq","q":"حسب قانون الضريبة العامة على المبيعات على مستورد الخدمة دفع الضريبة المستحقة عليها للدائرة:","o":["خلال ستة أشهر من تاريخ تلقي الخدمة أو أي جزء منها وذلك بحدود ما يتعلق بذلك الجزء.","خلال شهر واحد من دفع بدل الخدمة المستوردة أو أي جزء منه وذلك بحدود ما يتعلق بذلك الجزء.","عند إفراج السلطات الجمركية عن المادة التي قدمت بواسطتها تلك الخدمة.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج): يدفع مستورد الخدمة الضريبة عند أي من الحالات أيها أسبق: خلال شهر من دفع البدل، عند الإفراج الجمركي، خلال ستة أشهر من تلقي الخدمة."},{"num":18,"type":"mcq","q":"حسب تعليمات تحرير الفاتورة الضريبية لضريبة المبيعات يلتزم المسجل بإصدار الفاتورة الضريبية في حال تحقق واقعة البيع بتأدية الخدمة أو تسليم السلعة أو قبض الثمن ضمن التواريخ التالية ما عدا:","o":["مباشرة بعد تسليم السلعة أو تأدية الخدمة أو قبض الثمن إذا كان البائع يستخدم آلة النقد الذي يُعتبر شريط آلة النقد في هذه الحالة بمثابة الفاتورة.","في موعد أقصاه نهاية الشهر إذا كان البائع يستخدم سندات إخراج وبطاقة صنف.","خلال فترة أقصاها شهر من تاريخ انتهاء توريد الخدمة أو لدى قبض الثمن.","مباشرة بعد تسليم السلعة أو قبض الثمن إذا كان البائع لا يستخدم سندات إخراج وبطاقة صنف."],"answer":2,"orig_answer":null,"law":"sales","article":"18","status":"unverified","explanation":"من تعليمات تحرير الفاتورة الضريبية (غير واردة في نص القانون؛ المادة 18/أ تحيل للتعليمات). الإجابة الأرجح (ج) لاختلاف مدة الخدمات عن نص التعليمات؛ تحتاج تحققاً من التعليمات."},{"num":19,"type":"mcq","q":"حسب تعليمات تنظيم السجلات والمستندات في قانون ضريبة المبيعات أي من النصوص التالية غير صحيح:","o":["للمدير أن يلزم أي شخص غير مسجل عند بيعه لسلعة أو خدمة خاضعة للضريبة بإصدار فواتير ومسك سجلات وحسابات منتظمة لتسجيل عمليات البيع التي يقوم بها والاحتفاظ بتلك الفواتير والسجلات لمدة أربع سنوات تالية لتاريخ انتهاء السنة المالية التي صدرت أو نظمت بها.","للمدير أن يلزم أي شخص من أي فئة من الأشخاص من تلقاء نفسه أو بناء على طلب أي منهم بتنظيم سجلات ومستندات تبين مقدار مبيعات كل منهم وتراعي طبيعة عمل ونشاط هذه الجهات وله إعفاؤهم من تدقيقها وتصديقها من محاسب قانوني مرخص ومزاول لمهنة التدقيق.","يلتزم الشخص الطبيعي وشركة التضامن وشركة التوصية البسيطة ممن تزيد مبيعات أي منهم على 200,000 مئتي ألف دينار في السنة بتنظيم السجلات والمستندات وفق معايير المحاسبة الدولية ومصادق عليها من محاسب قانوني.","يلتزم الشخص الطبيعي وشركة التضامن ممن تزيد مبيعات أي منهم على 200,000 مئتي ألف دينار في السنة بتنظيم السجلات والمستندات وفق معايير المحاسبة الدولية ومصادق عليها من محاسب قانوني."],"answer":0,"orig_answer":null,"law":"sales","article":"18","status":"unverified","explanation":"المادة (18/ب) بنصها الحالي تحدد مدة احتفاظ غير المسجل بالفواتير والسجلات بخمس سنوات لا أربع، فالعبارة (أ) غير صحيحة وفق النص الحالي؛ أما (ج/د) فمن تعليمات تنظيم السجلات ولم يتم التحقق منها."},{"num":20,"type":"mcq","q":"حسب تعليمات تنظيم السجلات والمستندات في قانون ضريبة المبيعات على المكلف الذي يستخدم أجهزة الحاسوب في تنظيم سجلاته ومستنداته وبياناته المالية والتي تُعتبر هذه السجلات أصولية من الناحية المحاسبية عليه مراعاة التالي ما عدا:","o":["أن تكون هذه البيانات موثقة وتعكس حقيقة الوضع المالي للمكلف.","أن تتضمن البيانات المدخلة التوقيع الالكتروني لدخلها.","أن يسمح بإجراء التعديل والتغيير لمفردات البيانات المدخلة عند حدوث أي خطأ.","أن يحتفظ المكلف للمدة المقررة قانوناً بأصول المستندات والوثائق المعززة لها."],"answer":2,"orig_answer":null,"law":"sales","article":"","status":"unverified","explanation":"من تعليمات تنظيم السجلات: يشترط في السجلات المحوسبة ألا تسمح بتعديل أو تغيير البيانات المدخلة، لذا (ج) هي الاستثناء."},{"num":21,"type":"mcq","q":"شركة تمارس الاستيراد والشراء المحلي وبيع المواد التموينية والزيوت النباتية وعليه فالشركة ملزمة بالتسجيل في ضريبة المبيعات:","o":["عند بلوغ حد التسجيل أو أول عملية استيراد أيهما أسبق.","خلال 30 يوم من تاريخ أول استيراد.","منذ اليوم الأول للاستيراد.","عند حد التسجيل البالغ 75,000 خمسة وسبعون ألف دينار."],"answer":1,"orig_answer":null,"law":"sales","article":"13","status":"valid","explanation":"المادة (13/ب): يلتزم مستورد السلعة أو الخدمة الخاضعة بالتسجيل خلال ثلاثين يوماً من تاريخ أول استيراد مهما بلغ حجم مستورداته."},{"num":22,"type":"mcq","q":"أي من التالي صحيح فيما يتعلق بالشركة الدامجة الخلف القانوني للشركات المندمجة:","o":["تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة أو الشركة الناتجة عن الاندماج حكماً بعد انتهاء إجراءات الدمج وتسجيل الشركة وفقاً لأحكام القانون وتُعتبر الشركة الدامجة أو الناتجة عن الاندماج خلفاً قانونياً للشركات المندمجة وتحل محلها في جميع حقوقها والتزاماتها.","تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة أو الشركة الناتجة عن الاندماج وفقاً لعقد الاندماج الموقع حكماً، وذلك بعد قيام لجنة الاندماج بتقديم تقريرها إلى معالي الوزير وموافقة الوزير على ذلك.","تنتقل جميع حقوق والتزامات الشركات المندمجة إلى الشركة الدامجة أو الشركة الناتجة عن الاندماج، وذلك بموجب قرار الهيئة العامة للشركات الراغبة بالاندماج مباشرة وذلك بعد توقيع عقد الاندماج وتوريده إلى دائرة مراقبة الشركات وحصول الشركات المذكورة على شهادة بمضمون القرارات.","جميع ما ذكر صحيح."],"answer":0,"orig_answer":null,"law":"companies","article":"238","status":"valid","explanation":"المادة (238): تنتقل الحقوق والالتزامات حكماً بعد انتهاء إجراءات الدمج والتسجيل وتعتبر الدامجة أو الناتجة خلفاً قانونياً."},{"num":23,"type":"mcq","q":"أي من التالي يُعتبر صحيح فيما يتعلق بنفاذ قانون الشركات على الشركات القائمة وتوفيق أوضاعها:","o":["ألا يتوجب على الشركات القائمة والمسجلة قبل نفاذ هذا القانون توفيق أوضاعها وفق أحكام هذا القانون، وذلك لكون هذه الشركات مسجلة بموجب قوانين وأنظمة كانت نافذة سابقاً.","تعتبر جميع الشركات المسجلة بمقتضى القوانين المعمول بها قبل نفاذ هذا القانون قائمة وكأنها مسجلة وفق أحكامه، وعلى الشركات القائمة توفيق أوضاعها وإجراء التعديلات اللازمة على عقودها خلال مدة لا تتجاوز سنة واحدة من تاريخ نفاذ هذا القانون.","تُعتبر جميع الشركات المسجلة بمقتضى القوانين المعمول بها قبل نفاذ هذا القانون ملغاة ويتوجب تسجيلها وفق أحكام هذا القانون.","جميع ما ذكر صحيح."],"answer":1,"orig_answer":null,"law":"companies","article":"286","status":"valid","explanation":"المادة (286/ب): على الشركات القائمة توفيق أوضاعها خلال مدة لا تتجاوز سنة واحدة من تاريخ نفاذ القانون."},{"num":24,"type":"mcq","q":"أي من الجمل التالية يعتبر صحيح فيما يتعلق بالشركة المعفاة:","o":["يمكن للشركة المعفاة بعد تسديد الرسوم المقررة عليها أن تطرح أسهمها للاكتتاب العام في حالة إذا كانت شركة مساهمة عامة شريطة الالتزام بالأنظمة والتعليمات الصادرة عن هيئة الأوراق المالية وقانون الشركات.","يحق للشركة المعفاة أن تمارس أعمالها داخل وخارج المملكة شريطة أن تقوم بدفع رسوم سنوية تعادل ما لا يقل عن (20%) من إيراداتها السنوية كإيرادات للخزينة العامة.","الشركة المعفاة هي شركة مساهمة عامة أو شركة توصية بالأسهم أو شركة محدودة المسؤولية أو الشركات المساهمة الخاصة التي تسجل في المملكة وتزاول أعمالها خارجها ويضاف إلى اسمها عبارة (شركة معفاة) ويحظر عليها طرح أسهمها للاكتتاب العام في المملكة.","الشركة المعفاة هي الشركة التي يمكن تسجيلها بأي نوع من أنواع الشركات ويضاف على اسمها عبارة (شركة معفاة)."],"answer":null,"orig_answer":2,"law":"companies","article":"211","status":"changed","explanation":"المادة (211) بنصها الحالي: الشركة المعفاة شركة مساهمة عامة أو محدودة المسؤولية أو مساهمة خاصة (لم تعد تشمل التوصية بالأسهم) ويحظر عليها طرح أسهمها للاكتتاب في المملكة؛ لذا لا يطابق أي خيار النص تماماً."},{"num":25,"type":"mcq","q":"للوزير والمراقب اتخاذ الإجراءات المناسبة لمراقبة الشركات للتحقق من تقيدها بأحكام قانون الشركات والأحكام والعقود والأنظمة والقرارات، وتشمل الرقابة بشكل خاص ما يلي:","o":["التحقق من الخبرات العملية لمجلس الإدارة والإدارة التنفيذية ومدى ملائمة هذه الخبرات المتوفرة لديهم لقيام الشركة بتحقيق أهدافها وأهداف المساهمين.","فحص سجل المساهمين للتحقق من جنسياتهم وحصصهم أو مساهمتهم برأسمال الشركة ومدى ملائمة رأسمال الشركة للغايات التي تمارسها.","فحص حسابات الشركة وقيودها والتحقق من التزام الشركة بالغايات التي أسست من أجلها.","جميع ما ذكر صحيح."],"answer":2,"orig_answer":null,"law":"companies","article":"273","status":"valid","explanation":"المادة (273): تشمل الرقابة بشكل خاص فحص حسابات الشركة وقيودها والتأكد من التزامها بالغايات التي أسست من أجلها."},{"num":26,"type":"mcq","q":"تلتزم شركة التضامن بتعيين مدقق حسابات قانوني ينتخب بأكثرية الأعضاء إذا كان رأسمالها يبلغ:","o":["100,000 دينار أو أكثر.","75,000 دينار.","50,000 دينار.","10,000 دينار."],"answer":0,"orig_answer":null,"law":"companies","article":"24","status":"valid","explanation":"المادة (24/ب): تلتزم شركة التضامن التي يبلغ رأسمالها مئة ألف دينار أو أكثر بتعيين مدقق حسابات."},{"num":27,"type":"mcq","q":"لا يجوز للشركاء في شركة التضامن إخراج أي من الشركاء إلا:","o":["قرار من الوزير.","بقرار (75%) من حصص الشركاء.","بقرار من المحكمة بناء على طلب أي منهم.","بقرار من المراقب."],"answer":2,"orig_answer":null,"law":"companies","article":"23","status":"valid","explanation":"المادة (23): لا يجوز إخراج أي شريك إلا بقرار من المحكمة بناء على طلب أي من الشركاء."},{"num":28,"type":"mcq","q":"يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ باسمها الأصلي في حال:","o":["تم تصفيتها ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","رغبت بالتحول إلى شركة ذات مسؤولية محدودة.","تم شطب تسجيلها ورغبت بالتسجيل كشركة ذات مسؤولية محدودة.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"companies","article":"56","status":"valid","explanation":"المادة (56): يحق لشركة التضامن أو التوصية البسيطة الاحتفاظ باسمها الأصلي إذا رغبت بالتحول إلى ذات مسؤولية محدودة."},{"num":29,"type":"mcq","q":"إذا كان رأسمال الشركة ذات المسؤولية المحدودة أو جزء من حصصها عينية، فعلى مقدمي هذه الحصص المحافظة على هذه المقدمات وعدم التصرف بها إلى حين:","o":["تسليمها إلى الشركة وتسجيلها باسمها ونقل ملكيتها إليها.","بيعها وتوزيع حصيلة البيع على الشركاء مالكي هذه المقدمات العينية.","بيعها وإيداع حصيلة البيع في حسابات الشركة.","لا شيء مما ذكر."],"answer":0,"orig_answer":null,"law":"companies","article":"58","status":"valid","explanation":"المادة (58/ب): على مقدمي الحصص العينية تسليمها ونقل ملكيتها للشركة خلال ثلاثين يوماً من التسجيل."},{"num":30,"type":"mcq","q":"يشترط حضور مراقب عام الشركات اجتماع الهيئات العامة للشركات التالية:","o":["لا يشترط حضور مراقب عام الشركات لأي نوع من أنواع الشركات.","الشركات المساهمة العامة المحدودة.","الشركات المساهمة الخاصة والشركات المساهمة العامة المحدودة.","الشركات ذات المسؤولية المحدودة والمساهمة الخاصة والمساهمة العامة المحدودة."],"answer":1,"orig_answer":null,"law":"companies","article":"182","status":"valid","explanation":"المادة (182): يعتبر اجتماع الهيئة العامة للمساهمة العامة باطلاً إذا لم يحضره المراقب؛ ولا يدعى في ذات المسؤولية المحدودة والمساهمة الخاصة (64/هـ، 78 مكرر/هـ)."},{"num":31,"type":"mcq","q":"النسبة المئوية المحددة في قانون الشركات النافذ ليتقدم شركاء و/أو مساهمين بطلب تشكيل لجنة تدقيق على الشركة هي:","o":["(25%).","(20%).","(10%).","(15%)."],"answer":2,"orig_answer":null,"law":"companies","article":"275","status":"valid","explanation":"المادة (275/أ): لمساهمين يملكون ما لا يقل عن (10%) من رأس المال طلب إجراء تدقيق على أعمال الشركة."},{"num":32,"type":"mcq","q":"للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها سنداً لحالة من الحالات التالية:","o":["إذا لحقت بها خسائر تزيد على (40%) من رأسمالها.","إذا زاد عن حاجتها أو إذا لحقت بها خسائر تزيد عن نصف رأسمالها أو إذا انسحب أحد الشركاء منها.","إذا زاد عن حاجتها أو إذا لحقت بها خسائر تزيد عن (25%) من رأسمالها.","إذا زاد عن حاجتها أو إذا لحقت بها خسائر تزيد عن نصف رأسمالها."],"answer":3,"orig_answer":null,"law":"companies","article":"68","status":"valid","explanation":"المادة (68/أ): للمحدودة المسؤولية تخفيض رأسمالها إذا زاد عن حاجتها أو لحقت بها خسائر تزيد على نصف رأسمالها."},{"num":33,"type":"mcq","q":"أي من الحالات التالية صحيحة فيما يتعلق برأسمال الشركة المساهمة الخاصة عند التأسيس:","o":["رأسمال الشركة المصرح به وفق لما يحدده المساهمين دون سقف أعلى وأن لا يقل رأسمال الشركة المكتتب به عن (50,000) دينار/ سهم.","لا يقل رأس المال المصرح به عن (10) مليون دينار/سهم، وأن لا يقل رأسمال الشركة المكتتب به عن (20,000) دينار/سهم.","رأسمال الشركة المصرح به وفق لما يحدده المساهمين، وأن لا يقل رأسمال الشركة المكتتب به عن (100,000) دينار/سهم.","لا يقل رأس المال المصرح به عن (10) مليون دينار/سهم، ورأس المال المكتتب به عن (100,000) دينار/سهم."],"answer":0,"orig_answer":null,"law":"companies","article":"66 مكرر","status":"valid","explanation":"المادة (66 مكرر/أ): لا يقل رأس المال المكتتب به للمساهمة الخاصة عن خمسين ألف دينار ولا حد أعلى للمصرح به."},{"num":34,"type":"mcq","q":"يتوجب على المساهمين في الشركة المساهمة الخاصة عقد اجتماع هيئة عامة تأسيسي من تاريخ صدور شهادة تسجيل الشركة من قبل المراقب خلال مدة:","o":["خلال (10) يوم (عشرة أيام).","خلال (30) يوم (شهر).","خلال (60) يوم (شهرين).","خلال (90) يوم (ثلاث أشهر)."],"answer":1,"orig_answer":null,"law":"companies","article":"71 مكرر","status":"valid","explanation":"المادة (71 مكرر): يعقد الاجتماع التأسيسي خلال شهر من تاريخ صدور شهادة التسجيل."},{"num":35,"type":"mcq","q":"يحظر على مدير عام الشركة المساهمة الخاصة وموظفيها تولي وظيفة في شركة أخرى ذات غايات مماثلة أو منافسة لأعمال الشركة سواء لحسابه أو لحساب الغير بأجر أو بدون أجر إلا بموافقة:","o":["لا يشترط موافقة أي جهة.","موافقة مجلس الإدارة.","موافقة الهيئة العامة غير العادية.","مراقب عام الشركات."],"answer":1,"orig_answer":null,"law":"companies","article":"74 مكرر","status":"valid","explanation":"المادة (74 مكرر/ب): يحظر على المدير العام وموظفي المساهمة الخاصة ذلك إلا بموافقة مجلس الإدارة."},{"num":36,"type":"mcq","q":"ما هي النسبة التي يتوجب على الشركة المساهمة الخاصة اقتطاعها من أرباحها السنوية لحساب الاحتياطي الإجباري، والنسبة التي لا يتجاوز مجموع ما يقتطع من رأس المال المكتتب به:","o":["(10%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به.","(15%) سنوياً ولا يتجاوز مجموع ما يقتطع (15%) من رأس المال المكتتب به.","(20%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به.","(25%) سنوياً ولا يتجاوز مجموع ما يقتطع (50%) من رأس المال المكتتب به."],"answer":0,"orig_answer":null,"law":"companies","article":"85 مكرر","status":"valid","explanation":"المادة (85 مكرر/أ): تقتطع (10%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به."},{"num":37,"type":"mcq","q":"من المهام التي تتولاها اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب ما يلي باستثناء:","o":["تعيين محاسب قانوني لوحدة مكافحة غسل الأموال وتمويل الإرهاب وتحديد أتعابه.","تحليل أنماط جرائم غسل الأموال وتمويل الإرهاب وآلياتها وأساليبها وإعداد موجز عنها لنشرها.","متابعة المستجدات العالمية في مجال مكافحة غسل الأموال وتمويل الإرهاب وانتشار أسلحة الدمار الشامل واقتراح الإجراءات اللازمة بشأنها.","اعتماد إجراءات تقييم مخاطر غسل الأموال وتمويل الإرهاب وانتشار أسلحة الدمار الشامل في المملكة وتحديثها."],"answer":1,"orig_answer":null,"law":"aml","article":"6","status":"valid","explanation":"المادة (6/أ): من مهام اللجنة تعيين محاسب قانوني للوحدة ومتابعة المستجدات واعتماد تقييم المخاطر؛ أما تحليل الأنماط فليس من مهامها."},{"num":38,"type":"mcq","q":"تصدر المسكوكات التذكارية والخاصة بقرار من:","o":["محافظ البنك المركزي.","رئيس الوزراء.","مجلس إدارة البنك المركزي.","مجلس الوزراء."],"answer":3,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","explanation":"من قانون البنك المركزي الأردني (غير مدرج)؛ الإجابة الأرجح مجلس الوزراء، تحتاج تحققاً."},{"num":39,"type":"mcq","q":"جميع هذه العبارات صحيحة فيما يتعلق بإشراف البنك المركزي على نظام المدفوعات الوطني باستثناء:","o":["يحدد البنك المركزي أسس الفصل بين أموال مقدمي خدمات الدفع وأموال العملاء بمقتضى تعليمات يصدرها لهذه الغاية.","تقبل المطالبة بعكس أو إلغاء أو إبطال أي تسديد أو تسوية تم إجراؤها نتيجة لتسييل الضمانات والتأمينات المشار إليها في هذه الفقرة.","للبنك المركزي أن يطلب الضمانات والتأمينات اللازمة لتغطية الالتزامات والاستحقاقات التي قد تترتب على مقدمي خدمات الدفع ومديري ومشغلي نظم الدفع أو المشتركين فيها.","للبنك المركزي تحديد أنظمة الدفع أو التقاص أو التسوية التي يتولى إدارتها."],"answer":1,"orig_answer":null,"law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","explanation":"من قانون البنك المركزي (نظام المدفوعات): لا تقبل المطالبة بعكس أو إلغاء أو إبطال أي تسديد أو تسوية تمت نتيجة تسييل الضمانات، فالعبارة (ب) خاطئة."},{"num":40,"type":"mcq","q":"على كل شخص يرغب في تسويق أو بيع أوراق مالية غير أردنية داخل المملكة الحصول على:","o":["موافقة المركز.","موافقة الهيئة المسبقة وفقاً للتعليمات الصادرة.","موافقة السوق المالي.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"securities","article":"34","status":"valid","explanation":"المادة (34/د): يلزم الحصول على موافقة الهيئة المسبقة وفقاً للتعليمات لتسويق أو بيع أوراق مالية غير أردنية."},{"num":41,"type":"mcq","q":"تتبع هيئة الأوراق المالية إلى:","o":["رئيس هيئة الأوراق المالية.","رئاسة الوزراء.","رئيس الوزراء.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"securities","article":"7","status":"valid","explanation":"المادة (7/ب): ترتبط هيئة الأوراق المالية برئيس الوزراء."},{"num":42,"type":"mcq","q":"وفق تعليمات حوكمة الشركات، فإنه يتولى إدارة الشركة مجلس إدارة يتكون من:","o":["ما لا يقل عن 5 ولا يزيد عن 12 عضواً.","ما لا يقل عن 4 ولا يزيد عن 12 عضواً.","ما لا يقل عن 5 ولا يزيد عن 13 عضواً.","ما لا يقل عن 3 ولا يزيد عن 15 عضواً."],"answer":2,"orig_answer":null,"law":"other:تعليمات حوكمة الشركات المساهمة المدرجة","article":"","status":"unverified","explanation":"تعليمات حوكمة الشركات المساهمة المدرجة لسنة 2017: يتولى إدارة الشركة مجلس لا يقل عن 5 ولا يزيد على 13 عضواً."},{"num":43,"type":"mcq","q":"يعتبر التأكد من استقلالية الأعضاء المستقلين في مجلس إدارة الشركات بشكل مستمر من مهام:","o":["لجنة الترشيحات والمكافآت.","لجنة المخاطر.","لجنة الحوكمة.","لجنة التدقيق."],"answer":0,"orig_answer":null,"law":"other:تعليمات حوكمة الشركات المساهمة المدرجة","article":"","status":"unverified","explanation":"تعليمات الحوكمة: تتولى لجنة الترشيحات والمكافآت التأكد بشكل مستمر من استقلالية الأعضاء المستقلين."},{"num":44,"type":"mcq","q":"اللجنة التي يجوز أن تضم في عضويتها أعضاء من الإدارة التنفيذية العليا هي:","o":["لجنة الترشيحات والمكافآت.","لجنة المخاطر.","لجنة الحوكمة.","لجنة التدقيق."],"answer":1,"orig_answer":null,"law":"other:تعليمات حوكمة الشركات المساهمة المدرجة","article":"","status":"unverified","explanation":"تعليمات الحوكمة: يجوز أن تضم لجنة إدارة المخاطر في عضويتها أعضاء من الإدارة التنفيذية العليا."},{"num":45,"type":"mcq","q":"لا يجوز لأي شخص أن يقوم بأي عرض عام للورقة المالية إلا من خلال:","o":["دراسة جدوى اقتصادية.","نشرة معلومات.","نشرة إصدار.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"securities","article":"34","status":"valid","explanation":"المادة (34/أ/1): لا يجوز القيام بأي عرض عام إلا بتقديم نشرة إصدار إلى الهيئة."},{"num":46,"type":"mcq","q":"يشترط لاستحقاق المؤمن عليه الذي يعمل بإحدى المهن الخطيرة راتب التقاعد المبكر ما يلي:","o":["إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (216) اشتراكاً فعلياً للذكر و(180) للأنثى.","إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (252) اشتراكاً فعلياً للذكر و(216) للأنثى.","إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (240) اشتراكاً فعلياً للذكر و(204) للأنثى.","إكمال سن الخامسة والأربعين وأن تكون اشتراكاته قد بلغت على الأقل (228) اشتراكاً فعلياً للذكر و(192) للأنثى."],"answer":0,"orig_answer":null,"law":"social","article":"64","status":"valid","explanation":"المادة (64/ج/1): المهن الخطرة: (216) اشتراكاً فعلياً للذكر و(180) للأنثى مع إكمال سن الخامسة والأربعين."},{"num":47,"type":"mcq","q":"إذا نشأت من إصابة العمل وفاة المصاب فيستحق راتب تقاعد الوفاة الناشئة عن إصابة العمل بنسبة:","o":["( ) من أجره الذي اتخذ أساساً لتسديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]","( ) من أجره الذي اتخذ أساساً لتسديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]","( ) من أجره الذي اتخذ أساساً لتحديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]","( ) من أجره الذي اتخذ أساساً لتسديد اشتراكاته بتاريخ وقوع الإصابة. [النسبة غير مطبوعة في الورقة]"],"answer":null,"orig_answer":null,"law":"social","article":"30","status":"valid","explanation":"المادة (30/أ): يستحق راتب تقاعد الوفاة الناشئة عن إصابة العمل بنسبة (75%) من الأجر الذي اتخذ أساساً لتسديد الاشتراكات بتاريخ وقوع الإصابة؛ النسب غير مطبوعة في خيارات الورقة."},{"num":48,"type":"mcq","q":"مؤمن عليه تم إيقاف شموله نتيجة ترك العمل ولديه فترات شمول بلغت (200) اشتراكاً جميعها في وزارة الزراعة:","o":["يستحق لبدل التعطل عن (4) أشهر.","يستحق لبدل التعطل عن (3) أشهر.","يستحق لبدل التعطل عن (6) أشهر.","لا شيء مما ذكر."],"answer":3,"orig_answer":null,"law":"social","article":"49","status":"valid","explanation":"المادة (49/ب): يستثنى من تأمين التعطل موظفو الدوائر الحكومية الذين قرر مجلس الوزراء استثناءهم، فموظف وزارة الزراعة لا يستحق بدل التعطل (لا شيء مما ذكر)."},{"num":49,"type":"mcq","q":"يشترط لاستحقاق المؤمن عليه الذكر لراتب تقاعد الشيخوخة:","o":["إكماله سن 60 بغض النظر عن 180 اشتراك.","وجود ما لا يقل عن 180 اشتراك بغض النظر عن السن.","إكماله سن ال 55 بغض النظر عن 180 اشتراك.","إكماله سن ال 60 بغض النظر عن عدد الاشتراكات."],"answer":null,"orig_answer":null,"law":"social","article":"62","status":"valid","explanation":"المادة (62/أ): يشترط إكمال الذكر سن الستين وأن تكون اشتراكاته (180) اشتراكاً منها (84) فعلياً معاً؛ لا يطابق أي خيار الشرطين مجتمعين."},{"num":50,"type":"mcq","q":"يشترط في المؤمن عليه الأردني الذي يرغب في الجمع بين راتب التقاعد المبكر وأجره من العمل المشمول بأحكام القانون ما يلي:","o":["أن يعود للشمول بأحكام القانون في حال عودته للعمل.","أن يكون قد انقطع عن العمل لمدة لا تقل عن 24 شهراً، وأن لا يعود للعمل في أي من المنشآت التي كان يعمل بها خلال الستة والثلاثين اشتراكاً الأخيرة.","أن لا يعود المؤمن عليه الذي يعمل بإحدى المهن الخطيرة، وتم تخصيص راتب التقاعد المبكر له إلى العمل بمهنة خطرة.","جميع ما ذكر صحيح."],"answer":3,"orig_answer":null,"law":"social","article":"85","status":"valid","explanation":"المادة (85/د/1): شروط الجمع: الانقطاع 24 شهراً، عدم العودة لمنشآت آخر 36 اشتراكاً، عدم العودة لمهنة خطرة، العودة للشمول."},{"num":51,"type":"mcq","q":"يجب على العامل إبلاغ المؤسسة بعدم قيام المنشأة بشموله بأحكام القانون خلال مدة لا تتجاوز:","o":["ستة أشهر من تاريخ تركه العمل.","خلال مدة لا تتجاوز ستة أشهر من تاريخ التقدم بطلب الحصول على أية منفعة تأمينية.","سنة من تاريخ تركه للعمل.","ستة أشهر من تاريخ التحاقه بالعمل."],"answer":0,"orig_answer":null,"law":"social","article":"92","status":"valid","explanation":"المادة (92/أ/1): يبلغ العامل المؤسسة بعدم شموله خلال مدة لا تتجاوز ستة أشهر من تاريخ انتهاء خدماته لدى المنشأة."},{"num":52,"type":"mcq","q":"في حال وقوع حادث عمل لمؤمن عليه يجب على المؤمن عليه أو ذويه إبلاغ المؤسسة بالحادث خلال مدة:","o":["أسبوعين من تاريخ وقوع الحادث.","أربعة أشهر من تاريخ وقوع الحادث.","أربعة عشر يوم عمل من تاريخ وقوع الحادث.","أربعة وعشرون ساعة من تاريخ وقوع الحادث."],"answer":1,"orig_answer":null,"law":"social","article":"27","status":"valid","explanation":"المادة (27/د): للمؤمن عليه أو ذويه إشعار المؤسسة بإصابة العمل خلال أربعة أشهر من وقوعها إذا لم تقم المنشأة بذلك."},{"num":53,"type":"mcq","q":"حسب قانون الاستثمار الساري المفعول إذا كان المشروع قد حصل على مزايا وإعفاءات من ضريبة الدخل بمقتضى التشريعات السابقة، ولم يكن قد باشر عمله أو إنتاجه الفعلي فيشترط لغاية تطبيق أحكام هذا القانون، والذي ينص على إعفاء المواد والآلات والتجهيزات وقطع الغيار للصيانة أن يباشر عمله أو الإنتاج الفعلي خلال:","o":["3 سنوات.","سنتين من تاريخ نفاذ القانون تحت طائلة فقدان الحق في المزايا والإعفاءات.","سنة.","6 شهور."],"answer":null,"orig_answer":null,"law":"investment","article":"","status":"obsolete","explanation":"السؤال مبني على الأحكام الانتقالية لقانون الاستثمار لسنة 2014 الذي ألغي بقانون البيئة الاستثمارية رقم (21) لسنة 2022، ولا يوجد حكم مماثل فيه."},{"num":54,"type":"mcq","q":"حسب قانون الطوابع الساري المفعول تفرض غرامة على المكلف بدفع الرسم المقرر إذا تأخر عن دفعه في الموعد المحدد، وعلى النحو التالي:","o":["مثل الرسم أو مقدار النقص في حال التأخر لمدة تزيد عن 30 يوم ولا تتجاوز 60 يوم وبحد أدنى دينار واحد.","1% عن الرسم المستحق أو النقص عما تم دفعه من الرسم عن الأسبوع الأول من التأخر وبحد أدنى دينار واحد.","50% من الرسم أو مقدار النقص في حال التأخر لمدة تزيد عن 7 أيام ولا تتجاوز 30 يوم وبحد أدنى دينار واحد.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"stamp","article":"12","status":"valid","explanation":"المادة (12/أ): 1% عن الأسبوع الأول، 50% من 7 إلى 30 يوماً، مثل الرسم من 30 إلى 60 يوماً، مثلا الرسم بعد 60 يوماً؛ فجميع الخيارات صحيحة."},{"num":55,"type":"mcq","q":"حسب قانون ديوان المحاسبة الساري المفعول أي من العبارات التالية غير صحيحة:","o":["يكون ديوان المحاسبة مسؤولاً فيما يتعلق بالنفقات عن أسباب عدم صرف لكل أو بعض المخصصات التي رصدت للأعمال الجديدة.","يكون ديوان المحاسبة مسؤولاً فيما يتعلق بالنفقات عن أسباب عدم إصدار أوامر الصرف حسب الأصول الصحيحة ومن قبل الجهات المختصة.","يكون ديوان المحاسبة مسؤولاً عن تدقيق الواردات في معاملات شطب الواردات والإعفاء منها للتثبت من عدم إجراء شطب أو إعفاء في غير الحالات والأصول المنصوص عليها في القوانين والأنظمة.","يكون ديوان المحاسبة مسؤولاً عن تدقيق الواردات في معاملات بيع الأراضي والعقارات الأميرية وتأجيرها وتفويضها."],"answer":1,"orig_answer":null,"law":"audit","article":"9","status":"valid","explanation":"المادة (9/ج): يتثبت الديوان من أن إصدار أوامر الصرف تم حسب الأصول ومن الجهات المختصة، لا من أسباب عدم إصدارها؛ باقي العبارات وردت في المادتين (8) و(9)."},{"num":56,"type":"mcq","q":"حسب قانون المنافسة الساري المفعول، أي من العبارات التالية غير صحيحة:","o":["يسمح لكل منتج أو مستورد أو تاجر جملة أو مقدم خدمة أن يفرض بصورة مباشرة أو غير مباشرة حد أدنى لأسعار بيع سلعة أو خدمة.","تتحدد أسعار السلع والخدمات وفقاً لقواعد السوق ومبادئ المنافسة الحرة.","يحظر على أي مؤسسة إعادة بيع منتج على حالته بسعر أقل من سعر شرائه الحقيقي مضافاً إليه الضرائب والرسوم ولا يشمل هذا الحظر المنتجات سريعة التلف والتنزيلات المرخص بها لأي بيع يتم لتصفية الأعمال أو تحديد المخزون.","تسري أحكام هذا القانون على جميع أنشطة الإنتاج والتجارة والخدمات في المملكة كما ينصرف أحكامه إلى أي أنشطة اقتصادية تتم خارج المملكة وتترتب عليها آثار داخلها."],"answer":0,"orig_answer":null,"law":"competition","article":"8","status":"valid","explanation":"المادة (8/أ/1): يحظر على المنتج أو المستورد أو تاجر الجملة أو مقدم الخدمة فرض حد أدنى لأسعار إعادة البيع."},{"num":57,"type":"mcq","q":"تلتزم الجهات المبينة أدناه بالإجراءات المنصوص عليها في قانون مكافحة غسل الأموال والأنظمة والتعليمات والقرارات الصادرة بمقتضى أي منها:","o":["المحامون والمحاسبون القانونيون.","في المؤسسات المالية وتشمل البنوك وشركات الصرافة والأشخاص والشركات التي تخضع لرقابة وترخيص هيئة الأوراق المالية وشركات التأمين ووكلائهم ووسطاء التأمين.","شركات التأجير التمويلي.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"aml","article":"14","status":"valid","explanation":"المادة (14/أ): تشمل الجهات الملزمة المؤسسات المالية (بنوك، صرافة، شركات الأوراق المالية والتأمين، التأجير التمويلي) والمحامين والمحاسبين القانونيين."},{"num":58,"type":"mcq","q":"يتولى مجلس هيئة مكافحة الفساد المهام التالية ما عدا:","o":["الشكاوي والتنظيمات القابلة للطعن الإداري والمنظورة أمام جهة قضائية أو صدرت أحكام قضائية فيها.","اتخاذ القرارات اللازمة بخصوص قضايا الفساد بما في ذلك إحالتها إلى الجهات القضائية المختصة.","التعاون والتنسيق مع الجهات المحلية والإقليمية والدولية المتماثلة لعمل الهيئة.","وضع السياسات العامة للهيئة وإقرار الخطط والبرامج اللازمة لتنفيذها."],"answer":0,"orig_answer":null,"law":"integrity","article":"8","status":"valid","explanation":"المادة (8/أ): الشكاوى المنظورة أمام القضاء ليست من مهام المجلس؛ أما اتخاذ قرارات قضايا الفساد والتعاون والتنسيق ووضع السياسة العامة فمن مهامه."},{"num":59,"type":"mcq","q":"أي من التالي لا يُعتبر دليلاً على الإعسار الفعلي:","o":["صدور قرار من المحكمة يقضي بالاعتراف بإجراءات إعسار أجنبية رئيسية.","إذا كان المدين شخصاً طبيعياً غير واضح أو مجهول الإقامة أو أنه أغلق مركز المصالح الرئيسية له إذا كان شخصاً اعتبارياً.","إذا هرب المدين أمواله أو باعها بغبن فاحش.","إلقاء الحجز التنفيذي على جزء من أموال المدين."],"answer":3,"orig_answer":null,"law":"insolvency","article":"10","status":"valid","explanation":"المادة (10/ج/2): الدليل هو إلقاء الحجز التنفيذي على كامل أموال المدين لا على جزء منها."},{"num":60,"type":"mcq","q":"إذا صدر قرار بتجريد المدين من صلاحية إدارة ذمة الإعسار والتصرف فيها، فيحل محل المدين سواء بصفته مدعياً أو مدعى عليه في إجراءات قضائية مقابلة قبل إشهار الإعسار أي من التالي:","o":["لجنة من ممثلي العاملين لدى المدين.","وكيل الإعسار.","لجنة من دائني المدين.","محامي المدين للحفاظ على حقوق المدين."],"answer":1,"orig_answer":null,"law":"insolvency","article":"17","status":"valid","explanation":"المادة (17/هـ): يحل وكيل الإعسار محل المدين مدعياً أو مدعى عليه في الإجراءات القضائية المقامة قبل إشهار الإعسار."},{"num":61,"type":"mcq","q":"تجتمع الهيئة العامة للدائنين بناء على دعوة وكيل الإعسار إما من تلقاء نفسه أو بناء على طلب لجنة الدائنين أو دائنين يمثلون:","o":["10% على الأقل من إجمالي الديون.","20% على الأقل من إجمالي الديون.","30% على الأقل من إجمالي الديون.","50% على الأقل من إجمالي الديون."],"answer":1,"orig_answer":null,"law":"insolvency","article":"44","status":"valid","explanation":"المادة (44/أ): بناء على طلب لجنة الدائنين أو دائنين يمثلون (20%) على الأقل من إجمالي الديون."},{"num":62,"type":"mcq","q":"أي من الجهات التالية غير ملزمة بتعيين محاسب قانوني مسجل في سجل المحاسبين القانونيين المزاولين لغايات تدقيق حساباتها:","o":["النقابات والجمعيات التي تؤسس بمقتضى التشريعات المعمول بها.","شركات التضامن التي يقل رأسمالها أو حجم مبيعاتها السنوية على مائة ألف دينار.","شركات التوصية بالأسهم.","الشركات المساهمة العامة والشركات المساهمة الخاصة وذات المسؤولية المحدودة."],"answer":1,"orig_answer":null,"law":"accounting","article":"30","status":"valid","explanation":"المادة (30/أ/2): تلتزم شركات التضامن والتوصية البسيطة التي يزيد رأسمالها أو مبيعاتها على مئة ألف دينار، فالتي يقل رأسمالها غير ملزمة."},{"num":63,"type":"mcq","q":"يتم بقرار من المجلس نقل اسم المحاسب القانوني من سجل المزاولين إلى سجل غير المزاولين في أي من الأسباب والحالات التالية ما عدا:","o":["إذا تم التنسيب من لجنة التأديب.","إذا لم يسدد الالتزامات المالية المترتبة عليه للجمعية لمدة تزيد عن سنتين.","إذا مارس عملاً عدا العمل في المهنة.","بناء على طلبه."],"answer":0,"orig_answer":null,"law":"accounting","article":"","status":"unverified","explanation":"من نظام مزاولة المهنة/النظام الداخلي للجمعية (غير وارد في القانون)؛ الإجابة الأرجح (أ) لأن التأديب يتم بقرار اللجنة التأديبية وفق المادة (36)."},{"num":64,"type":"mcq","q":"يحظر على المحاسب القانوني المزاول لأعمال التدقيق أو المحاسبة القيام بأي مما يلي عدا:","o":["المتاجرة بالأسهم والسندات.","القيام بالدعاية لنفسه بأي وسيلة من وسائل الإعلان بطريقة تسيء للمهنة.","تدقيق حسابات أي شركة يكون شريكاً أو مساهماً فيها.","احتراف التجارة أو الصناعة أو العمل في أي مهنة أخرى."],"answer":0,"orig_answer":null,"law":"accounting","article":"","status":"unverified","explanation":"من قواعد سلوك المهنة (المادة 27 تحيل إليها): المتاجرة بالأسهم والسندات غير محظورة بينما الدعاية وتدقيق شركة يكون شريكاً فيها واحتراف التجارة محظورة."},{"num":65,"type":"mcq","q":"تستوفى رسوم طوابع على المبالغ الواردة في معاملات الشراء المباشر أو التلزيم أو استدراج العروض أو العطاءات التي تقوم بها أي وزارة أو دائرة حكومية أو مؤسسة رسمية أو مؤسسة عامة أو شركة مساهمة عامة ومعاملات البيع التي تتم من قبل أي من هذه الجهات فيما عدا العمليات المتعلقة بمبيعات الشركات المساهمة العامة بنسبة:","o":["(0.001) واحد بالألف.","(0.003) ثلاثة بالألف.","(0.006) ستة بالألف.","لا شيء مما ذكر."],"answer":2,"orig_answer":null,"law":"stamp","article":"","status":"unverified","explanation":"من جدول رسوم الطوابع الملحق بالقانون (غير مدرج في النص المتاح): ستة بالألف على معاملات الشراء والعطاءات الحكومية."},{"num":66,"type":"mcq","q":"تخضع الأهلية التجارية لأحكام:","o":["العرف العام.","العرف التجاري.","القانون المدني.","قانون التجارة."],"answer":2,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة لسنة 1966: تخضع الأهلية التجارية لأحكام القانون المدني."},{"num":67,"type":"mcq","q":"يجب على التاجر أن يحفظ الدفاتر التجارية بعد اختتامها مدة:","o":["مدة سنة واحدة.","مدة عشر سنوات.","مدة 5 سنوات.","مدة 4 سنوات."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: يجب حفظ الدفاتر التجارية مدة عشر سنوات بعد اختتامها."},{"num":68,"type":"mcq","q":"أي من العبارات التالية غير صحيحة حسب قانون التجارة:","o":["لحامل السند، حق الرجوع على مظهريه وساحبه وغيرهم من الملتزمين به قبل الاستحقاق في حالة إفلاس ساحب السند المشروط عدم تقديمه للقبول.","ليس لحامل السند حق الرجوع على مظهريه وساحبه وغيرهم من الملتزمين به قبل الاستحقاق في حال الحجز على أمواله حجزاً غير مجد.","لحامل السند حق الرجوع على مظهريه وساحبه وغيرهم من الملتزمين به قبل الاستحقاق في حالة الامتناع عن القبول كلياً أو جزئياً.","لا شيء مما ذكر."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: لحامل السند الرجوع قبل الاستحقاق في حالة الحجز على أموال المسحوب عليه حجزاً غير مجد، فالعبارة (ب) خاطئة."},{"num":69,"type":"mcq","q":"تسقط بالتقادم كل دعوى ناشئة عن سند السحب تجاه قابله بمضي:","o":["10 سنوات من تاريخ الاستحقاق.","5 سنوات من تاريخ الاستحقاق.","4 سنوات من تاريخ الاستحقاق.","3 سنوات من تاريخ الاستحقاق."],"answer":1,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: تسقط الدعاوى الناشئة عن سند السحب تجاه قابله بمضي خمس سنوات من تاريخ الاستحقاق."},{"num":70,"type":"mcq","q":"حسب قانون التجارة، أي من العبارات التالية تعتبر صحيحة:","o":["إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانوناً بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي والإفلاس.","يعد العرف الخاص والعرف المحلي مرجحين على العرف العام.","لا يعد تاجراً من قام بمعاملة تجارية عرضاً إلا أن المعاملة المذكورة تكون خاضعة لأحكام قانون التجارة.","جميع ما ذكر."],"answer":3,"orig_answer":null,"law":"other:قانون التجارة","article":"","status":"unverified","explanation":"قانون التجارة: جميع العبارات صحيحة (شمول الممنوعين من الاتجار بالإفلاس والصلح الواقي، ترجيح العرف الخاص والمحلي، خضوع المعاملة العرضية لقانون التجارة)."},{"num":71,"type":"essay","q":"السؤال الأول (علامتان): السيد ماهر موظف متقاعد ويتقاضى راتب من الضمان الاجتماعي وقدره 3,000 دينار شهرياً ويقتطع منه 25 دينار شهرياً ضريبة دخل، ويعمل براتب شهري وقدره 2,000 دينار ولديه عقار مؤجر بقيمة 10,000 دينار سنوياً، ويدفع مسقفات على العقار المؤجر 100 دينار سنوياً ولديه وديعة بالبنك أرباحها السنوية 4,000 دينار يقتطع منها ضريبة دخل 200 دينار. إذا علمت أن السيد ماهر متزوج وزوجته لا تعمل ولديه ولدان في الجامعة القسط السنوي لكل طالب 2,000 دينار. المطلوب: احتساب ضريبة الدخل التي تستحق عليه عن العام 2021.","law":"income","article":"4, 9, 11, 12, 18","status":"valid","model_answer":"- الراتب التقاعدي: يعفى أول 2,500 دينار شهرياً (م4/أ/14) فالخاضع (3,000-2,500)×12 = 6,000 دينار.\n- الراتب من الوظيفة: 2,000×12 = 24,000 دينار.\n- الإيجار: 10,000 دينار (المسقفات لا تنزل من الدخل بل تقاص من الضريبة م18/ب).\n- فوائد الوديعة: الاقتطاع 5% (200 دينار) ضريبة قطعية للشخص الطبيعي فلا تدخل في الدخل (م12/أ/2 و12/ج).\n- الدخل الإجمالي = 40,000 دينار.\n- الإعفاءات (م9): شخصي 9,000 + معالين 9,000 + نفقات تعليم/علاج: 1,000 للمكلف + 1,000 للزوجة + 1,000 لكل ولد (2,000) = 22,000 (ضمن سقف 23,000).\n- الدخل الخاضع = 18,000 دينار.\n- الضريبة (م11/أ): 5,000×5% = 250، 5,000×10% = 500، 5,000×15% = 750، 3,000×20% = 600 = 2,100 دينار (لا مساهمة وطنية لأن الدخل أقل من 200,000).\n- يطرح: تقاص المسقفات 100 (لا تتجاوز ضريبة الإيجار 2,100×10,000/40,000 = 525) والمقتطع من التقاعد 25×12 = 300.\n- الضريبة المستحقة الواجبة الدفع = 2,100 - 100 - 300 = 1,700 دينار (مع افتراض عدم اقتطاع ضريبة من الراتب الوظيفي)."},{"num":72,"type":"essay","q":"السؤال الثاني (علامتان): أذكر البيانات الواجب توافرها في الفاتورة الضريبية التي يحررها المسجل في الشبكة العامة للضريبة على المبيعات عند بيع سلعة أو خدمة خاضعة للضريبة لأي شخص أو جهة.","law":"sales","article":"18","status":"unverified","model_answer":"- المادة (18/أ) تلزم المسجل بتحرير فاتورة ضريبية وفق التعليمات التنفيذية، ومن أبرز بياناتها:\n- اسم البائع المسجل وعنوانه ورقم تسجيله الضريبي.\n- الرقم المتسلسل للفاتورة وتاريخ إصدارها.\n- اسم المشتري وعنوانه ورقمه الضريبي إن كان مسجلاً.\n- وصف السلعة أو الخدمة وكميتها وسعر الوحدة وقيمتها.\n- نسبة الضريبة العامة/الخاصة ومقدارها.\n- القيمة الإجمالية شاملة الضريبة، وأي خصومات.\n- (حالياً تصدر الفاتورة عبر نظام الفوترة الوطني الإلكتروني وفق التعليمات)."},{"num":73,"type":"essay","q":"السؤال الثالث (علامتان): عدد الشروط الواجب توافرها لاعتبار الخدمة مصدرة خارج المملكة حسب التعليمات في قانون الضريبة العامة على المبيعات.","law":"sales","article":"4 مكرر","status":"unverified","model_answer":"- وفق تعليمات تصدير الخدمات (غير واردة في نص القانون):\n- أن تقدم الخدمة لشخص غير مقيم ليس له مكان عمل أو منشأة ثابتة في المملكة.\n- أن تستهلك الخدمة أو يستفاد منها خارج المملكة.\n- أن يتم قبض بدلها بعملة أجنبية محولة من الخارج (أو وفق ما تحدده التعليمات).\n- أن تكون موثقة بعقد/فاتورة ومستندات تثبت التصدير.\n- حالياً: تعتبر الخدمة موردة داخل المنطقة الضريبية إذا أداها مورد يمارس عمله أو له منشأة ثابتة أو عنوان دائم فيها (م4 مكرر/ج)، ويحدد استيراد الخدمات وفق (م4 مكرر/هـ)."},{"num":74,"type":"essay","q":"السؤال الرابع (علامتان): شخص يمارس نشاط تأجير السيارات السياحية والذي يصنف من الأنشطة الخدمية الخاضعة للضريبة وكانت إيراداته الشهرية كما يأتي: 1-2018 = 2,000 دينار، 2-2018 = 1,000، 3-2018 = 2,500، 4-2018 = 2,500، 5-2018 = 2,000، 6-2018 = 1,000، 7-2018 = 2,000، 8-2018 = 3,000، 9-2018 = 5,000، 10-2018 = 500، 11-2018 = 2,000، 12-2018 = 5,000، 1-2019 = 7,000، 2-2019 = 5,500، 3-2019 = 4,000، 4-2019 = 3,000 دينار. مجموع المبيعات لغاية شهر 12-2018 = 25,000 دينار. المطلوب: من خلال البيانات أعلاه متى يتوجب على الشخص التسجيل في ضريبة المبيعات؟","law":"sales","article":"13, 14","status":"valid","model_answer":"- حد التسجيل لمقدمي الخدمات (30,000) دينار وفق نظام حد التسجيل الصادر بمقتضى المادة (14/أ).\n- المادة (13/أ): يلتزم بالتسجيل عند أسبق التواريخ: نهاية 12 شهراً متتالية تبلغ فيها المبيعات حد التسجيل، أو نهاية 11 شهراً يتبين فيها أن المبيعات قد تبلغ الحد خلالها والشهر اللاحق.\n- المبيعات المتراكمة لنهاية 12-2018 = 25,000 (حسب الورقة) أي أقل من الحد.\n- الفترة المتحركة 2-2018 إلى 1-2019 = 25,000 - 2,000 + 7,000 = 30,000 دينار = حد التسجيل.\n- إذن يلتزم بالتسجيل بنهاية شهر 1-2019 (ويقدم طلب التسجيل خلال المدة المحددة بالتعليمات)، وإذا توقع ذلك مسبقاً فبنهاية الأحد عشر شهراً (12-2018) وفق البند (3)."},{"num":75,"type":"essay","q":"السؤال الخامس (علامتان): الشركة (س) شركة تجارية ذات مسؤولية محدودة مسجلة في المملكة الأردنية الهاشمية تقوم بشراء بضائع من مصنع مقره في الولايات المتحدة الأمريكية وتقوم بتحويل ثمن تلك البضائع من حسابها لدى البنوك الأردنية، وتقوم ببيع تلك البضائع لشركة أردنية (ص) شريطة ورود البوالص باسم الشركة (ص)، والتي تقوم بعملية التخليص ودفع الرسوم الجمركية المطلوبة. المطلوب: 1- تحديد مدى خضوع الشركة (س) لضريبة الدخل والمساهمة الوطنية وشرائح الضريبة. 2- تحديد مدى خضوع الشركة (س) لضريبة المبيعات وحد التسجيل.","law":"income","article":"3, 11; sales 4 مكرر, 13","status":"valid","model_answer":"1) ضريبة الدخل:\n- الشركة (س) شخص اعتباري مقيم مسجل في المملكة وتمارس نشاطها التجاري (الشراء والبيع والتحويل) من داخل المملكة، فأرباحها دخل متحقق في المملكة خاضع للضريبة (م3).\n- تخضع بنسبة (20%) من الدخل الخاضع (م11/ب/1) دون شرائح (الشرائح للشخص الطبيعي فقط م11/أ).\n- وتدفع مساهمة وطنية (1%) من الدخل الخاضع لباقي الأشخاص الاعتباريين (م11/و/1/هـ).\n2) ضريبة المبيعات:\n- السلع تشحن من الخارج وتصل باسم (ص) التي تخلص عليها، فالتوريد يتم والسلع خارج المنطقة الضريبية (م4 مكرر/أ) ولا تعتبر (س) مستورداً؛ لذا لا تستحق على (س) ضريبة مبيعات على هذه المبيعات ولا تحتسب ضمن حد التسجيل (75,000 للسلع).\n- المستورد هو (ص) وتستحق الضريبة عليه عند التخليص (م9/د، 26/ب) ويلتزم بالتسجيل خلال 30 يوماً من أول استيراد (م13/ب)."},{"num":76,"type":"essay","q":"السؤال السادس (علامة واحدة): على دائرة الجمارك العامة ضبط النقد والأدوات القابلة للتداول لحاملها في حالات محددة اذكرها؟","law":"aml","article":"24","status":"valid","model_answer":"- المادة (24/أ): تضبط دائرة الجمارك النقد والأدوات القابلة للتداول لحاملها في الحالات:\n1. الاشتباه بارتباطها بغسل الأموال أو الجريمة الأصلية المرتبطة بها أو تمويل الإرهاب.\n2. الإقرار الكاذب بإعطاء المعلومات.\n3. عدم قيام الشخص بتقديم الإقرار."},{"num":77,"type":"essay","q":"السؤال السابع (علامة واحدة): استناداً لقانون الأوراق المالية، عرّف التمويل على الهامش.","law":"securities","article":"55","status":"valid","model_answer":"- المادة (55/ب): التمويل على الهامش هو قيام الوسيط المالي بتمويل نسبة من قيمة الأوراق المالية التي يقوم بشرائها لعميله وفق التعليمات والقرارات الصادرة عن الهيئة وبموجب اتفاقية تنظم العلاقة بينهما."},{"num":78,"type":"essay","q":"السؤال الثامن (علامة ونصف): استناداً لقانون الأوراق المالية، عدّد الحالات التي يقوم المرخص له بالتمويل على الهامش بتحديد حقوقه.","law":"securities","article":"55","status":"valid","model_answer":"- المادة (55/د): للمرخص له تحديد حقوقه دون الرجوع للعميل في الحالات:\n1. وفاة العميل.\n2. صدور قرار بتصفية العميل أو شهر إفلاسه أو الحجر عليه.\n3. صدور أمر حجز عن سلطة مختصة على الأوراق المالية العائدة لعميله."},{"num":79,"type":"essay","q":"السؤال التاسع (علامتان): اذكر الأعمال الواجب أن يقوم بها مصفي شركة التضامن عند البدء في عمله؟","law":"companies","article":"37","status":"valid","model_answer":"- المادة (37/أ): على المصفي أن يبدأ عمله بـ:\n- الإعلان عن تصفية الشركة على الموقع الإلكتروني للدائرة.\n- إعداد قائمة بموجودات الشركة ومطلوباتها.\n- تحديد وتسوية ما للشركة من حقوق على الغير وما عليها من التزامات.\n- لا يتنازل عن الأموال أو يتصرف بها إلا بموافقة جميع الشركاء أو إذن المحكمة، ولا يمارس عملاً جديداً إلا لإتمام عمل سابق (37/ب)."},{"num":80,"type":"essay","q":"السؤال العاشر (علامتان): اذكر تعريف شركة المحاسبة [كذا في الورقة، والمقصود شركة المحاصة] وبيان فيما إذا تتمتع بالشخصية الاعتبارية وبيان فيما إذا كانت تخضع لأحكام وإجراءات التسجيل والترخيص؟","law":"companies","article":"49","status":"valid","model_answer":"- المادة (49/أ): شركة المحاصة شركة تجارية تنعقد بين شخصين أو أكثر يمارس أعمالها شريك ظاهر يتعامل مع الغير بحيث تقتصر الشركة على العلاقة الخاصة بين الشركاء، ويجوز إثباتها بجميع طرق الإثبات.\n- المادة (49/ب): لا تتمتع بالشخصية الاعتبارية ولا تخضع لأحكام وإجراءات التسجيل والترخيص."},{"num":81,"type":"essay","q":"السؤال الحادي عشر (علامة ونصف): اذكر شكل إدارة الشركة ذات المسؤولية المحدودة وعدّد أعضاء هيئة مديريها ومدة الإدارة؟","law":"companies","article":"60","status":"valid","model_answer":"- المادة (60/أ): يتولى إدارتها مدير أو هيئة مديرين من الشركاء أو غيرهم.\n- عدد أعضاء هيئة المديرين لا يقل عن اثنين ولا يزيد على سبعة.\n- مدة الإدارة أربع سنوات ويجوز أن ينص النظام على مدة أقل، وتنتخب الهيئة رئيساً ونائباً والمفوضين بالتوقيع."},{"num":82,"type":"essay","q":"السؤال الثاني عشر (علامتان): اذكر أربع من البرامج التي قدمتها المؤسسة العامة للضمان الاجتماعي خلال جائحة كورونا للمؤمن عليهم والمنشآت.","law":"social","article":"","status":"unverified","model_answer":"- برامج صدرت بأوامر الدفاع لا بنصوص القانون، ومنها:\n- برنامج تضامن (1 و2) لدعم العمالة غير المنظمة.\n- برنامج مساند (1 و2 و3) لصرف جزء من الرصيد الادخاري لتأمين التعطل وسلف على حساب التعطل.\n- برنامج حماية لدعم عمال المنشآت المتضررة.\n- برنامج استدامة (واستدامة++) لدعم أجور العاملين في القطاعات الأكثر تضرراً.\n- برنامج تمكين اقتصادي (1 و2) وتخفيض اشتراكات الشمول وتأجيل اشتراكات المنشآت."},{"num":83,"type":"essay","q":"السؤال الثالث عشر (علامة واحدة): عرّف عقد التأمين.","law":"insurance","article":"2","status":"valid","model_answer":"- المادة (2): عقد التأمين اتفاق تلتزم بمقتضاه شركة التأمين أن تؤدي إلى المؤمن له أو إلى المستفيد عوضاً مالياً أو أي منفعة أخرى عند تحقق الخطر المؤمن منه أو حدوث الواقعة المحددة في العقد مقابل مبلغ محدد أو أقساط يؤديها المؤمن له إلى شركة التأمين."},{"num":84,"type":"essay","q":"السؤال الرابع عشر (علامتان): يكون العقد عقد تأجير تمويلي إذا تحقق الشرطان التاليان، وبغض النظر عن شموله أو عدم شموله لخيار الشراء، اذكرهما:","law":"leasing","article":"3","status":"valid","model_answer":"- المادة (3/أ):\n1. أن يكون تملك المؤجر للمأجور من المورد بهدف تأجيره بموجب عقد التأجير.\n2. أن يلتزم المؤجر بتمكين المستأجر من الانتفاع بالمأجور مقابل بدل الإيجار."},{"num":85,"type":"essay","q":"السؤال الخامس عشر (علامة واحدة): عرّف الإعسار الوشيك.","law":"insolvency","article":"2","status":"valid","model_answer":"- المادة (2): الإعسار الوشيك هو الحالة التي يتوقع فيها أن يفقد المدين القدرة المستقبلية على سداد ديونه عند استحقاقها خلال ستة أشهر رغم قدرته الحالية على سدادها."},{"num":86,"type":"essay","q":"السؤال السادس عشر (علامتان): لا تسري أحكام قانون الإعسار على عدة جهات، عدّد أربعاً منها:","law":"insolvency","article":"3","status":"valid","model_answer":"- المادة (3/ب): لا يسري القانون على:\n1. البنوك.\n2. شركات التأمين.\n3. الجمعيات والنوادي ما لم يقرر مجلس الوزراء إخضاعها.\n4. الأشخاص الطبيعيين الخاضعين للقانون المدني (عدا أصحاب المهن المسجلين).\n5. الوزارات والدوائر الحكومية والمؤسسات الرسمية العامة والمؤسسات العامة.\n6. البلديات."},{"num":87,"type":"essay","q":"السؤال السابع عشر (علامة واحدة): أذكر هدفين من أهداف قانون تنظيم مهنة المحاسبة القانونية:","law":"accounting","article":"3","status":"valid","model_answer":"- المادة (3): من أهداف القانون:\n- تنظيم مزاولة المهنة والارتقاء بها.\n- ضمان الالتزام بمعايير المحاسبة والتدقيق المعتمدة بما يحمي الاقتصاد الوطني.\n- الارتقاء بالمستوى العلمي والمهني للمحاسبين القانونيين.\n- تأكيد الالتزام بقواعد سلوك المهنة وآدابها.\n- تعزيز دور المحاسب القانوني وحيدته واستقلاليته."},{"num":88,"type":"essay","q":"السؤال الثامن عشر (علامة واحدة): توقع اللجنة التأديبية عقوبات إذا كان المخالف محاسباً قانونياً، عدّد هذه العقوبات؟","law":"accounting","article":"36","status":"valid","model_answer":"- المادة (36/أ):\n1. التنبيه.\n2. الإنذار الخطي.\n3. تعليق التسجيل وإيقاف العمل بإجازة المزاولة لمدة لا تزيد على سنتين.\n4. إلغاء إجازة المزاولة وشطب اسم المحاسب القانوني نهائياً من سجل المزاولين."},{"num":89,"type":"essay","q":"السؤال التاسع عشر: عرّف: أ. سند السحب. ب. سند الأمر.","law":"other:قانون التجارة","article":"","status":"unverified","model_answer":"- قانون التجارة لسنة 1966 (غير مدرج):\n- سند السحب (الكمبيالة): محرر مكتوب وفق شكل معين يتضمن أمراً من الساحب إلى المسحوب عليه بأن يدفع لأمر شخص ثالث (المستفيد) مبلغاً معيناً في تاريخ معين أو قابل للتعيين أو بمجرد الاطلاع.\n- سند الأمر (السند لأمر): محرر مكتوب وفق شكل معين يتعهد بمقتضاه محرره بأن يدفع مبلغاً معيناً في تاريخ معين أو قابل للتعيين أو لدى الاطلاع لأمر شخص آخر هو المستفيد."}]},{"id":"2022-9a07502e","year":2022,"month":0,"label":"أسئلة متوقعة — الناظر","session":"أسئلة متوقعة — الناظر","src":"9a07502e.json","questions":[{"num":1,"type":"essay","q":"بينت المادة (259) من قانون الشركات الحالات الأربع التي يمكن للشركة المساهمة العامة أن تصفى بموجبها تصفية اختيارية. المطلوب: اذكر ثلاثة منها؟","law":"companies","article":"259","status":"valid","model_answer":"المادة (259): تصفى الشركة المساهمة العامة تصفية اختيارية في أي من الحالات:\n- بانتهاء المدة المعينة للشركة ما لم تقرر الهيئة العامة تمديدها.\n- بإتمام أو انتفاء الغاية التي تأسست من أجلها أو باستحالة إتمامها.\n- بصدور قرار من الهيئة العامة بفسخها وتصفيتها.\n- في الحالات الأخرى التي ينص عليها نظام الشركة."},{"num":2,"type":"essay","q":"تنقضي شركة التضامن في أي من الحالات التالية: (اذكرها) — 1- باتفاق الشركاء جميعهم على حل الشركة أو دمجها في شركة أخرى. 2- بانتهاء المدة المحددة للشركة سواء أكانت المدة الأصلية لها أو التي مددت إليها باتفاق جميع الشركاء. بانتهاء الغاية التي أسست من أجلها. 3- ببقاء شريك واحد فيها، مع مراعاة ما ورد في الفقرة (د) من المادة (28) من هذا القانون. 4- بإشهار إفلاس الشركة، وفي هذه الحالة يترتب على إفلاس الشركة إفلاس الشركاء. 5- بإشهار إفلاس أحد الشركاء فيها أو بالحجر عليه، ما لم يقرر باقي الشركاء جميعهم استمرار الشركة بينهم وفقاً لعقد الشركة. 6- بفسخ الشركة بحكم قضائي. 7- بشطب تسجيل الشركة بقرار من المراقب بمقتضى أحكام هذا القانون.","law":"companies","article":"32","status":"changed","model_answer":"المادة (32) بعد التعديل: تنقضي شركة التضامن:\n- باتفاق الشركاء جميعهم على حلها أو دمجها.\n- بانتهاء مدتها الأصلية أو الممددة باتفاق جميع الشركاء.\n- بانتهاء الغاية التي أسست من أجلها.\n- ببقاء شريك واحد فيها مع مراعاة المادة (28/د).\n- بتصفية الشركة وشطب تسجيلها وفقاً لأحكام قانون الإعسار (بدلاً من «إشهار إفلاس الشركة وإفلاس الشركاء»).\n- بإشهار إعسار أحد الشركاء وخضوعه للتصفية وفق قانون الإعسار أو بالحجر عليه، ما لم يقرر باقي الشركاء الاستمرار (بدلاً من «إشهار إفلاس أحد الشركاء»).\n- بفسخ الشركة بحكم قضائي.\n- بشطب تسجيلها بقرار من المراقب.\nالتغيير: حلّت أحكام الإعسار محل الإفلاس."},{"num":3,"type":"essay","q":"يتولى إدارة الشركة (ذات المسؤولية المحدودة) مدير أو هيئة مديرين لا يقل عدد أعضائها عن اثنين ولا يزيد على سبعة سواء كانوا من الشركاء أو من غيرهم وذلك وفقاً لما ينص عليه النظام الأساسي للشركة لمدة أربع سنوات ويجوز أن ينص النظام على مدة أقل من ذلك وتنتخب هيئة المديرين رئيساً لها ونائباً له والمفوضين بالتوقيع عن الشركة.","law":"companies","article":"60","status":"valid","model_answer":"المادة (60/أ): مدير أو هيئة مديرين من 2 إلى 7 أعضاء (من الشركاء أو غيرهم) لمدة أربع سنوات ويجوز للنظام النص على مدة أقل؛ وتنتخب الهيئة رئيساً ونائباً والمفوضين بالتوقيع."},{"num":4,"type":"essay","q":"يكون لمدير الشركة ذات المسؤولية المحدودة أو لهيئة المديرين فيها الصلاحيات الكاملة في إدارة الشركة في الحدود التي يبينها نظامها. وتعتبر الأعمال والتصرفات التي يقوم بها أو يمارسها المدير أو هيئة المديرين باسم الشركة ملزمة لها في مواجهة الغير الذي يتعامل مع الشركة بحسن نية بغض النظر عن أي قيد يرد في نظام الشركة أو عقد تأسيسها. يعد الغير الذي يتعامل مع الشركة حسن النية ما لم يثبت غير ذلك على أنه لا يلزم ذلك الغير بالتحقق من وجود أي قيد على صلاحيات المدير أو هيئة المديرين على سلطتهم في إلزام الشركة بموجب عقدها أو نظامها.","law":"companies","article":"60","status":"valid","model_answer":"المادة (60/ب، ج):\n- للمدير/هيئة المديرين الصلاحيات الكاملة في الإدارة ضمن حدود النظام، وتصرفاتهم باسم الشركة ملزمة لها تجاه الغير حسن النية رغم أي قيد في النظام أو عقد التأسيس.\n- يفترض حسن نية الغير ما لم يثبت العكس، ولا يلزم بالتحقق من القيود على صلاحيات المدير."},{"num":5,"type":"essay","q":"تلتزم شركة التضامن التي يبلغ رأسمالها مائة ألف دينار أو أكثر بتعيين مدقق حسابات قانوني ينتخب بأكثرية الشركاء.","law":"companies","article":"24","status":"valid","model_answer":"المادة (24/ب): شركة التضامن التي يبلغ رأسمالها 100,000 دينار فأكثر تلتزم بتعيين مدقق حسابات قانوني ينتخب بأكثرية الشركاء (وتلتزم بمسك دفاتر محاسبية منظمة إذا بلغ رأسمالها 10,000 دينار فأكثر – 24/أ)."},{"num":6,"type":"essay","q":"يكون نصاب الاجتماع غير العادي للهيئة العامة للشركة ذات المسؤولية المحدودة قانونياً بحضور عدد من الشركاء يمثلون (75%) من الحصص المكونة لرأسمال الشركة على الأقل أصالة ووكالة، ما لم ينص نظام الشركة على أغلبية أعلى وإذا لم يتوفر النصاب خلال ساعة من الوقت المحدد لبدء الاجتماع فيؤجل الاجتماع إلى موعد آخر خلال عشرة أيام من التاريخ المحدد للاجتماع الأول ويعاد تبليغ الشركاء الذين لم يحضروا ويكون النصاب في الاجتماع الثاني قانونياً بحضور (50%) على الأقل من الحصص المكونة لرأسمال الشركة أصالة ووكالة ما لم ينص نظام الشركة على أغلبية أعلى، وإذا لم يتوفر هذا النصاب يلغى الاجتماع مهما كانت أسباب الدعوة إليه.","law":"companies","article":"65","status":"valid","model_answer":"المادة (65/ب): النصاب 75% من الحصص أصالة ووكالة؛ إن لم يتوفر خلال ساعة يؤجل خلال 10 أيام ويكون النصاب في الاجتماع الثاني 50% على الأقل، وإلا يلغى الاجتماع. (للمقارنة: الاجتماع العادي أكثر من نصف رأس المال، والثاني خلال 15 يوماً بمن حضر – 65/أ)."},{"num":7,"type":"essay","q":"أ- يقدم مجلس إدارة الشركة المساهمة العامة طلب تخفيض رأس مالها المكتتب به إلى المراقب مع الأسباب الموجبة له بعد أن تقرر الهيئة العامة للشركة الموافقة على التخفيض بأكثرية لا تقل عن (75%) خمسة وسبعين بالمائة من الأسهم الممثلة في اجتماعها غير العادي الذي تعقده لهذه الغاية، وترفق بالطلب قائمة بأسماء دائني الشركة ومقدار دين كل منهم وعنوانه وبيان بموجودات الشركة والتزاماتها، على أن تكون قائمة الدائنين للشركة وبيان موجوداتها والتزاماتها مصدقة من مدقق حساباتها.\nب- يبلغ المراقب الدائنين الواردة أسماؤهم في القائمة المقدمة من قبل الشركة إشعاراً يتضمن قرار هيئتها العامة بتخفيض رأس مال الشركة المكتتب به وينشر الإشعار في صحيفتين يوميتين محليتين على نفقة الشركة، ولكل دائن أن يقدم إلى المراقب خلال مدة لا تزيد على ثلاثين يوماً من تاريخ نشر الإشعار لآخر مرة اعتراضاً خطياً على تخفيض رأس مال الشركة، فإذا لم يتمكن المراقب من تسوية الاعتراضات التي قدمت إليه خلال ثلاثين يوماً من تاريخ انتهاء المدة المحددة لتقديمها فيحق لأصحابها مراجعة المحكمة بشأن ما ورد في اعتراضاتهم خلال ثلاثين يوماً من تاريخ انتهاء المدة التي منحت للمراقب لتسويتها وترد أي دعوى تقدم بعد هذه المدة.\nج- إذا تبلغ المراقب إشعاراً خطياً من المحكمة بإقامة أي دعوى لديها خلال المدة المنصوص عليها في الفقرة (ب) من هذه المادة بالطعن في تخفيض رأس مال الشركة المكتتب به، فيترتب عليه أن يوقف إجراءات التخفيض إلى أن يصدر قرار المحكمة في الدعوى ويكتسب الدرجة القطعية، على أن تعتبر الدعوى في هذه الحالة من الدعاوى ذات الصفة المستعجلة بمقتضى أحكام قانون أصول المحاكمات المدنية المعمول به.\nد- إذا لم تقدم أي دعوى إلى المحكمة بالطعن في قرار الهيئة العامة للشركة المساهمة العامة بتخفيض رأس مالها المكتتب به أو أقيمت دعوى وردتها المحكمة واكتسب الحكم الدرجة القطعية فيترتب على المراقب متابعة النظر في تخفيض رأس مال الشركة، وأن يرفع تنسيبه بشأنه إلى الوزير ليصدر القرار الذي يراه مناسباً فيه فإذا قرر الموافقة عليه تم تسجيله ونشره من قبل المراقب على نفقة الشركة وفقاً للإجراءات المنصوص عليها في هذا القانون وبحيث يحل رأس المال المخفض للشركة حكماً محل رأس مالها المدرج في عقد تأسيسها ونظامها.\nهـ- لا تشترط موافقة المراقب والدائنين على تخفيض الجزء غير المكتتب به من رأس المال المصرح به.","law":"companies","article":"115","status":"valid","model_answer":"المادة (115):\n- قرار الهيئة العامة غير العادية بأكثرية لا تقل عن 75% من الأسهم الممثلة، ويرفق بالطلب قائمة الدائنين وبيان الموجودات والالتزامات مصدقة من المدقق.\n- يبلغ المراقب الدائنين وينشر في صحيفتين؛ اعتراض الدائن خلال 30 يوماً من آخر نشر؛ للمراقب 30 يوماً للتسوية؛ ثم 30 يوماً لمراجعة المحكمة.\n- رفع الدعوى يوقف إجراءات التخفيض حتى الحكم القطعي (دعوى مستعجلة).\n- عند عدم الطعن أو رده: تنسيب المراقب للوزير، والتسجيل والنشر على نفقة الشركة.\n- لا تشترط موافقة المراقب والدائنين لتخفيض الجزء غير المكتتب به من رأس المال المصرح به."},{"num":8,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فإن نسبة الضريبة لقطاع التأجير التمويلي لسنة 2019 ب:","o":["24% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية.","24% ضريبة دخل ونسبة 4% لحساب المساهمة الوطنية.","24% ضريبة دخل ونسبة 3% لحساب المساهمة الوطنية.","20% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية."],"answer":1,"orig_answer":1,"law":"income","article":"11","status":"valid","explanation":"المادة (11/ب/2): 24% للأشخاص الاعتباريين الذين يمارسون أنشطة التأجير التمويلي، والمادة (11/و/1/ج): 4% من الدخل الخاضع لحساب المساهمة الوطنية."},{"num":9,"type":"mcq","q":"تملك شركة س 70% من أسهم شركة ص، بتاريخ 2020/1/1 حصلت شركة ص على قرض من شركة س لتمويل أنشطتها، قيمة القرض 1,200,000 دينار وبفائدة 3%، بلغ رأس المال المدفوع لشركة ص 100,000 دينار، ومتوسط حقوق الملكية 200,000 دينار، أن مصروف الفائدة المقبول تنزيله ضريبياً لشركة ص لسنة 2020:","o":["10,800 دينار.","18,000 دينار.","36,000 دينار.","لا شيء مما ذكر."],"answer":1,"orig_answer":1,"law":"income","article":"6","status":"valid","explanation":"المادة (6/ب/2): فوائد الأشخاص ذوي العلاقة تنزل بحدود نسبة 3:1 للدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر: (3×200,000 ÷ 1,200,000) × 36,000 = 18,000 دينار."},{"num":10,"type":"mcq","q":"بتاريخ 01/03/2021 أعلنت شركة الشرق لتجارة السيارات عن أسماء الفائزين بجوائزها السنوية، وهي عبارة عن 3 سيارات قيمة كل منها 20,000 دينار بهذا التاريخ، وتم تسليم السيارات للفائزين بتاريخ 2020/12/01؛ حيث كان السعر السوقي بتاريخ التسليم 19,000 دينار لكل سيارة. ضريبة الدخل الواجب اقتطاعها وتوريدها من الشركة مقابل هذه الجوائز:","o":["5,700 دينار.","9,000 دينار.","6,000 دينار.","8,550 دينار."],"answer":3,"orig_answer":3,"law":"income","article":"12","status":"valid","explanation":"المادة (12/أ/3): يقتطع 15% من الجوائز التي تزيد قيمة كل منها على ألف دينار كضريبة قطعية، والدخل العيني يقيّم بسعر السوق بتاريخ الاستحقاق (3/ب): 19,000×3×15% = 8,550 دينار (حسب حل المُعِد؛ تواريخ السؤال كما وردت في الأصل)."},{"num":11,"type":"mcq","q":"شخص غير أردني وغير مقيم بالأردن له دخل من عقار مؤجر بقيمة 30,000، وهو معيل لعائلته المقيمة في الأردن، فإن ضريبة الدخل المستحقة عليه عام 2000 [كذا في الأصل، والمقصود غالباً 2020] هي:","o":["2,750 دينار.","750 دينار.","1,050 دينار.","5,000 دينار."],"answer":3,"orig_answer":3,"law":"income","article":"11","status":"valid","explanation":"الإعفاءات في المادة (9/أ) للشخص الطبيعي المقيم، والمادة (9/د) تمنح إعفاء المعالين لغير المقيم الأردني فقط؛ فلا إعفاء له. الضريبة حسب الشرائح (11/أ): 250+500+750+1000+2,500 = 5,000 دينار."},{"num":12,"type":"mcq","q":"أظهرت قائمة الدخل لشركة الصلب والحديد الصناعية لسنة 2020 صافي دخل 500,000 دينار، وظهر في قائمة الدخل مصاريف إدارية وعمومية 100,000 دينار، وأرباح واستثمارات في شركات محلية 40,000 دينار، إن ضريبة الدخل المستحقة على الشركة:","o":["76,500 دينار.","81,600 دينار.","66,000 دينار.","88,000 دينار."],"answer":1,"orig_answer":1,"law":"income","article":"11","status":"valid","explanation":"حسب حل المُعِد: يضاف 25% من توزيعات الأرباح المعفاة (4/أ/8) كمصاريف غير مقبولة: 500,000+10,000 = 510,000 × 20% (11/ب/1) = 102,000، ويخفض 20% للنشاط الصناعي لسنة 2020 (11/ج/1) = 81,600 دينار."},{"num":13,"type":"essay","q":"أبرمت شركة الاتحاد عقد تأمين على المباني التي تملكها مع شركة ما وراء البحار للتأمين ولمدة سنة كاملة يبدأ العقد بتاريخ 2020/9/29 وينتهي بتاريخ 2021/9/28، حيث بلغت قيمة عقد التأمين 50,000 دينار، وقامت شركة التأمين بإعادة تأمين 75% من قيمة العقد لدى شركة زيورخ السويسرية. المطلوب احتساب قيمة مخصص الأقساط غير المكتسبة الواجب تنزيله في 2020/12/31؟","law":"income","article":"6","status":"valid","model_answer":"- المادة (6/د): تنزل مخصصات شركات التأمين المتعلقة بالأقساط غير المكتسبة، ويضاف ما نُزّل منها إلى دخل الفترة التالية.\n- المخصص = ((قيمة العقد − حصة معيدي التأمين) ÷ 365) × الأيام المتبقية في الفترة التالية.\n- = ((50,000 − 37,500) ÷ 365) × 271 يوماً (من 2021/1/1 حتى 2021/9/28) ≈ 9,281 دينار."},{"num":14,"type":"essay","q":"تلغى صفة الدين غير العامل لجميع حسابات العميل لدى البنك الواحد إذا تضمنت حسابات العميل وحسابات كفيله ديناً عاملاً لدى البنك نفسه ولا تعتبر المخصصات المتعلقة بحسابات العميل من المصاريف المقبولة ضريبياً.","law":"income","article":"6","status":"unverified","model_answer":"- المادة (6/ج): تنزل مخصصات البنوك وفق قانون البنوك، ويلتزم البنك بتخفيض المخصص الخاص للائتمان غير العامل عند تحويله إلى ائتمان عامل أو تحصيله أو شطبه، ويظهر التخفيض في دخله الإجمالي.\n- القاعدة الواردة (إلغاء صفة الدين غير العامل إذا تضمنت حسابات العميل أو كفيله ديناً عاملاً) مصدرها النظام/التعليمات التنفيذية وليست نصاً في القانون."},{"num":15,"type":"essay","q":"تتولى الهيئة العليا المهام والصلاحيات التالية: 1- اعتماد معايير المحاسبة ومعايير تدقيق الحسابات الواجبة التطبيق بناء على تنسيب المجلس. 2- تشكيل لجنة ترخيص المهنة ووضع التعليمات اللازمة لتنظيم عملها وتحديد صلاحياتها وكيفية إجراء الامتحانات وسائر الأمور المتعلقة بها. 3- المصادقة على منح إجازة المزاولة بناء على تنسيب لجنة الترخيص وإلغاء هذه الإجازة بناء على تنسيب المجلس. 4- النظر في الاعتراضات المقدمة على قرارات المجلس. 5- تشكيل اللجان اللازمة لمساعدة الهيئة العليا على القيام بمهامها وتحديد صلاحياتها. 6- إصدار التعليمات المتعلقة بتنظيم عملها والتعليمات اللازمة لتنفيذ أحكام هذا القانون والأنظمة الصادرة بمقتضاه. 7- إعداد مشروعات التشريعات المتعلقة بالمهنة بالتعاون والتنسيق مع المجلس. 8- اعتماد المعاهد المهنية للمحاسبين القانونيين أو ما يماثلها.","law":"accounting","article":"5","status":"valid","model_answer":"المادة (5): مهام الهيئة العليا: اعتماد معايير المحاسبة والتدقيق بتنسيب المجلس؛ تشكيل لجنة الترخيص ووضع تعليماتها والامتحانات؛ المصادقة على منح إجازة المزاولة (بتنسيب لجنة الترخيص) وإلغائها (بتنسيب المجلس)؛ النظر في الاعتراضات على قرارات المجلس؛ تشكيل اللجان؛ إصدار التعليمات؛ إعداد مشروعات التشريعات بالتنسيق مع المجلس؛ اعتماد المعاهد المهنية."},{"num":16,"type":"mcq","q":"يشترط للاستفادة من بدل إجازة الأمومة:","o":["أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (9) أشهر قبل الولادة.","أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (6) أشهر قبل الولادة.","أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (12) شهراً قبل الولادة.","لا شيء مما ذكر."],"answer":1,"orig_answer":1,"law":"social","article":"44","status":"valid","explanation":"المادة (44/أ): أن تكون مشمولة بتأمين الأمومة خلال الأشهر الستة الأخيرة التي تسبق استحقاقها إجازة الأمومة، وأن تثبت الولادة بشهادة رسمية."},{"num":17,"type":"essay","q":"يستحق المؤمن عليه راتب اعتلال العجز الكلي الطبيعي الدائم أو راتب اعتلال العجز الجزئي الطبيعي الدائم شريطة تحقق ما يلي: 1- انتهاء خدمته. 2- أن يتقدم بطلب تخصيص راتب الاعتلال خلال مدة لا تتجاوز ستة أشهر من تاريخ انتهاء الخدمة. 3- أن لا تقل اشتراكاته الفعلية عن (60) اشتراكاً منها (24) اشتراكاً متصلاً. 4- ثبوت حالة العجز بقرار من المرجع الطبي.","law":"social","article":"67","status":"valid","model_answer":"المادة (67/أ): انتهاء الخدمة؛ تقديم الطلب خلال 6 أشهر من انتهاء الخدمة؛ اشتراكات فعلية لا تقل عن 60 منها 24 متصلة؛ ثبوت العجز بقرار المرجع الطبي."},{"num":18,"type":"essay","q":"يستحق المؤمن عليه راتب تقاعد الوفاة الطبيعية إذا وقعت الوفاة خلال خدمته المشمولة بأحكام هذا القانون شريطة أن يكون قد سدد ما لا يقل عن (24) اشتراكاً فعلياً منها (6) اشتراكات متصلة.","law":"social","article":"66","status":"valid","model_answer":"المادة (66/أ): 24 اشتراكاً فعلياً منها 6 متصلة إذا وقعت الوفاة خلال الخدمة؛ والراتب 50% من متوسط أجر آخر 12 اشتراكاً (66/ب)."},{"num":19,"type":"essay","q":"يقصد بشرط الاختراق الشرط الوارد في عقد إعادة التأمين والذي يقضي بمسؤولية معيد التأمين في حدود حصته من الخسارة المعاد تأمينها لديه تجاه المؤمن له والمستفيد في الحالات التي يتعذر على المؤمن الوفاء بالتزاماته تجاه المؤمن له أو المستفيد كتصفية شركة التأمين وبحيث تنشأ علاقة مباشرة بين معيد التأمين والمؤمن له والمستفيد.","law":"insurance","article":"71","status":"valid","model_answer":"المادة (71/ب): التعريف كما ورد؛ و(71/أ): يحق للمؤمن له أو المستفيد الانتفاع من شرط الاختراق ولا يجوز لأي جهة الاعتراض على تفعيله."},{"num":20,"type":"essay","q":"- يخضع عمل وكيل الإعسار لإشراف المحكمة ورقابة الدائنين أو من يمثلهم في الحدود المبينة في هذا القانون.\n- للمحكمة وللجنة الدائنين، من وقت لآخر أن تكلف وكيل الإعسار بتزويدها بمعلومات محددة أو بتقديم تقرير عن سير إجراءات الإعسار وإدارة ذمة الإعسار.","law":"insolvency","article":"52","status":"valid","model_answer":"المادة (52/أ، ب): إشراف المحكمة ورقابة الدائنين على وكيل الإعسار، وللمحكمة ولجنة الدائنين تكليفه بتقديم معلومات أو تقارير عن سير الإجراءات وإدارة ذمة الإعسار."},{"num":21,"type":"mcq","q":"لا يجوز لأي شخص طلب شراء أوراق مالية أو مبادلتها بهدف تملك ما يزيد عن النسب التالية من الأوراق المالية المصدرة من مصدر عام إلا عن طريق عرض تملك عام وفقاً للتعليمات التي يصدرها المجلس:","o":["(33.3%).","(51%).","(40%).","(50%)."],"answer":2,"orig_answer":2,"law":"securities","article":"45","status":"valid","explanation":"المادة (45/أ): لا يجوز طلب شراء أو مبادلة أوراق مالية بهدف تملك (40%) أو أكثر من أوراق مصدر عام إلا بعرض تملك عام وفقاً لنظام يصدر لهذه الغاية (النص الحالي «40% أو أكثر» و«نظام» بدل «تعليمات»؛ الإجابة لم تتغير)."},{"num":22,"type":"essay","q":"المعتمد: الشخص الطبيعي الذي يكون عضواً في مجلس إدارة شركة خدمات مالية أو هيئة مديريها أو مديراً أو مسؤولاً إدارياً أو موظفاً فيها، أو ممن يشغل وضعاً مشابهاً في الشركة أو يمارس صلاحيات مماثلة لدى وسيط مالي أو وسيط لحسابه أو أمين استثمار أو مدير استثمار أو مستشار مالي أو مدير إصدار أو شركة خدمات مالية ولا يشمل ذلك المستخدمين في الوظائف المكتبية والخدمات وتلك التي لا علاقة لها بالنشاط المتعلق بالأوراق المالية.","law":"securities","article":"2","status":"valid","model_answer":"المادة (2): تعريف المعتمد كما ورد — شخص طبيعي (عضو مجلس/هيئة مديرين، مدير، مسؤول إداري، موظف أو من في حكمهم) لدى شركة خدمات مالية أو وسيط أو أمين/مدير استثمار أو مستشار مالي أو مدير إصدار، ويستثنى موظفو الوظائف المكتبية والخدماتية وغير المتعلقة بنشاط الأوراق المالية."},{"num":23,"type":"essay","q":"يعتبر مخالفة لأحكام هذا القانون قيام المرخص له أو المعتمد بأي مما يلي:\nأ- إساءة التصرف بأموال العملاء أو المساهمين بما في ذلك إساءة توظيفها أو استخدامها.\nب- ممارسة الخداع والتضليل والأعمال المحظورة.\nج- التأثير سلباً على المنافسة وذلك بالتلاعب بنسب العمولات أو ببدل الخدمات التي يتقاضاها أي منهما من العملاء أو الحد من الخدمات المقدمة سواء كان ذلك بشكل منفرد أو بالتواطؤ مع الغير.\nد- التأثير سلباً أو محاولة التأثير سلباً وبأي شكل من الأشكال على سوق رأس المال سواء كان ذلك بشكل منفرد أو بالتواطؤ مع الغير.","law":"securities","article":"56","status":"valid","model_answer":"المادة (56): إساءة التصرف بأموال العملاء/المساهمين؛ الخداع والتضليل والأعمال المحظورة؛ التأثير سلباً على المنافسة بالتلاعب بالعمولات أو بدل الخدمات أو الحد منها؛ التأثير أو محاولة التأثير سلباً على سوق رأس المال منفرداً أو بالتواطؤ."},{"num":24,"type":"essay","q":"أ- على كل مصدر أن يقدم إلى الهيئة، ووفقاً للتعليمات التي يصدرها المجلس، التقارير الدورية المبينة أدناه وأن يقوم بنشرها:\n1- تقريراً سنوياً، يتضمن البيانات المالية مدققة من مدقق حسابات قانوني خلال تسعين يوماً من تاريخ انتهاء سنته المالية.\n2- تقرير ربع سنوي يقدم خلال ثلاثين يوماً من تاريخ انتهاء الربع المعني مراجعاً من مدقق حسابات قانوني.\n3- تقريراً عن نتائج أعماله الأولية بعد قيام مدقق حسابات قانوني بإجراء عملية المراجعة الأولية لها، وذلك خلال خمسة وأربعين يوماً من انتهاء سنته المالية حداً أعلى.\n4- تقريراً يتعلق بانتخاب مجلس الإدارة وأي تغيير في تشكيلة أو هوية أي من أعضائه.","law":"securities","article":"43","status":"valid","model_answer":"المادة (43/أ): سنوي مدقق خلال 90 يوماً؛ ربع سنوي مراجَع خلال 30 يوماً؛ نتائج أولية مراجعة خلال 45 يوماً حداً أعلى؛ تقرير عن انتخاب مجلس الإدارة وأي تغيير فيه. و(43/د): بيان علني فوري بأي معلومة جوهرية."},{"num":25,"type":"essay","q":"أ- يتخذ الصندوق أحد الشكلين التاليين:\n1- الصندوق المفتوح وهو صندوق ذو رأسمال متغير تتم زيادة رأسماله من خلال طرح وحدات استثمارية جديدة ويتم تخفيض رأسماله من خلال استرداد وحداته الاستثمارية خلال الفترة المحددة في نظامه الأساسي ونشرة إصداره.\n2- الصندوق المغلق وهو صندوق ذو رأسمال ثابت تتم زيادة رأسماله وتخفيضه وفقاً لأحكام هذا النظام ونظامه الأساسي ونشرة إصداره.\nب- يتكون رأسمال الصندوق من مجموع القيم الاسمية لوحداته الاستثمارية عند التأسيس المحددة في النظام الأساسي للصندوق ونشرة إصداره، ويقسم إلى وحدات استثمارية متساوية في الحقوق تسدد قيمتها نقداً دفعة واحدة عند الاكتتاب بها، وتكون مسؤولية حملة الوحدات الاستثمارية محدودة بمقدار مساهمتهم في رأسمال الصندوق.\nج- يكون لكل وحدة استثمارية صوت واحد في اجتماعات الهيئة العامة للصندوق.\nد- يشترط أن لا يقل رأسمال الصندوق عند التأسيس عن مليوني دينار أردني أو ما يعادل ذلك من العملات الأجنبية الأخرى.\nهـ- يشترط أن لا تقل نسبة مساهمة مدير الاستثمار والشركات الحليفة له عن (5%) وأن لا تتجاوز (25%) من رأسمال الصندوق عند التأسيس، ولا يجوز التصرف في مساهمته ومساهمة الشركات الحليفة له قبل مضي سنتين من تاريخ منح الصندوق حق الشروع بالعمل، على أن لا تقل نسبة مساهمته والشركات الحليفة له في أي وقت بعد التأسيس عن (5%) من رأسماله.","law":"other:نظام صناديق الاستثمار المشترك","article":"","status":"unverified","model_answer":"- مصدر النص نظام صناديق الاستثمار المشترك (غير متوفر نصه هنا)؛ وقانون الأوراق المالية (المادتان 94، 95) يميز بين الصندوق المفتوح (يصدر وحداته ويستردها على أساس صافي قيمة الأصول) والمغلق (له التحول إلى مفتوح إذا نص نظامه على ذلك).\n- النقاط المتوقعة: الشكلان (مفتوح متغير رأس المال / مغلق ثابت)؛ وحدات متساوية تسدد نقداً دفعة واحدة؛ صوت لكل وحدة؛ حد أدنى لرأس المال مليونا دينار (الفقرة المظللة في الأصل)؛ مساهمة مدير الاستثمار وحلفائه 5%–25% عند التأسيس، وحظر التصرف بها سنتين، ولا تقل بعدها عن 5%."},{"num":26,"type":"essay","q":"مدير الاستثمار: الشخص الذي يمارس إدارة محافظ الأوراق المالية لحساب الغير بما في ذلك إدارة صندوق الاستثمار المشترك.","law":"securities","article":"2","status":"valid","model_answer":"المادة (2): مدير الاستثمار هو الشخص الذي يمارس إدارة محافظ الأوراق المالية لحساب الغير بما في ذلك إدارة صندوق الاستثمار المشترك."},{"num":27,"type":"mcq","q":"أي من العبارات التالية لا يعتبر صحيحاً بموجب قانون التجارة رقم (12) لعام 1966:","o":["إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانوناً بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي من الإفلاس.","إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانوناً بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي من الإفلاس.","لا تعد الدولة ودوائرها ذات شخصية اعتبارية من التجار وإن قامت بمعاملات تجارية.","يعد تاجراً كل من أعلن في الصحف أو النشرات أو أية واسطة أخرى عن المحل الذي أسسه وفتحه للاشتغال بالأعمال التجارية."],"answer":1,"orig_answer":1,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"الخياران (أ) و(ب) متطابقان في الأصل (خطأ في الورقة) والمظلل هو (ب). العبارة غير الصحيحة: الموظفون والقضاة الممنوعون من الاتجار إذا اشتغلوا بالتجارة تطبق عليهم أحكام الإفلاس ولا يستفيدون من الصلح الواقي — قانون التجارة 1966 غير متوفر للتحقق."},{"num":28,"type":"mcq","q":"جميع الأمور التالية صحيحة بخصوص الوكالة التجارية حسب قانون التجارة باستثناء:","o":["الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي.","في المواد التجارية يستحق الوكيل الأجر في جميع الأحوال ما لم يكن هنالك نص مخالف.","الوكالة التجارية إن احتوت على توكيل مطلق تجيز الأعمال غير التجارية وإن لم يرد نص.","تكون الوكالة تجارية عندما تختص بمعاملات تجارية."],"answer":2,"orig_answer":2,"law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","explanation":"حسب الورقة (الخيار المظلل ج): الوكالة التجارية المطلقة لا تجيز الأعمال غير التجارية إلا بنص صريح — من أحكام الوكالة في قانون التجارة 1966، غير متوفر للتحقق."},{"num":29,"type":"essay","q":"الأوراق التجارية هي أسناد قابلة للتداول بمقتضى أحكام هذا القانون وتشتمل على ما يلي:\nأ- سند السحب ويسمى أيضاً البوليصة أو السفتجة وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن أمراً صادراً من شخص هو الساحب إلى شخص آخر هو المسحوب عليه بأن يدفع لأمر شخص ثالث هو المستفيد أو حامل السند مبلغاً معيناً بمجرد الاطلاع أو في ميعاد معين أو قابل للتعيين.\nب- سند الأمر ويسمى أيضاً السند الإذني ومعروف باسم الكمبيالة وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن تعهد محرره بدفع مبلغ معين بمجرد الاطلاع أو في ميعاد معين أو قابل للتعيين لأمر شخص آخر هو المستفيد أو حامل السند.\nج- الشيك وهو محرر مكتوب وفق شرائط مذكورة في القانون ويتضمن أمراً صادراً من شخص هو الساحب إلى شخص آخر يكون معرفاً وهو المسحوب عليه بأن يدفع لشخص ثالث أو لأمره أو لحامل الشيك - وهو المستفيد - مبلغاً معيناً بمجرد الاطلاع على الشيك.\nد- السند لحامله أو القابل للانتقال بالتظهير.","law":"other:قانون التجارة رقم (12) لسنة 1966","article":"","status":"unverified","model_answer":"الأوراق التجارية: سند السحب (البوليصة/السفتجة): أمر من الساحب للمسحوب عليه بالدفع للمستفيد؛ سند الأمر (الكمبيالة): تعهد من المحرر بالدفع؛ الشيك: أمر بالدفع بمجرد الاطلاع؛ السند لحامله أو القابل للتظهير. (قانون التجارة 1966 – غير متوفر للتحقق)."},{"num":30,"type":"essay","q":"أ- يحتفظ البنك المركزي باحتياطي عام يقيد فيه 20% (عشرون بالمئة) من الربح الصافي للبنك المركزي في كل سنة مالية ويدفع الباقي أي (ثمانون بالمئة) من الربح الصافي للحكومة.\nب- تدفع جميع الأرباح الصافية للحكومة عندما يزيد مقدار الاحتياطي العام على مثلي رأس المال.","law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","model_answer":"من قانون البنك المركزي الأردني (غير متوفر هنا): يقيد 20% من صافي الربح السنوي في الاحتياطي العام ويدفع 80% للحكومة؛ وتدفع كامل الأرباح الصافية للحكومة إذا زاد الاحتياطي العام على مثلي رأس المال."},{"num":31,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات، يجوز للمدير أو المدقق حسب مقتضى الحال أن يصحح الأخطاء الحسابية التي تقع في القرارات عن طريق السهو العرضي:","o":["من تلقاء نفسه أو بناء على طلب المكلف ولا تكون إجراءات التصحيح خاضعة للطعن.","بناء على طلب المكلف وتكون إجراءات التصحيح خاضعة للطعن.","من تلقاء نفسه أو بناء على طلب المكلف وتكون إجراءات التصحيح خاضعة للطعن.","من تلقاء نفسه وتكون إجراءات التصحيح خاضعة للطعن."],"answer":0,"orig_answer":0,"law":"sales","article":"71","status":"valid","explanation":"المادة (71): للمدير أو الموظف المفوض أو المدقق في أي وقت تصحيح الأخطاء الكتابية والحسابية من تلقاء ذاته أو بناء على طلب المكلف ولا تكون إجراءات التصحيح خاضعة للطعن."},{"num":32,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات يتحمل المحاسب القانوني المسؤولية عن المصادقة على بيانات مالية تخالف معايير المحاسبة الدولية والأنظمة النافذة بسبب إهمال جسيم منه، ويعاقب وفقاً للقانون:","o":["لا تقل عن مقدار الضريبة ولا تزيد عن مثلي الضريبة أو بغرامة جزئية لا تقل عن 200 دينار ولا تزيد عن 500 دينار أو بكلتا العقوبتين.","لا يقل عن مثلي مقدار الضريبة ولا يزيد عن مثلي مقدار الضريبة أو بالحبس لمدة لا تقل عن ثلاثة أشهر ولا تزيد عن ستة أشهر.","لا تقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزئية لا تقل عن 200 دينار ولا تزيد عن 500 دينار.","لا يقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزئية لا تقل عن مئتي دينار ولا تزيد عن ألف دينار."],"answer":3,"orig_answer":3,"law":"sales","article":"67","status":"valid","explanation":"المادة (67): يعتبر المحاسب القانوني مرتكباً جرماً ويعاقب بعقوبة المادة (31): تعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها وغرامة جزائية 200–1,000 دينار."},{"num":33,"type":"mcq","q":"شركة قامت باستيراد خدمة بتاريخ 31-1-2022 وقامت بتسديد قيمة الخدمة بتاريخ 10-4-2022 وقامت بدفع ضريبة المبيعات بتاريخ 25-4-2022 فيترتب عليها:","o":["لا يترتب عليه غرامة الشركة.","يترتب على الشركة غرامة 0.4% عن كل أسبوع بعد نهاية شهر 2.","يترتب على الشركة غرامة 0.4% عن كل أسبوع بعد نهاية شهر 2، وغرامة مثل الضريبة.","يترتب على الشركة غرامة 0.4% عن كل أسبوع بعد نهاية شهر 2 وغرامة مثلي الضريبة."],"answer":0,"orig_answer":0,"law":"sales","article":"26","status":"valid","explanation":"المادة (26/ج): تدفع ضريبة الخدمة المستوردة أيهما أسبق: خلال شهر من دفع البدل (2022/5/10) أو خلال 6 أشهر من تلقيها (2022/7/31)؛ الأسبق 2022/5/10 والدفع تم في 2022/4/25 فلا غرامة."},{"num":34,"type":"essay","q":"قامت الشركة المتميزة بتاريخ 2022/1/1 بالتسجيل بشبكة المكلفين بالضريبة العامة على المبيعات وكان لديها بضاعة بتاريخ التسجيل بواقع 50,000 دينار مفصلة على النحو التالي:\nبضاعة خاضعة لنسبة 16% بواقع 35,000 دينار مشتراه بموجب فواتير ضريبية وتواريخها على النحو التالي:\n(رقم الفاتورة | تاريخ الفاتورة | قيمة الفاتورة شاملة الضريبة): 105 | 2015/1/1 | 15,000 ؛ 1234 | 2018/6/1 | 10,000 ؛ 117 | 2020/9/1 | 4,000 ؛ 2333 | 2021/11/1 | 6,000.\nبضاعة خاضعة لنسبة 4% بواقع 15,000 دينار مشتراه بموجب فواتير غير ضريبية.\nالمطلوب: احتساب قيمة الضريبة المقبول خصمها ضمن أول إقرار ضريبي تقديمه من قبل الشركة؟","law":"sales","article":"19","status":"valid","model_answer":"- المادة (19/د): للمسجل خصم ما سبق تحمله قبل التسجيل من ضريبة عامة على السلع التي في حوزته عند التسجيل (وتفاصيل الخصم في التعليمات).\n- بضاعة بفواتير ضريبية (حسب حل المُعِد تُرصّد 100%): 35,000 ÷ 1.16 = 30,172.41 × 16% = 4,827.585 دينار.\n- بضاعة 4% مشتراة من غير مسجلين بفواتير غير ضريبية: يرصد 50% من الضريبة المفترضة: 15,000 × 4% = 600 × 50% = 300 دينار.\n- المقبول خصمه في أول إقرار = 4,827.585 + 300 = 5,127.585 دينار."},{"num":35,"type":"essay","q":"احسب مبلغ ضريبة المبيعات للفترة 11+12 للعام 2022 إذا علمت أن بيانات الفترة كانت كما يلي:\nمشتريات خاضعة لنسبة 16% بواقع 20,000 دينار\nمستوردات خاضعة لنسبة 16% بواقع 15,000 دينار (تم إعادة تخمين البضاعة بقيمة 18,000 دينار)\nمصاريف الضيافة 1,160 شاملة الضريبة 16%\nمصاريف القرطاسية 116 دينار شاملة الضريبة 16%\nمبيعات معفاة بواقع 10,000 دينار\nمبيعات لجهات معفاة بواقع 30,000 دينار\nمبيعات خاضعة لنسبة 16% بواقع 50,000 دينار\nعلماً بأن الرصيد المدور من الفترة السابقة هو 1,500 دينار؟","law":"sales","article":"19","status":"unverified","model_answer":"حسب حل المُعِد:\n- ضريبة المخرجات: 50,000 × 16% = 8,000.\n- ضريبة المدخلات: مشتريات 3,200 + مستوردات (على القيمة المعاد تخمينها 18,000) 2,880 + قرطاسية 16 = 6,096؛ ضريبة الضيافة (160) غير قابلة للخصم (الجدول رقم 4 – المادة 19/ج).\n- ضريبة غير قابلة للخصم بالتناسب: السلع المعفاة (10,000/90,000)×16 = 1.777؛ الجهات المعفاة (30,000/90,000)×6,096 = 2,032.\n- الرصيد: 8,000 + 2,033.777 − (1,500 + 3,200 + 2,880 + 16) = 2,437.777 دينار لصالح الدائرة.\n- ملاحظة: أساس التوزيع النسبي للمدخلات مصدره التعليمات التنفيذية وليس نص القانون، وطريقة المُعِد في احتساب حصة السلع المعفاة (على القرطاسية فقط) محل نظر."}]},{"id":"2021-08","year":2021,"month":8,"label":"دورة آب 2021","session":"آب","src":"34369852.json","questions":[{"num":1,"type":"mcq","q":"يجوز للأشخاص الطبيعيين تنظيم دفاتر الإيرادات والتكاليف والنفقات بدلاً من دفتر اليومية باستثناء:","o":["الشخص الطبيعي الذي ينحصر دخله من ثلاث آليات إنشائية فأكثر.","المحاسبين القانونيين.","الأطباء.","المحامين."],"law":"income","answer":0,"orig_answer":null,"article":"23","status":"unverified","explanation":"المادة (23/د) تحيل استثناء فئات من تنظيم السجلات المدققة إلى نظام؛ والاستثناء من دفاتر الإيرادات والنفقات للشخص المالك لثلاث آليات إنشائية فأكثر يرد في النظام (غير موجود في نص القانون)."},{"num":2,"type":"mcq","q":"قامت شركة تأمين أردنية بدفع مبلغ 100,000 دينار لشركة تأمين بريطانية غير مقيمة مقابل عقود إعادة تأمين لسنة 2020، وعليه فإن ضريبة الدخل المتوجب على الشركة الأردنية اقتطاعه:","o":["معفاة.","7%.","10%.","5%."],"law":"income","answer":2,"orig_answer":null,"article":"12","status":"unverified","explanation":"المادة (12/ب/1): يقتطع (10%) من أي دخل غير معفى يدفع لشخص غير مقيم، وأقساط إعادة التأمين للأخطار داخل المملكة دخل متأتٍ في المملكة (المادة 3/أ/8)؛ قد تعالج التعليمات التنفيذية حالة إعادة التأمين بشكل خاص."},{"num":3,"type":"mcq","q":"قدم مكلف إقراره الضريبي لسنة 2019 ضمن المدة القانونية، وقام بدفع ضريبة الدخل المستحقة عليه البالغ 4,900 دينار، قامت الدائرة بالتقدير عليه بتاريخ 2019/10/1 صدر إشعار التقدير بضريبة دخل مستحقة 9,800 دينار قام المكلف بتسديد الفرق الضريبي بتاريخ 2019/10/25 فإن الغرامة المستحقة عليه:","o":["لا يترتب عليه غرامة.","100 دينار + 499 دينار.","499 دينار.","100 دينار."],"law":"income","answer":0,"orig_answer":null,"article":"36","status":"unverified","explanation":"المادة (36/ب): الفرق (4,900) لا يزيد على خمسة آلاف فتحتسب غرامة التأخير من تاريخ التبليغ إذا لم يسدد في موعده، وقد سدده خلال (30) يوماً؛ لكن المادة (64/أ/8) تفرض ضريبة مضافة (200-500) إذا كان النقص لا يقل عن 25%، وهو مبلغ غير وارد في الخيارات."},{"num":4,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل، فإن المخصص المقبول تنزيله نفقة ضريبية دون قيد أو شرط:","o":["مخصص الديون المشكوك في تحصيلها.","مخصص تدني التسهيلات الائتمانية تحت المراقبة.","مخصص تدني قيمة المخزون.","مخصص الديون المعدومة."],"law":"income","answer":3,"orig_answer":null,"article":"6","status":"unverified","explanation":"المادة (6/هـ،و): مخصص الديون المشكوك فيها مقيد بإعداد بيانات وفق المعايير ومدققة، ومخصصات التسهيلات خاصة بالبنوك؛ أما الديون الهالكة (المعدومة) فتنزل إذا سبق احتسابها في الدخل."},{"num":5,"type":"mcq","q":"يعفى من ضريبة الدخل من مكافأة نهاية الخدمة المتعلقة بالفترة الضريبية من عام 2010 لغاية 2014 :","o":["5,000 دينار.","50% من قيمة المكافأة.","100% من قيمة المكافأة.","15,000 دينار."],"law":"income","answer":1,"orig_answer":null,"article":"4","status":"valid","explanation":"المادة (4/أ/13/ب): يعفى (50%) من مكافأة نهاية الخدمة عن الخدمات من 2010/1/1 لغاية 2014/12/31."},{"num":6,"type":"mcq","q":"قدمت شركة مساهمة خاصة إقرار ضريبة الدخل لسنة 2020 بتاريخ 2021/6/1 بناء على ذلك يترتب على الشركة غرامة بقيمة:","o":["500 دينار.","300 دينار.","100 دينار.","لا شيء مما ذكر."],"law":"income","answer":3,"orig_answer":null,"article":"63","status":"valid","explanation":"المادتان (17) و(63): الإقرار يقدم حتى نهاية الشهر الرابع، وغرامة التأخير للشركات المساهمة العامة والخاصة بحد أقصى ألف دينار، فلا ينطبق أي من المبالغ المذكورة."},{"num":7,"type":"mcq","q":"تفرض ضريبة مضافة لا تقل عن مائتي دينار ولا تزيد عن 500 دينار إذا ثبت وجود نقص في الإقرار الضريبي أو زيادة في مبلغ التقاص أو خصم ضريبة مدفوعة على الحساب إذا كانت نسبة الفرق:","o":["لا تقل عن 15% من الضريبة المستحقة.","لا تقل عن 25% من الضريبة المستحقة.","لا تقل عن 10% من الضريبة المستحقة.","لا تقل عن 1,000 دينار."],"law":"income","answer":1,"orig_answer":null,"article":"64","status":"valid","explanation":"المادة (64/أ/8): إذا كانت نسبة الفرق لا تقل عن (25%) من الضريبة المستحقة أو مبلغ التقاص."},{"num":8,"type":"mcq","q":"تكون مدة التقادم للجرائم المرتكبة خلافاً لأحكام قانون ضريبة الدخل والعقوبات المفروضة بموجبه:","o":["أربع سنوات تحتسب من تاريخ تقديم الإقرار الضريبي أو الإقرار المعدل.","ثلاث سنوات.","أربع سنوات.","سنتين."],"law":"income","answer":1,"orig_answer":null,"article":"66","status":"valid","explanation":"المادة (66/د/2): مدة التقادم للجرائم والعقوبات المرتكبة خلافاً لأحكام القانون ثلاث سنوات."},{"num":9,"type":"mcq","q":"على الرغم مما ورد في أي قانون تعتبر خدمة موظف ضريبة الدخل الذي يمثل الادعاء العام الضريبي أمام محكمة البداية الضريبية أو أي محكمة أخرى خدمة مقبولة لغايات الإعفاء من شرط التدريب وامتحان القبول المنصوص عليها في قانون نقابة المحامين النظاميين شريطة ألا تقل هذه المدة عن:","o":["3 سنوات على أن لا تقل خدمته في الدائرة عن 7 سنوات.","أربع سنوات.","خمسة سنوات.","ثلاث سنوات."],"law":"income","answer":2,"orig_answer":null,"article":"55","status":"valid","explanation":"المادة (55/ح/1): تعتبر خدمة الموظف مدة لا تقل عن خمس سنوات خدمة مقبولة لغايات الإعفاء من التدريب وامتحان القبول."},{"num":10,"type":"mcq","q":"إذا تعذر تبليغ المكلف بإشعار التقدير فيتم التبليغ لمرتين في صحيفتين محليتين على أن لا تقل المدة بين النشر الأول والثاني عن :","o":["خمسة عشر يوماً.","سبعة أيام.","عشرة أيام.","ثلاث أيام."],"law":"income","answer":2,"orig_answer":null,"article":"59","status":"valid","explanation":"المادة (59/أ/3): النشر لمرتين في صحيفتين يوميتين محليتين على ألا تقل المدة بين النشرين عن عشرة أيام."},{"num":11,"type":"mcq","q":"أي من العبارات التالية صحيحة وفقاً لقانون ضريبة الدخل:","o":["على كل شخص اعتباري الحصول على براءة ذمة من الدائرة قبل بيع حصصه أو أسهمه أو أي جزء منها داخل المملكة، ويستثنى من ذلك الأسهم المتداولة في السوق عمان المالي.","على كل شخص اعتباري الحصول على براءة ذمة من الدائرة قبل بيع حصصه أو أسهمه أو أي جزء منها داخل المملكة، ويستثنى من ذلك الأسهم والسندات المتداولة في السوق المالي.","على كل شخص الحصول على براءة ذمة من الدائرة قبل بيع حصصه أو أسهمه أو أي جزء منها داخل المملكة، ويستثنى من ذلك الأسهم المتداولة في السوق المالي.","على كل شخص الحصول على براءة ذمة من الدائرة قبل بيع حصصه أو أسهمه أو أي جزء منها داخل المملكة، ويستثنى من ذلك الأسهم والسندات المتداولة في السوق المالي."],"law":"income","answer":0,"orig_answer":null,"article":"60","status":"valid","explanation":"المادة (60/ب/1): على كل شخص اعتباري الحصول على براءة ذمة قبل بيع أو التنازل عن حصصه أو أسهمه داخل المملكة ويستثنى من ذلك الأسهم المتداولة في السوق المالي."},{"num":12,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات، يجوز للمدير أو المدقق حسب مقتضى الحال أن يصحح الأخطاء الحسابية التي تقع في القرارات عن طريق السهو العرضي:","o":["من تلقاء نفسه أو بناء على طلب المكلف ولا تكون إجراءات التصحيح خاضعة للطعن.","بناء على طلب المكلف وتكون إجراءات التصحيح خاضعة للطعن.","من تلقاء نفسه أو بناء على طلب المكلف وتكون إجراءات التصحيح خاضعة للطعن.","من تلقاء نفسه وتكون إجراءات التصحيح خاضعة للطعن."],"law":"sales","answer":0,"orig_answer":null,"article":"71","status":"valid","explanation":"المادة (71) من قانون الضريبة العامة على المبيعات: التصحيح من تلقاء ذاته أو بناء على طلب المكلف ولا تكون إجراءات التصحيح خاضعة للطعن."},{"num":13,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات للمدير بناء على تنسيب أي من أعضاء النيابة العامة الضريبية إجراء مصالحه في أي قضية أقامها المكلف لدى المحكمة بموجب هذا القانون، وذلك قبل صدور الحكم القطعي:","o":["من محكمة التمييز الضريبية.","من محكمة الاستئناف الضريبية.","من محكمة البداية الضريبية.","جميع ما ذكر صحيح."],"law":"sales","answer":3,"orig_answer":null,"article":"70","status":"valid","explanation":"المادة (70): للمدير إجراء المصالحة في أي قضية أقامها المكلف لدى المحكمة قبل صدور الحكم القطعي، أي أمام أي درجة من درجات التقاضي."},{"num":14,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات يتحمل المحاسب القانوني المسؤولية عن المصادقة على بيانات مالية تخالف معايير المحاسبة الدولية والأنظمة النافذة بسبب إهمال جسيم منه، ويعاقب وفقاً للقانون:","o":["لا تقل عن مقدار الضريبة ولا تزيد عن مثلي الضريبة أو بغرامة جزئية لا تقل عن 200 دينار ولا تزيد عن 500 دينار أو بكلتا العقوبتين.","لا يقل عن مثلي مقدار الضريبة ولا يزيد عن مثلي مقدار الضريبة أو بالحبس لمدة لا تقل عن ثلاثة أشهر ولا تزيد عن ستة أشهر.","لا تقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزئية لا تقل عن 200 دينار ولا تزيد عن 500 دينار.","لا يقل عن مثلي مقدار الضريبة ولا يزيد عن ثلاثة أمثالها وبغرامة جزئية لا تقل عن مئتي دينار ولا تزيد عن ألف دينار."],"law":"sales","answer":3,"orig_answer":null,"article":"67","status":"valid","explanation":"المادة (67) تحيل إلى عقوبة المادة (31): تعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها وغرامة من مئتي دينار إلى ألف دينار."},{"num":15,"type":"mcq","q":"يجوز للمكلف المثول بشخصه أمام المحكمة وتوقيع اللوائح المقدمة وفقاً لقانون ضريبة المبيعات:","o":["لا يجوز له وعليه توكيل محامياً مزاولاً وفقاً لقانون نقابة المحامين الأردنيين.","إذا كان محامياً مزاولاً فقط.","إذا كان قاضياً عاملاً أو سابقاً أو محامياً مزاولاً أو سابقاً.","إذا كان قاضياً عاملاً فقط."],"law":"sales","answer":2,"orig_answer":null,"article":"60","status":"valid","explanation":"المادة (60): يجوز للمكلف المثول بشخصه إذا كان قاضياً عاملاً أو سابقاً أو محامياً مزاولاً أو غير مزاول."},{"num":16,"type":"mcq","q":"شركة الصناعات الدوائية أعلنت في قائمة الدخل لسنة 2019 دخل صافي 200,000 دينار، فإن ضريبة الدخل المستحقة:","o":["32,000 دينار.","28,000 دينار.","30,000 دينار.","40,000 دينار."],"law":"income","answer":null,"orig_answer":null,"article":"11","status":"unverified","explanation":"المادة (11/ب/1،ج/2): الضريبة 20% = 40,000 تخفض لصناعة الأدوية عن 2019 بنسبة 50% فتصبح 20,000 (+ مساهمة وطنية 1% = 2,000)؛ لا يطابق أي خيار (28,000 تقابل تخفيض 2020 بنسبة 30%)."},{"num":17,"type":"mcq","q":"بلغ الدخل الإجمالي لشركة س لصناعة الملابس عام 2019 مبلغ 2 مليون دينار، والدخل الصافي لنفس السنة 1,100,000 دينار، وبلغ الدخل الصافي للبيانات المالية النصف سنوية بتاريخ 2020/6/30، 300,000 دينار فإن ضريبة الدخل المستحقة الواجب توريدها النصف سنوية:","o":["18,000 دينار.","12,000 دينار.","44,000 دينار.","16,800 دينار."],"law":"income","answer":3,"orig_answer":null,"article":"19","status":"valid","explanation":"المادة (19/ب،ج) والمادة (11/ج/2): 300,000×20%=60,000 تخفض 30% لصناعة الملابس عن 2020 = 42,000، والدفعة المقدمة 40% = 16,800 دينار (بدون المساهمة الوطنية)."},{"num":18,"type":"mcq","q":"تملك شركة س 70% من أسهم شركة ص، بتاريخ 2020/1/1 حصلت شركة ص على قرض من شركة س لتمويل أنشطتها، قيمة القرض 1,200,000 دينار وبفائدة 3%، بلغ رأس المال المدفوعة لشركة ص 100,000 دينار، ومتوسط حقوق الملكية 200,000 دينار، أن مصروف الفائدة المقبول تنزيله ضريباً لشركة ص لسنة 2020:","o":["10,800 دينار.","18,000 دينار.","36,000 دينار.","لا شيء مما ذكر."],"law":"income","answer":1,"orig_answer":null,"article":"6","status":"valid","explanation":"المادة (6/ب/2): الحد المسموح 3:1 من أكبر رأس المال المدفوع ومتوسط حقوق الملكية (200,000) = 600,000 × 3% = 18,000 دينار."},{"num":19,"type":"mcq","q":"شخص غير أردني وغير مقيم بالأردن له دخل من عقار مؤجر بقيمة 30,000، وهو معيل لعائلته المقيمة في الأردن، فإن ضريبة الدخل المستحقة عليه عام 2000 هي:","o":["2,750 دينار.","750 دينار.","1,050 دينار.","5,000 دينار."],"law":"income","answer":3,"orig_answer":null,"article":"11","status":"valid","explanation":"المادتان (9/د) و(11/أ): لا إعفاءات لغير الأردني غير المقيم؛ ضريبة 30,000 حسب الشرائح = 250+500+750+1,000+2,500 = 5,000 دينار."},{"num":20,"type":"mcq","q":"بتاريخ 2021/03/01 أعلنت شركة الشرق لتجارة السيارات عن أسماء الفائزين بجوائزها السنوية، وهي عبارة عن 3 سيارات قيمة كل منها 20,000 دينار بهذا التاريخ، وتم تسليم السيارات للفائزين بتاريخ 2020/12/01، حيث كان السعر السوقي بتاريخ التسليم 19,000 دينار لكل سيارة. ضريبة الدخل الواجب اقتطاعها وتوريدها من الشركة مقابل هذه الجوائز:","o":["5,700 دينار.","9,000 دينار.","6,000 دينار.","8,500 دينار."],"law":"income","answer":1,"orig_answer":null,"article":"12","status":"valid","explanation":"المادة (12/أ/3): يقتطع 15% من الجوائز التي تزيد قيمة كل منها على ألف دينار: 3×20,000×15% = 9,000 دينار."},{"num":21,"type":"mcq","q":"أظهرت قائمة الدخل لشركة الصلب والحديد الصناعية لسنة 2020 صافي دخل 500,000 دينار، وظهر في قائمة الدخل مصاريف إدارية وعمومية 100,000 دينار، وأرباح واستثمارات في شركات محلية 40,000 دينار، إن ضريبة الدخل المستحقة على الشركة:","o":["76,500 دينار.","81,600 دينار.","66,000 دينار.","88,000 دينار."],"law":"income","answer":null,"orig_answer":null,"article":"11","status":"unverified","explanation":"المادتان (4/أ/8) و(11/ج/1): الدخل الخاضع 500,000-40,000=460,000 ×20%=92,000 تخفض 20% عن 2020 = 73,600 + مساهمة وطنية 1% (4,600) = 78,200؛ لا يطابق أي خيار."},{"num":22,"type":"mcq","q":"تلتزم جميع الجهات التالية بالإجراءات المنصوص عليها في قانون مكافحة غسيل الأموال وتمويل الإرهاب باستثناء:","o":["الجهات التي تمارس التأجير التمويلي.","شركات الصرافة وشركات تحويل الأموال.","الأشخاص أو الجهات التي تمارس التجارة.","البنوك العاملة في المملكة."],"law":"aml","answer":2,"orig_answer":null,"article":"14","status":"valid","explanation":"المادة (14/أ): الجهات الملزمة تشمل البنوك والصرافة وجهات التأجير التمويلي، ولا تشمل الأشخاص الذين يمارسون التجارة بصفة عامة."},{"num":23,"type":"mcq","q":"يعتبر فساداً لغايات قانون النزاهة ومكافحة الفساد الأفعال التالية:","o":["كل فعل أو امتناع يؤدي إلى هدر أموال الشركات المساهمة العامة.","الكسب غير المشروع.","المنازعات والشكاوى بين الأفراد.","الجرائم المخلة بواجبات الوظيفة."],"law":"integrity","answer":null,"orig_answer":null,"article":"16","status":"unverified","explanation":"المادة (16/أ): هدر أموال الشركات المساهمة العامة والكسب غير المشروع والجرائم المخلة بواجبات الوظيفة كلها فساد؛ والمنازعات بين الأفراد ليست فساداً، فالسؤال على الأرجح بصيغة (باستثناء) والإجابة حينها (ج)."},{"num":24,"type":"mcq","q":"تعتبر المنطقة التنموية حسب قانون الاستثمار لسنة 2014 هي:","o":["أي منطقة تقع داخل حدود أمانة عمان الكبرى.","أي منطقة تقع ضمن النطاق الجمركي للمملكة يتم إعلانها منطقة تنموية وفقاً لأحكام هذا القانون.","أي جزء من أراضي المملكة محدد ومسور بحاجز فاصل يخصص لغايات الأنشطة الاقتصادية.","لا شيء مما ذكر صحيح."],"law":"investment","answer":1,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2) من قانون البيئة الاستثمارية 2022 (والتعريف ذاته في قانون 2014): المنطقة التنموية أي منطقة تقع ضمن النطاق الجمركي يتم إعلانها منطقة تنموية."},{"num":25,"type":"mcq","q":"أي من التالية لا يعتبر صحيحاً فيما يتعلق بالممارسات المخلة بالمنافسة حسب قانون المنافسة:","o":["التواطؤ في العطاءات أو العروض في مناقصة أو مزايدة.","لا يعتبر تحديد شروط البيع وما في حكم ذلك من هذه الممارسات.","يعتبر تحديد كميات إنتاج السلع أو أداء الخدمات من هذه الممارسات.","يعتبر تحديد أسعار السلع أو بدل الخدمات من هذه الممارسات."],"law":"competition","answer":1,"orig_answer":null,"article":"5","status":"valid","explanation":"المادة (5/أ/1) من قانون المنافسة: تحديد أسعار السلع أو بدل الخدمات أو شروط البيع وما في حكم ذلك من الممارسات المحظورة."},{"num":26,"type":"mcq","q":"لا يجوز لمجلس الوزراء إنهاء خدمات عضو مجلس إدارة البنك المركزي في الحالة التالية:","o":["إذا تغيب عن جميع اجتماعات المجلس المنعقدة خلال شهرين متتاليين بدون موافقة مجلس إدارة البنك المركزي.","إذا اتخذت اللجنة الطبية العليا في الحكومة قراراً بأنه أصبح عاجزا عن القيام بعمله.","إذا قام بأي نشاط تجاري أو قبل عملاً دائماً بأجر.","إذا كان أفلس أو طلب بعقد تسوية مع دائنيه بمقتضى قانون التجارة."],"law":"other:قانون البنك المركزي الأردني","answer":0,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون البنك المركزي غير مدرج؛ الحالات (ب،ج،د) من أسباب إنهاء العضوية، أما التغيب خلال شهرين فلا يطابق النص."},{"num":27,"type":"mcq","q":"يعتبر آمر الصرف في البنك المركزي هو:","o":["المحافظ.","مدير التدقيق الداخلي.","مجلس إدارة البنك المركزي.","مدير الدائرة المالية."],"law":"other:قانون البنك المركزي الأردني","answer":0,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون البنك المركزي غير مدرج؛ يرجح أن المحافظ هو آمر الصرف."},{"num":28,"type":"mcq","q":"إن الجهة المخولة بتعيين مدققين خارجيين لتدقيق حسابات البنك المركزي وفقاً لقانون البنك المركزي:","o":["رئيس ديوان المحاسبة.","مجلس الوزراء بناء على تنسيب وزير المالية.","مجلس الوزراء بناء على تنسيب مجلس إدارة البنك المركزي.","مجلس إدارة البنك بناء على تنسيب محافظ البنك المركزي."],"law":"other:قانون البنك المركزي الأردني","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون البنك المركزي غير مدرج؛ يرجح أن تعيين المدققين الخارجيين يتم من مجلس الوزراء بتنسيب من مجلس الإدارة."},{"num":29,"type":"mcq","q":"مؤمن عليه مصري الجنسية ترك العمل لدى منشأة، وكان آخر أجر خاضع بموجبه لأحكام قانون الضمان الاجتماعي 200 دينار، ورغب بالانتساب بصفة اختيارية:","o":["يحدد الأجر الذي يرغب بالخضوع من خلاله لأحكام القانون بما لا يقل عن الحد الأدنى للأجور.","يحدد الأجر الذي يرغب بالخضوع من خلاله لأحكام القانون.","يخضع على أساس آخر أجر تقاضاه.","لا شيء مما ذكر."],"law":"social","answer":3,"orig_answer":null,"article":"7","status":"valid","explanation":"المادة (7/أ): الانتساب الاختياري مقصور على الأردنيين، فلا يحق للمصري الانتساب اختيارياً."},{"num":30,"type":"mcq","q":"مؤمن عليه تم إيقاف شموله نتيجة ترك العمل ولديه فترات شمول بلغت (150) اشتراكاً جميعها في وزارة الزراعة:","o":["يستحق لبدل التعطل عن (4) أشهر.","يستحق لبدل التعطل عن (6) أشهر.","يستحق لبدل التعطل عن (1) شهر واحد فقط.","لا شيء مما ذكر."],"law":"social","answer":3,"orig_answer":null,"article":"72","status":"valid","explanation":"المادة (72/أ): يقتصر شمول القطاع العام (الوزارات) على إصابات العمل والشيخوخة والعجز والوفاة دون تأمين التعطل، فلا يستحق بدل تعطل."},{"num":31,"type":"mcq","q":"يحق للمؤمن عليه طلب إضافة المدد:","o":["عند إكمال سن الخمسين دون استكمال الحد الأدنى للمدة الموجبة لاستحقاق الراتب.","عند إكمال سن الخامسة والأربعين للأنثى وسن 50 للذكر.","عند إكمال سن الشيخوخة أو تجاوزها دون استكمال الحد الأدنى للمدة الموجبة لاستحقاق الراتب.","في أي وقت يشاء لغايات زيادة الراتب التقاعدي."],"law":"social","answer":2,"orig_answer":null,"article":"65","status":"valid","explanation":"المادة (65/أ): عند إكمال سن الستين للذكر والخامسة والخمسين للأنثى أو بعده دون إكمال الحد الأدنى للاشتراكات."},{"num":32,"type":"mcq","q":"في حال وقوع حادث عمل لمؤمن عليه يجب على المنشأة إبلاغ المؤسسة بالحادث خلال مدة:","o":["أسبوعين من تاريخ وقوع الحادث.","أربعة عشر يوم عمل من تاريخ وقوع الحادث.","أربعة أشهر من تاريخ وقوع الحادث.","خلال أربعة وعشرون ساعة من تاريخ وقوع الحادث."],"law":"social","answer":1,"orig_answer":null,"article":"27","status":"valid","explanation":"المادة (27/ب): خلال أربعة عشر يوم عمل من تاريخ وقوع الإصابة حداً أعلى."},{"num":33,"type":"mcq","q":"يشمل المؤمن عليه بصفة اختيارية اعتباراً من:","o":["من بداية الشهر الذي دفع عنه الاشتراك.","الشهر التالي للشهر الذي يتقدم فيه بالطلب.","بداية الشهر الذي يدفع المؤمن عليه.","بداية الشهر الذي يتقدم فيه بالطلب."],"law":"social","answer":3,"orig_answer":null,"article":"7","status":"unverified","explanation":"المادة (7/د) تحيل آليات الاشتراك الاختياري إلى النظام؛ ووفق النظام يشمل اعتباراً من أول الشهر الذي يتقدم فيه بالطلب."},{"num":34,"type":"mcq","q":"لغايات تخصيص راتب تقاعد مبكر لمؤمن عليه عامل بإحدى المهن الخطرة يشترط تحقق ما يلي:","o":["أن تبلغ اشتراكاته على الأقل (216) للذكر و(180) للأنثى، بالإضافة إلى إكماله/ا سن الخامسة والأربعين على الأقل، وأن يكون عاملاً بالمهن الخطرة خلال مدة لا تقل عن ستين اشتراكاً خلال العشر سنوات السابقة على طلبة تخصيص راتب التقاعد المبكر.","أن تبلغ اشتراكاته على الأقل (252) للذكر و(228) للأنثى بالإضافة إلى إكماله/ا سن الخمسين على الأقل.","أن تبلغ اشتراكاته على الأقل (216) للذكر وللأنثى بالإضافة إلى إكماله/ا سن الخمسين على الأقل.","أن تبلغ اشتراكاته على الأقل (180) للذكر وللأنثى بالإضافة إلى إكماله/ا سن الخمسين على الأقل."],"law":"social","answer":0,"orig_answer":null,"article":"64","status":"valid","explanation":"المادة (64/ج/1): (216) اشتراكاً للذكر و(180) للأنثى وإكمال سن 45 على الأقل مع شروط العمل بالمهنة الخطرة."},{"num":35,"type":"mcq","q":"يجب على العامل إبلاغ المؤسسة بعدم قيام المنشأة بالتأمين عليه خلال مدة لا تتجاوز:","o":["سنة من تاريخ تركه للعمل.","ستة أشهر من تاريخ تركه للعمل.","خلال مدة لا تتجاوز ستة أشهر من تاريخ التقدم بطلب الحصول على أية منفعة تأمينية.","ستة أشهر من تاريخ التحاقه بالعمل."],"law":"social","answer":1,"orig_answer":null,"article":"92","status":"valid","explanation":"المادة (92/أ/1): خلال مدة لا تتجاوز ستة أشهر من تاريخ انتهاء خدماته لدى المنشأة."},{"num":36,"type":"mcq","q":"يشترط حضور مراقب عام الشركات اجتماع الهيئات العامة للشركات التالية:","o":["لا يشترط حضور مراقبة عام الشركات لأي نوع من أنواع الشركات.","الشركات المساهمة الخاصة والشركات المساهمة العامة المحدودة.","الشركات المساهمة العامة المحدودة.","الشركات ذات المسؤولية المحدودة والمساهمة الخاصة والمساهمة العامة المحدودة."],"law":"companies","answer":2,"orig_answer":null,"article":"182","status":"valid","explanation":"المادة (182): يعتبر اجتماع الهيئة العامة للمساهمة العامة باطلاً إذا لم يحضره المراقب أو من ينتدبه."},{"num":37,"type":"mcq","q":"النسبة المئوية المحددة في قانون الشركات النافذ ليتقدم شركاء و/أو مساهمين بطلب تشكيل لجنة تدقيق على الشركة هي:","o":["(25%).","(10%).","(20%).","(15%)."],"law":"companies","answer":1,"orig_answer":null,"article":"275","status":"valid","explanation":"المادة (275/أ): مساهمون يملكون ما لا يقل عن (10%) من رأس المال أو ربع أعضاء المجلس طلب إجراء تدقيق على أعمال الشركة."},{"num":38,"type":"mcq","q":"للشركة ذات المسؤولية المحدودة أن تخفض رأسمالها سنداً لحالة من الحالات التالية:","o":["إذا لحقت بها الخسائر تزيد على (40%) من رأسمالها.","إذا زاد عن حاجتها أو إذا لحقت بها الخسائر تزيد عن (25%) من رأسمالها.","إذا زاد عن حاجتها أو إذا لحقت بها الخسائر تزيد على نصف رأسمالها أو إذا انسحب أحد الشركاء منها.","إذا زاد عن حاجتها أو إذا لحقت بها الخسائر تزيد على نصف رأسمالها."],"law":"companies","answer":3,"orig_answer":null,"article":"68","status":"valid","explanation":"المادة (68/أ): إذا زاد رأسمالها على حاجتها أو لحقت بها خسائر تزيد على نصف رأسمالها."},{"num":39,"type":"mcq","q":"يتوجب على الشركة ذات المسؤولية المحدودة أن تقتطع من أرباحها السنوية النسبة التالية لحساب الاحتياطي الإجباري:","o":["(20%) لكل سنة على أن لا يتجاوز مجموع ما اقتطع لهذا الاحتياطي (50%) من رأس مال الشركة.","(10%) لكل سنة على أن لا يتجاوز مجموع ما اقتطع لهذا الاحتياطي رأس مال الشركة.","(20%) لكل سنة على أن لا يتجاوز مجموع ما اقتطع لهذا الاحتياطي رأس مال الشركة.","(10%) لكل سنة على أن لا يتجاوز مجموع ما اقتطع لهذا الاحتياطي (50%) من رأس المال."],"law":"companies","answer":1,"orig_answer":null,"article":"70","status":"valid","explanation":"المادة (70/أ): (10%) سنوياً على ألا يتجاوز مجموع الاحتياطي رأس مال الشركة."},{"num":40,"type":"mcq","q":"أي من الحالات التالية صحيحة فيما يتعلق برأس مال الشركة المساهمة الخاصة عند التأسيس:","o":["رأس مال الشركة المصرح به وفق ما يحدده المساهمين دون سقف أعلى وأن لا يقل رأس مال الشركة المكتتب به عن (50,000) دينار/ سهم.","رأس مال الشركة المصرّح به وفق ما يحدده المساهمين، وأن لا يقل رأس مال الشركة المكتتب به عن (100,000) دينار/ سهم.","لا يقل رأس المال المصرح به (10) مليون دينار/ سهم، وأن لا يقل رأس مال الشركة المكتتب به عن (20,000) دينار/سهم.","لا يقل رأس المال المصرح به (10) مليون دينار/ سهم، ورأس المال المكتتب به عن (100,000) دينار/ سهم."],"law":"companies","answer":0,"orig_answer":null,"article":"66 مكرر","status":"valid","explanation":"المادة (66 مكرر/أ): لا يقل رأس المال المكتتب به للمساهمة الخاصة عن خمسين ألف دينار، والمصرح به يحدده المساهمون."},{"num":41,"type":"mcq","q":"يتوجب على المساهمين في الشركة المساهمة الخاصة عقد اجتماع هيئة عامة تأسيسي من تاريخ صدور شهادة تسجيل الشركة من قبل المراقب خلال مدة:","o":["خلال (10) يوم (عشرة أيام).","خلال (60) يوم (شهرين).","خلال (30) يوم (شهر).","خلال (90) يوم (ثلاث أشهر)."],"law":"companies","answer":2,"orig_answer":null,"article":"71 مكرر","status":"valid","explanation":"المادة (71 مكرر): عقد اجتماع هيئة عامة تأسيسي خلال شهر من تاريخ صدور شهادة التسجيل."},{"num":42,"type":"mcq","q":"يحظر على مدير عام الشركة المساهمة الخاصة وموظفيها تولي وظيفة في شركة أخرى ذات غايات مماثلة أو منافسة لأعمال الشركة سواء لحسابه أو لحساب الغير بأجر أو بدون أجر إلا بموافقة:","o":["لا يشترط موافقة أي جهة.","موافقة الهيئة العامة غير العادية.","موافقة مجلس الإدارة.","مراقب عام الشركات."],"law":"companies","answer":2,"orig_answer":null,"article":"74 مكرر","status":"valid","explanation":"المادة (74 مكرر/ب): إلا بموافقة مجلس إدارة الشركة."},{"num":43,"type":"mcq","q":"ما هي النسبة التي يتوجب على الشركة المساهمة الخاصة اقتطاعها من أرباحها السنوية لحساب الاحتياطي الإجباري والنسبة التي لا يتجاوز مجموع ما يقتطع من رأس المال المكتتب به:","o":["(10%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به.","(20%) سنوياً ولا يتجاوز مجموع ما يقتطع (25%) من رأس المال المكتتب به.","(15%) سنوياً ولا يتجاوز مجموع ما يقتطع (15%) من رأس المال المكتتب به.","(25%) سنوياً ولا يتجاوز مجموع ما يقتطع (50%) من رأس المال المكتتب به."],"law":"companies","answer":0,"orig_answer":null,"article":"85 مكرر","status":"valid","explanation":"المادة (85 مكرر/أ): (10%) سنوياً حتى (25%) من رأس المال المكتتب به."},{"num":44,"type":"mcq","q":"أي العبارات التالية يعتبر صحيحاً فيما يتعلق بتأسيس شركة التضامن :","o":["تتألف شركة التضامن من عدد من الأشخاص الطبيعيين من (1) شريك ولا يزيد على (20) عشرين إلا إذا طرأت الزيادة على ذلك نتيجة للإرث شريطة أن لا يقل عمر الشريك عن (18) سنة.","تتألف شركة التضامن من عدد من الشركاء لا يقل عن شريكين ولا يزيد على (20) عشرين شريك إلا إذا طرأت الزيادة على ذلك نتيجة للإرث.","تتألف شركة التضامن من عدد من الأشخاص الطبيعيين لا يقل عن (2) ولا يزيد على ( عشرين إلا إذا طرأت الزيادة على ذلك نتيجة للإرث وبغض النظر عن أعمار الشركاء.","تتألف شركة التضامن من عدد من الأشخاص الطبيعيين لا يقل عن (2) ولا يزيد على (20) عشرين إلا إذا طرأت الزيادة على ذلك نتيجة للإرث ولا يقبل أي شخص شريكا في شركة التضامن إلا إذا أكمل الثامنة عشر من عمره على الأقل."],"law":"companies","answer":3,"orig_answer":null,"article":"9","status":"valid","explanation":"المادة (9/أ،ب): من 2 إلى 20 شخصاً طبيعياً إلا بالإرث، ولا يقبل شريكاً إلا من أكمل الثامنة عشرة."},{"num":45,"type":"mcq","q":"إن مدة تسديد الجزء غير المكتتب به من رأسمال الشركة المساهمة العامة هي:","o":["يتوجب تسديد الجزء المكتتب به من رأسمال الشركة المساهمة العامة خلال سنة من تاريخ تسجيلها أو زيادة رأسمالها، ويعكس ذلك ليتولى المراقب إخطار الشركة بضرورة التسديد ويتم منحها (60) يوماً إضافياً، وفي حالة عدم قدرة الشركة على التسديد، يبلغ المراقب الشركة بأن رأسمالها المسجل والمدفوع أصبح يساوي قيمة الأسهم المكتتب بها فعلياً.","يسدد الجزء غير المكتتب به من رأسمال الشركة المساهمة العامة خلال سنتين من تاريخ تسجيل الشركة أو تاريخ زيادة رأسمالها.","يسدد الجزء غير المكتتب به من رأسمال الشركة المساهمة العامة خلال ثلاث سنوات من تاريخ تسجيل الشركة أو زيادة رأس المال.","لا شيء مما ذكر أعلاه، وذلك لكون الأسهم المكتتب بها يتوجب تسديدها مباشر ودفعة واحدة فقط، وعليه لا يوجد لدى الشركات المساهمة العامة أسهم غير مكتتب بها."],"law":"companies","answer":2,"orig_answer":null,"article":"95","status":"valid","explanation":"المادة (95/ب): يسدد الجزء غير المكتتب به خلال ثلاث سنوات من تاريخ تسجيل الشركة أو زيادة رأس المال."},{"num":46,"type":"mcq","q":"تكون مهام هيئة مالكي إسناد القرض كما يلي:","o":["تكون مهمة هيئة مالكي إسناد القرض حماية حقوق مالكيها واتخاذ التدابير اللازمة لصيانة هذه الحقوق بالتعاون مع وزير الصناعة والتجارة و/أو مراقب عام الشركات، وذلك للمحافظة على حقوق الشركة المصدرة للإسناد وضمان الرقابة والرعاية من قبل دائرة مراقبة الشركات.","تكون مهمة هيئة مالكي إسناد القرض حماية حقوق المساهمين في الشركة، وذلك لضمان استرداد العوائد على المساهمين.","تكون مهمة هيئة مالكي إسناد القرض حماية حقوق مالكيها، واتخاذ التدابير اللازمة لصيانة هذه الحقوق بالتعاون مع أمين الإصدار وتجتمع بناء على دعوة منه بعد المرة الأولى.","جميع ما ذكر صحيح."],"law":"companies","answer":2,"orig_answer":null,"article":"127","status":"valid","explanation":"المادة (127): حماية حقوق مالكيها بالتعاون مع أمين الإصدار، وتجتمع أول مرة بدعوة من مجلس الإدارة ثم بدعوة أمين الإصدار."},{"num":47,"type":"mcq","q":"إذا تعذر على مدقق حسابات الشركة القيام بالمهام والواجبات الموكلة إليه بموجب أحكام قانون الشركات لأي سبب من الأسباب، فيتوجب عليه:","o":["قبل الاعتذار عن القيام بتدقيق الحسابات أن يقدم تقريرا خطيا للمراقب ونسخة منه لمجلس الإدارة، يتضمن الأسباب التي تعرقل أعماله أو تحول دون قيامه بها، وعلى المراقب معالجة هذه الأسباب مع مجلس الإدارة، وإذا تعذر عليه ذلك يعرض المراقب الأمر على الهيئة العامة في أول اجتماع تعقده.","قبل الاعتذار عن القيام بتدقيق الحسابات أن يقدم تقريرا خطيا لديوان المحاسبة ونسخة منه لكل من مراقب عام الشركات ولمجلس إدارة الشركة، يتضمن الأسباب التي تعرقل أعماله أو تحول دون قيامه بها، وعلى المراقب أن يعين لجنة من ثلاث مدققين بدلاً منه للقيام بذلك.","قبل الاعتذار عن القيام بتدقيق الحسابات أن يتفاوض مع رئيس وأعضاء مجلس الإدارة، وذلك لضمان مستحقاته المالية لقاء الجهد المبذول منه .","كل ما ذكره أعلاه صحيح."],"law":"companies","answer":0,"orig_answer":null,"article":"194","status":"valid","explanation":"المادة (194): تقرير خطي للمراقب ونسخة لمجلس الإدارة، وإن تعذرت المعالجة يعرض الأمر على الهيئة العامة."},{"num":48,"type":"mcq","q":"أي من حالات شطب تسجيل الشركة الأجنبية غير العاملة يُعتبر صحيحاً:","o":["للوزير بناء على تنسيب المراقبة شطب تسجيل الشركة الأجنبية غير العاملة في المملكة إذا تبين له أنها تمارس أي عمل تجاري في المملكة أو لم يعد لها مقر فعلي.","للوزير بناء على تنسيب المراقب العام للشركات شطب تسجيل الشركة الأجنبية غير العاملة في المملكة شريطة إذا تبين له أنها تمارس أي عمل تجاري في المملكة وكذلك لم يعد لها مقر فعلي وذلك بموجب تقارير فعلية وموافقة الشركة على ذلك.","لا يجوز شطب تسجيل الشركة الأجنبية غير العاملة في المملكة إذا تبين أنها تمارس اي عمل تجاري في المملكة أو لم يعد لها مقر فعلي وذلك حيث أنه يتوجب تقديم طلب خطي من الشركة لشطبها.","جميع ما ذكر خطأ."],"law":"companies","answer":0,"orig_answer":null,"article":"251","status":"valid","explanation":"المادة (251): للوزير بتنسيب المراقب شطب التسجيل إذا مارست عملاً تجارياً أو لم يعد لها مقر فعلي."},{"num":49,"type":"mcq","q":"بموجب قانون نظام الإعسار رقم (8) 2019 أي من العبارات التالية لا يعتبر صحيحاً:","o":["للمراقب أن يصدر التعليمات اللازمة لاعتماد سجل إعسار ورقي إلى حين استكمال اجراءات إنشاء السجل الإلكتروني.","تبقى الجهة التي قامت بالإشهار مسؤولة عن صحة البيانات والمعلومات التي يتم اشهارها في السجل أو دقتها.","لا يرتب الإشهار أي حق لأي جهة أو ينتقص منه أو يسقطه.","يتحمل المسجل المسؤولية عن عدم صحة البيانات والمعلومات التي يتم إشهارها في السجل أو دقتها."],"law":"insolvency_sys","answer":3,"orig_answer":null,"article":"5","status":"valid","explanation":"المادة (5/أ) من نظام الإعسار: لا يتحمل المسجل أي مسؤولية عن صحة البيانات المشهرة."},{"num":50,"type":"mcq","q":"يتم استخدام حساب نفقات حالات الإعسار بالأموال بتغطية النفقات الناشئة عن دعاوي الإعسار التالية:","o":["أتعاب وكيل الإعسار التي تحددها المحكمة.","أي نفقات ومصاريف قضائية لازمة للسير في دعوى الإعسار.","أتعاب الخبرة.","جميع ما ذكر صحيح."],"law":"insolvency_sys","answer":3,"orig_answer":null,"article":"27","status":"valid","explanation":"المادة (27/ب) من نظام الإعسار: حساب (نفقات حالات الإعسار بلا أموال) يغطي أتعاب الخبرة والنفقات القضائية وأتعاب وكيل الإعسار."},{"num":51,"type":"mcq","q":"يحق أن يتقدم للمحكمة بطلب وإشهار الإعسار:","o":["المدين أو أي من دائنيه وللمراقب اذا كان المدين شركة.","المدين أو أي من دائنيه فقط.","الدائنين فقط.","لا شيء مما ذكر."],"law":"insolvency","answer":0,"orig_answer":null,"article":"6","status":"valid","explanation":"المادة (6/أ) من قانون الإعسار: للمدين ولأي من دائنيه وللمراقب إذا كان المدين شركة."},{"num":52,"type":"mcq","q":"يتوقف احتساب الفوائد وغرامات التأخير على ديون الإعسار:","o":["يستمر احتساب الفوائد لحين تسديد الديون المترتبة على الشركة.","اعتباراً من تاريخ إشهار الإعسار من قبل الشركة.","عند تقديم طلب إشهار الإعسار.","لا شيء مما ذكر."],"law":"insolvency","answer":1,"orig_answer":null,"article":"25","status":"valid","explanation":"المادة (25/أ) من قانون الإعسار: يتوقف احتساب الفوائد وغرامات التأخير من تاريخ إشهار الإعسار."},{"num":53,"type":"mcq","q":"أي من العبارات التالية لا يعتبر صحيحاً بموجب قانون التجارة رقم (12) لعام 1966:","o":["إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانونا بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي من الإفلاس.","يعد تاجراً من قام بمعاملة تجارية عرضاً إلا أن المعاملة المذكورة لا تكون خاضعة لأحكام قانون التجارة.","لا تعد الدولة ودوائرها ذات شخصية اعتبارية من التجار وإن قامت بمعاملات تجارية.","يعد تاجرا كل من أعلن الصحف أو النشرات أو أية واسطة أخرى من المحل الذي أسسه وفتحه للاشتغال بالأعمال التجارية."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":1,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966 غير مدرج: من قام بمعاملة تجارية عرضاً لا يعد تاجراً ولكن المعاملة تخضع لأحكام قانون التجارة."},{"num":54,"type":"mcq","q":"جميع الأمور التالية صحيحة بخصوص الوكالة التجارية حسب قانون التجارة باستثناء:","o":["الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي.","في المواد التجارية يستحق الوكيل الاجر في جميع الأحوال ما لم يكن هنالك نص مخالف.","الوكالة التجارية إن احتوت على توكيل مطلق تجيز الأعمال غير التجارية وإن لم يرد نص صريح.","تكون الوكالة تجارية عندما تختص بمعاملات تجارية."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966 غير مدرج: الوكالة التجارية ولو كانت مطلقة لا تجيز الأعمال غير التجارية إلا بنص صريح."},{"num":55,"type":"mcq","q":"أي من العبارات التالية غير صحيحة حسب قانون التجارة فيما يتعلق بالحساب الجاري:","o":["لا يجوز في حال من الأحوال أن يستقر الحساب الجاري على رصيد إيجابي لمصلحته.","يجوز أن يكون الحساب الجاري مكشوفا لجهة الفريقين ولا يجوز مكشوف لجهة واحدة.","وجود الحساب الجاري لا يمنع أحد المتعاقدين من مطالبة الآخر بالعمولة عن عمل قام به بالعمولة.","يتوقف مدى الحساب الجاري على إرادة المتعاقدين منها أن يجعلاه شاملاً لجميع معاملاتها أو لنوع معين منها فقط."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":1,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966 غير مدرج: يجوز أن يكون الحساب الجاري مكشوفاً لجهة واحدة أو للجهتين."},{"num":56,"type":"mcq","q":"على الرغم مما ورد في قانون ضريبة الدخل النافذ يتم تخفيض ضريبة الدخل المستحقة في المناطق الأقل نمواً في المملكة على الأنشطة الاقتصادية والحرفية والأنشطة الاقتصادية الواردة في البند (4) من الفقرة (ب) من المادة (4) من قانون الاستثمار بنسبة لا تقل عن:","o":["50%.","15%.","30%.","25%."],"law":"investment","answer":2,"orig_answer":null,"article":"10","status":"valid","explanation":"المادة (10) من قانون البيئة الاستثمارية 2022 (والنسبة ذاتها في قانون 2014): الإعفاء أو التخفيض بنسبة لا تقل عن (30%) في المناطق الأقل نمواً."},{"num":57,"type":"mcq","q":"تتخذ الهيئة العامة غير العادية لجمعية المحاسبين القانونيين القرارات:","o":["نسبة 50% زائد واحد من أصوات المحاسبين القانونيين الحاضرين.","بأكثرية لا تقل عن 25% من أصوات المحاسبين القانونيين الحاضرين.","بأكثرية لا تقل عن ثلثي أصوات المحاسبين القانونيين الحاضرين.","لا شيء مما ذكر صحيح."],"law":"accounting","answer":2,"orig_answer":null,"article":"15","status":"valid","explanation":"المادة (15/د): بأكثرية لا تقل عن ثلثي أصوات المحاسبين القانونيين الحاضرين."},{"num":58,"type":"mcq","q":"من صلاحيات مجلس إدارة جمعية المحاسبين القانونيين ما يلي:","o":["المصادقة على منح إجازة المزاولة.","التنسيب للهيئة العليا بإلغاء إجازة المزاولة.","عقد اجتماعات وتحديد مواعيد امتحان المهنة.","اعتماد معايير المحاسبة ومعايير تدقيق الحسابات."],"law":"accounting","answer":1,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/هـ): من مهام المجلس التنسيب للهيئة العليا بإلغاء إجازة المزاولة (أما المصادقة واعتماد المعايير فللهيئة العليا)."},{"num":59,"type":"mcq","q":"يتم اعتماد معايير المحاسبة ومعايير تدقيق الحسابات الواجبة التطبيق في الأردن من قبل:","o":["الهيئة العليا لتنظيم مهنة المحاسبة القانونية.","مراقب عام الشركات.","مجلس إدارة جمعية المحاسبين القانونيين الأردنيين.","لا شيء مما ذكر."],"law":"accounting","answer":0,"orig_answer":null,"article":"5","status":"valid","explanation":"المادة (5/أ): تعتمد الهيئة العليا معايير المحاسبة والتدقيق بناء على تنسيب المجلس."},{"num":60,"type":"mcq","q":"أي من العبارات التالية غير صحيح حسب قانون تنظيم مهنة المحاسبة القانونية لسنة 2003:","o":["يسري تعليق التسجيل إيقاف العمل بإجازة المزاولة بعد صدور قرار اللجنة التأديبية.","إذا ارتكب المتدرب أي مخالفة لأحكام قانون المهنة والأنظمة والتعليمات الصادرة بمقتضاه أو أخل بواجبات عمله أو قواعد سلوك المهنة وآدابها يحيله المجلس إلى اللجنة التأديبية.","توقع اللجنة التأديبية عقوبة إلغاء إجازة المزاولة وشطب اسم المحاسب القانوني نهائيا من سجل المزاولين.","إذا ارتكب المحاسب القانوني أي مخالفة لأحكام قانون المهنة والأنظمة والتعليمات الصادرة بمقتضاه أو أخل بواجبات عمله أو قواعد سلوك المهنة وآدابها يحيله المجلس إلى اللجنة التأديبية."],"law":"accounting","answer":0,"orig_answer":null,"article":"37","status":"valid","explanation":"المادتان (35-37): (ب،ج،د) صحيحة، أما قرارات اللجنة التأديبية فلا تنفذ بمجرد صدورها بل تخضع لمصادقة المجلس (والهيئة العليا في الإلغاء)."},{"num":61,"type":"mcq","q":"لمدير مديرية المنافسة أن يكلف أياً من موظفي المديرية المفوضين من الوزير للقيام بما يلي:","o":["يتوجب على الموظفين المكلفين الكشف عن هوياتهم واطلاع صاحب العلاقة على نسخة من التفويض الخطي.","الاطلاع على المستندات والسجلات والملفات بما فيها ملفات الحاسوب ولا يجوز الاحتفاظ بأي منها أو نسخ عنها.","الدخول خلال ساعات العمل فقط إلى المحلات التجارية والمكاتب والمخازن لإجراء المعاينة والتفتيش.","إجراء التحقيقات اللازمة والاستماع لإفادة أي شخص يشتبه بمخالفته لأحكام قانون المنافسة."],"law":"competition","answer":3,"orig_answer":null,"article":"19","status":"valid","explanation":"المادة (19/أ/3): إجراء التحقيقات اللازمة والاستماع لإفادة أي شخص يشتبه بمخالفته؛ ويجوز الاحتفاظ بالمستندات ونسخها مقابل إشعار."},{"num":62,"type":"mcq","q":"تمكن تحريك القضايا المتعلقة بمخالفة قانون المنافسة بناء على شكوى تقدم إلى المدير العام من الجهات التالية عدا :","o":["أي تجمع لخمسة مستهلكين متضررين على الأقل.","غرف الصناعة والتجارة وتستثنى مؤسسات القطاع الخاص.","جمعيات حماية المستهلكين المرخصة.","الوزير بتنسيب من المدير أو بناء على طلب أي جهة رسمية أخرى."],"law":"competition","answer":1,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/أ): يجوز تقديم الشكوى من أي مؤسسة من القطاع الخاص وغرف الصناعة والتجارة، فعبارة استثناء مؤسسات القطاع الخاص غير صحيحة."},{"num":63,"type":"mcq","q":"بموجب قانون رسوم طوابع الواردات تعتبر العبارات التالية الخاصة بقرار الوزير إعادة الرسوم المستوفاة صحيحة باستثناء:","o":["يحسم لحساب الخزينة ما نسبته (15%) من مقدار الرسوم التي يتم إعادتها وفقا لأحكام الفقرة (1) من هذه المادة.","إذا ألصق المكلف طوابع أو دمغها بقيمة تزيد على الرسم المستحق على المعاملة.","إلغاء المعاملة الخاضعة لرسوم الطوابع.","إذا تلفت الطوابع التي في حيازة أي شخص دون أي تقصير متعمد منه، وكان التلف واقعا بصورة يتعذر معها استعمالها."],"law":"stamp","answer":0,"orig_answer":null,"article":"16","status":"valid","explanation":"المادة (16/ب): يحسم لحساب الخزينة (10%) وليس (15%)."},{"num":64,"type":"mcq","q":"وفقاً لقانون الأوراق المالية، عرض التملك العام هو:","o":["أي عرض يقصد به شراء (35%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد، أو حيازتها عن طريق المبادلة.","أي عرض يقصد به شراء (50%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد، أو حيازتها عن طريق المبادلة.","أي عرض يقصد به شراء (45%) أو أكثر من الأوراق المالية العائدة إلى مصدر واحد، أو حيازتها عن طريق المبادلة.","أي عرض يقصده به شراء (40%) أو اكثر من الأوراق المالية العائدة إلى مصدر واحد، أو حيازتها عن طريق المبادلة."],"law":"securities","answer":3,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): عرض التملك العام أي عرض يقصد به شراء (40%) أو أكثر من الأوراق المالية لمصدر واحد أو حيازتها بالمبادلة."},{"num":65,"type":"mcq","q":"وفقاً لقانون الأوراق المالية يشترط في نشرة الإصدار أن تكون مقدمة وفقاً للأنموذج الخطي أو الالكتروني الذي تحدده الهيئة بموجب التعليمات الصادرة عن المجلس، وأن تكون موقعة من كل من رئيس مجلس الإدارة وكل من المدير العام أو المدير التنفيذي والمدير المالي للمصدر إضافة إلى من يلي:","o":["مدير الإصدار أو مديري الإصدار حسب مقتضى الحال.","غالبية أعضاء مجلس إدارة المصدر إذا كان شركة مساهمة عامة أو شركة مساهمة خاصة.","مؤسسين يملكون أكثر من (75%) من أسهم التأسيس إذا كانت الشركة في مرحلة التأسيس.","جميع ما ذكر."],"law":"securities","answer":3,"orig_answer":null,"article":"37","status":"valid","explanation":"المادة (37/أ): يوقعها أيضاً مؤسسون يملكون أكثر من 75% وغالبية أعضاء المجلس ومدير الإصدار والمدقق."},{"num":66,"type":"mcq","q":"وفقاً لقانون الأوراق المالية الأقرباء هم:","o":["الزوج والزوجة والأولاد القصر.","الزوج والزوجة والوالدين والأولاد القصر.","الأولاد القصر.","الزوج والزوجة."],"law":"securities","answer":0,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): الأقرباء: الزوج والزوجة والأولاد القصر."},{"num":67,"type":"mcq","q":"أي من العبارات التالية غير صحيحة وفقاً لقانون الأوراق المالية:","o":["لا يجوز لأي شخص طلب شراء أوراق مالية أو مبادلتها لهدف تملك (40%) أو أكثر من الأوراق المالية المصدرة من مصدر عام إلا عن طريق عرض تملك عام وفقاً لنظام يصدر لهذه الغاية.","يجوز لأي شخص طلب شراء أوراق مالية أو مبادلتها لهدف تملك (40%) أو أكثر من الأوراق المالية المصدرة من مصادر عام عن طريق عرض تملك عام وفقاً لنظام يصدر لهذه الغاية.","يجوز لأي شخص طلب شراء أوراق مالية أو مبادلتها لهدف تملك (45%) أو اكثر من الأوراق المالية المصدرة من مصدر عام عن طريق عرض تملك عام وفقاً لنظام يصدر لهذه الغاية.","لا شيء مما ذكر."],"law":"securities","answer":2,"orig_answer":null,"article":"45","status":"valid","explanation":"المادة (45/أ): النسبة المحددة (40%) أو أكثر؛ والعبارة (ج) مصاغة على نسبة 45% بخلاف النص، فهي المقصودة بعدم الصحة."},{"num":68,"type":"mcq","q":"وفقاً لقانون الأوراق المالية يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفض أي منهما خلال:","o":["خمسون يوماً من تاريخ تقديم الطلب إليها سواء كان مستكمل أو غير مستكمل الشروط والمتطلبات.","ستين يوما من تاريخ تقديم الطلب إليها مستكملا الشروط والمتطلبات.","خمس وستون يوماً من تاريخ تقديم الطلب إليها مستكملاً الشروط والمتطلبات.","ستين يوما من تاريخ تقديم الطلب إليها سواء كان مستكمل أو غير مستكمل الشروط والمتطلبات."],"law":"securities","answer":1,"orig_answer":null,"article":"48","status":"valid","explanation":"المادة (48/هـ): خلال ستين يوماً من تاريخ تقديم الطلب مستكملاً الشروط والمتطلبات."},{"num":69,"type":"mcq","q":"وفقاً لقانون الأوراق المالية، يُقصد بالوسيط لحسابه:","o":["الشخص الاعتباري الذي يمارس أعمال الحفظ الأمين للأوراق المالية.","الشخص الذي يمارس شراء الأوراق المالية وبيعها لحسابه الخاص مباشرة من خلال السوق المالي.","الشخص الذي يمارس إدارة محافظ الأوراق المالية لحساب الغير بما في ذلك إدارة صندوق الاستثمار المشترك.","الشخص الذي يمارس شراء الأوراق المالية وبيعها لحساب الغير."],"law":"securities","answer":1,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): الوسيط لحسابه من يمارس شراء الأوراق المالية وبيعها لحسابه الخاص مباشرة من خلال السوق المالي."},{"num":70,"type":"mcq","q":"وفقاً لقانون الأوراق المالية، تكون العضوية في مركز إيداع الأوراق المالية إلزامية ل:","o":["الحافظ الأمين بالإضافة إلى أي جهة أخرى يحددها المجلس.","الشخص الاعتباري المرخص له بممارسة أعمال الوسيط المالي أو الوسيط لحسابه.","الشركات المساهمة العامة.","جميع ما ذكر."],"law":"securities","answer":3,"orig_answer":null,"article":"80","status":"valid","explanation":"المادة (80/أ): العضوية إلزامية للشركات المساهمة العامة والوسيط المالي والوسيط لحسابه والحافظ الأمين وأي جهة يحددها المجلس."},{"num":71,"type":"essay","q":"السؤال الأول (ثلاث علامات)\nباستثناء الشركات المساهمة العامة والشركات المساهمة الخاصة المتداولة:\nولغايات احتساب ضريبة الدخل على أرباح بيع أسهم أو حصص الشركات، أو أرباح بيع أسهم أو حصص الشخص الطبيعي المقيم أو غير المقيم، يتم اعتماد النسب التالية (أكمل الجدول):\n1- نسبة 0.5% من قيمة البيع إذا كانت ...\n2- نسبة 0.75% من قيمة البيع إذا كانت ...\n3- نسبة 1% من قيمة البيع إذا كانت ...\n4- نسبة 1.5% من قيمة البيع إذا كانت ...\n5- نسبة 2% من قيمة البيع إذا كانت ...\n6- نسبة 3% من قيمة البيع إذا كانت ...\n7- نسبة 4% من قيمة البيع إذا كانت ...\n8- نسبة 5% من قيمة البيع إذا كانت ...","law":"income","article":"4","status":"unverified","model_answer":"- المادة (4/أ/5): الأرباح الرأسمالية معفاة باستثناء أرباح بيع الحصص والأسهم على الشخص الاعتباري؛ ونسب احتساب الضريبة على قيمة البيع (0.5% إلى 5%) حسب نوع الشركة/نسبة موجوداتها العقارية ومدة الاحتفاظ تحددها الأنظمة والتعليمات التنفيذية وليست في نص القانون، فلا يمكن التحقق من الجدول من نص القانون."},{"num":72,"type":"essay","q":"السؤال الثاني (ثلاث علامات)\nشركة زراعية بلغت مبيعاتها 1,000,000 دينار، حققت صافي ربح من نشاط الزراعة 110 ألف دينار، كما ظهر في قائمة الدخل أرباح بيع أصل ماكنة زراعية مستهلكة بالكامل بربح قدره 5,000 دينار، وأرباح استثمارات في شركة زراعية في السودان بقيمة 50 ألف دينار، وصافي إيرادات من الأملاك المؤجرة في الأردن بقيمة 40 ألف دينار، بعد تنزيل مصاريف الإيجارات البالغة 20 ألف دينار، علماً بأن المسقفات المدفوعة من الأملاك المؤجرة بلغت 4 آلاف دينار.\nالمطلوب:\nاحتساب ضريبة الدخل المستحقة على الشركة والمساهمة الوطنية.","law":"income","article":"5","status":"valid","model_answer":"- المادة (5/ب): يعفى أول 50,000 من صافي دخل الشخص الاعتباري من النشاط الزراعي: 110,000-50,000=60,000 خاضع.\n- أرباح بيع ماكنة مستهلكة (أصل خاضع للاستهلاك) خاضعة (المادة 4/أ/5): 5,000.\n- صافي إيراد الإيجار 40,000 خاضع.\n- الدخل الخاضع داخلياً = 105,000 × 20% (المادة 11/ب/1) = 21,000.\n- يقاص 100% من المسقفات (4,000) بحد أقصى ضريبة دخل الإيجار 8,000 (المادة 18/ب) ← الضريبة 17,000.\n- أرباح الاستثمار في السودان: دخل من مصدر خارجي نشأ عن أموال من المملكة يخضع بنسبة 10% دون تنزيلات (المادة 3/ج): 5,000.\n- مجموع ضريبة الدخل = 22,000 دينار.\n- المساهمة الوطنية 1% من الدخل الخاضع (المادة 11/و/1/هـ): 105,000×1% = 1,050 دينار (أو 1,550 إذا أدخل الدخل الخارجي)."},{"num":73,"type":"essay","q":"السؤال الثالث (ثلاث علامات)\nقدمت الشركة الأولى التجارية إقرار ضريبة المبيعات عن الفترة 2021/06+05 متضمناً البيانات التالية:\n1. مستوردات ومشتريات خاضعة للضريبة العامة على المبيعات بنسبة 16%: 150,000 دينار.\n2. مبيعات خاضعة للضريبة العامة على المبيعات بنسبة 16%: 12,000 دينار.\n3. مبيعات خاضعة للضريبة العامة على المبيعات بنسبة 4%: 10,000 دينار.\n4. مبيعات للقوات المسلحة الأردنية - الجيش العربي: 35,000 دينار.\n5. ضريبة غير قابلة للخصم تخص مبيعات معفاة : 230 دينار.\n6. حركة تعديل لصالح الدائرة تمثل فرق ضريبي ناتج عن تدقيق إقرارات سابقة: 300 دينار.\nكما تم استخراج البيانات التالية من الإقرارات الضريبية المقدمة عن الفترات السابقة لدائرة ضريبة الدخل والمبيعات وكالآتي:\nأ- الفترة 2021/02+01\n1. الرصيد الافتتاحي للفترة 2021/02+01: 25,000 دينار.\n2. مستوردات ومشتريات خاضعة للضريبة العامة على المبيعات بنسبة 16% 18,000 دينار.\n3. مبيعات خاضعة للضريبة العامة على المبيعات بنسبة 16%: 23,000 دينار.\n4. مبيعات خاضعة للضريبة العامة على المبيعات بنسبة 4%: 1,000 دينار.\n5. مبيعات للقوات المسلحة الأردنية - الجيش العربي: 35,000 دينار.\nب- الفترة 2021/04+03\n1. مستوردات ومشتريات خاضعة للضريبة العامة على المبيعات بنسبة 16%: 15,000 دينار.\n2. مبيعات خاضعة للضريبة العامة على المبيعات بنسبة 16%: 18,000 دينار.\n3. مبيعات خاضعة للضريبة العامة على المبيعات بنسبة 4%: 9,000 دينار.\nالمطلوب:\nاحتساب رصيد الضريبة الذي مضى على تأديته أكثر من 6 شهور، والذي يحق للشركة المطالبة به في إقرار الفترة 06+05؟","law":"sales","article":"20","status":"changed","model_answer":"- المادة (20/ج) في القانون الحالي: يرد رصيد ضريبة المدخلات الذي مضى على دفعه أكثر من شهرين (وليس ستة أشهر كما في نص وقت الامتحان).\n- الفترة 01+02: مخرجات 23,000×16%+1,000×4% = 3,720، مدخلات 18,000×16% = 2,880، مبيعات الجيش معفاة؛ صافي مستحق 840 يخصم من الرصيد الافتتاحي ← 24,160.\n- الفترة 03+04: مخرجات 2,880+360 = 3,240، مدخلات 2,400، صافي مستحق 840 ← الرصيد 23,320 (كله من الرصيد القديم).\n- الفترة 05+06: مدخلات 24,000 ناقص الضريبة غير القابلة للخصم 230، مخرجات 1,920+400 = 2,320، تعديل لصالح الدائرة 300 ← رصيد جديد دائن 21,150.\n- الرصيد الذي مضى على تأديته المدة المحددة ويحق المطالبة برده في إقرار 05+06 = 23,320 دينار (الرصيد الافتتاحي بعد استهلاك 1,680 منه على أساس الأقدم فالأقدم)؛ إجمالي الرصيد الدائن 44,470."},{"num":74,"type":"essay","q":"السؤال الرابع (علامتان)\nاذكر النصاب القانوني للاجتماع غير العادي للشركة المساهمة العامة المحدودة في حالتي تصفيتها أو اندماجها بغيرها من الشركات المادة (173/ب).","law":"companies","article":"173","status":"valid","model_answer":"- المادة (173/ب): لا يقل النصاب القانوني للاجتماع غير العادي في حالتي التصفية أو الاندماج عن ثلثي أسهم الشركة المكتتب بها، بما في ذلك الاجتماع المؤجل للمرة الأولى.\n- إذا لم يكتمل النصاب فيه يلغى الاجتماع مهما كانت أسباب الدعوة."},{"num":75,"type":"essay","q":"السؤال الخامس (ثلاث علامات)\nما هي المهام التي يتولى مدققوا حسابات الشركة المساهمة العامة القيام بها وفقاً لما هو محدد بقانون الشركات المادة (193).","law":"companies","article":"193","status":"valid","model_answer":"- المادة (193): مراقبة أعمال الشركة.\n- تدقيق حساباتها وفق قواعد التدقيق المعتمدة ومتطلبات المهنة.\n- فحص الأنظمة المالية والإدارية وأنظمة المراقبة الداخلية والتأكد من ملاءمتها.\n- التحقق من موجودات الشركة وملكيتها لها وقانونية التزاماتها وصحتها.\n- الاطلاع على قرارات مجلس الإدارة والهيئة العامة والتعليمات وأي بيانات لازمة.\n- أي واجبات أخرى بموجب القانون وقانون المهنة.\n- تقديم تقرير خطي للهيئة العامة وتلاوته أمامها."},{"num":76,"type":"essay","q":"السؤال السادس (علامتان)\nاذكر أربعة من البيانات والمعلومات والوثائق الخاصة بكل دعوى إعسار والتي يتوجب على وكيل الإعسار الاحتفاظ بها وتدوينها:","law":"insolvency_sys","article":"22","status":"valid","model_answer":"- المادة (22/أ) من نظام الإعسار: اسم المدين ورقمه الوطني أو الرقم الوطني للمنشأة.\n- نسخة من قرار إشهار الإعسار.\n- سجل مستقل للوقائع والمعاملات اليومية المتعلقة بإجراءات الإعسار.\n- المراسلات الخاصة بدعوى الإعسار.\n- العقود والاتفاقيات التي يبرمها، القيود المحاسبية وفق المعايير الدولية، البيانات المالية المدققة للمدين، وأي بيانات أو وثائق تتعلق بالدعوى."},{"num":77,"type":"essay","q":"السؤال السابع (علامة ونصف)\nإذا تبين لمجلس مفوضي هيئة الأوراق المالية ولأسباب مبررة أن حماية المستثمرين تقتضي اتخاذ تدبير فوري، فله وللمدة التي يراها مناسبة اتخاذ تدابير أو أكثر، اذكر هذه التدابير:","law":"securities","article":"19","status":"valid","model_answer":"- المادة (19/أ): وقف أو تعليق أي نشاط يتعلق بالأوراق المالية أو بورقة مالية معينة.\n- تعليق العرض العام لورقة مالية.\n- تعليق أعمال المرخص له أو المعتمد."},{"num":78,"type":"essay","q":"السؤال الثامن (علامة واحدة)\nوفقاً لقانون الأوراق المالية يُقصد بالمعلومة الجوهرية:","law":"securities","article":"2","status":"valid","model_answer":"- المادة (2): المعلومة الجوهرية: أي واقعة أو معلومة قد تؤثر في قرار الشخص لشراء الورقة المالية أو الاحتفاظ بها أو بيعها أو التصرف بها."},{"num":79,"type":"essay","q":"السؤال التاسع (علامة واحدة)\nيُقصد بسوق تداول الأوراق المالية وفقاً لقانون الأوراق المالية:","law":"securities","article":"2","status":"valid","model_answer":"- المادة (2): سوق تداول الأوراق المالية: أي سوق منظم أو أي استخدام دوري أو مستمر لوسائل الاتصال يتيح تداول الأوراق والأصول المالية."},{"num":80,"type":"essay","q":"السؤال العاشر (علامة واحدة)\nعرف النشاط الاقتصادي حسب قانون الاستثمار لسنة 2014","law":"investment","article":"2","status":"changed","model_answer":"- قانون الاستثمار لسنة 2014 ألغي وحل محله قانون البيئة الاستثمارية رقم (21) لسنة 2022.\n- المادة (2) من القانون الحالي: النشاط الاقتصادي: أي نشاط صناعي أو تجاري أو زراعي أو خدمي أو سياحي أو تكنولوجيا معلومات أو صناعة إبداعية، ولا يشمل المصرفية أو الصيرفة أو النشاطات المهنية المنظمة بموجب تشريعات خاصة."},{"num":81,"type":"essay","q":"السؤال الحادي عشر (علامتان)\nاذكر الشركات التي لا يجوز لها ممارسة أعمال المؤمن حسب قانون تنظيم أعمال التأمين.","law":"insurance","article":"8","status":"changed","model_answer":"- القانون الحالي: قانون تنظيم أعمال التأمين رقم (12) لسنة 2021 (حل محل قانون 1999).\n- المادة (5): لا يجوز لأي شخص ممارسة أعمال التأمين إلا بعد الترخيص.\n- المادة (8/أ): يشترط أن تكون شركة التأمين شركة مساهمة عامة، فلا يجوز لغيرها (كالتضامن والتوصية وذات المسؤولية المحدودة والمساهمة الخاصة) ممارسة أعمال المؤمن، باستثناء: فرع شركة التأمين الأجنبية، الشركة التابعة لشركة تأمين، شركة التأمين الأردنية العاملة خارج المملكة (المعفاة)، وشركة التأمين المقيدة (مساهمة خاصة أو ذات مسؤولية محدودة)."},{"num":82,"type":"essay","q":"السؤال الثاني عشر (علامتان)\nفي علاقة البنك المركزي مع الحكومة، ما هي الأعمال التي يقوم بها البنك المركزي بالنيابة عن الحكومة أو المؤسسة العامة، اذكر أربعة منها؟","law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","model_answer":"- قانون البنك المركزي غير مدرج في القوانين المعتمدة؛ أبرز ما يقوم به البنك بالنيابة عن الحكومة والمؤسسات العامة:\n- العمل كبنك ووكيل مالي للحكومة ومسك حساباتها وقبول ودائعها.\n- إدارة إصدار سندات وأذونات الدين العام وخدمتها وتسديدها.\n- تحصيل المبالغ وصرفها نيابة عن الحكومة.\n- تنفيذ معاملات الحكومة بالعملات الأجنبية وتقديم المشورة في الشؤون المالية والاقتصادية."},{"num":83,"type":"essay","q":"السؤال الثالث عشر (علامة ونصف)\nاذكر ثلاثة من الخدمات التى تقدمها المؤسسة للمصاب بموجب تأمين إصابات العمل؟","law":"social","article":"26","status":"valid","model_answer":"- المادة (26/أ): تكاليف المعالجة الطبية والإقامة في المستشفى.\n- نفقات انتقال المصاب من مكان العمل أو سكنه إلى مكان العلاج والعودة.\n- توفير الخدمات والتجهيزات التأهيلية بما فيها الأطراف الصناعية.\n- إضافة إلى البدل اليومي خلال العجز المؤقت (المادة 29) ورواتب/تعويضات الاعتلال الإصابي."},{"num":84,"type":"essay","q":"السؤال الرابع عشر (علامتان)\nاذكر شروط استحقاق راتب الاعتلال الطبيعي.","law":"social","article":"67","status":"valid","model_answer":"- المادة (67/أ): انتهاء خدمة المؤمن عليه.\n- تقديم طلب تخصيص الراتب خلال مدة لا تتجاوز ستة أشهر من تاريخ انتهاء الخدمة.\n- ألا تقل اشتراكاته الفعلية عن (60) اشتراكاً منها (24) اشتراكاً متصلاً.\n- ثبوت حالة العجز بقرار من المرجع الطبي.\n- (67/ب): لا يستحق عن حالات العجز السابقة لشموله."},{"num":85,"type":"essay","q":"السؤال الخامس عشر (علامتان)\nعدد أربعة من مهام ديوان المحاسبة:","law":"audit","article":"3","status":"valid","model_answer":"- المادة (3) من قانون ديوان المحاسبة: مراقبة واردات الدولة ونفقاتها وحسابات الأمانات والسلفات والقروض والتسويات والمستودعات.\n- تقديم المشورة في المجالات المحاسبية للجهات الخاضعة لرقابته.\n- الرقابة على الأموال العامة للتأكد من سلامة إنفاقها بصورة قانونية وفاعلة.\n- التأكد من سلامة تطبيق التشريعات البيئية.\n- التثبت من أن القرارات والإجراءات الإدارية تتم وفقاً للتشريعات النافذة."}]},{"id":"2021-01","year":2021,"month":1,"label":"دورة كانون الثاني 2021","session":"كانون الثاني","src":"c6acf75a.json","questions":[{"num":1,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فإن نسبة الضريبة لقطاع التأجير التمويلي لسنة 2019 بـ:","o":["24% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية.","24% ضريبة دخل ونسبة 4% لحساب المساهمة الوطنية.","24% ضريبة دخل ونسبة 3% لحساب المساهمة الوطنية.","20% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية."],"law":"income","answer":1,"orig_answer":null,"article":"11","status":"valid","explanation":"المادة (11/ب/2) و(11/و/1/ج): 24% لأنشطة التأجير التمويلي و4% لحساب المساهمة الوطنية."},{"num":2,"type":"mcq","q":"ينتهي الإعفاء للأرباح الرأسمالية الناشئة عن بيع أسهم أو حصص شركات ومؤسسات تكنولوجيا المعلومات المتحققة للشركة التي تم تأسيسها في عام 2020:","o":["2035/12/31.","2033/12/31.","2034/12/31.","2032/12/31."],"law":"income","answer":1,"orig_answer":null,"article":"4","status":"valid","explanation":"المادة (4/ب/7): الإعفاء لمدة لا تتجاوز 15 سنة من تاريخ التسجيل أو نفاذ القانون المعدل (2019/1/1) أيهما أسبق، فينتهي في 2033/12/31."},{"num":3,"type":"mcq","q":"الدخل من الاستثمار هو:","o":["الدخل الصافي الذي يتحقق للشخص المقيم من أي مصدر داخل المملكة أو مصدر خارج المملكة شريطة أن يكون نشأ عن أمواله وودائعه من المملكة.","النشاط الذي يمارسه الشخص بقصد تحقيق ربح أو مكسب سواء كان في المملكة أو من خارج المملكة شريطة أن يكون نشأ عن أمواله وودائعه من المملكة.","أي دخل يتحقق خلاف الدخل من الوظيفة أو الدخل من نشاط الأعمال.","النشاط الذي يمارسه الشخص بقصد تحقيق ربح أو مكسب بما في ذلك النشاط التجاري أو الصناعي أو الزراعي أو المهني أو الخدمي أو الحرفي."],"law":"income","answer":2,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): الدخل من الاستثمار هو أي دخل متحقق خلاف الدخل من الوظيفة أو من نشاط الأعمال."},{"num":4,"type":"mcq","q":"مكلف تخلف عن تقديم إقرار ضريبة المبيعات ضمن الموعد المحدد بالقانون وتم فرض غرامة عليه 200 دينار فإن من حق المكلف:","o":["الاعتراض لدى هيئة الاعتراض خلال 45 تاريخ إرسال التبليغ بالبريد المسجل.","الاعتراض لدى هيئة الاعتراض خلال 30 يوم من تاريخ تبلغه.","الطعن في القرار الصادر لدى محكمة البداية خلال 30 يوم من تاريخ تبلغه.","أ + ب."],"law":"sales","answer":2,"orig_answer":null,"article":"29","status":"valid","explanation":"المادتان (28 و29): غرامة التأخر عن الإقرار يفرضها المدير ويُعترض عليها لدى الوزير خلال 30 يوماً، وقرار الوزير قابل للطعن لدى المحكمة المختصة خلال 30 يوماً من تبليغه؛ لا اختصاص لهيئة الاعتراض."},{"num":5,"type":"mcq","q":"يترتب على المكلف الذي ارتكب جرم التهرب من ضريبة المبيعات ما يلي:","o":["تعويض مدني لا يزيد عن ثلاث أمثال الضريبة وغرامة جزائية لا تزيد عن خمسمائة دينار.","تعويض مدني لا يزيد عن ثلاثة أمثال الضريبة وغرامة جزائية لا تزيد عن ألف دينار.","تعويض مدني لا يزيد عن مثلي الضريبة وغرامة جزائية لا تقل عن مئتي دينار.","تعويض مدني لا يزيد عن مثلي الضريبة وغرامة جزائية لا تزيد عن ألف دينار."],"law":"sales","answer":1,"orig_answer":null,"article":"31","status":"valid","explanation":"المادة (31): تعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها وغرامة لا تقل عن 200 ولا تزيد على 1000 دينار."},{"num":6,"type":"mcq","q":"لهيئة الاعتراض وفقاً لقانون ضريبة الدخل:","o":["وبناء على طلب خطي من المعترض ولأسباب مبررة تأجيل موعد جلسة الاعتراض مدة لا تزيد عن 10 أيام ولمرة واحدة.","وبناء على طلب خطي من المعترض ولأسباب مبررة تأجيل موعد جلسة الاعتراض مدة لا تزيد عن شهر ولمرة واحدة.","وبناء على طلب خطي من المعترض ولأسباب مبررة تأجيل موعد جلسة الاعتراض مدة لا تزيد عن 30 يوم ولمرة واحدة.","وبناء على طلب خطي من المعترض ولأسباب مبررة تأجيل موعد جلسة الاعتراض مدة لا تزيد عن 15 يوم ولمرة واحدة."],"law":"income","answer":3,"orig_answer":null,"article":"33","status":"unverified","explanation":"المادة (33/أ/2) تحيل إجراءات عمل هيئة الاعتراض إلى نظام؛ مدة التأجيل غير واردة في نص القانون (الإجابة الشائعة 15 يوماً وفق النظام)."},{"num":7,"type":"mcq","q":"لا تخضع السلع والخدمات المدرجة في جدول الضريبة الخاصة في أي من الحالات التالية:","o":["وضع السلع والخدمات المنتجة محلياً والخاضعة للضريبة الخاصة للتداول لأول مرة.","استيراد أي من تلك السلع والخدمات في المناطق والمدن والأسواق الحرة.","وضع السلع والخدمات المنتجة محلياً والخاضعة للضريبة الخاصة في تصرف المستهلك النهائي لهذه السلع.","استيراد أي من تلك السلع والخدمات من خارج المملكة."],"law":"sales","answer":1,"orig_answer":null,"article":"10","status":"valid","explanation":"المادة (10/هـ): لا تخضع للضريبة السلع والخدمات المستوردة لحساب المشاريع القائمة في المناطق والمدن والأسواق الحرة."},{"num":8,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل فإن نسبة الضريبة لقطاع صناعة الأجهزة الكهربائية لسنة 2020 هي:","o":["20% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية.","15% ضريبة دخل ونسبة 3% لحساب المساهمة الوطنية.","16% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية.","15% ضريبة دخل ونسبة 1% لحساب المساهمة الوطنية."],"law":"income","answer":2,"orig_answer":null,"article":"11","status":"valid","explanation":"المادة (11/ج/1): تخفض ضريبة الأنشطة الصناعية لسنة 2020 بنسبة 20% فتصبح 16% (20%×80%) إضافة إلى 1% مساهمة وطنية."},{"num":9,"type":"mcq","q":"يعفى ضريبة الدخل:","o":["الدخل من النشاط الزراعي معفي شريطة أن يكون من إنتاج المحاصيل والحبوب والخضروات وتربية المواشي والأسماك والطيور.","أول 500.000 دينار من الدخل الصافي للشخص الاعتباري المتأتي من النشاط الزراعي.","أول 50.000 دينار من الدخل الصافي للشخص الاعتباري المتأتي من النشاط الزراعي.","أول مليون دينار من مبيعات الشخص المعنوي المتأتي من النشاط الزراعي داخل المملكة."],"law":"income","answer":2,"orig_answer":null,"article":"5","status":"valid","explanation":"المادة (5/ب): يعفى أول 50,000 دينار من الدخل الصافي للشخص الاعتباري المتأتي من النشاط الزراعي (والمليون للشخص الطبيعي من المبيعات)."},{"num":10,"type":"mcq","q":"رتب قانون ضريبة الدخل إنشاء حساب المساهمة الوطنية والذي ألزم الشركات باقتطاع المبالغ التالية:","o":["فرضت نسب هذا الحساب على الدخل الخاضع للضريبة مما يزيد عن 200.000 دينار للشخص الطبيعي والاعتباري.","3% من الدخل الخاضع لشركات الوساطة المالية والشركات المالية.","2% من الدخل الخاضع لشركات التأمين.","7% من الدخل الخاضع للبنوك."],"law":"income","answer":2,"orig_answer":null,"article":"11","status":"valid","explanation":"المادة (11/و/1): 2% لشركات التأمين؛ 4% للوساطة المالية و3% للبنوك و1% للشخص الطبيعي فقط فيما يزيد على 200,000."},{"num":11,"type":"mcq","q":"ضريبة صناعة الأدوية عام 2020 في المنطقة التنموية:","o":["10% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 14% إذا كانت القيمة المضافة أقل من 30%.","5% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 14% إذا كانت القيمة المضافة أقل من 30%.","5% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 10% إذا كانت القيمة المضافة أقل من 30%.","10% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 15% إذا كانت القيمة المضافة أقل من 30%."],"law":"income","answer":2,"orig_answer":null,"article":"11","status":"valid","explanation":"المادة (11/ط): 5% للصناعات التحويلية في المناطق التنموية التي لا تقل قيمتها المضافة عن 30%، و10% لباقي الأنشطة."},{"num":12,"type":"mcq","q":"وفقاً لقانون ضريبة الدخل أي من العبارات التالية خطأ (الشخص الاعتباري المقيم الذي):","o":["تملك الحكومة أو أي من المؤسسات العامة نسبة لا تقل عن 50% من رأسماله.","تم تأسيسه أو تسجيله وفق أحكام التشريعات الأردنية وكان له في المملكة مركز يمارس الإدارة والرقابة على عمله.","مركز إدارته الفعلي في المملكة.","تم تأسيسه أو تسجيله وفق أحكام التشريعات الأردنية وكان له في المملكة فرع يمارس الإدارة والرقابة على عمله."],"law":"income","answer":0,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): يشترط أن تملك الحكومة أو المؤسسات العامة نسبة تزيد على 50% من رأسماله وليس (لا تقل عن 50%)."},{"num":13,"type":"mcq","q":"تفرض غرامة على المكلف الذي يتأخر في تقديم الإقرار الضريبي:","o":["100 دينار على الشخص الطبيعي، 300 دينار على الشركات ذات المسؤولية المحدودة والمساهمة الخاصة، 1000 دينار على الشركات المساهمة العامة.","100 دينار على الشخص الطبيعي، 200 دينار على شركات التضامن والذات مسؤولية محدودة، 1000 دينار على المساهمة العامة والخاصة.","100 دينار على الشخص الطبيعي، 300 دينار على الشركات الذات مسؤولية محدودة، 1000 دينار على الشركات المساهمة العامة والمساهمة الخاصة.","100 دينار على الشخص الطبيعي، 200 دينار على شركات التضامن، 500 دينار على الشركات ذات المسؤولية المحدودة والمساهمة الخاصة."],"law":"income","answer":2,"orig_answer":null,"article":"63","status":"valid","explanation":"المادة (63): غرامة بحد أقصى 100 دينار للشخص الطبيعي و300 للشخص الاعتباري و1000 للشركات المساهمة العامة والخاصة."},{"num":14,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات أي من العبارات التالية ليس صحيح (يجوز للمكلف المثول أمام محكمة الضريبة وتوقيع اللوائح المقدمة إليها):","o":["إذا كان من الأشخاص المعفيين من التدريب بموجب قانون نقابة المحامين.","إذا كان محامياً غير مزاول وفقاً لقانون نقابة المحامين.","إذا كان قاضياً عاملاً.","جميع ما ذكر خطأ."],"law":"sales","answer":3,"orig_answer":null,"article":"60","status":"valid","explanation":"المادة (60): يجوز للمكلف المثول إذا كان قاضياً عاملاً أو سابقاً أو محامياً مزاولاً أو غير مزاول أو من المعفيين من التدريب، فالعبارات (أ،ب،ج) صحيحة."},{"num":15,"type":"mcq","q":"إحدى هذه العبارات صحيحة: (تطبق محكمة البداية الضريبية وفقاً لقانون الضريبة العامة على المبيعات):","o":["أصول المحاكمات المدنية بما لا يتعارض مع قانون الضريبة العامة على المبيعات.","قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية.","أصول المحاكمات الجزائية بما لا يتعارض مع أصول المحاكمات المدنية.","أصول المحاكمات الضريبية."],"law":"sales","answer":0,"orig_answer":null,"article":"59","status":"valid","explanation":"المادة (59): تطبق المحكمة أصول المحاكمات الجزائية والمدنية بالقدر الذي لا يتعارض مع قانون الضريبة العامة على المبيعات."},{"num":16,"type":"mcq","q":"موظف كانت مكافأة نهاية الخدمة المستحقة له عن فترة عمله من 1998/1/1 لغاية 2019/1/31 180000 دينار وبلغت رواتبه خلال عام 2019 بقيمة 15000 دينار وهو أعزب وغير معيل، فإن الضريبة المستحقة عليه على النحو التالي:","o":["13525 دينار.","23125 دينار.","32500 دينار.","لا شيء مما ذكر."],"law":"income","answer":3,"orig_answer":null,"article":"4","status":"valid","explanation":"المادة (4/ب/13) والمادة (9): الإعفاء 100% قبل 2010 و50% لـ2010-2014 وأول 15,000 بعد 2015 والزائد بنسبة 9%؛ فضريبة المكافأة نحو 3,708 وضريبة الرواتب نحو 250 فلا يطابق أي خيار."},{"num":17,"type":"mcq","q":"يلتزم الورثة أو من يمثلهم بتقديم إقرار ضريبي عن المتوفي خلال:","o":["قبل 4/30 من السنة التالية لوفاته.","60 يوم من تاريخ الوفاة.","90 يوم من تاريخ الوفاة.","30 يوم من تاريخ الوفاة."],"law":"income","answer":2,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/ب): يلتزم الورثة بتقديم إقرار عن المتوفى خلال تسعين يوماً من تاريخ الوفاة."},{"num":18,"type":"mcq","q":"يعتبر التعليق للفوائد المعلقة بالنسبة للبنوك:","o":["قيام العميل بتسديد 25% من المبالغ المستحقة عليه.","قيام العميل بتسديد جزء من المبالغ المستحقة عليه.","منح العميل تسهيلات جديدة.","جميع ما ذكر صحيح."],"law":"income","answer":3,"orig_answer":null,"article":"14","status":"unverified","explanation":"المادة (14/ج): للبنك احتساب الضريبة على الفوائد المعلقة في سنة قبضها وفق التعليمات التنفيذية التي تحدد حالات القبض."},{"num":19,"type":"mcq","q":"ترد الضريبة التي حصلت بطريق الخطأ من قبل شخص مسجل عن السلع المنتجة محلياً، أو المؤداة محليا وفق ما يلي:","o":["الضريبة التي تحصل من قبل البائع ضريبة قطعية لا يجوز ردها بعد استيفائها وعلى البائع توريدها إلى الدائرة ومن خلال الإقرار الضريبي خلال المدة المحددة بالقانون.","من قبل الدائرة بعد أن يقدم المشتري طلباً خطياً للدائرة مبيناً فيه قيمة الضريبة المستوفاة بطريق الخطأ والمستندات المؤيدة لذلك.","من قبل الجهة التي تخولها الدائرة بالرد بعد تقديم المشتري طلباً خطياً مبيناً قيمة الضريبة والمستوفاة بطريق الخطأ والمستندات المؤيدة لذلك.","من قبل البائع بعد أن تقدم المشتري طلباً خطياً للشخص البائع مبيناً فيه قيمة الضريبة المستوفاة بطريق الخطأ مع المستندات المؤيدة لذلك."],"law":"sales","answer":1,"orig_answer":null,"article":"20","status":"valid","explanation":"المادة (20/ب): ترد الدائرة الضريبة المحصلة بطريق الخطأ بناء على طلب خطي مع المستندات خلال 30 يوماً من تقديم الطلب."},{"num":20,"type":"mcq","q":"اشترط القانون عند تقديم طلب تأجيل دفع ضريبة المبيعات عند الاستيراد الشروط التالية باستثناء:","o":["أن يكون مضى على تسجيله في ضريبة المبيعات مدة تزيد عن سنة.","أن لا تكون الضريبة المطلوب دفعها على استيراد سيارات مستعملة.","أن يكون ملتزم بتقديم إقرارات ضريبة المبيعات في موعدها لستة شهور متتالية.","أن يكون لديه رخصة مهن."],"law":"sales","answer":3,"orig_answer":null,"article":"26","status":"unverified","explanation":"المادة (26/د): يجوز بموافقة المدير تأجيل دفع ضريبة الاستيراد للمسجل وفق الشروط التي تحددها التعليمات التنفيذية (ورخصة المهن ليست منها)."},{"num":21,"type":"mcq","q":"أي من العبارات التالية ليست صحيحة وفقاً لقانون ضريبة المبيعات:","o":["لا يحتسب اليوم الذي تم فيه التبلغ لغايات احتساب المدد المنصوص عليها في قانون ضريبة المبيعات.","يعتبر النشر في صحيفتين يوميتين محليتين لمرتين تبلغ قانوني إذا تعذر تبلغ المكلف بالبريد.","يعتبر النشر في صحيفتين يوميتين محليتين لمرة واحدة تبلغ قانوني للمكلف إذا لم يتوفر لدى الدائرة عنوان للمكلف.","تقدم لائحة الاعتراض خلال 30 يوم من تاريخ تبلغ المعترض للقرار."],"law":"sales","answer":null,"orig_answer":null,"article":"63","status":"unverified","explanation":"المادتان (63) و(48/ب): جميع العبارات تبدو صحيحة نصاً (لا يحتسب يوم التبليغ، النشر مرتين، النشر مرة على الأقل عند عدم وجود عنوان، والاعتراض خلال 30 يوماً)."},{"num":22,"type":"mcq","q":"أي من العبارات التالية خطأ وفقاً لقانون ضريبة المبيعات، يلزم الشخص المسجل بالاحتفاظ بالدفاتر والسجلات والمستندات لمدة أربع سنوات ابتداء من آخر تاريخ أي من التواريخ التالية:","o":["تاريخ تبلغ الإشعار بنتيجة قرار التقدير الإداري.","تاريخ تبلغ الإشعار بنتيجة قرار التقدير الأولي.","تاريخ تقديم الإقرار الضريبي.","تاريخ تقديم الإقرار الضريبي."],"law":"sales","answer":1,"orig_answer":null,"article":"38","status":"valid","explanation":"المادة (38/أ): التواريخ هي انتهاء الفترة الضريبية وتقديم الإقرار وتبليغ إشعار قرار التقدير الإداري، وليس التقدير الأولي."},{"num":23,"type":"mcq","q":"وفقاً لقانون ضريبة المبيعات للمدير ان يلزم اي شخص غير مسجل عند بيعه لسلعة أو خدمة خاضعة للضريبة بإصدار فواتير ومسك سجلات وحسابات منتظمة لتسهيل عمليات البيع التي يقوم بها والاحتفاظ بتلك الفواتير والسجلات:","o":["خمس سنوات تالية لتاريخ السنة المالية التي صدرت أو نظمت بها.","أربع سنوات تالية لتاريخ السنة المالية التي صدرت أو نظمت بها.","خمس سنوات تبدأ من السنة المالية التي صدرت أو نظمت بها.","أربع سنوات تبدأ من السنة المالية التي صدرت أو نظمت بها."],"law":"sales","answer":0,"orig_answer":null,"article":"18","status":"valid","explanation":"المادة (18/ب): الاحتفاظ بالفواتير والسجلات مدة الخمس سنوات التالية لتاريخ انتهاء السنة المالية التي صدرت فيها."},{"num":24,"type":"mcq","q":"إحدى العبارات التالية خطأ وفقاً لقانون ضريبة المبيعات (تنظر هيئة الاعتراض بالاعتراض شكلاً للتثبيت) مما يلي:","o":["إن القرار المعترض عليه من القرارات القابلة للاعتراض.","إن الاعتراض مقدم خلال المهلة القانونية.","إن المعترض قام بدفع الضريبة المسلم فيها.","إن البنود المعترض عليها مخالفة لما ورد نصه في القانون."],"law":"sales","answer":3,"orig_answer":null,"article":"48","status":"valid","explanation":"المادة (48/د): الشروط الشكلية هي قابلية القرار للاعتراض وتقديمه في المدة ودفع المبالغ المسلم بها؛ مخالفة البنود للقانون مسألة موضوعية."},{"num":25,"type":"mcq","q":"يحق لوزير الصناعة والتجارة تشكيل لجنة إدارة لإدارة الشركة وذلك وفقاً لما يلي:","o":["إذا قدم رئيس مجلس الإدارة استقالته أو توفي.","من الأسباب الموجبة التي تعطي الحق للوزير بتشكيل لجنة إدارة لإدارة للشركة المساهمة العامة لمدة لا تزيد عن ستة أشهر وذلك لانتخاب إدارة جديد للشركة إذا فقد المجلس نصابه القانوني أو إذا لم تتمكن الهيئة العامة من انتخاب مجلس إدارة لإدارة الشركة.","إذا قدم رئيس وأعضاء مجلس الإدارة للشركة المساهمة العامة استقالتهم أو فقد المجلس نصابه القانوني شريطة أن يكون قد مضى على انتخابهم مدة لا تقل عن سنة.","كل ما ذكر خطأ."],"law":"companies","answer":1,"orig_answer":null,"article":"167","status":"valid","explanation":"المادة (167/أ): يشكل الوزير بتنسيب المراقب لجنة مؤقتة لإدارة الشركة ودعوة الهيئة العامة خلال 6 أشهر لانتخاب مجلس جديد إذا فقد المجلس نصابه أو تعذر انتخابه."},{"num":26,"type":"mcq","q":"للهيئة العامة للشركة في حالة توصية مدقق الحسابات بعدم المصادقة على البيانات المالية وردها للمجلس ان تقرر:","o":["تعيين مدقق حسابات آخر لإبداء رأيه في الميزانية العمومية وحساب الأرباح والخسائر ويعتبر الأرباح والخسائر وفقا لذلك.","مناقشة تقرير مدقق الحسابات والتفاوض معه بتعديل تقريره واعتبار أن الميزانية وحساب الأرباح والخسائر قد تم المصادقة عليها بعد ذلك.","الطلب إلى المجلس تصحيح الميزانية وحساب الأرباح والخسائر وفقا لملاحظات مدقق الحسابات واعتبارها مصدقة بعد هذا التعديل أو إحالة الموضوع إلى المراقب لتعيين لجنة خبراء من مدققي الحسابات القانونيين للفصل في موضوع الخلاف بين مجلس الإدارة ومدققي حساباتها ويكون قرار اللجنة ملزما بعد عرضه مرة أخرى على الهيئة العامة لإقراره وتعديل الميزانية وحساب الأرباح والخسائر وفقا لذلك.","تشكيل لجنة من المساهمين غير أعضاء مجلس الإدارة وذلك للتنسيق بين مدقق الحسابات ومجلس الإدارة، وذلك للوصول إلى حل وسطي حول الخلافات وعلى مدقق الحسابات ومجلس الإدارة إعداد بيانات مالية معدلة وفقا لذلك."],"law":"companies","answer":2,"orig_answer":null,"article":"196","status":"valid","explanation":"المادة (196): الطلب إلى المجلس تصحيح البيانات وفق ملاحظات المدقق أو إحالة الموضوع للمراقب لتعيين لجنة خبراء يكون قرارها ملزماً بعد عرضه على الهيئة العامة."},{"num":27,"type":"mcq","q":"يقدم طلب التصفية الإجبارية إلى المحكمة بلائحة دعوى من المحامي العام المدني أو المراقب أو من ينيبه وللمحكمة أن تقرر التصفية في أي من الحالات التالية:","o":["إذا عجزت الشركة عن الوفاء بالتزامها أو زاد مجموع خسائرها على (75%) من رأسمالها المكتتب به ما لم تقرر هيئتها العامة زيادة رأسمالها.","إذا ارتكبت الشركة أي مخالفة للقانون أو لنظامها الأساسي.","إذا فقد مجلس إدارة الشركة أو هيئة المديرين فيها نصابه القانوني.","جميع ما ذكر صحيح."],"law":"companies","answer":0,"orig_answer":0,"article":"266","status":"changed","explanation":"المادة (266/أ): يقدم الطلب الآن من وكيل عام إدارة قضايا الدولة (بدل المحامي العام المدني)؛ ومن حالاته العجز عن الوفاء أو زيادة الخسائر على 75%، والمخالفة يجب أن تكون جسيمة."},{"num":28,"type":"mcq","q":"لا يجوز أن يترشح لعضوية مجلس إدارة الشركة المساهمة العامة أو يكون عضواً فيه:","o":["أي شخص حكم عليه من محكمة مختصة بأي عقوبة جنائية او جنحية في جريمة مخلة بالشرف أو مخلة بالآداب والأخلاق العامة أو فاقداً للأهلية أو صدر بحقه أي عقوبة من العقوبات المنصوص عليها في المادة (278) من قانون الشركات أو أن يقل عمره عن (21) عاما.","أي شخص حكم عليه من محكمة مختصة بأي عقوبة جنائية أو جنحية في جريمة مخلة بالشرف أو مخلة بالآداب والأخلاق العامة أو فاقداً للأهلية ولم يرد له اعتباره.","أي شخص حكم عليه من محكمة مختصة بأي عقوبة جنائية أو جنحية في جريمة مخلة بالشرف أو الآداب ورد إليه اعتباره وعمره لا يقل عن (19) سنة.","جميع ما ذكر صحيح."],"law":"companies","answer":0,"orig_answer":null,"article":"134","status":"valid","explanation":"المادتان (134) و(147): يمنع المحكوم بجناية أو جنحة مخلة بالشرف أو فاقد الأهلية أو المعاقب وفق المادة (278)، ويشترط ألا يقل العمر عن 21 سنة."},{"num":29,"type":"mcq","q":"لشركة التضامن أن تتحول إلى شركة ذات مسؤولية محدودة وذلك باتباع الإجراءات التالية:","o":["تقديم طلب خطي موقع من جميع الشركاء مقدم إلى مراقب عام الشركات ومرفقا به بيان أسباب ومبررات التحويل وميزانية الشركة لآخر سنتين مصدقة من مدقق حسابات قانوني أو آخر سنة مالية وبيان بتقديرات الشركاء لموجودات ومطلوبات الشركة.","تقديم طلب خطي موقع من المفوضين بالتوقيع عن الشركة إلى المراقب ومرفقا به بيان بأسباب ومبررات التحويل وميزانيات الشركة المدققة وبيان بتقديرات الشركاء لموجودات ومطلوبات الشركة.","تقديم طلب خطي موقع من جميع الشركاء إلى المراقب مرفقاً به مبررات التحويل والميزانية العمومية وحساب الأرباح والخسائر المدققة لآخر سنتين ماليتين على الأقل وأن تكون حققت أرباحاً في أي منها وبيان بتقديرات الشركاء لموجودات الشركة.","تقديم طلب موقع من معظم الشركاء إلى المراقب ومرفقاً به بيان بأسباب ومبررات التحويل وميزانيات الشركة المدققة وبيان بتقديرات الشركاء الموجودات الشركة ومطلوباتها."],"law":"companies","answer":0,"orig_answer":null,"article":"216","status":"valid","explanation":"المادة (216/أ): طلب خطي من جميع الشركاء إلى المراقب مع أسباب التحويل وميزانية آخر سنتين مصدقة (أو آخر سنة) وبيان بتقديرات الموجودات والمطلوبات."},{"num":30,"type":"mcq","q":"في ما يتعلق بالشخصية الاعتبارية للشركة أي العبارات التالية صحيحة حسب قانون الشركات:","o":["لا يترتب على تحويل أية شركة إلى أية شركة أخرى نشوء شخص اعتباري جديد وتحتفظ ببعض حقوقها السابقة وتكون مسؤولة عن التزاماتها بعد التحويل فقط.","يترتب على تحويل أية شركة إلى أية شركة أخرى نشوء شخص اعتباري جديد وذلك لكون نوع الشركة قد اختلف وكذلك اختلف رقم وتاريخ تأسيسها بعد التحويل.","يترتب على تحويل أية شركة إلى أية شركة أخرى نشوء شخص اعتباري جديد وذلك لقيام اللجنة المشكلة من قبل مراقب عام الشركات بإعادة تقدير موجودات ومطلوبات الشركة وبيان صافي حقوق الشركاء.","لا يترتب على تحويل أية شركة إلى أية شركة أخرى نشوء شخص اعتباري جديد وتحتفظ الشركة بجميع حقوقها وتكون مسؤولة عن التزاماتها السابقة على التحويل."],"law":"companies","answer":3,"orig_answer":null,"article":"221","status":"valid","explanation":"المادة (221): لا يترتب على التحويل نشوء شخص اعتباري جديد وتحتفظ الشركة بجميع حقوقها وتبقى مسؤولة عن التزاماتها السابقة."},{"num":31,"type":"mcq","q":"فيما يتعلق بتسديد الأسهم العينية المكتتب بها في رأسمال الشركة المساهمة العامة أي العبارات التالية صحيحة حسب قانون الشركات:","o":["إذا لم يلتزم أصحاب المقدمات العينية بتسليمها أو نقل الملكية الى الشركة خلال شهر من تاريخ تسجيلها يمكن للمراقب أن يمنح الشركة فترة زمنية للتسديد، لا تتجاوز (6) أشهر وذلك بناء على طلب مقدم من الشركة.","إذا لم يلتزم أصحاب المقدمات العينية بتسليمها أو نقل الملكية الى الشركة خلال شهر من تاريخ تسجيلها يكونون ملزمين حكماً بتسديد ودفع قيمتها المعتمدة وعلى (4) مراحل فقط.","إذا لم يلتزم أصحاب المقدمات العينية بتسليمها أو نقل الملكية إلى الشركة خلال شهر من تاريخ تسجيلها فيكونوا ملزمين حكما بدفع قيمتها نقداً وبالسعر الذي اعتمده المؤسسون.","يلتزم مساهمي (أصحاب) المقدمات العينية بتسليم أو نقل ملكية المقدمات العينية للشركة فور تسجيل الأسهم باسمهم مباشرة وبعكس ذلك تلغي الأسهم العينية المكتتب بها."],"law":"companies","answer":2,"orig_answer":null,"article":"97","status":"valid","explanation":"المادة (97/1): إذا لم يسلم أصحاب المقدمات العينية خلال شهر من التسجيل يلزمون حكماً بدفع قيمتها نقداً بالسعر الذي اعتمده المؤسسون."},{"num":32,"type":"mcq","q":"إذا علمت أن أعضاء مجلس الإدارة للشركة يتكون من (12) عضو فإن شروط إصدار اسناد القرض:","o":["لا يشترط موافقة مجلس الإدارة على إصدار إسناد القرض لكون أن هذا الإسناد عبارة عن اقتراض الأموال من البنوك أو غيرها لقيام الشركة بتسيير أمورها اليومية ويتولى ذلك المدير العام للشركة لكونه مفوض بالتوقيع عنها.","يشترط في إسناد القرض موافقة جميع أعضاء مجلس الإدارة لإصدارها في حين إذا كان إسناد القرض قابل للتحويل إلى أسهم يتوجب موافقة الهيئة العامة غير العادية للشركة على ذلك.","يشترط في إسناد القرض موافقة جميع أعضاء مجلس إدارة الشركة على إصدارها بموافقة نصف (عدد) أعضاء المجلس على الأقل، ويشترط موافقة الهيئة العامة غير العادية على ذلك في حالة إذا كان إسناد القرض قابل للتحويل إلى أسهم.","يشترط في إصدار إسناد القرض لهذه الشركة موافقة بأغلبية (8) أعضاء من المجلس على الأقل إذا كانت هذه الأسناد قابلة للتحويل إلى أسهم فيشترط الحصول على موافقة الهيئة العامة غير العادي للشركة لذلك."],"law":"companies","answer":3,"orig_answer":null,"article":"117","status":"valid","explanation":"المادة (117): موافقة ثلثي أعضاء المجلس (8 من 12) وموافقة الهيئة العامة غير العادية إذا كانت الأسناد قابلة للتحويل لأسهم."},{"num":33,"type":"mcq","q":"يكون لمجلس إدارة الشركة المساهمة العامة أو مديرها العام الصلاحيات الكاملة في إدارة الشركة في الحدود التي بيّنها نظامها:","o":["تعتبر الأعمال والتصرفات التي يقوم بها ويمارسها المجلس أو مدير الشركة باسمها ملزمة لها في مواجهة الغير الذي يتعامل مع الشركة بحسن النية ولها الرجوع عليه بقيمة التعويض عن الضرر الذي لحق بها.","تعتبر الأعمال والتصرفات التي يقوم بها ويمارسها المجلس أو مدير الشركة باسمها في مواجهة الغير ملزمة لأعضاء المجلس والمدير العام بحدود الأموال الشخصية لكل منهم.","تعتبر الأعمال والتصرفات التي يقوم بها ويمارسها المجلس أو مدير الشركة باسمها ملزمة لها في مواجهة الغير بحدود قيمة إجمالي الأسهم التي يمتلكها كل عضو من أعضاء المجلس.","كل ما ذكر صحيح."],"law":"companies","answer":0,"orig_answer":null,"article":"156","status":"valid","explanation":"المادة (156/أ): تصرفات المجلس أو المدير العام باسم الشركة ملزمة لها تجاه الغير حسن النية ولها الرجوع بالتعويض عن الضرر."},{"num":34,"type":"mcq","q":"يعد مجلس إدارة الشركة المساهمة العامة تقريراً كل ستة أشهر يتضمن المركز المالي للشركة ونتائج أعمالها وحساب الأرباح والخسائر وقائمة التدفق النقدي والإيضاحات المتعلقة بالبيانات المالية بحيث يكون هذا التقرير:","o":["معد من قبل مجلس الإدارة ولم يشترط القانون بأن يكون مدقق أو مصادق عليه من مدقق حسابات الشركة وذلك لكونه لا يمثل بيانات مالية سنوية.","معد من قبل مجلس الإدارة وعلى أن يكون هذا التقرير النصف سنوي مدقق من قبل مدقق حسابات الشركة وإصدار تقرير تدقيق حوله وذلك لأنه الركيزة الأساسية بإصدار البيانات المالية السنوية.","معد من قبل مجلس الإدارة ومصادق عليه من مدقق حسابات الشركة ويزود المراقب بنسخة من التقرير خلال ستين يوماً من صدور التقرير.","معد من قبل مجلس الإدارة ومصادق عليه من مدقق حسابات الشركة ويزود المراقب بنسخة امنه خلال ستين يوما من انتهاء المدة."],"law":"companies","answer":3,"orig_answer":null,"article":"142","status":"valid","explanation":"المادة (142): تقرير نصف سنوي مصادق عليه من المدقق ويزود المراقب بنسخة خلال ستين يوماً من انتهاء المدة."},{"num":35,"type":"mcq","q":"أي العبارات التالية تعتبر صحيحة فيما يتعلق بمدقق الحسابات والحق في مناقشته من قبل الهيئة العامة:","o":["يعتبر مدقق حسابات الشركة وكيلاً عن المساهمين فيها وذلك في حدود المهمة الموكلة إليه ويجوز لكل مساهم أن يستوضح منه أي استفسار ورد في تقريره سواء أثناء الجلسة أو في مكتبه وكيلا منتخب من قبل الهيئة العامة.","يعتبر مدقق حسابات الشركة وكيلا عن مجلس الإدارة وعليه أن يرد على كافة استفسارات الهيئة العامة وذلك أثناء انعقاد الجلسة فقط.","يعتبر مدقق حسابات الشركة وكيلا عن المساهمين وعليه أن يوضح كافة المفردات المالية التي ظهرت ضمن البيانات المالية ويبين مدى مصداقية هذه المفردات ومدى تحققها ونسبة ذلك.","يعتبر مدقق حسابات الشركة وكيلا عن المساهمين فيها وذلك في حدود المهمة الموكلة إليه ولكل مساهم أثناء انعقاد الهيئة العامة أن يستوضح مدقق الحسابات عما ورد في تقريره ويناقشه فيه."],"law":"companies","answer":3,"orig_answer":null,"article":"199","status":"valid","explanation":"المادة (199): المدقق وكيل عن المساهمين في حدود مهمته ولكل مساهم أثناء انعقاد الهيئة العامة أن يستوضحه ويناقشه."},{"num":36,"type":"mcq","q":"أي من العبارات التالية يعتبر صحيحاً فيما يتعلق بتخفيض الجزء غير المكتتب به من رأس المال المصرح به للشركة المساهمة العامة (م. ع.م):","o":["لا يشترط موافقة الهيئة العامة ولا يشترط موافقة كل من مراقب عام الشركات ولا الدائنين على تخفيض الجزيء غير المكتتب به من رأس المال المصرح به للشركة (م.ع.م)، وذلك لكون أن هذا الجزء لا يوجد به أسهم مكتتب بها وغير مسددة.","يشترط موافقة الهيئة العامة باجتماع غير عادي وبنصاب قانوني على تخفيض الجزء غير المكتتب به من رأس المال المصرح به للشركة (م.ع.م)، ولا يشترط موافقة المراقب والدائنين على ذلك.","يتوجب موافقة مجلس إدارة الشركة المساهمة العامة وبنصاب لا يقل عن ثلثي أعضاء المجلس فقط لتخفيض الجزء غير المكتتب به من رأس المال المصرح به ولا يشترط موافقة المراقب على ذلك.","يتوجب موافقة الهيئة العامة غير العادية وبنصاب وتمثيل قانوني وموافقة مراقب عام الشركات على تخفيض الجزيء غير المكتتب به من رأس المال المصرح به الشركة م.ع.م."],"law":"companies","answer":3,"orig_answer":null,"article":"114","status":"valid","explanation":"المادة (114/أ): يخفض الجزء غير المكتتب به بقرار من الهيئة العامة غير العادية، ويخضع قرارها للموافقة والتسجيل لدى المراقب (المادة 175/ج)."},{"num":37,"type":"mcq","q":"أي من التالية من حقوق مالك الأسهم في الشركات المساهمة العامة:","o":["لا يجوز تأسيس أي شركة مساهمة عامة تكون أسهمها (عينية) ناتجة عن مقدمات عينية، وذلك لعدم قدرة اللجان الفنية من تحديد القيمة العادلة لهذه الأسهم و/أو المغالاة باحتساب قيمتها مما يضر في حقوق المساهمين الآخرين والغير.","يتمتع مالكو الأسهم العينية في الشركة المساهمة العامة بمزايا وحقوق إضافية عن أصحاب الأسهم النقدية لكون أن هذه الأسهم العينية ناتجة عن مقدمات عينية ممكن أن تكون ماكنات عاملة، بضاعة جاهزة للبيع، حقوق امتياز ذات مردود ربحي عالي.","يتمتع مالكو الأسهم العينية في الشركة المساهمة العامة بالحقوق التي يتمتع بها أصحاب الأسهم النقدية وإذا كانت الأسهم العينية تأسيسية تطبق عليها القيود المطبقة على الأسهم النقدية عند التأسيس.","كل ما ذكر خطأ."],"law":"companies","answer":2,"orig_answer":null,"article":"111","status":"valid","explanation":"المادة (111): يتمتع مالكو الأسهم العينية بحقوق أصحاب الأسهم النقدية وتطبق على التأسيسية منها قيود الأسهم النقدية التأسيسية."},{"num":38,"type":"mcq","q":"وفقاً لقانون الضمان الاجتماعي يشترط لاعتبار الحادث إصابة عمل أن يكون المؤمن عليه مشمولاً بأحكام القانون لمدة:","o":["6 اشتراكات.","24 اشتراك.","لا يشترط عدد معين من الاشتراكات.","12 اشتراك."],"law":"social","answer":2,"orig_answer":null,"article":"2","status":"valid","explanation":"تأمين إصابات العمل يشمل المؤمن عليه من أول يوم شموله دون اشتراط عدد معين من الاشتراكات."},{"num":39,"type":"mcq","q":"تلتزم المنشأة بإشعار مؤسسة الضمان بوقوع إصابة العمل خطياً وإرفاق التقرير الطبي الأولي وذلك خلال:","o":["ثلاثون يوم عمل من تاريخ وقوعها.","إحدى وعشرون يوم عمل من تاريخ وقوعها.","سبعة وعشرون يوم عمل من تاريخ وقوعها.","أربعة عشر يوما عمل من تاريخ وقوعها."],"law":"social","answer":3,"orig_answer":null,"article":"27","status":"valid","explanation":"المادة (27/ب): خلال أربعة عشر يوم عمل من تاريخ وقوع الإصابة حداً أعلى."},{"num":40,"type":"mcq","q":"يستحق المؤمن عليه راتب اعتلال العجز الجزئي الإصابي الدائم إذا نتج عن الإصابة عجز بنسبة:","o":["أقل من 30%.","15%.","30% فأكثر.","25%."],"law":"social","answer":2,"orig_answer":null,"article":"30","status":"valid","explanation":"المادة (30/ج): يستحق راتب اعتلال العجز الجزئي الإصابي الدائم إذا كانت نسبة العجز 30% فأكثر."},{"num":41,"type":"mcq","q":"يستحق المؤمن عليه الذي لديه أقل من (180) اشتراك لبدل التعطل عن العمل عن ثلاثة أشهر وفقاً للنسب التالية:","o":["ما نسبته (75%) من آخر أجر خاضع للاقتطاع عن الشهر الأول و(65%) عن الشهر الثاني و(55%) عن الشهر الثالث بسقف 500 دينار مربوطا بالتضخم.","ما نسبته (65%) من آخر أجر خاضع للاقتطاع عن الشهر الأول و(55%) عن الشهر الثاني و(45%) عن الشهر الثالث.","ما نسبته (75%) من آخر أجر خاضع للاقتطاع عن الشهر الأول و(65%) عن الشهر الثاني و(45%) عن الشهر الثالث.","لا شيء مما ذكر."],"law":"social","answer":0,"orig_answer":null,"article":"53","status":"valid","explanation":"المادتان (52 و53): ثلاثة أشهر لمن اشتراكاته أقل من 180 بنسب 75% و65% و55% بسقف 500 دينار مربوط بالتضخم."},{"num":42,"type":"mcq","q":"يشترط للاستفادة من بدل إجازة الأمومة:","o":["أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (9) أشهر قبل الولادة.","أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (6) أشهر قبل الولادة.","أن تكون المؤمن عليها مشمولة بأحكام القانون لمدة لا تقل عن (12) شهرا قبل الولادة.","لا شيء مما ذكر."],"law":"social","answer":1,"orig_answer":null,"article":"44","status":"valid","explanation":"المادة (44/أ): أن تكون مشمولة خلال الأشهر الستة الأخيرة السابقة لاستحقاق إجازة الأمومة."},{"num":43,"type":"mcq","q":"يشترط في المؤمن عليه الأردني الذي يرغب في الجمع بين راتب التقاعد المبكر وأجره من العمل المشمول بأحكام القانون ما يلي:","o":["أن يكون قد انقطع عن العمل لمدة لا تقل عن 24 شهرا وأن لا يعود للعمل في أي من المنشآت التي كان يعمل بها خلال الستة والثلاثين اشتراكاً الأخيرة.","ان يكون قد انقطع عن العمل لمدة لا تقل عن 24 شهرا.","أن يكون قد انقطع عن العمل لمدة لا تقل عن 16 شهرا وأن لا يعود للعمل في أي من المنشآت التي كان يعمل بها خلال الستة والثلاثين اشتراكا الأخيرة.","أن يكون قد انقطع عن العمل لمدة لا تقل عن 24 شهرا وألا يعود للعمل في أي من المنشآت التي كان يعمل بها خلال الستة والثلاثين اشتراكا الأخيرة."],"law":"social","answer":0,"orig_answer":null,"article":"85","status":"valid","explanation":"المادة (85/د): الانقطاع عن العمل 24 شهراً من تاريخ استحقاق الراتب وعدم العودة للمنشآت التي عمل بها خلال آخر 36 اشتراكاً (الخيار د مطابق أيضاً)."},{"num":44,"type":"mcq","q":"لا يجوز الحجز على راتب التقاعد أو راتب الاعتلال للمؤمن عليه أو للمستحقين عنه إلا لما يلي:","o":["دين النفقة وبما لا يتجاوز ربع الراتب التقاعدي أو راتب الاعتلال.","دين المؤسسة ودين النفقة وتعطى الأولوية لدين النفقة وبما لا يتجاوز ربع الراتب التقاعدي أو راتب الاعتلال.","دين المؤسسة وبما لا يتجاوز ربع الراتب التقاعدي أو راتب الاعتلال.","دين المؤسسة ودين النفقة وتعطى الأولوية لدين المؤسسة وبما لا يتجاوز ربع الراتب التقاعدي أو راتب الاعتلال."],"law":"social","answer":1,"orig_answer":null,"article":"93","status":"valid","explanation":"المادة (93): يجوز الحجز لدين النفقة أو دين المؤسسة بما لا يتجاوز الربع والأولوية لدين النفقة."},{"num":45,"type":"mcq","q":"يعتبر المصدر حسب قانون هيئة الأوراق المالية:","o":["أي سوق منظم أو أي استخدام دوري أو مستمر لوسائل الاتصال يتيح تداول الأوراق والأصول المالية.","الشخص الذي يمارس شراء الأوراق المالية وبيعها لحساب الغير.","الشخص الاعتباري الذي يصدر أوراقا مالية أو يعلن عن رغبته في إصدارها.","لا شيء مما ذكر."],"law":"securities","answer":2,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): المصدر هو الشخص الاعتباري الذي يصدر أوراقاً مالية أو يعلن عن رغبته في إصدارها."},{"num":46,"type":"mcq","q":"لا يجوز لأي شخص طلب شراء أوراق مالية أو مبادلتها بهدف تملك ما يزيد عن النسب التالية من الأوراق المالية المصدرة من مصدر عام إلا عن طريق عرض تملك عام وفقاً للتعليمات التي تصدر التي يصدرها المجلس:","o":["(33.3%).","(51%).","(40%).","(50%)."],"law":"securities","answer":2,"orig_answer":null,"article":"45","status":"valid","explanation":"المادة (45/أ): تملك 40% أو أكثر من أوراق مصدر عام لا يتم إلا بعرض تملك عام."},{"num":47,"type":"mcq","q":"تمنح الأوراق المالية وفقاً لأحكام قانون الأوراق المالية الميزة التالية:","o":["عدم جواز إلغاء التسويات النهائية لعقود التداول في السوق.","حقوق ملكية وأثمان مستحقة وفقا لحسابات المركز.","الصفة النهائية والقطعية لتداولها في الأسواق المالية.","جميع ما ذكر صحيح."],"law":"securities","answer":3,"orig_answer":null,"article":"112","status":"valid","explanation":"المادة (112): الصفة النهائية للتداول وحقوق الملكية وفق حسابات المركز وعدم جواز إلغاء التسويات النهائية."},{"num":48,"type":"mcq","q":"تصدر التعليمات لتنفيذ أحكام قانون الأوراق المالية من خلال:","o":["مجلس مفوضي هيئة الأوراق المالية.","مجلس مفوضي هيئة الأوراق المالية.","رئيس الوزراء بتنسيب من مجلس مفوضي هيئة الأوراق المالية.","رئيس الهيئة."],"law":"securities","answer":0,"orig_answer":null,"article":"118","status":"valid","explanation":"المادتان (12/ص) و(118/ب): يصدر مجلس المفوضين التعليمات اللازمة لتنفيذ القانون (الخياران أ وب متطابقان)."},{"num":49,"type":"mcq","q":"يتم انتخاب أعضاء مجلس إدارة الشركة المساهمة العامة المدرجة في السوق المالي وفق الأسلوب التالي:","o":["بالأغلبية لمن حضر اجتماع الهيئة العامة.","نسبة وتناسب مما يحمله المساهم من أسهم وبالاقتراع السري.","اسلوب التصويت التراكمي من قبل الهيئة العامة للشركة بالاقتراع السري.","لكل مساهم الحق في اختيار عضو مجلس إدارة واحد وبالاقتراع السري."],"law":"securities","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"وفق تعليمات حوكمة الشركات المساهمة المدرجة الصادرة عن مجلس مفوضي الهيئة: الانتخاب بأسلوب التصويت التراكمي بالاقتراع السري؛ لا نص في القانون."},{"num":50,"type":"mcq","q":"تكون مهام لجنة الحوكمة وبشكل رئيسي حسب قانون هيئة الأوراق المالية ما يلي:","o":["التأكد من التزام الشركة بأحكام هذه التعليمات ودراسة ملاحظات الهيئة بخصوص تطبيق الحوكمة في الشركة ومتابعة ما تم بشأنها.","وضع إجراءات عمل خطية لتطبيق أحكام هذه التعليمات ومراجعتها وتقييم مدى تطبيقها بشكل سنوي.","إعداد تقرير الحوكمة وتقديمه لمجلس الإدارة.","جميع ما ذكر."],"law":"securities","answer":3,"orig_answer":null,"article":"","status":"unverified","explanation":"وفق تعليمات حوكمة الشركات المساهمة المدرجة (مهام لجنة الحوكمة)؛ لا نص في القانون."},{"num":51,"type":"mcq","q":"بموجب أحكام قانون الأوراق المالية والأنظمة والتعليمات والقرارات الصادرة بموجبه لا يجوز للوسيط المالي القيام بتمويل شراء الأوراق المالية لعملائه إلا بعد الحصول على ترخيص:","o":["التمويل على الهامش.","مدير الاستثمار.","الوسيط لحسابه.","الوسيط المالي."],"law":"securities","answer":0,"orig_answer":null,"article":"55","status":"valid","explanation":"المادة (55/أ): لا يجوز للوسيط تمويل شراء الأوراق لعملائه إلا بعد الترخيص بأعمال التمويل على الهامش."},{"num":52,"type":"mcq","q":"عقد التداول حسب قانون هيئة الأوراق المالية هو:","o":["صفقة التداول التي تزيد عن (100000) دينار.","طريقة من طرق التسوية يتم بموجبها تسليم الأوراق المالية مقابل تسديد أثمانها.","أوامر الشراء أو البيع الصادرة عن العميل.","العقد الذي يتم بموجبه شراء أوراق مالية وبيعها."],"law":"securities","answer":3,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): عقد التداول هو العقد الذي يتم بموجبه شراء أوراق مالية وبيعها."},{"num":53,"type":"mcq","q":"إن حق إصدار أوراق النقد والمسكوكات في المملكة من صلاحية:","o":["وزارة المالية.","البنك المركزي.","مجلس الوزراء والبنك المركزي.","مجلس الوزراء."],"law":"banks","answer":1,"orig_answer":null,"article":"","status":"unverified","explanation":"حق إصدار النقد والمسكوكات للبنك المركزي وفق قانون البنك المركزي الأردني (غير مشمول بقانون البنوك)."},{"num":54,"type":"mcq","q":"ترتبط وحدة مكافحة غسل الأموال وتمويل الإرهاب بما يلي:","o":["اللجنة الوطنية لمكافحة غسل الأموال وتمويل الإرهاب.","محافظ البنك المركزي.","مجلس إدارة البنك المركزي.","لا شيء مما ذكر أعلاه صحيح."],"law":"aml","answer":1,"orig_answer":null,"article":"7","status":"valid","explanation":"المادة (7/أ): تنشأ وحدة مكافحة غسل الأموال وتمويل الإرهاب وترتبط بالمحافظ."},{"num":55,"type":"mcq","q":"يجب على كل شخص عند دخوله إلى المملكة التصريح عما يحمله من الأموال المنقولة عبر الحدود إذا كانت قيمتها تتجاوز القيمة التي تحددها اللجنة تحت طائلة أي من العقوبات التالية:","o":["غرامة لا تزيد عن 10% من قيمة الأموال غير المصرح بها وتضاعف الغرامة في حال تكرار المخالفة.","غرامة 500 دينار.","غرامة 1000 دينار أو 10% من قيمة الأموال غير المصرح عنها ايهما أكثر تضاعف الغرامة في حالة التكرار.","لا شيء مما ذكر أعلاه صحيح."],"law":"aml","answer":null,"orig_answer":0,"article":"31","status":"changed","explanation":"المادة (31/د) من القانون النافذ: الغرامة لا تقل عن 10% من قيمة النقد غير المصرح عنه وتضاعف بالتكرار، بينما كان القانون السابق ينص على (لا تزيد على 10%)."},{"num":56,"type":"mcq","q":"أي من العبارات التالية لا يعتبر صحيحاً بموجب قانون التجارة رقم (12) لعام 1966:","o":["إذا اشتغل الموظفون والقضاة الممنوعون من الاتجار قانونا بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي من الإفلاس.","يُعد تاجرا من قام بمعاملة تجارية عرضا إلا أن المعاملة المذكورة لا تكون خاضعة لأحكام قانون التجارة.","لا تعد الدولة ودوائرها ذات شخصية اعتبارية من التجار وإن قامت بمعاملات تجارية.","يعد تاجرا كل من أعلن في الصحف أو النشرات او أية واسطة أخرى عن المحل الذي أسسه وفتحه للاشتغال بالأعمال التجارية."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":null,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966 غير مشمول في القوانين المعتمدة؛ تعد العبارة (ب) خاطئة لأن من قام بمعاملة تجارية عرضاً لا يعد تاجراً لكن معاملته تخضع لقانون التجارة."},{"num":57,"type":"mcq","q":"بموجب قانون التجارة يمكن أن يكون سند السحب باستثناء:","o":["يجوز سحبه لحساب شخص آخر.","يجوز سحبه عليه.","لا يجوز سحبه لحساب شخص آخر.","يجوز سحب سند السحب لأمر الساحب نفسه."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: يجوز سحب السند لأمر الساحب نفسه وعليه ولحساب شخص آخر، فعبارة (لا يجوز سحبه لحساب شخص آخر) هي المستثناة."},{"num":58,"type":"mcq","q":"جميع الأمور التالية صحيحة بخصوص الوكالة التجارية حسب قانون التجارة باستثناء:","o":["الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي.","في المواد التجارية يستحق الوكيل الاجر في جميع الأحوال ما لم يكن هنالك نص مخالف.","الوكالة التجارية إن احتوت على توكيل مطلق تجيز الأعمال غير التجارية وإن لم يرد نص صريح.","تكون الوكالة تجارية عندما تختص بمعاملات تجارية."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: الوكالة التجارية ولو كانت عامة مطلقة لا تجيز الأعمال غير التجارية إلا بنص صريح."},{"num":59,"type":"mcq","q":"أي من العبارات التالية غير صحيحة حسب قانون التجارة فيما يتعلق بالحساب الجاري:","o":["لا يجوز في حال من الأحوال أن يستقر الحساب الجاري على رصيد ايجابي لمصلحته.","يجوز أن يكون الحساب الجاري مكشوفًا لجهة الفريقين ولا يجوز مكشوف أن يكون لجهة واحدة.","وجود الحساب الجاري لا يمنع أحد المتعاقدين من مطالبة الآخر بالعمولة عن عمل قام به بالعمولة.","يتوقف مدى الحساب الجاري على إرادة المتعاقدين منها أن يجعلاه شاملاً لجميع معاملاتها أو لنوع معين منها فقط."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":1,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: يجوز أن يكون الحساب الجاري مكشوفاً لجهة واحدة أو لجهة الفريقين، فالعبارة (ب) غير صحيحة."},{"num":60,"type":"mcq","q":"أي من العبارات التالية تعد صحيحة فيما يتعلق بالرهن التجاري حسب قانون التجارة رقم (12) لسنة 1966:","o":["إذا كان الرهن قائمًا على أشياء او اسناد مثليه معقد الرهن يظل قائمًا وإن بدلت هذه الاشياء أو الاسناد بأشياء أو اسناد من النوع نفسه.","لا ينتج عقد الرهن أثراً بصفته رهناً إذا بقي المرهون في حيازه المدين.","يجوز وضع نص يجيز للدائن أن يمتلك المرهون أو يتصرف به بدون مراجعة المحكمة المختصة.","يجري رهن السند لأمر بتظهير تدرج فيه عبارة (القيمة وضعت تأمينا) أو عبارة أخرى بالمعنى نفسه."],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":3,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: يجري رهن السند لأمر بتظهير تدرج فيه عبارة (القيمة وضعت تأميناً) أو ما يماثلها."},{"num":61,"type":"mcq","q":"حسب قانون الاستثمار رقم (30) لسنة 2014 أيا منها وفيما يتعلق بضريبة المبيعات غير صحيح:","o":["لمزودي البضائع المسجلين بموجب قانون الضريبة العامة على المبيعات في المملكة الحق في طلب رد الضريبة العامة على المبيعات التي سبق دفعها على السلع المباعة إلى المؤسسات المسجلة في المنطقة التنموية.","تخضع للضريبة العامة على المبيعات والرسوم الجمركية السلع المستهلكة داخل المناطق التنموية أو المناطق الحرة ما لم يكن استهلاكها قد تم لغايات ممارسة المؤسسات المسجلة لأنشطتها الاقتصادية.","تخضع للضريبة العامة على المبيعات السلع والخدمات التي يكون منشؤها في المنطقة التنموية والتي يتم بيعها إلى باقي مناطق المملكة.","لا تخضع مبيعات السلع الخاضعة للضريبة الخاصة بما فيها المركبات والتبغ ومصنوعاته والمشروبات الكحولية والمسكرات والجعة عند بيعها للاستهلاك في المنطقة التنموية لضريبة المبيعات التي يتم تقاضيها في المملكة."],"law":"investment","answer":3,"orig_answer":null,"article":"30","status":"valid","explanation":"المادة (30/أ/3) من قانون البيئة الاستثمارية 2022 (الذي حل محل قانون 2014): تخضع مبيعات السلع الخاضعة للضريبة الخاصة عند بيعها للاستهلاك في المنطقة التنموية للضريبة والرسوم الجمركية."},{"num":62,"type":"mcq","q":"من صلاحيات مجلس إدارة جمعية المحاسبين القانونيين ما يلي:","o":["المصادقة على منح إجازة المزاولة.","التنسيب للهيئة العليا بإلغاء إجازة المزاولة.","عقد اجتماعات وتحديد مواعيد امتحان المهنة.","اعتماد معايير المحاسبية ومعايير تدقيق الحسابات."],"law":"accounting","answer":1,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/هـ): من مهام المجلس التنسيب للهيئة العليا بإلغاء إجازة المزاولة (أما اعتماد المعايير فبتنسيب للهيئة العليا)."},{"num":63,"type":"mcq","q":"أي من العبارات التالية غير صحيح حسب قانون تنظيم مهنة المحاسبة القانونية لسنة 2003:","o":["يسري تعليق التسجيل إيقاف العمل بإجازة المزاولة بعد صدور قرار اللجنة التأديبية.","إذا ارتكب المتدرب أي مخالفة لأحكام قانون المهنة والأنظمة والتعليمات الصادرة بمقتضاه أو أخل بواجبات عمله أو قواعد سلوك المهنة وآدابها يحيله المجلس إلى اللجنة التأديبية.","توقع اللجنة التأديبية عقوبة إلغاء إجازة المزاولة وشطب اسم المحاسب القانوني نهائيا من سجل المزاولين.","إذا ارتكب المحاسب القانوني أي مخالفة لأحكام قانون المهنة والأنظمة والتعليمات الصادرة بمقتضاه أو أخل بواجبات عمله أو قواعد سلوك المهنة وآدابها يحيله المجلس إلى اللجنة التأديبية."],"law":"accounting","answer":0,"orig_answer":null,"article":"37","status":"valid","explanation":"المادتان (36 و37): قرارات اللجنة التأديبية خاضعة لمصادقة المجلس (والهيئة العليا للإلغاء)، فلا يسري التعليق بمجرد صدور قرار اللجنة."},{"num":64,"type":"mcq","q":"من مهام ديوان المحاسبة ما يلي باستثناء:","o":["الرقابة على المؤسسات العامة والمجالس القروية.","مراقبة مستودعات الدولة.","تقديم المشورة في المجالات المحاسبية لجميع الأجهزة الرسمية.","مراقبة واردات الدولة ونفقاتها وحساب الأمانات والسلفات والقروض."],"law":"audit","answer":2,"orig_answer":null,"article":"3","status":"valid","explanation":"المادة (3/ب): تقديم المشورة في المجالات المحاسبية للجهات الخاضعة لرقابة الديوان وليس لجميع الأجهزة الرسمية."},{"num":65,"type":"mcq","q":"لمدير مديرية المنافسة ان يكلف أيا من موظفي المديرية المفوضين من الوزير للقيام بما يلي:","o":["يتوجب على الموظفين المكلفين الكشف عن هوياتهم وإطلاع صاحب العلاقة على نسخة من التفويض الخطي.","الاطلاع على المستندات والسجلات والملفات بما فيها ملفات الحاسوب ولا يجوز الاحتفاظ بأي منها أو نسخ عنها.","الدخول خلال ساعات العمل فقط إلى المحلات التجارية والمكاتب والمخازن لإجراء المعاينة والتفتيش.","إجراء التحقيقات اللازمة والاستماع لإفادة أي شخص يشتبه بمخالفته لأحكام قانون المنافسة."],"law":"competition","answer":3,"orig_answer":null,"article":"19","status":"valid","explanation":"المادة (19/أ/3): إجراء التحقيقات اللازمة والاستماع لإفادة أي شخص يشتبه بمخالفته؛ ويجوز الاحتفاظ بالمستندات أو نسخ عنها."},{"num":66,"type":"mcq","q":"أي من المخصصات التالية لا يتم رصده ضمن مخصصات شركات التأمين التي تزاول أعمال التامين باستثناء التأمين على الحياة:","o":["مخصص الادعاءات غير المبلغة تحت التسوية.","مخصص الادعاءات المبلغة تحت التسوية.","مخصص الأقساط غير المكتسبة.","جميع ما ذكر."],"law":"insurance","answer":3,"orig_answer":null,"article":"24","status":"valid","explanation":"المادة (24/ب): أسس احتساب المخصصات الفنية تحددها تعليمات البنك المركزي، وتشمل لأعمال التأمين العامة مخصص الأقساط غير المكتسبة والادعاءات المبلغة وغير المبلغة."},{"num":67,"type":"mcq","q":"أي من التالية يعتبر غير صحيح بموجب قانون مكافحة غسل الأموال وتمويل الارهاب الساري المفعول:","o":["يقصد بالأموال محل الغسل النقد والأدوات المالية القابلة للتداول سواء كانت بالدينار أو بالعملات الاجنبية والأحجار الكريمة والمعادن الثمينة.","يحظر غسل الأموال المتحصلة من أي من الجرائم التي نص عليها القانون والتي وقعت هذه الجرائم داخل المملكة فقط.","حظر تقديم الأموال أو جمعها أو تأمين الحصول عليها سواء بصورة مباشرة أو غير مباشرة وإن كانت من مصادر مشروعة لإرهابي أو منظمة أو جمعية إرهابية.","كل ما ذكر غير صحيح."],"law":"aml","answer":1,"orig_answer":null,"article":"3","status":"valid","explanation":"المادة (3/ج): تشمل المتحصلات الأفعال المرتكبة خارج المملكة إذا كانت جريمة فيها وفي دولة وقوعها، فلا يقتصر الحظر على الجرائم الواقعة داخل المملكة."},{"num":68,"type":"mcq","q":"تسري أحكام قانون الإعسار رقم (21) لسنة 2018 على أي شخص يمارس نشاطا اقتصاديًا وأي نشاط من التالية باستثناء ما يلي:","o":["أصحاب المهن المسجلون والمرخص لهم بالعمل بموجب أحكام التشريعات النافذة.","التجار أصحاب المؤسسات الفردية.","البنوك.","الأشخاص الاعتباريون بما في ذلك الشركات المدنية والشركات التي تملكها الحكومة."],"law":"insolvency","answer":2,"orig_answer":null,"article":"3","status":"valid","explanation":"المادة (3/ب): لا تسري أحكام قانون الإعسار على البنوك وشركات التأمين."},{"num":69,"type":"mcq","q":"إذا وجدت المحكمة أن طلب إشهار الإعسار المقدم من الدائنين أو المراقب موافقا للشروط المنصوص عليها في المادة (10) من القانون فتتولى تبليغه للمدين مع حافظة المستندات المرفقة به خلال مدة:","o":["خلال ثلاثون يوما من تاريخ تقديم طلب الإشهار.","خمسة عشر يوما من تاريخ تقديم طلب الإشهار.","خلال مدة لا تزيد عن شهر من تاريخ تقديم طلب الإشهار.","خمسة أيام من تاريخ تقديم طلب الإشهار."],"law":"insolvency","answer":3,"orig_answer":null,"article":"11","status":"valid","explanation":"المادة (11/أ): تبلغ المحكمة الطلب للمدين مع حافظة المستندات خلال خمسة أيام من تاريخ تقديمه."},{"num":70,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة فيما يتعلق في آثار إشهار الإعسار:","o":["إذا كان طلب إشهار الإعسار مقدما من المدين ينقل صلاحية إدارة أعماله تحت إشراف وكيل الإعسار.","لدائني المدين ولوكيل الإعسار في أي وقت بعد إشهار الإعسار ولأسباب مبرر أن يطلبوا من المحكمة أن تقر وقف صلاحيات المدين في إدارة ذمة الإعسار والتصرف فيها.","إذا صدر قرار بتجريد المدين من صلاحية إدارة ذمة الإعسار والتصرف فيها فيحل وكيل الإعسار محل المدين سواء بصفته دعيا أو مدعى عليه في أي إجراءات قضائية مقامة قبل إشهار الإعسار.","إذا كان طلب إشهار الإعسار مقدم من الدائنين أو المراقب فتعلق صلاحيات المدين في إدارة أموال ذمة الإعسار والتصرف فيها."],"law":"insolvency","answer":0,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/أ): إذا كان الطلب مقدماً من المدين فإنه يحتفظ بصلاحية إدارة أعماله المعتادة تحت إشراف وكيل الإعسار ولا تنقل."},{"num":71,"type":"essay","q":"السؤال الأول (أربع علامات): تاجر مواد تموينية بدأ أعماله في شهر 2020/2 وكانت مبيعاته الشهرية على النحو التالي:\nالشهر | مبيعات 16% | مبيعات 4% | مبيعات صفر% | مبيعات معفاة\n2020/2 | 3000 | 500 | 1000 | 2500\n2020/3 | 4000 | 1000 | 1500 | 3500\n2020/4 | 4500 | 1500 | 2750 | 3250\n2020/5 | 3800 | 2000 | 2000 | 4000\n2020/6 | 5000 | 2500 | 4250 | 3000\n2020/8 | 6000 | 3000 | 2500 | 7000\n2020/9 | 6500 | 3500 | 3500 | 5000\n2020/10 | 7000 | 4000 | 2750 | 4000\n2020/11 | 10000 | 4500 | 7000 | 9000\n2020/12 | 11000 | 4500 | 10000 | 8000\n2021/1 | 11500 | 5000 | 8000 | 7000\nالمطلوب ماذا يترتب على التاجر إذا قام بالتسجيل في أي من التواريخ التالية:\nأ- التقدم بطلب للتسجيل لدى الدائرة في شبكة المكلفين بالضريبة العامة على المبيعات في 2020/9/2.\nب- التقدم بطلب للتسجيل لدى الدائرة في شبكة المكلفين بالضريبة العامة على المبيعات في 2020/11/2.\nج- التقدم بطلب للتسجيل لدى الدائرة في شبكة المكلفين بالضريبة العامة على المبيعات في 2020/12/30.\nد- التقدم بطلب للتسجيل لدى الدائرة في شبكة المكلفين بالضريبة العامة على المبيعات في 2020/2/2.","law":"sales","article":"13","status":"valid","model_answer":"- المبيعات الخاضعة (16% و4% وصفر%) دون المعفاة؛ مجموعها التراكمي: 64,300 حتى 2020/9 ثم 78,050 في 2020/10 فيتجاوز حد التسجيل للسلع (75,000 دينار وفق نظام حد التسجيل) خلال شهر 10/2020 (المادتان 13 و14).\n- أ) 2020/9/2: قبل بلوغ الحد، فهو تسجيل اختياري جائز وتسري عليه أحكام المسجل (المادة 14/ب) دون أي غرامة.\n- ب) 2020/11/2: ضمن المهلة القانونية للتسجيل بعد بلوغ الحد، فلا غرامة ويلتزم بالضريبة من تاريخ التسجيل.\n- ج) 2020/12/30: تأخر عن الموعد مدة لا تزيد على 60 يوماً: غرامة 100-500 دينار (المادة 28/أ) مع دفع الضريبة المستحقة على مبيعاته من تاريخ وجوب التسجيل (ولو زاد التأخير على 60 يوماً لعُدّ تهرباً - المادة 30/أ).\n- د) 2020/2/2: تسجيل عند بدء العمل؛ جائز اختيارياً أو إلزامياً إذا قدّر أن مبيعاته خلال 12 شهراً ستتجاوز حد التسجيل (المادة 13/أ/1)، ولا غرامة."},{"num":72,"type":"essay","q":"السؤال الثاني (علامتان): أبرمت شركة الاتحاد عقد تأمين على المباني التي تملكها مع شركة ما وراء البحار للتأمين ولمدة سنة كاملة يبدأ العقد بتاريخ 2020/9/29 وينتهي بتاريخ 2021/9/28، حيث بلغت قيمة عقد التأمين 50.000 دينار، وقامت شركة التأمين بإعادة تأمين 75% من قيمة العقد لدى شركة زيورخ السويسرية.\nالمطلوب احتساب قيمة مخصص الأقساط غير المكتسبة الواجب تنزيله في 2020/12/31.","law":"insurance","article":"24","status":"valid","model_answer":"- الأيام المنقضية حتى 2020/12/31 = 94 يوماً، والمتبقية = 271 يوماً من 365.\n- القسط المحتفظ به = 50,000 × 25% = 12,500 دينار.\n- مخصص الأقساط غير المكتسبة (الصافي) = 12,500 × 271/365 ≈ 9,281 دينار (وإجمالياً قبل حصة معيد التأمين: 50,000 × 271/365 ≈ 37,123 دينار، وحصة معيد التأمين ≈ 27,842).\n- أسس احتساب المخصصات الفنية تحددها تعليمات البنك المركزي بموجب المادة (24/ب) من قانون تنظيم أعمال التأمين 2021."},{"num":73,"type":"essay","q":"السؤال الثالث (ثلاث علامات): تظهر البيانات التالية قائمة الدخل لشركة الأردن الصناعية عن السنة المنتهية 2020/12/31:\nالمبيعات 200000 دينار\nكلفة المبيعات 140000 دينار\nمجمل الربح 60000 دينار\nمصاريف إدارية وعمومية 40000 دينار\nالدخل الصافي من النشاط 20000 دينار\nأرباح / متاجرة بالأسهم داخلي 8000 دينار\nحصة الشركة من توزيعات الأرباح (من شركة الفوسفات) علماً بأن نسبة التملك في شركة الفوسفات تزيد عن 10% 10000 دينار\nأرباح تقييم أسهم 30000 دينار\nصافي الدخل الشامل 68000 دينار\nالمطلوب: احسب الضريبة المستحقة على الشركة.","law":"income","article":"11","status":"valid","model_answer":"- أرباح المتاجرة بالأسهم داخل المملكة أرباح رأسمالية معفاة (المادة 4/ب/5) = 8,000.\n- توزيعات أرباح الشركات المساهمة المقيمة معفاة للشركة المستلمة (المادة 4/ب/8) = 10,000.\n- أرباح تقييم الأسهم غير متحققة فلا تخضع = 30,000.\n- الدخل الخاضع = 20,000 دينار (الدخل من النشاط الصناعي).\n- نسبة 2020 للنشاط الصناعي: 20% مخفضة بنسبة 20% (المادة 11/ج/1) = 16% → 3,200 دينار.\n- المساهمة الوطنية 1% (المادة 11/و/1/هـ) = 200 دينار.\n- المجموع = 3,400 دينار."},{"num":74,"type":"essay","q":"السؤال الرابع (علامة ونصف): بينت المادة (259) من قانون الشركات الحالات الأربع التي يمكن للشركة المساهمة العامة أن تصفى بموجبها تصفية اختيارية.\nالمطلوب: اذكر ثلاثة منها.","law":"companies","article":"259","status":"valid","model_answer":"المادة (259):\n- انتهاء المدة المعينة للشركة ما لم تقرر الهيئة العامة تمديدها.\n- إتمام الغاية التي تأسست من أجلها أو استحالة إتمامها أو انتفاؤها.\n- صدور قرار من الهيئة العامة بفسخها وتصفيتها.\n- الحالات الأخرى التي ينص عليها نظام الشركة."},{"num":75,"type":"essay","q":"السؤال الخامس (علامتان): اذكر أربع من واجبات مدقق الحسابات وفقا لما ذكر بأحكام المادة (193) من قانون الشركات:","law":"companies","article":"193","status":"valid","model_answer":"المادة (193):\n- مراقبة أعمال الشركة.\n- تدقيق حساباتها وفق قواعد التدقيق المعتمدة ومتطلبات المهنة.\n- فحص الأنظمة المالية والإدارية وأنظمة الرقابة الداخلية والتأكد من ملاءمتها.\n- التحقق من موجودات الشركة وملكيتها لها وقانونية التزاماتها.\n- الاطلاع على قرارات المجلس والهيئة العامة وأي بيانات لازمة.\n- تقديم تقرير خطي للهيئة العامة وتلاوته أمامها."},{"num":76,"type":"essay","q":"السؤال السادس (علامتان): بينت المادة (191) من قانون الشركات، آلية توزيع الأرباح على المساهمين في الشركات المساهمة العامة من حيث: نشوء حق المساهم في الأرباح والمهام المنوطة بمجلس الإدارة وآلية إعلام المساهمين بذلك، والفترة الزمنية للتوزيع وبيان الالتزامات المترتبة على الشركة في حالة عدم الالتزام بالفترة الزمنية بالتوزيع، أذكر هذه الآلية:","law":"companies","article":"191","status":"valid","model_answer":"المادة (191):\n- ينشأ حق المساهم في الأرباح بصدور قرار الهيئة العامة بتوزيعها، ويكون الحق لمالك السهم بتاريخ اجتماع الهيئة.\n- يعلن المجلس عن القرار في صحيفتين يوميتين محليتين على الأقل ووسائل الإعلام خلال أسبوع من القرار ويبلغ المراقب والسوق المالي.\n- تدفع الأرباح خلال 45 يوماً من تاريخ اجتماع الهيئة العامة.\n- عند التأخير تدفع الشركة فائدة بمعدل سعر الفائدة السائد على الودائع لأجل، على ألا يتجاوز التأخير ستة أشهر من تاريخ الاستحقاق."},{"num":77,"type":"essay","q":"السؤال السابع (ثلاث علامات): ماذا تشمل العناية الطبية التي تقدمها المؤسسة العامة للضمان الاجتماعي للمصاب؟","law":"social","article":"26","status":"valid","model_answer":"المادة (26/أ):\n- تكاليف المعالجة الطبية والإقامة في المستشفى.\n- نفقات انتقال المصاب من مكان العمل أو سكنه إلى مكان العلاج والعودة منه.\n- توفير الخدمات والتجهيزات التأهيلية بما فيها الأطراف الصناعية التي يقررها المرجع الطبي.\n- (وتتحمل المؤسسة الأدوية والمستلزمات اللازمة لاستمرار الحياة عند ثبوت العجز الدائم - المادة 28/ب)."},{"num":78,"type":"essay","q":"السؤال الثامن (علامتان): ما هي التقارير الدورية التي على كل مصدر أن يقدمها لهيئة الأوراق المالية ووفقا للتعليمات التي يصدرها مجلس مفوضي هيئة الأوراق المالية:","law":"securities","article":"43","status":"valid","model_answer":"المادة (43/أ):\n- تقرير سنوي يتضمن البيانات المالية مدققة من محاسب قانوني خلال تسعين يوماً من انتهاء السنة المالية.\n- تقرير ربع سنوي مراجع من محاسب قانوني خلال ثلاثين يوماً من انتهاء الربع المعني.\n- تقرير عن نتائج الأعمال الأولية بعد المراجعة الأولية من المدقق خلال خمسة وأربعين يوماً من انتهاء السنة المالية.\n- وعلى المصدر نشر هذه التقارير وفق تعليمات مجلس المفوضين."},{"num":79,"type":"essay","q":"السؤال التاسع (علامة ونصف): اذكر الأعمال المصرفية الإسلامية التي يجوز للبنوك الإسلامية ممارستها وفقا لقانون البنوك؟","law":"banks","article":"52","status":"valid","model_answer":"المادة (52):\n- قبول الودائع النقدية في حسابات ائتمان أو استثمار مشترك أو استثمار مخصص.\n- إصدار صكوك التمويل الإسلامي أو إنشاء محافظ أو صناديق استثمارية.\n- أعمال التمويل والاستثمار على غير أساس الفائدة: المضاربة والمشاركة المتناقصة والمرابحة للآمر بالشراء وغيرها مما توافق عليه هيئة الرقابة الشرعية، وتوظيف الأموال بنظام المضاربة المشتركة، واستثمار الأموال في المشاريع المختلفة."},{"num":80,"type":"essay","q":"السؤال العاشر (علامة ونصف): اذكر ثلاثا من الوسائل التي تقوم هيئة النزاهة ومكافحة الفساد بحماية المبلغين أو الشهود أو المخبرين والخبراء في قضايا الفساد وأقاربهم من أي اعتداء أو انتقام أو ترهيب محتمل.","law":"integrity","article":"24","status":"valid","model_answer":"المادة (24/أ):\n- توفير الحماية لهم في أماكن إقامتهم.\n- عدم الإفصاح عن المعلومات المتعلقة بهويتهم وأماكن وجودهم.\n- الإدلاء بأقوالهم وشهاداتهم باستخدام تقنيات الاتصال الحديثة بما يكفل سلامتهم.\n- حمايتهم في أماكن عملهم وغيرها من الوسائل الواردة في المادة ونظام حماية المبلغين."},{"num":81,"type":"essay","q":"السؤال الحادي عشر (علامة ونصف): عدد الحقوق والمزايا المترتبة للمستأجر حسب قانون التأجير التمويلي:","law":"leasing","article":"10","status":"valid","model_answer":"المادة (10/أ):\n- اختيار المورد والمأجور.\n- حيازة المأجور والانتفاع به وفق عقد التأجير.\n- الرجوع على المورد مباشرة فيما يخص جودة المأجور ونوعيته وكميته وتسليمه وشروط عقد التوريد، دون إجحاف بحق المؤجر."},{"num":82,"type":"essay","q":"السؤال الثاني عشر (علامة ونصف): إذا لم يشتمل سند السحب على أحد البيانات الرئيسية فإنه لا يعتبر سند سحب، أذكر ثلاثاً من هذه الحالات:","law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","model_answer":"وفق قانون التجارة 1966 (البيانات الإلزامية لسند السحب):\n- عبارة سند السحب مكتوبة في متن السند بلغة كتابته.\n- أمر غير معلق على شرط بأداء قدر معين من النقود.\n- اسم من يلزمه الأداء (المسحوب عليه).\n- تاريخ الاستحقاق ومكان الأداء.\n- اسم من يجب الأداء له أو لأمره.\n- تاريخ إنشاء السند ومكانه وتوقيع الساحب."},{"num":83,"type":"essay","q":"السؤال الثالث عشر (علامة ونصف): اذكر مراحل إجراءات الإعسار حسب قانون الإعسار رقم (21) لسنة 2018:","law":"insolvency","article":"5","status":"valid","model_answer":"المادة (5):\n- المرحلة التمهيدية: تبدأ من قرار إشهار الإعسار لحصر ذمة الإعسار والدائنين وتحليل أسباب الإعسار.\n- مرحلة إعادة التنظيم: التوصل لاتفاق بين المدين ودائنيه على خطة إعادة التنظيم.\n- مرحلة التصفية: بيع أموال ذمة الإعسار وتوزيع حصيلتها على الدائنين."},{"num":84,"type":"essay","q":"السؤال الرابع عشر (ثلاث علامات): عدد الشروط الواجبة فيمن يتقدم بطلب الحصول على إجازة المزاولة لمهنة المحاسبة القانونية:","law":"accounting","article":"22","status":"valid","model_answer":"المادة (22):\n- أن يكون أردني الجنسية.\n- أن يكون متمتعاً بالأهلية المدنية الكاملة.\n- غير محكوم عليه بجناية أو جنحة مخلة بالأخلاق أو الأمانة.\n- حاصلاً على أحد المؤهلات: شهادة جامعية أو دبلوم كلية مجتمع في المحاسبة أو شهادة ذات علاقة بالحد الأدنى من مواد المحاسبة أو شهادة مهنية معترف بها مع شهادة جامعية.\n- استكمال متطلبات التدريب.\n- اجتياز امتحان لجنة الترخيص بما فيه امتحان التشريعات."}]},{"id":"2020-01","year":2020,"month":1,"label":"دورة كانون الثاني 2020","session":"كانون الثاني","src":"96727428.json","questions":[{"num":1,"type":"mcq","q":"يعفى من الضريبة:","o":["الفوائد المدفوعة أو المستحقة للأشخاص ذوي العلاقة على أن لا يتجاوز المبلغ الجائز تنزيله بنسبة ثلاثة الى واحد لإجمالي الدين الى رأس المال المسجل أو حقوق الملكية أيهما أكبر","الفوائد المدفوعة أو المستحقة لغير الأشخاص ذوي العلاقة","الفوائد المدفوعة أو المستحقة للأشخاص ذوي العلاقة على أن لا يتجاوز المبلغ الجائز تنزيله بنسبة ثلاثة الى واحد لإجمالي الدين الى حقوق الملكية","الفوائد المدفوعة أو المستحقة للأشخاص ذوي العلاقة على أن لا يتجاوز المبلغ الجائز تنزيله بنسبة ثلاثة الى واحد لإجمالي الدين الى رأس المال المسجل"],"law":"income","answer":1,"orig_answer":null,"article":"6","status":"valid","explanation":"المادة (6/ب/1): تُنزّل الفوائد المدفوعة لغير ذوي العلاقة كاملة، أما لذوي العلاقة فبنسبة 3:1 لإجمالي الدين إلى رأس المال المدفوع أو متوسط حقوق الملكية أيهما أكبر (لا المسجل)؛ والمسألة تنزيل لا إعفاء."},{"num":2,"type":"mcq","q":"ضريبة صناعة الأدوية عام 2020 في المنطقة التنموية:","o":["5% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 10% إذا كانت القيمة المضافة أقل من 30%","10% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 14% إذا كانت القيمة المضافة أقل من 30%","5% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 14% إذا كانت القيمة المضافة أقل من 30%","10% إذا كانت القيمة المضافة فيها لا تقل عن 30% أو 15% إذا كانت القيمة المضافة أقل من 30%"],"law":"income","answer":0,"orig_answer":null,"article":"11","status":"valid","explanation":"المادة (11/ط/1،2): 5% لأنشطة الصناعات التحويلية في المناطق التنموية إذا لم تقل القيمة المحلية المضافة عن 30%، و10% لباقي الأنشطة."},{"num":3,"type":"mcq","q":"يجوز للمكلف تعديل إقراره الضريبي المقدم للدائرة باستثناء الإقرار الذي صدرت بشأنه مذكرة تدقيق أو قرار بالقبول وفقاً لأحكام المادة (28) وذلك خلال:","o":["بزيادة الدخل أو الضريبة أو تخفيض أي منهما خلال سنتين من تاريخ تقديم الإقرار","بزيادة الدخل أو الضريبة أو تخفيض أي منهما خلال أربع سنوات من تاريخ تقديم الإقرار","بزيادة الدخل أو الضريبة أو تخفيض أي منهما خلال أربع سنوات من تاريخ 30 نيسان من السنة التالية","بزيادة الدخل أو الضريبة أو تخفيض أي منهما خلال سنتين من تاريخ 30 نيسان من السنة التالية"],"law":"income","answer":0,"orig_answer":null,"article":"27","status":"valid","explanation":"المادة (27): للمكلف تعديل إقراره خلال سنتين من تاريخ تقديمه بزيادة الدخل أو الضريبة أو تخفيض أي منهما."},{"num":4,"type":"mcq","q":"أي من العبارات التالية خطأ: (الشخص الاعتباري المقيم الذي):","o":["مركز إدارته الفعلي في المملكة","تملك الحكومة أو أي من المؤسسات العامة نسبة لا تقل عن 50% من رأسماله","تم تأسيسه أو تسجيله وفق أحكام التشريعات الأردنية وكان له في المملكة مركز يمارس الإدارة والرقابة على عمله","تم تأسيسه أو تسجيله وفق أحكام التشريعات الأردنية وكان له في المملكة فرع يمارس الإدارة والرقابة على عمله"],"law":"income","answer":1,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): الشخص الاعتباري المقيم هو الذي تملك الحكومة أو المؤسسات العامة نسبة تزيد على 50% من رأسماله، لا \"لا تقل عن 50%\"."},{"num":5,"type":"mcq","q":"أي العبارات التالية خطأ: (تعدين المواد الأساسية هو استكشاف واستخراج واستغلال خامات):","o":["الإسمنت ومشتقاته","صناعة الأسمدة","الفوسفات","البوتاس"],"law":"income","answer":0,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): تعدين المواد الأساسية يشمل الفوسفات والبوتاس واليورانيوم وتستثنى صناعة الأسمدة والاسمنت، فالعبارتان (أ) و(ب) كلتاهما خطأ والسؤال معيب."},{"num":6,"type":"mcq","q":"أي من العبارات التالية صحيحة: (الشركة المالية):","o":["الشركة المرخصة لممارسة الأعمال المصرفية في المملكة بما في ذلك شركة الصرافة وشركة التمويل وفقاً لقانون البنوك","الشركة المالية المعرّفة وفقاً لقانون البنوك بما في ذلك شركة الصرافة وشركة التمويل","الشركة المرخصة لممارسة الأعمال المصرفية في المملكة باستثناء شركة الصرافة وشركة التمويل وفقاً لقانون البنوك","الشركة المالية المعرّفة وفقاً لقانون البنك المركزي بما في ذلك شركة الصرافة وشركة التمويل"],"law":"income","answer":1,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): الشركة المالية هي الشركة المالية المعرفة وفقاً لقانون البنوك بما في ذلك شركة الصرافة وشركة التمويل."},{"num":7,"type":"mcq","q":"يعفى من الضريبة:","o":["أول 50,000 دينار من الدخل الخاضع للشخص الاعتباري المتأتي داخل المملكة من النشاط الزراعي","يعفى من الضريبة انتاج المحاصيل الزراعية من الحبوب والخضراوات للشخص الطبيعي","أول 50,000 دينار من الدخل الصافي للشخص الاعتباري داخل المملكة من النشاط الزراعي","أول 50,000 دينار من الدخل الإجمالي للشخص الاعتباري داخل المملكة من النشاط الزراعي"],"law":"income","answer":2,"orig_answer":null,"article":"5","status":"valid","explanation":"المادة (5/ب): يعفى أول 50,000 دينار من الدخل الصافي للشخص الاعتباري المتأتي داخل المملكة من النشاط الزراعي."},{"num":8,"type":"mcq","q":"يجوز للمدير إعادة النظر بالإقرار الضريبي المقبول قانوناً في حال وجود خطأ في تطبيق القانون واتخاذ القرار المناسب خلال:","o":["خلال سنتين من تاريخ تقديم الإقرار وفقاً لأحكام هذا القانون","خلال اربع سنوات من تاريخ تقديم الإقرار وفقاً لأحكام هذا القانون","خلال سنتين من تاريخ تقديم الإقرار أو الإقرار المعدل وفقاً لأحكام هذا القانون","أربع سنوات من تاريخ تقديم الإقرار أو الإقرار المعدل وفقاً لأحكام هذا القانون"],"law":"income","answer":2,"orig_answer":null,"article":"28","status":"valid","explanation":"المادة (28/أ/3): يعيد المدير النظر بالإقرار المقبول قانوناً خلال سنتين من تاريخ تقديم الإقرار أو الإقرار المعدل عند وجود خطأ في تطبيق القانون."},{"num":9,"type":"mcq","q":"تفرض غرامة على المكلف الذي يتأخر في تقديم الإقرار الضريبي:","o":["100 دينار على الشخص الطبيعي، 300 دينار على الشركات ذات المسؤولية المحدودة، 1,000 دينار على الشركات المساهمة العامة والمساهمة الخاصة","100 دينار على الشخص الطبيعي، 500 دينار على الشركات ذات المسؤولية المحدودة والمساهمة الخاصة، 1,000 دينار على الشركات المساهمة العامة","100 دينار على الشخص الطبيعي، 200 دينار على شركات التضامن وذات المسؤولية المحدودة، 1,000 دينار على المساهمة العامة والمساهمة الخاصة","100 دينار على الشخص الطبيعي، 200 دينار على شركات التضامن، 500 دينار على الشركات ذات المسؤولية المحدودة والمساهمة الخاصة"],"law":"income","answer":0,"orig_answer":null,"article":"63","status":"valid","explanation":"المادة (63): غرامة بحد أقصى 100 دينار للشخص الطبيعي و300 للشخص الاعتباري و1,000 للشركات المساهمة العامة والخاصة."},{"num":10,"type":"mcq","q":"أي من العبارات التالية ليس صحيح: (يجوز للمكلف المثول أمام محكمة الضريبة وتوقيع اللوائح المقدمة اليها):","o":["اذا كان قاضياً عاملاً وذلك وفقاً لقانون الضريبة العامة على المبيعات","اذا كان من الأشخاص المعفيين من التدريب بموجب قانون نقابة المحامين","اذا كان محامياً غير مزاول وفقاً لقانون نقابة المحامين.","ليس كل ما ذكر صحيحاً"],"law":"sales","answer":3,"orig_answer":null,"article":"60","status":"valid","explanation":"المادة (60): يجوز المثول إذا كان قاضياً عاملاً أو سابقاً أو محامياً مزاولاً أو غير مزاول أو من المعفيين من التدريب، فالعبارات (أ-ج) صحيحة و(د) هي غير الصحيحة."},{"num":11,"type":"mcq","q":"احدى هذه العبارات صحيحة: (تطبق محكمة البداية الضريبية وفقاً لقانون الضريبة العامة على المبيعات):","o":["أصول المحاكمات الجزائية بما لا يتعارض مع أصول المحاكمات المدنية","أصول المحاكمات المدنية بما لا يتعارض مع قانون الضريبة العامة على المبيعات","قانون الضريبة العامة على المبيعات بما لا يتعارض مع أصول المحاكمات المدنية","أصول المحاكمات الضريبية"],"law":"sales","answer":1,"orig_answer":null,"article":"59","status":"valid","explanation":"المادة (59): تطبق المحكمة أصول المحاكمات الجزائية والمدنية بالقدر الذي لا يتعارض مع أحكام قانون الضريبة العامة على المبيعات."},{"num":12,"type":"mcq","q":"أي من العبارات التالية صحيحة: (كل من امتنع عن تقديم المعلومات الضرورية لتنفيذ أحكام قانون الضريبة العامة على المبيعات يعاقب):","o":["بغرامة لا تقل عن 100 دينار ولا تتجاوز 500 دينار وبغرامة لا تقل عن مثلي مقدار الضريبة ولا تزيد عن ثلاث أمثال الضريبة","بغرامة لا تقل عن 200 دينار ولا تزيد عن 1,000 دينار وغرامة لا تقل عن مثلي مقدار الضريبة ولا تزيد عن ثلاث أمثال الضريبة","بغرامة لا تقل عن 200 دينار ولا تزيد عن 1,000 دينار","بغرامة لا تقل عن 100 دينار ولا تتجاوز 500 دينار"],"law":"sales","answer":1,"orig_answer":null,"article":"65","status":"valid","explanation":"المادة (65/أ) تحيل إلى عقوبة المادة (31): تعويض مدني لا يقل عن مثلي الضريبة ولا يزيد على ثلاثة أمثالها وغرامة 200-1,000 دينار."},{"num":13,"type":"mcq","q":"أي العبارات التالية صحيحة وفقاً لقانون الضريبة العامة على المبيعات:","o":["للوزير بناء على تنسيب المدير عدم قبول الدائرة للحسابات التي يدققها المحاسب القانوني اذا ارتكب ما من شأنه التحايل على هذا القانون.","للمدير بناء على تنسيب الادعاء العام أو المحكمة عدم قبول الدائرة للحسابات التي يدققها المحاسب القانوني اذا ارتكب ما من شأنه التحايل على هذا القانون.","للمدير بناء على توصية لجنة عدم قبول الدائرة للحسابات التي يدققها المحاسب القانوني اذا ارتكب ما من شأنه التحايل على هذا القانون.","جميع ما ذكر خطأ"],"law":"sales","answer":0,"orig_answer":null,"article":"69","status":"valid","explanation":"المادة (69/أ): للوزير بتنسيب من المدير بناء على توصية لجنة أن يقرر عدم قبول الحسابات التي يدققها المحاسب القانوني إذا ارتكب ما من شأنه التحايل على القانون."},{"num":14,"type":"mcq","q":"إذا دفع المكلف ضريبة مبيعات تزيد عن المبلغ المستحق دفعه فعلى الدائرة رد هذا المبلغ خلال مدة:","o":["بعد مضي ست شهور على الضريبة المستحقة الرد وتضمين الإقرارات اللاحقة المطالبة برد هذه المبالغ","خلال مدة لا تزيد على ثلاثة أشهر من تاريخ تسلم الدائرة طلباً خطياً بذلك","بعد مضي ست شهور على تقديم الإقرارات وتقديم المكلف طلباً خطياً بذلك","بعد تدقيق الإقرارات وصدور الإشعارات"],"law":"sales","answer":1,"orig_answer":null,"article":"53","status":"valid","explanation":"المادة (53/أ/1): تُحوّل الزيادة لتسديد أي مبالغ مستحقة ثم يرد الباقي خلال مدة لا تزيد على ثلاثة أشهر من تسلم طلب خطي."},{"num":15,"type":"mcq","q":"عرّف قانون الضريبة الدخل المعفى على النحو التالي:","o":["الدخل الذي لا يدخل ضمن الدخل الخاضع للمكلف بموجب أحكام هذا القانون","الدخل المعفى من الضريبة وفقاً لقانون ضريبة الدخل والأنظمة والتعليمات الصادرة بموجبه","الدخل الذي لا يدخل ضمن الدخل الصافي للمكلف بموجب أحكام هذا القانون","الدخل الذي لا يدخل ضمن الدخل الإجمالي للمكلف بموجب أحكام هذا القانون"],"law":"income","answer":3,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): الدخل المعفى هو الدخل الذي لا يدخل ضمن الدخل الإجمالي للمكلف بموجب أحكام القانون."},{"num":16,"type":"mcq","q":"يجوز تصحيح الأخطاء الحسابية التي تقع في القرارات والإشعارات وفقاً لقانون ضريبة المبيعات من قبل:","o":["من قبل المدقق حسب مقتضى الحال","من قبل مدير المديرية حسب مقتضى الحال","من قبل لجنة إجازة القرار حسب مقتضى الحال","من قبل المدير العام او الموظف المناب حسب مقتضى الحال"],"law":"sales","answer":3,"orig_answer":null,"article":"71","status":"valid","explanation":"المادة (71): للمدير أو الموظف المفوض من قبله أو المدقق حسب مقتضى الحال تصحيح الأخطاء الكتابية والحسابية (و\"المدقق\" وحده صحيح جزئياً أيضاً)."},{"num":17,"type":"mcq","q":"في حال قيام مكلف بخصم ضريبة المبيعات أو ردها بصورة مخالفة لأحكام هذا القانون وكانت قيمة الزيادة في ذلك 500 دينار يعاقب:","o":["غرامة لا تقل عن 100 دينار ولا تتجاوز 500 دينار","بتعويض مدني مثلي مقدار الضريبة وبغرامة جزائية لا تقل عن 200 دينار ولا تتجاوز 500 دينار وفي حال التكرار تضاعف الغرامة الجزائية","بتعويض مدني مثلي مقدار الضريبة وبغرامة جزائية لا تقل عن 200 دينار ولا تتجاوز 1,000 دينار وفي حال التكرار تضاعف الغرامة الجزائية","بتعويض مدني مثلي مقدار الضريبة وبغرامة جزائية لا تقل عن 100 دينار ولا تتجاوز 500 دينار وفي حال التكرار تضاعف الغرامة الجزائية"],"law":"sales","answer":0,"orig_answer":null,"article":"28","status":"valid","explanation":"المادة (28/ط): الزيادة في الخصم أو الرد التي لا تتجاوز 500 دينار مخالفة غرامتها 100-500 دينار؛ وما زاد عن 500 تهرب وفق المادتين (30/ز) و(31)."},{"num":18,"type":"mcq","q":"عرّف قانون ضريبة الدخل الضريبة المستحقة على النحو التالي:","o":["مقدار الضريبة المستحقة على الدخل الخاضع بعد تنزيل الخسائر المدورة","مقدار الضريبة المستحقة على الدخل الخاضع بعد تنزيل الخسائر المدورة والإعفاءات","مقدار الضريبة المستحقة وفق أحكام قانون ضريبة الدخل","مقدار الضريبة المستحقة بعد إجراء التقاص وفق ما تقتضيه أحكام قانون الضريبة"],"law":"income","answer":2,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2): الضريبة المستحقة هي مقدار الضريبة المستحقة وفق أحكام هذا القانون؛ والخيار (د) هو تعريف رصيد الضريبة المستحقة."},{"num":19,"type":"mcq","q":"موظف كانت مكافأة نهاية الخدمة المستحقة له عن فترة عمله من 1998/1/1 لغاية 2019/1/31 مبلغ 180,000 دينار وبلغ رواتبه خلال عام 2019 بقيمة 15,000 دينار وهو أعزب وغير معيل فإن الضريبة المستحقة عليه على النحو التالي:","o":["32,500 دينار","13,525 دينار","23,125 دينار","لا شيء مما ذكر"],"law":"income","answer":3,"orig_answer":null,"article":"4","status":"valid","explanation":"المادة (4/أ/13): الخدمة قبل 2010 معفاة 100%، و2010-2014 تُعفى 50%، وبعد 2015 يُعفى أول 15,000، والزائد يخضع لـ9%. ضريبة المكافأة نحو 3,709 دينار + 250 على الراتب، وهذا لا يطابق أي خيار."},{"num":20,"type":"mcq","q":"ما هي قيمة الإعفاءات المستحقة لشخص متزوج و زوجته لا تعمل ولديه 4 أولاد قسط أحدهم في المدرسة 3,000 دينار و استحق عليه فوائد قرض إسكان بقيمة 2,000 دينار وذلك خلال عام 2020:","o":["21,000 دينار","25,000 دينار","25,000 دينار","23,000 دينار"],"law":"income","answer":3,"orig_answer":null,"article":"9","status":"valid","explanation":"المادة (9/أ) لسنة 2020: 9,000 إعفاء شخصي + 9,000 للمعالين + 1,000 للمكلف + 1,000 للزوجة + 3,000 للأولاد (حد أقصى) = 23,000 دينار."},{"num":21,"type":"mcq","q":"يلتزم المدقق بإصدار قرار تقدير ضريبة الدخل خلال :","o":["سنتين من تاريخ تقديم الإقرار الضريبي للمكلف","خلال أربع سنوات من تاريخ تقديم الإقرار الضريبي للمكلف","خلال سنتين من تاريخ تقديم الإقرار الضريبي أو تاريخ تقديم الإقرار الضريبي المعدل للمكلف","جميع ما ذكر خطأ"],"law":"income","answer":3,"orig_answer":null,"article":"29","status":"valid","explanation":"المادة (29/أ): يصدر المدقق قرار التدقيق خلال سنتين من تاريخ إصدار مذكرة التدقيق، لا من تاريخ تقديم الإقرار."},{"num":22,"type":"mcq","q":"يلتزم الورثة أو من يمثلهم بتقديم إقرار ضريبي عن المتوفى خلال :","o":["90 يوم من تاريخ الوفاة","قبل 4/30 من السنة التالية لوفاته","60 يوم من تاريخ الوفاة","30 يوم من تاريخ الوفاة"],"law":"income","answer":0,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/ب): يقدم الورثة الإقرار عن المتوفى خلال تسعين يوماً من تاريخ الوفاة."},{"num":23,"type":"mcq","q":"أعلنت شركة في بياناتها المالية لسنة 2018 دخل إجمالي بلغ 1,200,000 دينار ودخل خاضع 750,000 دينار كما أعلنت ضريبة دخل في الإقرار الضريبي لسنة 2018 150,000 دينار وقامت الشركة بتوريد الدفعة النصف سنوية عن الفترة من 2019/1/1 لغاية 2019/6/30 علماً بأن الشركة لديها أيرادات فوائد عن وديعة لدى البنك تم اقتطاع ضريبة عنها خلال نفس الفترة 2,000 دينار كما قامت بالاستيراد ودفعت ضريبة 2% على البيانات الجمركية 1,000 دينار علماً أن الشركة تجارية وعليه فإن الضرائب الواجب دفعها عن أول 6 شهور من سنة 2019 هي:","o":["59,000","66,500","57,000","60,000"],"law":"income","answer":0,"orig_answer":null,"article":"19","status":"valid","explanation":"المادة (19/ب،ج،د): الدفعة المقدمة 40% من ضريبة إقرار السنة السابقة (150,000×40%=60,000) ناقصاً 2% المدفوعة على المستوردات (1,000) = 59,000؛ ولا يخصم الاقتطاع على الفوائد من الدفعة."},{"num":24,"type":"mcq","q":"لا يجوز للمدقق وفقاً لقانون ضريبة الدخل اصدار :","o":["قرار بنتيجة التدقيق في حالات التهرب الضريبي بعد مضي 4 سنوات من تقديم الإقرار الضريبي أو الإقرار المعدل","إشعار خطي بنتيجة قرار التدقيق في حالات التهرب الضريبي بعد مضي 4 سنوات من تقديم الإقرار الضريبي أو الإقرار المعدل","إشعار خطي بنتيجة قرار التدقيق في حالات التهرب الضريبي بعد مضي 8 سنوات من تقديم الإقرار الضريبي أو الإقرار المعدل","قرار بنتيجة التدقيق في حالات التهرب الضريبي بعد مضي 8 سنوات من تقديم الإقرار الضريبي أو الإقرار المعدل"],"law":"income","answer":2,"orig_answer":null,"article":"29","status":"valid","explanation":"المادة (29/د): لا يجوز إصدار الإشعار الخطي بنتيجة قرار التدقيق بعد أربع سنوات من تقديم الإقرار أو تعديله، وتضاعف المدة (8 سنوات) عند وجود تهرب."},{"num":25,"type":"mcq","q":"يعتبر قرار التقدير الأولي الصادر عن الدائرة والمبلّغ للمكلف بموجب أشعار خطي :","o":["ملغى اذا قدم المكلف الإقرار الضريبي عن هذه الفترة ودفع الضريبة المستحقة عليه قبل صدور القرار الإداري","ملغى في حال تقديم المكلف اعتراض على هذا القرار ما لم يمضي 30 يوم على تبلغه أشعار التقدير","يلغى اذا قدم المكلف الإقرار الضريبي عن هذه الفترة ودفع الضريبة المستحقة عليه ما لم يمضي 30 يوم على تبلغه الأشعار","قرار نهائي اذا مضى على تاريخ التبلغ 30 يوم دون أن يقدم المكلف اعتراض على هذا القرار قبل انتهاء المدة"],"law":"income","answer":0,"orig_answer":null,"article":"30","status":"valid","explanation":"المادة (30/ج): يعتبر قرار التقدير الأولي ملغى حكماً إذا قدّم المكلف الإقرار ودفع الضريبة قبل صدور قرار التقدير الإداري."},{"num":26,"type":"mcq","q":"تنقضي شركة التضامن في الحالات التالية:","o":["بانتهاء السنة المالية المحددة في عقد الشركة","بإشهار إفلاس أحد الشركاء فيها أو بالحجر عليه بغض النظر عن قرار باقي الشركاء جميعهم","بفسخ الشركة بحكم قضائي","كل ما ذكر أعلاه."],"law":"companies","answer":2,"orig_answer":null,"article":"32","status":"valid","explanation":"المادة (32/ز): تنقضي شركة التضامن بفسخها بحكم قضائي؛ أما الإعسار (لا الإفلاس) أو الحجر فما لم يقرر باقي الشركاء الاستمرار."},{"num":27,"type":"mcq","q":"اجتماع الهيئة العامة العادي التأسيسي للشركة المساهمة الخاصة يتوجب على المساهمين في الشركة المساهمة الخاصة عقد اجتماع هيئة عامة عادي تأسيسي خلال شهر من تاريخ صدور شهادة تسجيل الشركة من قبل المراقب ليتم فيه ما يلي:","o":["انتخاب مدير عام للشركة والمفوضين بالتوقيع عنها","اتخاذ القرار المناسب بشان مصاريف التأسيس وأي التزامات ترتبت على المؤسسين نتيجة مساهمتهم في الشركة","انتخاب مجلس إدارة الشركة الأول وانتخاب مدقق حسابات وتحديد أتعابه على الأقل","جميع ما ذكر صحيح"],"law":"companies","answer":2,"orig_answer":null,"article":"71 مكرر","status":"valid","explanation":"المادة (71 مكرر): يُنتخب مجلس الإدارة الأول ومدقق الحسابات وتُحدد أتعابه، ويُبتّ في مصاريف التأسيس والتزامات المؤسسين قبل التأسيس."},{"num":28,"type":"mcq","q":"اذا تعذر على مدقق حسابات الشركة القيام بالمهام والواجبات الموكلة إليه بموجب أحكام قانون الشركات لأي سبب من الأسباب فيتوجب عليه:","o":["قبل الاعتذار عن القيام بتدقيق الحسابات أن يتفاوض مع رئيس وأعضاء مجلس الإدارة وذلك لضمان مستحقاته المالية","قبل الاعتذار عن القيام بتدقيق الحسابات ان يقدم تقريراً خطياً للمراقب ونسخة منه لمجلس الإدارة يتضمن الأسباب التي تعرقل أعماله أو تحول دون قيامه بها وعلى المراقب معالجة هذه الأسباب مع مجلس الإدارة واذا تعذر عليه ذلك يعرض المراقب الأمر على الهيئة في أول اجتماع تعقده","قبل الاعتذار عن القيام بتدقيق الحسابات أن يقدم تقريراً خطياً لديوان المحاسبة ونسخة منه لكل من مراقب عام الشركات ولمجلس إدارة الشركة يتضمن الأسباب التي تعرقل أعماله أو تحول دون قيامه بها","كل ما ذكر أعلاه صحيح"],"law":"companies","answer":1,"orig_answer":null,"article":"194","status":"valid","explanation":"المادة (194): يقدم المدقق تقريراً خطياً للمراقب ونسخة لمجلس الإدارة، ويعالج المراقب الأسباب وإلا يعرض الأمر على الهيئة العامة في أول اجتماع."},{"num":29,"type":"mcq","q":"من واجبات الشركة الأجنبية العاملة المسجلة في المملكة: (على الشركة أو الهيئة الأجنبية المسجلة وفقاً لأحكام قانون الشركات) ما يلي:","o":["أن تقدم الى المراقب خلال أشهر من نهاية كل سنة مالية ميزانيتها وحساب الأرباح والخسائر عن جميع أعمالها التي قامت بها داخل المملكة ومقارنتها مع أعمالها خارج المملكة وأن تكون هذه البيانات مدققة من مدقق حسابات أردني ومدقق الحسابات الخارجي للشركة (مركزها الرئيسي) كونها شركة أجنبية عاملة","أن تقدم الى المراقب خلال أشهر من نهاية كل سنة مالية ميزانيتها وحساب الأرباح والخسائر في المملكة مصدقة من مدقق حسابات قانوني أردني","أن تنشر ميزانيتها المشار إليها في البند (1) أعلاه في صحيفتين يوميتين على الأقل وذلك خلال سنة من انتهاء السنة المالية","كل ما ذكر صحيح"],"law":"companies","answer":1,"orig_answer":null,"article":"243","status":"valid","explanation":"المادة (243/أ/1): تقدم الشركة الأجنبية خلال ثلاثة أشهر من نهاية السنة المالية ميزانيتها وحساب الأرباح والخسائر عن أعمالها في المملكة مصدقة من مدقق أردني، وتنشرها خلال ستين يوماً."},{"num":30,"type":"mcq","q":"تأسيس الشركة المساهمة الخاصة:","o":["تتألف الشركة المساهمة الخاصة من شخصين أو أكثر ويجوز للوزير بناء على تنسيب مبرر من المراقب الموافقة على تسجيل شركة مساهمة خاصة مؤلفة من شخص واحد أو أن يصبح عدد مساهميها شخصاً واحداً","تتألف الشركة المساهمة الخاصة بعدد من المساهمين لا يقل عن عدد أعضاء مجلس إدارتها وذلك وفقاً لعقدها ونظامها الأساسي","تتألف الشركة المساهمة الخاصة بعدد من المساهمين لا يقل عن شخصين ويجوز للمراقب تسجيلها بشخص واحد اذا كان رأسمالها يقل عن 50,000 دينار","تتألف الشركة المساهمة الخاصة بعدد من المساهمين لا يقل عن (3) أشخاص ويمكن أن يصبح عدد مساهميها شخصاً واحداً وذلك نتيجة الإرث"],"law":"companies","answer":0,"orig_answer":null,"article":"65 مكرر","status":"valid","explanation":"المادة (65 مكرر/أ): تتألف المساهمة الخاصة من شخصين أو أكثر، وللوزير بتنسيب مبرر من المراقب الموافقة على تسجيلها من شخص واحد."},{"num":31,"type":"mcq","q":"حقوق مالك الأسهم العينية في الشركات المساهمة العامة:","o":["يتمتع مالكو الأسهم العينية في الشركة المساهمة العامة بالحقوق التي يتمتع بها أصحاب الأسهم النقدية إذا كانت الأسهم العينية تأسيسية تطبق عليها القيود المطبقة على الأسهم النقدية عند التأسيس","لا يجوز تأسيس أي شركة مساهمة عامة تكون أسهمها (عينيه) ناتجة عن مقدمات عينية وذلك لعدم قدرة اللجان الفنية من تحديد القيمة العادلة لهذه الأسهم و/أو المغالاة باحتساب قيمتها مما يضر في حقوق المساهمين الآخرين والغير","يتمتع مالكو الأسهم العينية في الشركة المساهمة العامة بمزايا وحقوق إضافية عن أصحاب الأسهم النقدية لكون أن هذه الأسهم العينية ناتجة عن مقدمات عينية ممكن أن تكون ماكنات عاملة، بضاعة جاهزة للبيع، حقوق امتياز ذات مردود ربحي عالي","كل ما ذكر غير صحيح"],"law":"companies","answer":0,"orig_answer":null,"article":"111","status":"valid","explanation":"المادة (111): لمالكي الأسهم العينية حقوق أصحاب الأسهم النقدية، وإذا كانت تأسيسية تطبق عليها قيود الأسهم النقدية التأسيسية."},{"num":32,"type":"mcq","q":"حسب قانون الشركات رقم (34) لسنة 2017 المعدل، بماذا يمكن استخدام الاحتياطي الإجباري لأغراض تصويب الوضع القانوني للشركة المتعثرة ومعالجة خسائرها وتشجيع الشركاء أو المساهمين على التعامل بحصص الشركة أو بأسهمها فقد أجاز قانون الشركات استخدام الاحتياطي الإجباري في الحالات التالية:","o":["استخدام الاحتياطي الإجباري لمعالجة خسائر الشركة (إطفائها) وذلك في حالة عدم وجود أية احتياطات أخرى لإطفاء خسائر الشركة وضمن شروط محددة وذلك لتصويب أوضاعها القانونية","توزيع جزء من الاحتياطي الإجباري على المساهمين نقداً بالرغم من وجود خسائر مدورة لدى الشركة وذلك لتشجيع الشركاء والمساهمين على التعامل مع مثل هذه الشركات","كل ما ذكر أعلاه صحيح","كل ما ذكر أعلاه غير صحيح"],"law":"companies","answer":0,"orig_answer":null,"article":"186","status":"valid","explanation":"المادة (186/ج) و(85 مكرر/ج) و(70/ج): للهيئة العامة غير العادية بعد استنفاد الاحتياطيات الأخرى إطفاء الخسائر من الاحتياطي الإجباري، ولا يجوز توزيعه."},{"num":33,"type":"mcq","q":"تعتبر عملية إقرار السياسات المتعلقة بنظام المدفوعات الوطني من صلاحيات:","o":["مجلس إدارة البنك المركزي الأردني","وزير المالية","مجلس الوزراء","محافظ البنك المركزي الأردني"],"law":"other:قانون البنك المركزي الأردني","answer":0,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون البنك المركزي الأردني: يتولى مجلس إدارة البنك المركزي إقرار السياسات المتعلقة بنظام المدفوعات الوطني (غير مشمول بقاعدة القوانين المتاحة)."},{"num":34,"type":"mcq","q":"جميع هذه العبارات صحيحة فيما يتعلق بالنقد في المملكة الأردنية الهاشمية باستثناء:","o":["تصدر المسكوكات التذكارية والخاصة بقرار من مجلس الوزراء ويحدد البنك المركزي المواصفات والأشكال التي يضعها لذلك","يقرر البنك المركزي الأردني الظروف والشروط التي تصدر بمقتضاها أوراق النقد والمسكوكات ويقوم بإعادة إصدارها وتبديلها","يجب أن يجري كل بيع أو وفاء في المملكة بالدينار الأردني ولا يجوز استعمال أي عملة اجنبيه لهذا الغرض","للبنك المركزي وحده حق اصدار أوراق النقد والمسكوكات في المملكة وتكون هذه الأوراق والمسكوكات وحدها العملة القانونية لدفع أي مبلغ كان"],"law":"other:قانون البنك المركزي الأردني","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون البنك المركزي: لا يوجب القانون أن يجري كل بيع أو وفاء بالدينار حصراً، فالعبارة (ج) هي المستثناة (غير مشمول بقاعدة القوانين المتاحة)."},{"num":35,"type":"mcq","q":"يتم انتخاب أعضاء إدارة الشركة المساهمة العامة المدرجة في السوق المالي وفق الأسلوب التالي:","o":["أسلوب التصويت التراكمي من قبل الهيئة العامة للشركة بالاقتراع السري","بالأغلبية لمن حضر اجتماع الهيئة العامة","نسبة وتناسب مما يحمله المساهم من أسهم وبالاقتراع السري","لكل مساهم الحق في اختيار عضو مجلس إدارة واحد وبالاقتراع السري"],"law":"securities","answer":0,"orig_answer":null,"article":"","status":"unverified","explanation":"تعليمات حوكمة الشركات المساهمة المدرجة لسنة 2017 (هيئة الأوراق المالية): يُنتخب أعضاء مجلس الإدارة بأسلوب التصويت التراكمي وبالاقتراع السري."},{"num":36,"type":"mcq","q":"الحساب المشترك للاستثمار هو:","o":["الحساب الذي يضم الاستثمارات العائدة لأكثر من خمسة عشر شخصاً وذلك لأغراض إدارة هذا الحساب","الحساب الذي يضم استثمارات متعددة ومختلفة لنفس الشخص وذلك لأغراض إدارة هذا الحساب","الحساب الذي يضم الاستثمارات العائدة لأكثر من خمسة اشخاص وذلك لأغراض إدارة هذا الحساب","الحساب الذي يضم الاستثمارات العائدة لأكثر من شخص واحد وذلك لأغراض إدارة هذا الحساب"],"law":"securities","answer":3,"orig_answer":null,"article":"2","status":"valid","explanation":"المادة (2) من قانون الأوراق المالية: الحساب المشترك للاستثمار هو الحساب الذي يضم الاستثمارات العائدة لأكثر من شخص واحد لأغراض إدارته."},{"num":37,"type":"mcq","q":"هامش الصيانة هو:","o":["الحد الأدنى لمساهمة العميل في القيمة الدفترية للأوراق المالية في حسابات التمويل على الهامش في أي وقت بعد تاريخ الشراء","الحد الأدنى لمساهمة العميل في القيمة الإسمية للأوراق المالية في حسابات التمويل على الهامش في أي وقت بعد تاريخ الشراء","مساهمة العميل في القيمة السوقية للأوراق المالية في حسابات التمويل على الهامش في أي وقت بعد تاريخ الشراء","الحد الأدنى لمساهمة العميل في القيمة السوقية للأوراق المالية في حسابات التمويل على الهامش في أي وقت بعد تاريخ الشراء"],"law":"securities","answer":3,"orig_answer":null,"article":"","status":"unverified","explanation":"تعليمات التمويل على الهامش: هامش الصيانة هو الحد الأدنى لمساهمة العميل في القيمة السوقية للأوراق المالية في أي وقت بعد الشراء."},{"num":38,"type":"mcq","q":"تسري أحكام قانون الإعسار رقم (21) لسنة 2018 على أي شخص يمارس نشاطاً اقتصادياً وأي نشاط من التالية باستثناء ما يلي:","o":["شركات التأمين","أصحاب المهن المسجلون والمرخص لهم بالعمل بموجب أحكام التشريعات النافذة","التجار أصحاب المؤسسات الفردية","الأشخاص الاعتباريون بما في ذلك الشركات المدنية والشركات التي تملكها الحكومة"],"law":"insolvency","answer":0,"orig_answer":null,"article":"3","status":"valid","explanation":"المادة (3/ب): لا تسري أحكام قانون الإعسار على البنوك وشركات التأمين، بينما تسري على الفئات (ب-د)."},{"num":39,"type":"mcq","q":"اذا وجدت المحكمة ان طلب إشهار الإعسار المقدم من الدائنين أو المراقب موافقاً للشروط المنصوص عليها في المادة (10) من القانون فتتولى تبليغه للمدين مع حافظة المستندات المرفقة به خلال مدة:","o":["خلال شهر من تاريخ تقديم طلب الإشهار","خلال ثلاثون يوماً من تاريخ تقديم طلب الإشهار","خمسة عشر يوماً من تاريخ تقديم طلب الإشهار","خمسة أيام من تاريخ تقديم طلب الإشهار"],"law":"insolvency","answer":3,"orig_answer":null,"article":"11","status":"valid","explanation":"المادة (11/أ): تبلغ المحكمة المدين الطلب وحافظة مستنداته خلال خمسة أيام من تاريخ تقديمه."},{"num":40,"type":"mcq","q":"يخضع للضمان الاجتماعي كل من أكمل عمر:","o":["سبعة عشر سنة للمؤمن عليه الأردني وغير الأردني","ستة عشر سنة للمؤمن عليه الأردني وغير الأردني","ثمانية عشر سنة للمؤمن عليه الأردني وغير الأردني","ستة عشر سنة للمؤمن عليه الأردني وثمانية عشر سنة للمؤمن عليه غير الأردني"],"law":"social","answer":1,"orig_answer":null,"article":"4","status":"valid","explanation":"المادة (4/أ): يخضع للضمان كل من أكمل ست عشرة سنة دون تمييز بسبب الجنسية."},{"num":41,"type":"mcq","q":"يشترط لاستحقاق المؤمن عليه بدل التعطل عن العمل الوارد ضمن قانون الضمان الاجتماعي ما يلي:","o":["أن لا يقل عدد اشتراكاته وفقاً لأحكام هذا القانون عن (24) اشتراكاً قبل تاريخ استحقاقه لبدل التعطل عن العمل وأن يكون له اشتراك واحد على الأقل في تأمين التعطل عن العمل","أن لا يقل عدد اشتراكاته وفقاً لأحكام هذا القانون عن (24) اشتراكاً قبل تاريخ استحقاقه لبدل التعطل عن العمل","أن لا يقل عدد اشتراكاته وفقاً لأحكام هذا القانون عن (36) اشتراكاً قبل تاريخ استحقاقه لبدل التعطل عن العمل وأن يكون له اشتراك واحد على الأقل في تأمين التعطل عن العمل","أن لا يقل عدد اشتراكاته وفقاً لأحكام هذا القانون عن (36) اشتراكاً قبل تاريخ استحقاقه لبدل التعطل عن العمل"],"law":"social","answer":2,"orig_answer":null,"article":"50","status":"valid","explanation":"المادة (50/أ/1): لا يقل عدد الاشتراكات عن 36 اشتراكاً قبل الاستحقاق، مع اشتراك واحد على الأقل في تأمين التعطل."},{"num":42,"type":"mcq","q":"عند نقل المستثمر المشروع الخاضع لأحكام قانون الاستثمار رقم (30) لسنة 2014 فإنه:","o":["يستمر المشروع في هذه الحالة من الاستفادة من الإعفاءات الممنوحة","لا يسمح بنقل المشروع المستفيد من الإعفاءات بموجب قانون الاستثمار","يستفيد المشروع من الإعفاءات كمشروع جديد","لا شيء مما ذكر أعلاه"],"law":"investment","answer":null,"orig_answer":0,"article":"","status":"obsolete","explanation":"ألغي قانون الاستثمار رقم 30 لسنة 2014 بقانون البيئة الاستثمارية رقم 21 لسنة 2022. وكان القانون الملغى يُبقي المشروع المنقول مستفيداً من الإعفاءات."},{"num":43,"type":"mcq","q":"بموجب أحكام قانون الاستثمار رقم (30) لسنة 2014 فإن:","o":["يحق لأي شخص غير اردني أن يستثمر في المملكة بالتملك أو المشاركة او بالمساهمة بأي نشاط اقتصادي","تبقى الأنشطة الاقتصادية التي تتمتع بمزايا او إعفاءات جمركية أو ضريبية بمقتضى أي تشريعات سابقة للاستثمار مستفيدة من تلك الإعفاءات والمزايا حتى نهاية مدة الإعفاء الممنوح","يعامل المستثمر غير الأردني معاملة المستثمر الأردني","جميع ما ذكر أعلاه صحيح"],"law":"investment","answer":null,"orig_answer":3,"article":"","status":"obsolete","explanation":"القانون رقم 30 لسنة 2014 ملغى. وفي قانون البيئة الاستثمارية 2022 (المادتان 3/أ و5/أ): المساواة بين المستثمر الأردني وغيره، وحق الاستثمار باستثناء الأنشطة المقيدة بنظام."},{"num":44,"type":"mcq","q":"على الرغم مما ورد في قانون ضريبة الدخل النافذ يتم تخفيض ضريبة الدخل المستحقة في المناطق الأقل نمواً في المملكة على الأنشطة الاقتصادية والحرفية والأنشطة الاقتصادية الواردة في البند (4) من الفقرة (ب) من المادة (4) من قانون الاستثمار بنسبة لا تقل عن:","o":["30%","50%","15%","25%"],"law":"investment","answer":0,"orig_answer":null,"article":"10","status":"obsolete","explanation":"القانون رقم 30 لسنة 2014 ملغى. والمادة (10) من قانون البيئة الاستثمارية 2022 تقضي بالإعفاء أو التخفيض بنسبة لا تقل عن 30% في المناطق الأقل نمواً لمدة 5 سنوات حداً أعلى."},{"num":45,"type":"mcq","q":"أي من العبارات التالية لا تعتبر صحيحة حسب قانون النزاهة ومكافحة الفساد رقم (13) لسنة 2016:","o":["يجوز تفتيش مقر هيئة النزاهة ومكافحة الفساد على أن يتم تبليغ الرئيس بذلك ودعوة من يمثل الهيئة لحضور التفتيش","لمجلس الهيئة المساهمة في استرداد الأموال المتحصلة عن أفعال الفساد سواء كانت الأموال داخل المملكة أو خارجها","يجوز لضابط الارتباط المعين من قبل رئيس مجلس الهيئة حضور اجتماعات لجان العطاءات والمشتريات بالوزارة","لرئيس مجلس الهيئة تعين ضابط ارتباط واحد أو أكثر لدى الوزارة للتحقق من مدى التزامها بمعايير النزاهة الوطنية والتشريعات"],"law":"integrity","answer":0,"orig_answer":null,"article":"5","status":"valid","explanation":"المادة (5/ب): لا يجوز تفتيش مقر الهيئة إلا بأمر قضائي وبحضور المدعي العام مع تبليغ الرئيس، فالعبارة (أ) ناقصة وغير صحيحة."},{"num":46,"type":"mcq","q":"بموجب قانون رسوم طوابع الواردات تعتبر العبارات التالية الخاصة بقرار الوزير بإعادة الرسوم المستوفاة صحيحة باستثناء:","o":["الغاء المعاملة الخاضعة لرسوم الطوابع","يحسم لحساب الخزينة ما نسبته (15%) من مقدار الرسوم التي يتم إعادتها وفقاً لأحكام القانون","اذا الصق المكلف طوابع أو دمغها بقيمة تزيد على الرسم المستحق على المعاملة","اذا تلفت الطوابع التي في حيازة أي شخص دون أي تقصير متعمد منه وكان التلف واقعاً بصورة يتعذر معها استعمالها"],"law":"stamp","answer":1,"orig_answer":null,"article":"16","status":"valid","explanation":"المادة (16/ب): يُحسم لحساب الخزينة 10% (لا 15%) من الرسوم المعادة."},{"num":47,"type":"mcq","q":"بموجب قانون التجارة يمكن ان يكون سند السحب باستثناء:","o":["لا يجوز سحبه لحساب شخص اخر","يجوز سحبه لحساب شخص آخر","يجوز سحبه عليه","يجوز سحب سند السحب لأمر الساحب نفسه"],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":0,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: يجوز سحب سند السحب لأمر الساحب نفسه وعليه ولحساب شخص آخر، فعبارة \"لا يجوز سحبه لحساب شخص آخر\" هي المستثناة."},{"num":48,"type":"mcq","q":"جميع الأمور التالية صحيحة بخصوص الوكالة التجارية حسب قانون التجارة باستثناء:","o":["الوكالة التجارية إن احتوت على توكيل مطلق تجيز الأعمال غير التجارية وان لم يرد نص صريح","الوكيل الذي لم يتلق تعليمات إلا في شأن جزء من العمل يعد مطلق اليد في الجزء الباقي","في المواد التجارية يستحق الوكيل الأجر في جميع الأحوال ما لم يكن هنالك نص مخالف","تكون الوكالة تجارية عندما تختص بمعاملات تجارية"],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":0,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: التوكيل المطلق في الوكالة التجارية لا يجيز الأعمال غير التجارية إلا بنص صريح."},{"num":49,"type":"mcq","q":"أي من العبارات التالية غير صحيحة حسب قانون التجارة فيما يتعلق بالحساب الجاري:","o":["وجود الحساب الجاري لا يمنع احد المتعاقدين من مطالبة الأخر بالعمولة عن عمل قام به بالعمولة","لا يجوز في حال من الأحوال أن يستقر الحساب الجاري على رصيد إيجابي لمصلحته","يجوز أن يكون الحساب الجاري مكشوفاً لجهة الفريقين ولا يجوز مكشوف لجهة واحدة","يتوقف مدى الحساب الجاري على إرادة المتعاقدين منها أن يجعلاه شاملاً لجميع معاملاتها أو لنوع معين منها فقط"],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: يجوز أن يكون الحساب الجاري مكشوفاً لجهة الفريقين أو لجهة واحدة."},{"num":50,"type":"mcq","q":"أي من العبارات التالية لا يعتبر صحيحاً بموجب قانون التجارة رقم (12) لعام 1966:","o":["لا تعد الدولة ودوائرها ذات شخصية اعتبارية من التجار وان قامت بمعاملات تجارية","اذا اشتغل الموظفون والقضاة الممنوعون من الإتجار قانونا بالمعاملات التجارية فتشملهم الأحكام القانونية المتعلقة بالصلح الواقي من الإفلاس","يعد تاجراً من قام بمعاملة تجارية عرضا الا ان المعاملة المذكورة لا تكون خاضعة لأحكام قانون التجارة","يعد تاجراً كل من اعلن في الصحف او النشرات أو أية واسطة أخرى عن المحل الذي أسسه وفتحه للاشتغال بالأعمال التجارية"],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":2,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: من قام بمعاملة تجارية عرضاً لا يعد تاجراً، لكن المعاملة تخضع لأحكام قانون التجارة."},{"num":51,"type":"mcq","q":"أي من العبارات التالية تعد صحيحة فيما يتعلق بالرهن التجاري حسب قانون التجارة رقم (12) لسنة 1966:","o":["يجوز وضع نص يجيز للدائن ان يمتلك المرهون أو يتصرف به بدون مراجعة المحكمة المختصة","اذا كان الرهن قائماً على أشياء أو أسناد مثليه فعقد الرهن يظل قائما وان بدلت هذه الأشياء أو الأسناد بأشياء أو أسناد من النوع نفسه","لا ينتج عقد الرهن أثراً بصفته رهناً اذا بقي المرهون في حيازة المدين","يجري رهن السند لأمر بتظهير تدرج فيه عبارة (القيمة وضعت تأميناً) أو عبارة أخرى بالمعنى نفسه"],"law":"other:قانون التجارة رقم 12 لسنة 1966","answer":3,"orig_answer":null,"article":"","status":"unverified","explanation":"قانون التجارة 1966: يجري رهن السند لأمر بتظهير يتضمن عبارة \"القيمة وضعت تأميناً\". والعبارتان (ب) و(ج) صحيحتان أيضاً، فالسؤال معيب."},{"num":52,"type":"mcq","q":"تتخذ الهيئة العامة غير العادية لجمعية المحاسبين القانونيين القرارات:","o":["بأكثرية لا تقل عن ثلثي أصوات المحاسبين القانونيين الحاضرين","نسبه 50% زائد واحد من أصوات المحاسبين القانونيين الحاضرين","بأكثرية لا تقل عن 25% من أصوات المحاسبين القانونيين الحاضرين","لا شيء مما ذكر صحيح"],"law":"accounting","answer":0,"orig_answer":null,"article":"15","status":"valid","explanation":"المادة (15/د): تتخذ قرارات الهيئة العامة غير العادية بأكثرية لا تقل عن ثلثي أصوات الحاضرين."},{"num":53,"type":"mcq","q":"من صلاحيات مجلس إدارة جمعية المحاسبين القانونيين ما يلي:","o":["عقد اجتماعات وتحديد مواعيد امتحان المهنة","المصادقة على منح إجازة المزاولة","التنسيب للهيئة العليا بإلغاء إجازة المزاولة","اعتماد معايير المحاسبة ومعايير تدقيق الحسابات"],"law":"accounting","answer":2,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/هـ): من صلاحيات المجلس التنسيب للهيئة العليا بإلغاء إجازة المزاولة؛ أما المصادقة واعتماد المعايير فللهيئة العليا (م5)."},{"num":54,"type":"mcq","q":"يتم إعتماد معايير المحاسبة ومعايير تدقيق الحسابات الواجبة التطبيق في الأردن من قبل:","o":["مجلس إدارة جمعية المحاسبين القانونين الأردنيين","الهيئة العليا لتنظيم مهنة المحاسبة القانونية","مراقب عام الشركات","لا شيء مما ذكر"],"law":"accounting","answer":1,"orig_answer":null,"article":"5","status":"valid","explanation":"المادة (5/أ): تعتمد الهيئة العليا معايير المحاسبة والتدقيق بناء على تنسيب مجلس الجمعية."},{"num":55,"type":"mcq","q":"أي من العبارات التالية غير صحيح حسب قانون تنظيم مهنة المحاسبة القانونية لسنة 2003:","o":["توقع اللجنة التأديبية عقوبة إلغاء إجازة المزاولة وشطب أسم المحاسب القانوني نهائياً من سجل المزاولين","يسري تعليق التسجيل إيقاف العمل بإجازة المزاولة بعد صدور قرار اللجنة التأديبية","إذا ارتكب المتدرب أي مخالفة لأحكام قانون المهنة والأنظمة والتعليمات الصادرة بمقتضاه أو أخل بواجبات عمله أو قواعد سلوك المهنة وآدابها يحيله المجلس الى اللجنة التأديبية","إذا ارتكب المحاسب القانوني أي مخالفة لأحكام قانون المهنة والأنظمة والتعليمات الصادرة بمقتضاه أو أخل بواجبات عمله أو قواعد سلوك المهنة وآدابها يحيله المجلس الى اللجنة التأديبية"],"law":"accounting","answer":1,"orig_answer":null,"article":"37","status":"valid","explanation":"المادة (37): قرارات اللجنة التأديبية خاضعة لمصادقة المجلس، فلا يسري التعليق بمجرد صدور قرار اللجنة."},{"num":56,"type":"mcq","q":"أي من التالية يعتبر غير صحيح بموجب قانون مكافحة غسل الأموال وتمويل الإرهاب الساري المفعول:","o":["يحظر تقديم الأموال أو جمعها أو تأمين الحصول عليها سواء بصورة مباشرة أو غير مباشرة وان كانت من مصادر مشروعة لإرهابي أو منظمة أو جمعية إرهابية","يقصد بالأموال محل الغسل النقد والأدوات المالية القابلة للتداول سواء كانت بالدينار أو بالعملات الأجنبية والأحجار الكريمة والمعادن الثمينة","يحظر غسل الأموال المتحصلة من أي من الجرائم التي نص عليها القانون والتي وقعت هذه الجرائم داخل المملكة فقط","كل ما ذكر غير صحيح"],"law":"aml","answer":2,"orig_answer":null,"article":"3","status":"valid","explanation":"قانون غسل الأموال 2021 (المادتان 2 و3): الجريمة الأصلية أي جناية أو جنحة، ويشمل الحظر المتحصلات أياً كان مكان وقوع الجريمة، فقصرها على داخل المملكة غير صحيح."},{"num":57,"type":"mcq","q":"من مهام وصلاحيات مدير عام هيئة التأمين ما يلي :","o":["إعداد برامج وخطط لتطوير قطاع التأمين وعرضها على المجلس.","إعداد القوانين والأنظمة والتعليمات الصادرة بمقتضى أحكام هذا القانون والمتعلقة بأعمال التأمين وعرضها على المجلس بعد الاستئناس برأي الاتحاد الأردني لشركات التأمين.","إعداد الهيكل التنظيمي للجهاز التنفيذي للهيئة والإشراف عليه","إقرار السياسة والخطط والبرامج التي يقترحها المجلس."],"law":"insurance","answer":null,"orig_answer":null,"article":"","status":"obsolete","explanation":"ألغيت هيئة التأمين ونقلت صلاحياتها إلى البنك المركزي بموجب قانون تنظيم أعمال التأمين رقم 12 لسنة 2021، فلم يعد لمنصب مدير عام الهيئة وجود."},{"num":58,"type":"mcq","q":"أي من المخصصات التالية لا يتم رصده ضمن مخصصات شركات التأمين التي تزاول أعمال التأمين باستثناء التامين على الحياه.","o":["مخصص الأقساط غير المكتسبة","مخصص الادعاءات غير المبلغة تحت التسوية","مخصص الادعاءات المبلغة تحت التسوية","جميع ما ذكر"],"law":"insurance","answer":null,"orig_answer":null,"article":"24","status":"unverified","explanation":"المادة (24/ب): يحدد البنك المركزي بتعليمات أسس المخصصات الفنية. وتُرصد عادةً مخصصات الأقساط غير المكتسبة والادعاءات المبلغة وغير المبلغة، وصيغة الخيار (ب) \"غير المبلغة تحت التسوية\" غير دقيقة، فالسؤال معيب."},{"num":59,"type":"mcq","q":"لمدير مديريه المنافسة ان يكلف أياً من موظفي المديرية المفوضين من الوزير للقيام بما يلي:","o":["الدخول خلال ساعات العمل فقط الى المحلات التجارية والمكاتب والمخازن لإجراء المعاينة والتفتيش","يتوجب على الموظفين المكلفين الكشف عن هوياتهم واطلاع صاحب العلاقة على نسخة من التفويض الخطي","الاطلاع على المستندات والسجلات والملفات بما فيها ملفات الحاسوب ولا يجوز الاحتفاظ بأي منها أو نسخ عنها","إجراء التحقيقات اللازمة والاستماع لإفادة أي شخص يشتبه بمخالفته لأحكام قانون المنافسة"],"law":"competition","answer":3,"orig_answer":null,"article":"19","status":"valid","explanation":"المادة (19/أ/3): من صلاحيات الموظفين إجراء التحقيقات والاستماع لإفادة المشتبه به؛ ويجوز الاحتفاظ بالمستندات أو نسخها، والدخول ليس مقيداً بكلمة \"فقط\"."},{"num":60,"type":"mcq","q":"يمكن تحريك القضايا المتعلقة بمخالفة قانون المنافسة بناء على شكوى تقدم إلى المدير العام من الجهات التالية عدا:","o":["جمعيات حماية المستهلكين المرخصة","أي تجمع لخمسة مستهلكين متضررين على الأقل","غرف الصناعة والتجارة ويستثنى مؤسسات القطاع الخاص","الوزير بتنسيب من المدير أو بناء على طلب أي جهة رسمية أخرى"],"law":"competition","answer":2,"orig_answer":null,"article":"17","status":"valid","explanation":"المادة (17/أ): يحق لمؤسسات القطاع الخاص وغرف الصناعة والتجارة تقديم الشكوى (إلى المدعي العام)، فاستثناء القطاع الخاص غير صحيح."},{"num":61,"type":"essay","q":"السؤال الأول (سبع علامات): ما هي مقدار الضريبة وحساب المساهمة الوطنية المستحقة على الدخل الخاضع لسنة 2020 للشركات التالية (الدخل الخاضع): 1. بنك 3,000,000 دينار. 2. شركة صناعة الأدوية 150,000 دينار. 3. شركة اتصالات 300,000 دينار. 4. شركة تأمين 500,000 دينار. 5. شركة وساطة مالية 500,000 دينار. 6. شركة تعدين مواد أساسية 1,000,000 دينار. 7. شركة تأجير تمويلي 100,000 دينار.","law":"income","article":"11","status":"valid","model_answer":"- بنك: 3,000,000×35% = 1,050,000 ضريبة؛ مساهمة وطنية 3% = 90,000 (م11/ب/3، و/1/أ).\n- أدوية: 150,000×20% = 30,000 تخفض 30% لسنة 2020 = 21,000؛ مساهمة 1% = 1,500 (م11/ج/2).\n- اتصالات: 300,000×24% = 72,000؛ مساهمة 2% = 6,000.\n- تأمين: 500,000×24% = 120,000؛ مساهمة 2% = 10,000.\n- وساطة مالية: 500,000×24% = 120,000؛ مساهمة 4% = 20,000.\n- تعدين: 1,000,000×24% = 240,000؛ مساهمة 7% = 70,000.\n- تأجير تمويلي: 100,000×24% = 24,000؛ مساهمة 4% = 4,000."},{"num":62,"type":"essay","q":"السؤال الثاني (علامتان): أردني مقيم في قطر كان نشاطه عام 2019 ودخله على النحو التالي: 1. أخذ قرض من بنك أردني بقيمة 2,000,000 دينار. 2. دفع فوائد على القرض 200,000 دينار. 3. استثمر جزء من القرض في قطر حقق منه دخل خلال عام 2019 مبلغ 400,000 دينار. 4. وقام بإيداع جزء من القرض وديعة في أحد البنوك استحق له فائدة منها 120,000 دينار. 5. اقتطع البنك منها ضريبة بواقع 6,000 دينار. 6. له دخل من إيجارات في الأردن بقيمة 15,000 دينار دفع عليها مسقفات 1,000 دينار. 7. متزوج وزوجته لا تعمل. المطلوب: قيمة الضريبة المستحقة عليه عام 2019؟","law":"income","article":"3","status":"valid","model_answer":"- هو غير مقيم (لم يقم 183 يوماً)، فلا يخضع دخله القطري، لأن م3/ج تخص المقيم. ولو عُدّ مقيماً لخضع الدخل الخارجي الناشئ عن أموال من المملكة بنسبة 10% دون أي تنزيل: 400,000×10% = 40,000.\n- فوائد الوديعة: الاقتطاع 5% (6,000) ضريبة قطعية للشخص الطبيعي، فلا تدخل في الدخل الإجمالي (م12/أ/2، ج).\n- فوائد القرض 200,000 لا تُنزل لأنها لم تنفق لإنتاج دخل خاضع.\n- الإيجار 15,000 دخل خاضع. يُمنح غير المقيم إعفاء المعالين 10,000 إذا كانت زوجته مقيمة في المملكة (م9/د)، فيبقى 5,000×5% = 250، ويُقاص منها ما دفعه من مسقفات بحدود ضريبة هذا الدخل (م18/ب)، فالضريبة المستحقة صفر.\n- إن كانت زوجته غير مقيمة: 15,000 خاضع، ضريبته 1,500 (5%+10%+15%) ناقص 1,000 مسقفات = 500 دينار."},{"num":63,"type":"essay","q":"السؤال الثالث (علامتان): أعلن أحد البنوك دخل خاضع عام 2019 بقيمة 2 مليون دينار مفصل على النحو التالي: دخل خاضع من نشاطه 1,700,000؛ حصة البنك من أرباح مساهمة في شركة A بنسبة مساهمة بلغت 5% 100,000؛ حصة البنك من أرباح مساهمة في شركة B بنسبة مساهمة بلغت 15% 200,000؛ مجموع الدخل الخاضع 2,000,000 دينار. المطلوب: احسب الضريبة المستحقة على البنك المتوجب دفعها عند تقديم الإقرار الضريبي.","law":"income","article":"11","status":"valid","model_answer":"- أرباح الأسهم الموزعة للبنوك مستثناة من الإعفاء (م4/أ/8)، فتخضع كاملة أياً كانت نسبة المساهمة.\n- الضريبة: 2,000,000×35% = 700,000 (م11/ب/3).\n- المساهمة الوطنية: 2,000,000×3% = 60,000 (م11/و).\n- المجموع 760,000 دينار، يُطرح منه ما دُفع مقدماً أو اقتُطع إن وجد، ويُدفع الرصيد مع الإقرار (م18)."},{"num":64,"type":"essay","q":"السؤال الرابع (ثلاث علامات): موظف راتبه الشهري 100,000 دينار لعام 2019 متزوج وله ثلاث أولاد أحدهم في مدرسة خاصة يدفع عنه رسوم تعليم 2,000 دينار ولديه قرض بنكي باسمه واسم زوجته دفع عنه فائدة عام 2019 مبلغ 2,500 دينار يمتلك عقار مؤجر بقيمة 20,000 دينار سنوياً ويدفع مسقفات عن هذا العقار سنوياً 1,500 دينار وأرباح بيع أسهم 2,000 دينار وأرباح بيع حصة في شركة 3,000 دينار وأرباح أسهم في أحد البنوك 4,000 دينار وفوائد وديعة بنكية 5,000 دينار مقتطع عنها 250 دينار ضريبة دخل. المطلوب: احتساب ضريبة الدخل المستحقة.","law":"income","article":"11","status":"valid","model_answer":"- الرواتب 1,200,000 + الإيجار 20,000 = 1,220,000. أرباح بيع الأسهم والحصة معفاة (م4/أ/5)، وأرباح الأسهم الموزعة معفاة (م4/أ/8)، وفوائد الوديعة اقتطاعها 5% قطعي (م12).\n- إعفاءات 2019: 10,000 شخصي + 10,000 معالين = 20,000. إعفاءات التعليم وفوائد الإسكان (1,000 لكل فرد) تبدأ من 2020 (م9/أ/3)، فلا تُمنح لسنة 2019.\n- الدخل الخاضع 1,200,000.\n- الضريبة: 2,500 (على أول 20,000) + 980,000×25% = 245,000 + 200,000×30% = 60,000، فالمجموع 307,500.\n- يُقاص منها ما دفعه من مسقفات 1,500 (بحدود ضريبة دخل الإيجار، م18/ب)، فتصبح 306,000.\n- المساهمة الوطنية 1% على ما زاد عن 200,000: 1,000,000×1% = 10,000 (م11/و/1/و)."},{"num":65,"type":"essay","q":"السؤال الخامس (علامتان): ما هي شروط تصدير الخدمة للمدن والأسواق الحرة وفقاً لقانون ضريبة المبيعات؟","law":"sales","article":"7","status":"unverified","model_answer":"- تخضع السلع والخدمات المباعة إلى المناطق والمدن والأسواق الحرة أو المصدرة للخارج للضريبة بنسبة صفر (م7/أ/2).\n- تحدد التعليمات التنفيذية شروط ذلك، ومنها:\n  - أن تقدَّم الخدمة لمشروع مسجل في المنطقة أو السوق الحرة لغايات ممارسة نشاطه فيها.\n  - أن يُستفاد من الخدمة داخل المنطقة الحرة أو خارج المملكة.\n  - أن تُثبت بفاتورة ضريبية وعقد ومستندات قبض."},{"num":66,"type":"essay","q":"السؤال السادس (علامتان): اذكر أربعة من الأمور التي يقوم بها البنك المركزي بالنيابة عن الحكومة أو المؤسسة العامة.","law":"other:قانون البنك المركزي الأردني","article":"","status":"unverified","model_answer":"- العمل كبنك ووكيل مالي للحكومة والمؤسسات العامة وإدارة حساباتها.\n- إصدار سندات وأذونات الخزينة وإدارتها وخدمة الدين العام.\n- قبض الأموال ودفعها لحسابها.\n- الاحتفاظ بالأوراق المالية والذهب عنها.\n- تقديم المشورة في الشؤون المالية والنقدية."},{"num":67,"type":"essay","q":"السؤال السابع (علامة ونصف): لهيئة الأوراق المالية شطب قيد المدقق من السجل لديها وذلك في الحالات التالية:","law":"securities","article":"","status":"unverified","model_answer":"- إذا شُطب أو أُلغيت إجازته لمزاولة المهنة بموجب قانون تنظيم مهنة المحاسبة.\n- إذا ثبتت مخالفته لأحكام قانون الأوراق المالية أو الأنظمة والتعليمات أو معايير التدقيق.\n- إذا فقد أياً من شروط القيد.\n- إذا طلب ذلك بنفسه."},{"num":68,"type":"essay","q":"السؤال الثامن (علامة ونصف): اذكر مراحل إجراءات الإعسار حسب قانون الإعسار رقم (21) لسنة 2018.","law":"insolvency","article":"","status":"valid","model_answer":"- طلب إشهار الإعسار وإشهاره بقرار من المحكمة، وتعيين وكيل الإعسار (م10-11).\n- إعادة التنظيم: إعداد خطة إعادة التنظيم والتصويت عليها وتصديقها.\n- التصفية: بيع أموال المدين وتوزيعها على الدائنين حسب المراتب، ثم شطب التسجيل.\n- توجد إجراءات مبسطة للمدين الصغير."},{"num":69,"type":"essay","q":"السؤال التاسع (علامتان): بين مدة حظر التصرف بالسهم التأسيسي للشركة المساهمة العامة وكذلك بين استثناءات الحظر للسهم التأسيسي للشركة المساهمة العامة؟","law":"companies","article":"100","status":"valid","model_answer":"- يحظر التصرف بالسهم التأسيسي قبل مرور سنتين على الأقل من تأسيس الشركة، وأي تصرف مخالف باطل (م100/أ).\n- يُستثنى من الحظر (م100/ب):\n  - الانتقال إلى الورثة.\n  - الانتقال بين الزوجين والأصول والفروع.\n  - الانتقال من مؤسس إلى مؤسس آخر.\n  - الانتقال إلى الغير بقرار قضائي أو بالبيع بالمزاد العلني."},{"num":70,"type":"essay","q":"السؤال العاشر (علامتان ونصف): اذكر خمسة من واجبات مدقق الحسابات وفقاً لما ذكر بأحكام المادة (193) من قانون الشركات؟ يتولى مدققو الحسابات مجتمعين أو منفردين القيام بما يلي:","law":"companies","article":"193","status":"valid","model_answer":"- مراقبة أعمال الشركة.\n- تدقيق حساباتها وفق قواعد التدقيق المعتمدة.\n- فحص الأنظمة المالية والإدارية وأنظمة الرقابة الداخلية.\n- التحقق من موجودات الشركة وملكيتها وقانونية التزاماتها.\n- الاطلاع على قرارات المجلس والهيئة العامة والتعليمات.\n- تقديم تقرير خطي للهيئة العامة وتلاوته أمامها."},{"num":71,"type":"essay","q":"السؤال الحادي عشر (علامتان): إذا تكرر حدوث إصابة العمل فتتبع بشأن تعويض المصاب أو راتب الاعتلال الذي يستحقه القواعد التالية:","law":"social","article":"35","status":"valid","model_answer":"- إذا كان العجز الإجمالي أقل من 30%: يُعوَّض عن عجز الإصابة الأخيرة وحدها، على أساس أجره بتاريخ وقوعها (م35/أ).\n- إذا بلغ 30% فأكثر، يُحسب راتب الاعتلال عن العجز الناشئ عن الإصابات جميعاً، وفق أجره بتاريخ الإصابة الأخيرة (م35/ب):\n  - إذا سبق له قبض تعويض عن إصابة سابقة.\n  - إذا كان يتقاضى راتب اعتلال، على ألا يقل الراتب الجديد عن السابق."},{"num":72,"type":"essay","q":"السؤال الثاني عشر (علامة ونصف): اذكر ثلاثاً من النشاطات التي لا تسري عليها أحكام قانون الاستثمار رقم (30) لسنة 2014 والخاصة بنسبة ضريبة الدخل البالغة (5%).","law":"investment","article":"","status":"obsolete","model_answer":"- قانون الاستثمار رقم 30 لسنة 2014 ملغى بقانون البيئة الاستثمارية رقم 21 لسنة 2022، وتنظم نسب المناطق التنموية حالياً المادة (11/ط) من قانون ضريبة الدخل.\n- كانت الأنشطة المستثناة من نسبة 5% في القانون الملغى:\n  - تعدين المواد الأساسية.\n  - شركات التأمين وإعادة التأمين.\n  - البنوك والشركات المالية.\n  - الاتصالات الأساسية.\n  - التأجير التمويلي."},{"num":73,"type":"essay","q":"السؤال الثالث عشر (علامة ونصف): اذكر ثلاثاً من الوسائل التي تقوم هيئة النزاهة ومكافحة الفساد بحماية المبلغين أو الشهود أو المخبرين والخبراء في قضايا الفساد وأقاربهم من أي اعتداء أو انتقام أو ترهيب محتمل.","law":"integrity","article":"24","status":"valid","model_answer":"وسائل الحماية (م24/أ):\n- توفير الحماية في أماكن إقامتهم.\n- عدم الإفصاح عن هويتهم وأماكن وجودهم.\n- الإدلاء بالشهادة بتقنيات الاتصال الحديثة.\n- حمايتهم في أماكن عملهم من التمييز والفصل التعسفي.\n- توفير أماكن إيواء عند الضرورة."},{"num":74,"type":"essay","q":"السؤال الرابع عشر (علامة ونصف): عدد الحقوق والمزايا المترتبة للمستأجر حسب قانون التأجير التمويلي.","law":"leasing","article":"10","status":"valid","model_answer":"- اختيار المورد والمأجور (م10/أ).\n- حيازة المأجور والانتفاع به وفق العقد.\n- الرجوع على المورد مباشرة فيما يخص جودة المأجور ونوعيته وكميته وتسليمه.\n- حقوق أخرى:\n  - التملك بتسديد باقي البدل قبل انتهاء العقد (م6/ب).\n  - التأجير من الباطن بموافقة خطية من المؤجر (م9)."},{"num":75,"type":"essay","q":"السؤال الخامس عشر (علامتان): عدد أربعاً من مهام ديوان المحاسبة.","law":"audit","article":"3","status":"valid","model_answer":"مهام ديوان المحاسبة (م3):\n- مراقبة واردات الدولة ونفقاتها وحسابات الأمانات والسلف والقروض والمستودعات.\n- تقديم المشورة المحاسبية للجهات الخاضعة لرقابته.\n- الرقابة على الأموال العامة للتأكد من سلامة إنفاقها.\n- التأكد من سلامة تطبيق التشريعات البيئية.\n- التثبت من قانونية القرارات والإجراءات الإدارية."},{"num":76,"type":"essay","q":"السؤال السادس عشر (علامة ونصف): إذا كان السحب لا يشتمل أحد البيانات الرئيسية لا يعتبر سند سحب إلا في حالات معينة اذكر ثلاثاً منها.","law":"other:قانون التجارة رقم 12 لسنة 1966","article":"","status":"unverified","model_answer":"حالات قانون التجارة 1966:\n- إذا خلا من تاريخ الاستحقاق اعتُبر مستحق الأداء لدى الاطلاع.\n- إذا خلا من مكان الوفاء اعتُبر المكان المبين بجانب اسم المسحوب عليه مكاناً للوفاء ومحلاً لإقامته.\n- إذا خلا من مكان الإنشاء اعتُبر منشأً في المكان المبين بجانب اسم الساحب."},{"num":77,"type":"essay","q":"السؤال السابع عشر (علامة ونصف): عدد الجهات غير المالية الخاضعة لقانون مكافحة غسل الأموال وتمويل الإرهاب رقم (46) لسنة 2007.","law":"aml","article":"14","status":"changed","model_answer":"- القانون 46 لسنة 2007 حل محله القانون رقم 20 لسنة 2021.\n- المهن والأعمال غير المالية الخاضعة حالياً (م14/أ/2):\n  - تجار العقارات ومطوروها.\n  - تجار المعادن الثمينة والأحجار الكريمة.\n  - المحامون والمحاسبون القانونيون عند قيامهم بعمليات مالية لعملائهم، كبيع العقارات وإدارة الأموال والحسابات وتأسيس الشركات.\n  - أي جهة يقرر مجلس الوزراء إخضاعها (م14/ب)."},{"num":78,"type":"essay","q":"السؤال الثامن عشر (علامة ونصف): احسب العجز بهامش الملاءة إن وجد لشركة تأمين لديها فرع بدولة قطر حسب المعطيات التالية: رأسمال الأساسي 7,2 مليون دينار، رأسمال المطلوب 3,2 مليون دينار، العجز في إعادة تقييم الاستثمارات 1,4 مليون دينار.","law":"insurance","article":"24","status":"unverified","model_answer":"- رأس المال المتوفر = 7.2 − 1.4 = 5.8 مليون.\n- هامش الملاءة = 5.8 ÷ 3.2 = 181%، وهو أعلى من الحد الأدنى 150%، فلا عجز.\n- تحدد متطلبات الملاءة حالياً بتعليمات البنك المركزي (م24/أ من القانون 12/2021)."},{"num":79,"type":"essay","q":"السؤال التاسع عشر (علامة ونصف): حسب قانون تنظيم مهنة المحاسبة القانونية لسنة 2003 يقسم مقدم طلب إجازة مزاولة المهنة قبل منحه إياها يميناً أمام رئيس الهيئة العليا أو من ينتدبه من أعضائها بحضور رئيس مجلس إدارة الجمعية. المطلوب: كتابة نص هذا اليمين.","law":"accounting","article":"24","status":"valid","model_answer":"نص اليمين (م24/أ):\n\"أقسم بالله العظيم أن أقوم بواجبات مهنتي بشرف وأمانة دون تحيز وأن أتقيد بالقوانين والأنظمة والتعليمات المعمول بها وأن أحافظ على أسرار المهنة وآدابها وقواعدها\"."}]}]};
